KB.add({"board":"13","title":"时政、科技政策与国际关系","note":"2020—2026年交大名解几乎每年有一到两个时政或科技词：人类命运共同体（2020）、两弹一星精神（2021）、双循环与双碳（2022）、《共产党宣言》（2024）、数智技术与天使投资（2025）、四个军种与四个兵种（2026，见板块15）；选择题考过新时代三件大事与新中国宪法（2023）、第三个历史决议（2024）、二十届三中全会决定（2025）。2013—2019年名解考过大量国际关系与美国政治、金融市场词条。今年重点：“十五五”开局、人工智能治理、新质生产力、网络生态治理（2026作文就是网络治理）。时政名解要写全“提出时间与场合—内涵—意义”三层，数字和年份必须准。","clusters":[{"cid":"13a","name":"党史主线：党代会、历史决议与中央全会","line":"1848年《共产党宣言》奠定理论源头，1921年建党；三个历史决议（1945、1981、2021）总结历史，历次党代会把指导思想写入党章（七大毛泽东思想、十五大邓小平理论、十六大“三个代表”、十七大科学发展观、十九大习近平新时代中国特色社会主义思想）；1978年十一届三中全会开启改革开放，十八届、二十届三中全会接续深化，二十届四中全会定“十五五”规划建议，五中全会作出全面从严治党决定。"},{"cid":"13b","name":"新时代理论表述：数字合称","line":"按“总布局、总战略、发展理念、奋斗目标、本质特征”记：“五位一体”（2012）、“四个全面”（2014至2015）、新发展理念（2015）、“两个一百年”与“两步走”、中国式现代化五个特征（2022）；落脚在共同富裕、全过程人民民主和社会主义核心价值观。"},{"cid":"13c","name":"发展战略、规划与绿色转型","line":"五年规划是主线：“十四五”提出以国内大循环为主体、国内国际双循环相互促进的新发展格局，2020年宣布“双碳”目标（2030年前碳达峰、2060年前碳中和），“十五五”（2026至2030）在2026年开局；高质量发展、新型举国体制、自贸试验区与区域重大战略是路径，《巴黎协定》是双碳的国际背景。"},{"cid":"13d","name":"经济学与资本市场常识","line":"宏观看总量与物价（GDP、CPI、通胀与通缩），政府用财政政策和货币政策调控；生活水平与分配看恩格尔系数和基尼系数；企业按生命周期融资，从天使投资、风险投资到IPO上市（纽交所、纳斯达克、创业板、科创板、北交所）；各种“陷阱”“效应”“定律”是名解常客。"},{"cid":"13e","name":"数字技术与人工智能","line":"数据（大数据、数据要素）、算力（云计算、芯片）和算法（基础大模型）是三大底座；1956年达特茅斯会议提出“人工智能”，2016年AlphaGo、2022年ChatGPT两次引爆关注；国家层面以数字中国、“人工智能+”行动和新质生产力统摄，前沿方向是具身智能与量子科技。"},{"cid":"13f","name":"“两弹一星”到航天强国：重大科技成就","line":"从“两弹一星”（1964年原子弹、1967年氢弹、1970年东方红一号）起步，中国航天走过三大里程碑：人造地球卫星、载人航天（2003年神舟五号）、深空探测（嫦娥“绕、落、回”与天问）；北斗、天宫、天眼、“墨子号”和杂交水稻、青蒿素构成当代科技成就清单，新型举国体制是共同机制。"},{"cid":"13g","name":"网络生态与人工智能治理","line":"治理分三层：国内立法与部门规章（网络安全法、数据安全法、个人信息保护法，2023年《生成式人工智能服务管理暂行办法》、2025年生成合成内容标识办法），平台与内容治理（算法、深度合成、网络暴力、信息茧房），全球规则（2023年《全球人工智能治理倡议》、欧盟《人工智能法》）。"},{"cid":"13h","name":"中国外交与国际组织","line":"外交理念从和平共处五项原则（1953至1954）、万隆会议“求同存异”到人类命运共同体与全球四大倡议；中国1945年为联合国创始会员国，1971年恢复合法席位，2001年加入世贸组织，并借上合（2001）、金砖、G20、东盟与RCEP、“一带一路”参与全球治理。"},{"cid":"13i","name":"国际关系概念与冷战史","line":"1648年威斯特伐利亚体系确立主权国家原则；二战后雅尔塔体系奠定两极格局，1946年铁幕演说、1947年杜鲁门主义与马歇尔计划开启冷战，北约与华约对峙；1991年苏联解体后进入“一超多强”，多极化、全球化与地缘政治成为分析框架。"},{"cid":"13j","name":"美国政治与中美关系","line":"美国以1787年宪法确立三权分立：国会分参众两院，总统由选举人团选出，共和党与民主党轮替执政；外交上从门罗主义、孤立主义走向二战后的全球干预；中美关系经1971年基辛格秘密访华、1972年尼克松访华与三个联合公报走向建交。"}],"entries":[{"id":"b13-001","t":"人类命运共同体","cid":"13h","p":1,"kind":"概念","exam":["2020名解"],"alias":["人类命运共同体","命运共同体"],"one":"中国倡导的国际关系理念，各国命运相连、休戚与共。","ans":"人类命运共同体是**中国倡导的处理国际关系、推进全球治理的理念**，指**各国命运相连、休戚与共，应同舟共济、合作共赢**。**2012年党的十八大首次提出“倡导人类命运共同体意识”**，**2013年习近平在莫斯科国际关系学院演讲时向世界阐述**，此后**写入党章（2017）、宪法（2018）和多项联合国决议**。其目标是建设**持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界**，实践路径包括共建“一带一路”、建设新型国际关系，以及**全球发展、全球安全、全球文明、全球治理四大倡议**。它超越零和博弈，为应对气候变化、公共卫生、人工智能等全球性挑战提供中国方案。","pts":["各国命运相连，同舟共济","2012十八大提出，2013阐述，入党章宪法","五个世界；一带一路与四大倡议"],"mem":"“五个世界”首字串联：和（持久和平）、安（普遍安全）、荣（共同繁荣）、容（开放包容）、美（清洁美丽），记“和安荣容美”。三个年份：2012提出、2013阐述、2017入党章、2018入宪法。","mix":"“共同体”不等于一带一路，后者是实践平台；十八大提出的是“倡导人类命运共同体意识”，2013年才由习近平在莫斯科国际关系学院向世界阐述。","mcq":[{"q":"“人类命运共同体”概念首次写入党代会报告是在","o":["十八大","十六大","十七大","十九大"],"a":0,"w":"2012年十八大提出“倡导人类命运共同体意识”。"},{"q":"下列不属于“五个世界”目标的是","o":["持久和平","普遍安全","共同繁荣","绝对平等"],"a":3,"w":"五个目标为持久和平、普遍安全、共同繁荣、开放包容、清洁美丽。"}],"rel":[{"t":"全球四大倡议","n":"实践路径"},{"t":"一带一路","n":"实践平台"},{"t":"中国梦","n":"对内对外理念对举"},{"t":"《联合国家宣言》","n":"国际合作历史对照"}],"more":"2017年写入党章，2018年写入宪法序言；2020年名解真题。"},{"id":"b13-002","t":"两弹一星精神","cid":"13f","p":1,"kind":"概念","exam":["2021名解"],"alias":["两弹一星精神","两弹一星"],"one":"“热爱祖国、无私奉献，自力更生、艰苦奋斗，大力协同、勇于登攀”。","ans":"“两弹一星”指**原子弹、导弹和人造地球卫星**（后来常把原子弹和氢弹并称“两弹”）。新中国在极端困难条件下，**1964年成功爆炸第一颗原子弹，1966年导弹核武器试验成功，1967年第一颗氢弹爆炸成功，1970年发射第一颗人造卫星“东方红一号”**。**1999年中共中央、国务院、中央军委表彰23位科技专家，授予“两弹一星功勋奖章”**，并概括出**“热爱祖国、无私奉献，自力更生、艰苦奋斗，大力协同、勇于登攀”**的两弹一星精神。它是**中国共产党人精神谱系的组成部分**，钱学森、邓稼先、郭永怀等是代表人物。","pts":["原子弹、导弹、卫星，四个时间节点","1999年表彰23位功勋，二十四字精神","精神谱系；钱学森等代表"],"mem":"年份串成顺口溜：“六四弹，六六导，六七氢，七零星”，即1964原子弹、1966导弹、1967氢弹、1970卫星。二十四字三组：爱国奉献、自力艰苦、协同攀登，各八字。交大校友钱学森是代表人物。","mix":"“两弹”最初指原子弹和导弹，后来常指原子弹和氢弹；“一星”是人造卫星。1999年表彰的是23位科学家，别与“共和国勋章”混。","mcq":[{"q":"我国第一颗原子弹爆炸成功的年份是","o":["1964年","1960年","1967年","1970年"],"a":0,"w":"1964年10月，第一颗原子弹爆炸成功。"},{"q":"1999年被授予“两弹一星功勋奖章”的科技专家人数是","o":["12位","18位","23位","30位"],"a":2,"w":"共23位。"}],"rel":[{"t":"“两弹一星”功勋科学家","n":"精神的承载者"},{"t":"钱学森","n":"交大校友代表人物"},{"t":"邓稼先","n":"核武器研制代表"},{"t":"中国共产党人精神谱系","n":"属其中一环"}],"more":"1999年9月18日表彰大会，授予23位科技专家“两弹一星功勋奖章”。"},{"id":"b13-003","t":"双循环","cid":"13c","p":1,"kind":"概念","exam":["2022名解"],"alias":["新发展格局","国内国际双循环","双循环"],"one":"以国内大循环为主体、国内国际双循环相互促进的新发展格局。","ans":"双循环即**“以国内大循环为主体、国内国际双循环相互促进的新发展格局”**，**2020年5月中央政治局常委会会议首次提出**，同年十九届五中全会写入“十四五”规划建议。它是**在逆全球化抬头、外部环境深刻变化和我国拥有超大规模市场的背景下作出的战略选择**：**以扩大内需为战略基点，畅通生产、分配、流通、消费各环节**，依靠科技自立自强提升国内循环质量；同时**坚持高水平对外开放，以国内循环吸引全球资源**。新发展格局**是开放的国内国际双循环，并非封闭的国内循环**。","pts":["2020年提出：国内大循环为主体，双循环相互促进","背景：逆全球化、外部环境变化、超大规模市场","扩大内需、畅通循环、科技自立与高水平开放"],"mem":"逻辑线：外部不确定（逆全球化）→所以靠自己的大市场（内循环为主）→但不关门（外循环相促进）。关键词“内需、畅通、科技、开放”。一句话区分：不是“闭门造车”，是“以内为主，内外联动”。","mix":"“双循环”2020年提出，是新发展格局；“新发展理念”是2015年；“内循环为主”不等于封闭，答题时务必加上高水平对外开放。","mcq":[{"q":"“新发展格局”的表述是","o":["以国际大循环为主体","国内循环与国际循环并重","以出口为导向的开放格局","以国内大循环为主体、国内国际双循环相互促进"],"a":3,"w":"2020年提出，核心是国内大循环为主体。"},{"q":"新发展格局以什么为战略基点","o":["扩大出口","吸引外资","扩大内需","发展金融"],"a":2,"w":"以扩大内需为战略基点。"}],"rel":[{"t":"新发展理念","n":"2015年同类表述"},{"t":"全球化与逆全球化","n":"提出的外部背景"},{"t":"供给侧结构性改革","n":"提升国内循环质量"},{"t":"五年规划","n":"写入“十四五”规划建议"}],"more":"2020年5月中央政治局常委会会议首次提出；2020年十九届五中全会写入“十四五”规划建议。"},{"id":"b13-004","t":"碳达峰碳中和","cid":"13c","p":1,"kind":"概念","exam":["2022名解"],"alias":["双碳","“双碳”目标","碳达峰","碳中和","3060目标"],"one":"2030年前碳达峰、2060年前碳中和，中国2020年宣布。","ans":"碳达峰碳中和（“双碳”）是**中国应对气候变化的重大战略目标**。**2020年9月习近平在第七十五届联合国大会一般性辩论上宣布：二氧化碳排放力争于2030年前达到峰值，努力争取2060年前实现碳中和**。**碳达峰指二氧化碳排放量达到历史最高值后稳中有降；碳中和指一定时期内人为排放的二氧化碳通过植树造林、节能减排、碳捕集等方式抵消，实现“净零排放”**。我国构建了**“1+N”政策体系**，**2021年7月全国碳排放权交易市场上线**，“双碳”推动能源和产业结构绿色转型，体现负责任大国的担当。","pts":["2020年联大宣布：2030前达峰，2060前中和","达峰是峰值后下降，中和是净零排放","“1+N”政策体系，全国碳市场上线"],"mem":"数字串“30·60”：三十年前达峰，六十年前中和，先“峰”后“中”，中间约30年。“碳达峰”像爬山到顶，“碳中和”像收支相抵。“1+N”：一个顶层文件加N个配套。","mix":"碳达峰是排放最高点，碳中和是净零；“双碳”不等于“零排放”；2025年中国宣布的新一轮国家自主贡献是到2035年比峰值下降7%—10%。","mcq":[{"q":"中国提出碳中和的目标年份是","o":["2030年","2035年","2050年","2060年"],"a":3,"w":"努力争取2060年前实现碳中和；2030年前是碳达峰。"},{"q":"中国宣布“双碳”目标的场合是","o":["联合国大会一般性辩论","巴黎气候大会","G20峰会","博鳌亚洲论坛"],"a":0,"w":"2020年9月第七十五届联合国大会一般性辩论。"}],"rel":[{"t":"《巴黎协定》","n":"国际背景"},{"t":"全国碳排放权交易市场","n":"落实工具"},{"t":"绿色转型","n":"推动能源产业转型"},{"t":"“绿水青山就是金山银山”","n":"生态理念依据"}],"more":"2020年9月第七十五届联合国大会宣布；2021年7月全国碳排放权交易市场上线。\n2025年新一轮国家自主贡献：到2035年全经济范围温室气体净排放量比峰值下降7%—10%。"},{"id":"b13-005","t":"《共产党宣言》","cid":"13a","p":1,"kind":"作品","exam":["2024名解"],"alias":["共产党宣言","宣言"],"one":"马克思、恩格斯1848年发表，科学社会主义第一个纲领性文献。","ans":"《共产党宣言》是**马克思、恩格斯为共产主义者同盟起草的纲领**，**1848年2月在伦敦以德文发表**，是**第一部科学社会主义的纲领性文献，标志着马克思主义的诞生**。全书以“一个幽灵，共产主义的幽灵，在欧洲游荡”开篇，用唯物史观阐明**阶级斗争是社会发展的动力**，论证**资本主义必然灭亡、社会主义必然胜利**，以“全世界无产者，联合起来！”收尾。**1920年8月陈望道在上海译出第一个中文全译本**，为中国共产党的创建提供了思想准备。","pts":["马恩为共产主义者同盟起草，1848年发表","科学社会主义纲领，马克思主义诞生标志","陈望道1920年首个中文全译本"],"mem":"一个画面记全：1848年伦敦，两个德国人写下一份“党的纲领”。1920年陈望道在浙江义乌老家柴屋里翻译，母亲送来粽子和红糖，他蘸着墨汁吃还说“甜”，“真理的味道非常甜”。年份挂钩：1848（宣言）、1920（中文全译）、1921（建党），三个年份一路排下来。","mix":"《资本论》第一卷是1867年，不是1848年；《共产党宣言》由马克思和恩格斯合写，不是列宁著作；首个中文全译本译者是陈望道，不是李大钊或陈独秀。","mcq":[{"q":"《共产党宣言》第一个中文全译本的译者是","o":["李大钊","瞿秋白","陈望道","陈独秀"],"a":2,"w":"陈望道1920年8月在上海出版，2024届名解考过《共产党宣言》。"},{"q":"《共产党宣言》最初发表于","o":["1848年","1867年","1871年","1844年"],"a":0,"w":"1848年2月在伦敦以德文发表；1867年是《资本论》第一卷。"}],"rel":[{"t":"陈望道与《共产党宣言》首个中文全译本","n":"中文全译本的故事"},{"t":"中国共产党第一次全国代表大会","n":"1921年建党，受其影响"},{"t":"亚当·斯密与《国富论》","n":"经济思想上常被对举"},{"t":"《独立宣言》","n":"同为纲领性“宣言”"}],"more":"名句：一个幽灵，共产主义的幽灵，在欧洲游荡。\n名句：全世界无产者，联合起来！\n1848年2月在伦敦以德文首次发表；1920年8月陈望道中文全译本在上海出版。"},{"id":"b13-006","t":"数智技术","cid":"13e","p":1,"kind":"概念","exam":["2025名解"],"alias":["数智技术","数智化","数智化转型"],"one":"数字化与智能化深度融合的新一代信息技术统称。","ans":"数智技术是**数字化与智能化深度融合的新一代信息技术的统称**，包括**大数据、云计算、物联网、区块链和人工智能**等。数字化把信息转化为可记录、传输和计算的数据，智能化借助算法和模型对数据进行识别、预测和决策，二者结合形成**“数据采集—分析—智能决策”的应用链**。数智技术是**发展新质生产力、建设数字中国的重要支撑**，正推动智能制造、智慧城市、数字政务、智慧医疗和智慧教育等领域的数智化转型。同时它带来数据安全、隐私保护、算法偏见和数字鸿沟等问题，需要**依法治理、科技向善**。","pts":["数字化+智能化深度融合的信息技术","数据采集、分析、智能决策应用链","支撑新质生产力与数字中国；需防风险"],"mem":"拆字记：数智=“数”（数字化，把世界变成数据）+“智”（智能化，让数据会思考）。顺序口诀“先数后智”：先采集，再分析，后决策。2025届名解考过，答案骨架就是“定义—两化关系—应用—风险治理”四步。","mix":"数智技术是技术统称，数字经济是经济形态，新质生产力是生产力质态，三者层级不同；别把“数智”写成“数治”。","mcq":[{"q":"下列关于“数智技术”的表述，正确的是","o":["仅指传统办公软件","数字化与智能化深度融合的新一代信息技术","只包括区块链技术","只用于金融行业"],"a":1,"w":"数智技术涵盖大数据、云计算、物联网、区块链、人工智能等。"},{"q":"数智技术应用链的正确顺序是","o":["智能决策—数据采集—分析","分析—数据采集—智能决策","数据采集—智能决策—分析","数据采集—分析—智能决策"],"a":3,"w":"先采集数据，再分析，最后形成智能决策。"}],"rel":[{"t":"新质生产力","n":"数智技术是其重要支撑"},{"t":"数字中国","n":"国家数字化战略"},{"t":"大数据","n":"数智技术的组成部分"},{"t":"数字鸿沟","n":"数智化带来的社会风险"}],"more":"2025届交大名解真题。"},{"id":"b13-007","t":"天使投资","cid":"13d","p":1,"kind":"概念","exam":["2025名解"],"alias":["天使投资","天使投资人","天使轮"],"one":"富人个人对初创企业的早期权益投资，处在创业融资链最前端。","ans":"天使投资是**一种早期权益投资，指富有的个人或机构出资，对具有发展潜力的初创企业进行直接投资并换取股权**。“天使”一词**源于20世纪初美国纽约百老汇，指资助有风险的原创演出的富人**。天使投资**多发生在企业种子期或初创期，金额较小、风险高、潜在回报高**，投资人除资金外还常提供**经验、人脉和管理指导**。它处于**创业融资链的最前端，之后依次是风险投资（VC）、私募股权投资（PE）和首次公开募股（IPO）**，对鼓励创新创业、促进科技成果转化有重要作用。","pts":["早期权益投资，个人出资投初创企业换股权","百老汇起源，高风险高回报，“资金+经验”","融资链最前端：天使→VC→PE→IPO"],"mem":"融资链口诀“天、风、私、上”：天使、风投、私募、上市（IPO）。画面：百老汇一个没钱排戏的剧团，台下的富人像“天使”一样出手相救，后来这个词用到了初创企业。关键词“早、小、险、帮”：早期、金额小、风险高、帮忙。","mix":"天使投资（种子期、个人）与风险投资（VC，成长期、机构）、私募股权（PE，成熟期）按阶段区分；天使投资是股权投资，不属于借贷。","mcq":[{"q":"创业企业融资链中最前端的是","o":["首次公开募股","私募股权投资","风险投资","天使投资"],"a":3,"w":"天使投资多在种子期或初创期，在VC、PE、IPO之前。"},{"q":"“天使投资”一词最早源于","o":["美国纽约百老汇","伦敦证券交易所","华尔街","硅谷"],"a":0,"w":"源于20世纪初百老汇，指资助有风险的原创演出的富人。"}],"rel":[{"t":"风险投资","n":"天使之后的融资阶段"},{"t":"首次公开募股（IPO）","n":"融资链终点"},{"t":"创业板","n":"成长型企业上市板块"},{"t":"科创板","n":"硬科技企业上市板块"}],"more":"2025届名解考过；同组材料为大学生创新大赛，“数智技术”“天使投资”都来自创业语境。"},{"id":"b13-008","t":"新质生产力","cid":"13e","p":1,"kind":"概念","alias":["新质生产力"],"one":"创新起主导作用、具有高科技高效能高质量特征的先进生产力质态。","ans":"新质生产力是**2023年9月习近平在黑龙江考察时首次提出、2024年1月中央政治局集体学习时系统阐述**的概念，指**创新起主导作用，摆脱传统经济增长方式和生产力发展路径，具有高科技、高效能、高质量特征**的先进生产力质态。它由技术革命性突破、生产要素创新性配置、产业深度转型升级催生，**以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵，以全要素生产率大幅提升为核心标志**。发展新质生产力要**因地制宜**，既培育人工智能、量子科技、生物制造等未来产业，也用新技术改造提升传统产业。","pts":["2023年提出，2024年系统阐述","创新主导，高科技高效能高质量","催生因素、基本内涵、核心标志、因地制宜"],"mem":"三个“新”串联：技术新突破、要素新配置、产业新升级（催生）；核心标志是全要素生产率提升。年份挂钩：2023年9月黑龙江，2024年1月中央政治局集体学习，先后顺序按“先提出后阐述”。","mix":"新质生产力不是抛弃传统产业，要求用新技术改造传统产业；它强调“新”与“质”，别写成单纯的“高科技产业”。","mcq":[{"q":"新质生产力首次提出的地点是","o":["黑龙江","浙江","上海","广东"],"a":0,"w":"2023年9月习近平在黑龙江考察时首次提出。"},{"q":"新质生产力的核心标志是","o":["国内生产总值增速","全要素生产率大幅提升","出口规模","城镇化率"],"a":1,"w":"以全要素生产率大幅提升为核心标志。"}],"rel":[{"t":"数智技术","n":"重要技术支撑"},{"t":"“人工智能+”行动","n":"培育未来产业的抓手"},{"t":"高质量发展","n":"新质生产力是其内在要求"},{"t":"数字经济","n":"同属新经济形态"}],"more":"“高质量发展”是新时代首要任务，新质生产力是推动高质量发展的内在要求和重要着力点。","exam":[]},{"id":"b13-009","t":"“人工智能+”行动","cid":"13e","p":1,"kind":"时事","alias":["人工智能+","AI+行动","“人工智能+”"],"one":"推动人工智能与经济社会各领域深度融合的国家行动。","ans":"“人工智能+”行动是**推动人工智能与经济社会各领域深度融合的国家行动**。**2024年政府工作报告首次提出开展“人工智能+”行动**，**2025年8月国务院印发《关于深入实施“人工智能+”行动的意见》**，部署**科学技术、产业发展、消费提质、民生福祉、治理能力、全球合作**六大重点行动，提出到2027年新一代智能终端、智能体等应用普及率超过70%，到2035年全面步入智能经济和智能社会发展新阶段。它以应用为导向，推动人工智能从技术突破走向规模化应用，同时强调**安全可控、以人为本**。","pts":["AI与各领域融合的国家行动","2024年提出，2025年国务院意见，六大行动","2027年普及率超70%，2035年智能经济"],"mem":"六大行动按“科、产、消、民、治、全”记：科学技术、产业发展、消费提质、民生福祉、治理能力、全球合作。时间轴三个节点：2024提出、2025出意见、2027与2035两个目标。","mix":"“互联网+”是2015年政府工作报告提出的行动计划，“人工智能+”是2024年提出，两者别混；“人工智能+”是应用行动，《新一代人工智能发展规划》（2017）是更早的总体规划。","mcq":[{"q":"“人工智能+”行动首次写入政府工作报告是在","o":["2024年","2015年","2017年","2022年"],"a":0,"w":"2024年政府工作报告首次提出开展“人工智能+”行动。"},{"q":"下列不属于“人工智能+”六大重点行动的是","o":["科学技术","消费提质","民生福祉","土地改革"],"a":3,"w":"六大行动为科学技术、产业发展、消费提质、民生福祉、治理能力、全球合作。"}],"rel":[{"t":"新质生产力","n":"培育未来产业的抓手"},{"t":"《新一代人工智能发展规划》","n":"更早的国家总体规划"},{"t":"人工智能治理","n":"强调安全可控"},{"t":"数字中国","n":"同属国家数字战略"}],"more":"2025年8月《关于深入实施“人工智能+”行动的意见》：到2027年新一代智能终端、智能体等应用普及率超过70%；到2035年全面步入智能经济和智能社会发展新阶段。","exam":[]},{"id":"b13-010","t":"具身智能","cid":"13e","p":2,"kind":"概念","alias":["Embodied AI","具身人工智能"],"one":"依托物理载体与环境交互学习的智能形态，2025年首次写入政府工作报告。","ans":"具身智能指**智能系统依托机器人等物理载体，通过感知、决策与行动在与真实世界交互中学习适应**的智能形态。区别于“离身”智能，它强调**“感知—决策—行动”闭环**，载体含**人形机器人、机械臂与自动驾驶汽车**。**2025年政府工作报告首次将其列为未来产业**，它在制造、养老与救援领域前景广阔，亦面临安全与伦理挑战。","pts":["依托物理载体、与真实世界交互学习的智能","强调感知—决策—行动闭环，载体不限人形","2025年政府工作报告首列为未来产业"],"mem":"拆字直记：**“具身”=具备身体**。大脑（大模型）装进身体（机器人或汽车），形成**“看环境→想办法→动手做”**的闭环，走出屏幕进入物理世界。","mix":"常见误区是把具身智能等同于人形机器人；人形机器人只是其代表性载体之一，工业机械臂、自动驾驶汽车、特种巡检机器人等同样属于具身智能。","mcq":[{"q":"2025年我国《政府工作报告》首次列为重点培育未来产业、强调智能系统依托物理载体与真实世界交互学习的技术方向是","o":["具身智能","区块链","云计算","信息茧房"],"a":0,"w":"2025年《政府工作报告》提出培育生物制造、量子科技、具身智能、6G等未来产业。"}],"rel":[{"t":"未来产业","n":"2025年列为培育的未来产业"},{"t":"“人工智能+”行动","n":"AI赋能实体经济国家行动"},{"t":"智能体（AI Agent）","n":"软件与物理世界的智能对照"},{"t":"脑机接口","n":"同属前沿未来产业领域"}],"more":"2025年《政府工作报告》原文表述：“培育生物制造、量子科技、具身智能、6G等未来产业。”","exam":[]},{"id":"b13-011","t":"人工智能治理","cid":"13g","p":1,"kind":"概念","alias":["人工智能治理","AI治理","人工智能全球治理"],"one":"围绕AI研发、部署和使用的风险与责任，建立规则与协调机制。","ans":"人工智能治理是指**围绕人工智能研发、部署和使用中的风险、责任和公共利益，建立规则、标准和协调机制的过程**，涉及安全评估、数据和隐私保护、算法透明与公平、内容可信和人类监督等。我国陆续施行**《生成式人工智能服务管理暂行办法》（2023）、《人工智能生成合成内容标识办法》（2025）**等规定；国际上，**2023年提出《全球人工智能治理倡议》**，**2025年世界人工智能大会发布《人工智能全球治理行动计划》**，**2026年7月世界人工智能合作组织协定在上海签署，总部设在上海**。良好治理应坚持**以人为本、智能向善，统筹发展与安全**。","pts":["规则、标准、协调机制，防范风险","国内：生成式AI办法、标识办法","国际：全球倡议、行动计划、世界人工智能合作组织"],"mem":"三层记忆：国内规章（2023暂行办法、2025标识办法）、全球倡议（2023）、国际组织（2025行动计划、2026合作组织落户上海）。原则八个字“以人为本、智能向善”，再加“统筹发展与安全”。","mix":"欧盟《人工智能法》是欧盟立法，不属于中国规章；《全球人工智能治理倡议》（2023，中国提出）与《人工智能全球治理行动计划》（2025，世界人工智能大会）是两个文件。","mcq":[{"q":"2023年中国提出的全球层面治理文件是","o":["《全球人工智能治理倡议》","《人工智能法》","《数据安全法》","《人工智能全球治理行动计划》"],"a":0,"w":"《全球人工智能治理倡议》2023年提出；行动计划是2025年。"},{"q":"世界人工智能合作组织总部设在","o":["北京","日内瓦","深圳","上海"],"a":3,"w":"2026年7月协定在上海签署，总部设在上海。"}],"rel":[{"t":"《生成式人工智能服务管理暂行办法》","n":"国内规章"},{"t":"《人工智能生成合成内容标识办法》","n":"国内规章"},{"t":"世界人工智能合作组织","n":"国际机构"},{"t":"欧盟《人工智能法》","n":"国际立法对照"},{"t":"人类命运共同体","n":"全球治理理念"}],"more":"2023年《全球人工智能治理倡议》；2025年《人工智能全球治理行动计划》；2026年7月世界人工智能合作组织协定在上海签署。","exam":[]},{"id":"b13-012","t":"数据要素","cid":"13e","p":2,"kind":"概念","alias":["数据生产要素","数据二十条"],"one":"作为新型生产要素参与价值创造的数据，2019年首列为生产要素。","ans":"数据要素指**数据作为新型生产要素，经加工利用参与生产经营与社会治理并创造价值的属性**。**2019年十九届四中全会首将数据列为生产要素**；**2022年12月“数据二十条”**确立产权**“三权分置”**等四项制度；**2023年组建国家数据局**。数据具**可复制、非竞争、边际成本低**特点，须在保障安全与隐私前提下流通利用。","pts":["数据作为新型生产要素创造价值的属性","19年列为要素、22年数据二十条、23年数据局","可复制、非竞争、边际成本低，须守安全底线"],"mem":"时间三步走：**19定身份**（十九届四中全会列为要素）→**22立规矩**（“数据二十条”定产权“三权分置”）→**23设管家**（组建国家数据局）。","mix":"“数据二十条”确立的产权**“三权分置”**指数据资源持有权、数据加工使用权、数据产品经营权，勿与农村土地承包经营权“三权分置”（所有权、承包权、经营权）混淆。","mcq":[{"q":"我国首次将数据增列为与劳动、资本、土地等并列的生产要素是在哪次会议上","o":["党的十八届三中全会","党的十九大","党的十九届四中全会","党的二十届三中全会"],"a":2,"w":"2019年党的十九届四中全会首次将数据列为生产要素。"}],"rel":[{"t":"数字中国","n":"数据资源体系是其基础之一"},{"t":"数字经济","n":"以数据资源为关键生产要素"},{"t":"《数据安全法》","n":"数据流通的安全法律保障"},{"t":"跨境数据流动","n":"数据要素国际规则议题"}],"more":"“数据二十条”四大制度：数据产权（资源持有权、加工使用权、产品经营权“三权分置”）、流通交易、收益分配、安全治理。\n国家数据局于2023年10月25日正式挂牌。","exam":[]},{"id":"b13-013","t":"数字中国","cid":"13e","p":2,"kind":"概念","alias":["数字中国建设","2522框架"],"one":"以数字技术推动“五位一体”变革的国家布局，按“2522”框架推进。","ans":"数字中国是**以数字技术推动“五位一体”全面变革的国家战略布局**。**2015年第二届世界互联网大会首提、2017年党的十九大写入报告**，**2023年2月印发《数字中国建设整体布局规划》**，确立**“2522”框架**：夯实基础设施与数据资源两大基础，推进数字技术与“五位一体”融合，强化技术创新与安全屏障两大能力，优化国内国际两个环境，是**中国式现代化的重要引擎**。","pts":["以数字技术推动全面变革的国家战略布局","2015年首提、2017年十九大写入报告，2023年印发整体布局规划","“2522”框架：两大基础、五位融合、两能力两环境"],"mem":"数字口诀**“2522”**：**2基**（数字设施+数据资源）、**5融**（融入“五位一体”）、**2能**（技术创新+安全屏障）、**2境**（国内+国际环境）。记住**“基融能境”**四字顺序。","mix":"数字中国涵盖数字经济、数字政务、数字文化、数字社会和数字生态文明五个领域，外延大于仅聚焦产业与经济形态的“数字经济”。","mcq":[{"q":"2023年2月印发的《数字中国建设整体布局规划》确立了数字中国建设的整体框架，该框架简称为","o":["“1+N”框架","“2522”框架","“四梁八柱”框架","“三步走”框架"],"a":1,"w":"《数字中国建设整体布局规划》按照“2522”整体框架进行布局。"}],"rel":[{"t":"数据要素","n":"两大基础之一的数据资源"},{"t":"数字经济","n":"数字中国的核心经济领域"},{"t":"“五位一体”","n":"“2522”深度融合对象"},{"t":"网络强国","n":"同在十九大并提的建设目标"}],"more":"规划目标：到2025年基本形成横向打通、纵向贯通、协调有力的一体化推进格局；到2035年数字化发展水平进入世界前列。","exam":[]},{"id":"b13-014","t":"网络生态治理","cid":"13g","p":1,"kind":"概念","alias":["网络生态治理","清朗行动","网络空间治理"],"one":"多元主体共同治理网络信息内容环境，营造清朗网络空间。","ans":"网络生态治理是**政府、平台、行业组织和网民等多元主体，对网络信息内容的生产、传播和使用环境进行综合治理**，以营造清朗网络空间的活动。其对象包括网络谣言、网络暴力、低俗信息、流量造假、算法滥用和人工智能生成内容乱象等。我国施行**《网络信息内容生态治理规定》（2020）、《网络暴力信息治理规定》（2024）、《人工智能生成合成内容标识办法》（2025）**，网信部门持续开展**“清朗”系列专项行动**，压实平台主体责任。网络生态治理要**依法管网与提升网民媒介素养相结合**，维护公民合法权益和健康的公共讨论。","pts":["多元主体综合治理网络环境","对象：谣言、网暴、算法滥用、AI乱象","法规、清朗行动、平台责任、网民素养"],"mem":"三个年份三个规定：2020生态、2024网暴、2025标识，“二〇生态、二四网暴、二五标识”。主体“政、平、行、民”：政府、平台、行业组织、网民。2026作文已考“网络乱象与网络治理”。","mix":"《网络安全法》（2016年通过）重点是网络安全，网络生态治理规定重点是内容生态；“清朗”由国家网信办牵头，不是公安部专项行动。","mcq":[{"q":"下列规定中，2024年出台的是","o":["《网络信息内容生态治理规定》","《网络暴力信息治理规定》","《人工智能生成合成内容标识办法》","《生成式人工智能服务管理暂行办法》"],"a":1,"w":"《网络暴力信息治理规定》2024年；其余分别为2020、2025、2023。"},{"q":"网信部门持续开展的网络治理专项行动称为","o":["“净网”行动","“蓝天”行动","“护苗”行动","“清朗”系列行动"],"a":3,"w":"“清朗”系列专项行动由网信部门牵头。"}],"rel":[{"t":"网络暴力治理","n":"重点治理对象"},{"t":"算法治理","n":"算法滥用治理"},{"t":"信息茧房","n":"算法带来的问题"},{"t":"《网络安全法》","n":"上位法律"},{"t":"网络强国","n":"战略目标"}],"more":"2026年作文题“网络乱象与网络治理”。","exam":[]},{"id":"b13-015","t":"“十五五”规划","cid":"13c","p":1,"kind":"时事","alias":["十五五","十五五规划","第十五个五年规划"],"one":"2026至2030年国民经济和社会发展规划，2026年3月批准。","ans":"“十五五”规划即**《中华人民共和国国民经济和社会发展第十五个五年规划纲要》，规划期为2026年至2030年**。**2025年10月党的二十届四中全会审议通过“十五五”规划建议**，**2026年3月12日十四届全国人大四次会议批准规划纲要**。“十五五”时期是**基本实现社会主义现代化夯实基础、全面发力的关键时期**，主要目标包括高质量发展取得显著成效、科技自立自强水平大幅提高、进一步全面深化改革取得新突破等。纲要提出**16个“强国”建设目标、20项主要指标和109项重大工程**。","pts":["2026至2030年，四中全会建议、人大批准","基本实现社会主义现代化夯实基础的关键期","七方面主要目标，16个强国、20项指标、109项工程"],"mem":"时间链：2025年10月四中全会提“建议”→2026年3月人大批“纲要”，先建议后纲要。数字“16、20、109”：16个强国，20项指标，109项工程。位置：2035基本实现现代化的路上，十五五是“夯实基础、全面发力”。","mix":"“十四五”是2021至2025年，“十五五”是2026至2030年；四中全会通过的是“建议”，全国人大批准的才是“纲要”。","mcq":[{"q":"“十五五”规划的规划期是","o":["2025至2029年","2027至2031年","2026至2030年","2021至2025年"],"a":2,"w":"2026至2030年；2021至2025年是“十四五”。"},{"q":"“十五五”规划建议审议通过于","o":["二十届三中全会","二十届四中全会","二十届五中全会","十九届六中全会"],"a":1,"w":"2025年10月二十届四中全会。"}],"rel":[{"t":"五年规划","n":"规划体系"},{"t":"二十届四中全会","n":"审议通过建议"},{"t":"新质生产力","n":"“十五五”重点方向"},{"t":"“两步走”战略安排","n":"迈向2035基本实现现代化"}],"more":"2025年10月二十届四中全会审议通过建议；2026年3月12日十四届全国人大四次会议批准纲要。\n纲要提出16个“强国”建设目标、20项主要指标、109项重大工程。","exam":[]},{"id":"b13-016","t":"中国式现代化","cid":"13b","p":1,"kind":"概念","alias":["中国式现代化"],"one":"党领导的社会主义现代化，二十大系统阐述，有五个特征。","ans":"中国式现代化是**中国共产党领导的社会主义现代化**，**2022年党的二十大报告系统阐述**，既有各国现代化的共同特征，更有基于自身国情的中国特色。它有**五个特征：人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路**。战略安排是**到2035年基本实现社会主义现代化，到本世纪中叶建成社会主义现代化强国**。中国式现代化**打破了“现代化等于西方化”的迷思**，为发展中国家提供了新选择。","pts":["党领导的社会主义现代化，二十大阐述","五个特征","2035基本实现，本世纪中叶建成强国"],"mem":"五个特征首字串联“人、共、物、人、和”：人口、共同富裕、物质精神、人与自然、和平。画面：一个人口巨大的国家，大家一起富，物质精神双丰收，青山绿水，不称霸。战略安排对应“两步走”：2035、本世纪中叶。","mix":"“中国式现代化”2021年建党百年讲话已有表述，2022年二十大才系统概括五个特征；2024年二十届三中全会《决定》以“推进中国式现代化”为主题。","mcq":[{"q":"下列不属于中国式现代化五个特征的是","o":["人口规模巨大","高度城市化","全体人民共同富裕","走和平发展道路"],"a":1,"w":"五个特征中没有“高度城市化”。"},{"q":"中国式现代化被系统阐述于","o":["十八大报告","十九大报告","二十届三中全会","二十大报告"],"a":3,"w":"2022年二十大报告。"}],"rel":[{"t":"中国式现代化五个特征","n":"五个特征逐项"},{"t":"“两步走”战略安排","n":"战略安排"},{"t":"共同富裕","n":"特征之一"},{"t":"二十届三中全会","n":"以推进其为主题"}],"more":"二十大报告：以中国式现代化全面推进中华民族伟大复兴。","exam":[]},{"id":"b13-017","t":"二十届五中全会","cid":"13a","p":1,"kind":"时事","alias":["二十届五中全会","五中全会"],"one":"2026年10月召开，通过全面从严治党《决定》，定二十一大2027年下半年召开。","ans":"二十届五中全会是**中国共产党第二十届中央委员会第五次全体会议**，**2026年10月26日至29日在北京举行**。会议**审议通过《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》**，要求**坚持严的基调不动摇**，**一体推进不敢腐、不能腐、不想腐**。公报写入**“习近平党建思想”**，该思想已在2026年6月15日全国党建工作座谈会上系统阐述，概括为“十四个坚持”。会议还宣布**党的二十一大于2027年下半年在北京召开**。","pts":["2026年10月26至29日，通过全面从严治党《决定》","严的基调不动摇，一体推进“三不腐”","写入习近平党建思想；二十一大2027年下半年召开"],"mem":"顺序记：四中全会（2025年10月）管“十五五”建议，管发展；五中全会（2026年10月）管全面从严治党，管党自身。一个管“做什么”，一个管“谁来做”。选择题把“从严治党决定”挂在五中全会，“十五五建议”挂在四中全会，不要对调。","mix":"二十届三中全会（2024年7月）是改革《决定》，四中全会（2025年10月）是“十五五”规划建议，五中全会才是全面从严治党《决定》。","mcq":[{"q":"2026年10月二十届五中全会审议通过的文件是","o":["关于持之以恒推进全面从严治党若干重大问题的决定","关于进一步全面深化改革的决定","关于制定“十五五”规划的建议","关于党的百年奋斗重大成就和历史经验的决议"],"a":0,"w":"前三项分别属于二十届三中全会、四中全会、十九届六中全会。"},{"q":"二十届五中全会宣布党的二十一大召开的时间是","o":["2027年上半年","2027年下半年","2028年上半年","2026年年底"],"a":1,"w":"二十一大定于2027年下半年在北京召开。"}],"rel":[{"t":"二十届四中全会","n":"上一次全会，“十五五”建议"},{"t":"全面从严治党","n":"《决定》的主题"},{"t":"习近平党建思想","n":"公报写入"},{"t":"二十届三中全会","n":"近年中央文件选择题来源"}],"more":"2026年6月15日全国党建工作座谈会系统阐述习近平党建思想，概括为“十四个坚持”。\n近年448选择题各考过一份中央文件：2023届“新时代三件大事”，2024届第三个历史决议，2025届二十届三中全会决定。","exam":[]},{"id":"b13-018","t":"上海合作组织","cid":"13h","p":1,"kind":"制度","exam":["2019名解"],"alias":["上合组织","上合","上海合作组织","SCO"],"one":"2001年在上海成立的政府间国际组织，倡导“上海精神”。","ans":"上海合作组织是**2001年6月15日在上海成立的永久性政府间国际组织**，前身是1996年起的**“上海五国”会晤机制**，**创始成员国为中国、俄罗斯、哈萨克斯坦、吉尔吉斯斯坦、塔吉克斯坦和乌兹别克斯坦**，后有印度、巴基斯坦（2017）、伊朗（2023）、白俄罗斯（2024）加入，现有10个成员国。其宗旨是加强互信与睦邻友好，在安全、经济、人文等领域合作，倡导**“互信、互利、平等、协商、尊重多样文明、谋求共同发展”的“上海精神”**。**秘书处设在北京**，2025年峰会在天津举行。","pts":["2001年在上海成立，前身上海五国","创始六国，现有10个成员国","上海精神；秘书处在北京"],"mem":"创始六国口诀“中俄加中亚三国再加乌”：中、俄、哈、吉、塔、乌。扩员年份“17印巴、23伊、24白”。五国变六国就是2001年加入乌兹别克斯坦。2026年是成立25周年。","mix":"“上海五国”不含乌兹别克斯坦；上合成立在上海，秘书处却设在北京；印度、巴基斯坦2017年同时加入，伊朗2023年、白俄罗斯2024年加入。","mcq":[{"q":"2001年上海合作组织成立时新加入“上海五国”的是","o":["印度","巴基斯坦","伊朗","乌兹别克斯坦"],"a":3,"w":"上海五国扩为六国，新增乌兹别克斯坦。"},{"q":"上海合作组织秘书处所在地是","o":["上海","北京","塔什干","莫斯科"],"a":1,"w":"秘书处设在北京；塔什干是地区反恐怖机构所在地。"}],"rel":[{"t":"“上海五国”机制","n":"前身"},{"t":"“上海精神”","n":"核心理念"},{"t":"2025年上海合作组织天津峰会","n":"最近一次峰会"},{"t":"2026年上海合作组织比什凯克峰会","n":"2026年峰会"}],"more":"2019年名解真题；2026年6月15日为成立25周年。"},{"id":"b13-019","t":"新时代三件大事","cid":"13a","p":1,"kind":"合称","exam":["2023选择"],"alias":["三件大事","新时代三大成就","党的二十大三件大事"],"one":"二十大报告概括：建党百年、进入新时代、全面建成小康社会。","ans":"新时代三件大事是**2022年党的二十大报告对新时代十年的概括**，指**迎来中国共产党成立一百周年**、**中国特色社会主义进入新时代**、**完成脱贫攻坚和全面建成小康社会，实现第一个百年奋斗目标**。三件大事对应2021年建党百年庆祝大会、十九大作出的新时代判断，以及2021年宣布的脱贫攻坚胜利和全面小康。报告称它们是**党和国家事业发展进程中具有里程碑意义的大事**，为开启全面建设社会主义现代化国家新征程奠定了基础。","pts":["迎来建党一百周年","中国特色社会主义进入新时代","完成脱贫攻坚、全面建成小康社会"],"members":[["迎来建党一百周年","2021年，庆祝大会宣布一个百年目标实现"],["中国特色社会主义进入新时代","十九大作出的政治判断"],["完成脱贫攻坚、全面建成小康社会","第一个百年奋斗目标"]],"mem":"首字串联“党、时、小”：建党、时代、小康。按报告列举顺序记：建党百年、进入新时代、脱贫攻坚和全面小康。选择题常把“建成社会主义现代化强国”作干扰项，那是第二个百年目标，还没发生。","mix":"“全面建成社会主义现代化强国”属于第二个百年奋斗目标，不属于三件大事；2023选择“中国新时代三大成就”指的就是二十大报告的这“三件大事”。","mcq":[{"q":"党的二十大报告概括的“新时代三件大事”不包括","o":["迎来中国共产党成立一百周年","建成社会主义现代化强国","中国特色社会主义进入新时代","完成脱贫攻坚、全面建成小康社会"],"a":1,"w":"建成现代化强国是第二个百年目标，尚在进程中。"},{"q":"“新时代三件大事”出自","o":["党的二十大报告","党的十九大报告","十九届六中全会决议","二十届三中全会决定"],"a":0,"w":"二十大报告回顾新时代十年时概括。"}],"rel":[{"t":"“两个一百年”奋斗目标","n":"第一个目标已实现"},{"t":"精准扶贫与脱贫攻坚","n":"第三件大事的内容"},{"t":"党的三个历史决议","n":"同属近年中央文件考点"},{"t":"中国式现代化","n":"同为二十大报告核心表述"}],"more":"2023届选择题考过。"},{"id":"b13-021","t":"全过程人民民主","cid":"13b","p":2,"kind":"概念","alias":["全过程民主"],"one":"社会主义民主政治本质属性，2019年习近平在上海长宁区虹桥街道首次提出。","ans":"全过程人民民主是**社会主义民主政治的本质属性**，也是中国式现代化本质要求之一。**2019年11月2日**，习近平在**上海市长宁区虹桥街道**考察基层立法联系点时，首次提出**“人民民主是一种全过程的民主”**。它贯通民主选举、协商、决策、管理、监督全链条，实现过程与成果民主统一，是**最广泛、最真实、最管用**的民主，拓展了人类政治文明新形态。","pts":["2019年11月习近平在上海长宁区虹桥街道首次提出","社会主义民主政治的本质属性，贯通五大民主环节","最广泛、最真实、最管用，上海重要本土时政考点"],"mem":"上海本土坐标记忆：“2019长宁虹桥立法点，五个民主连成线”（选举、协商、决策、管理、监督）。记住关键词“全链条、全方位、全覆盖”与“最广泛、最真实、最管用”。","mix":"首提地点精确到**上海市长宁区虹桥街道**（全国人大常委会法工委基层立法联系点），选择题常以浦东陆家嘴、黄浦区、徐汇区等上海地名作干扰项。","mcq":[{"q":"2019年11月习近平总书记首次提出“人民民主是一种全过程的民主”的地点是","o":["上海浦东陆家嘴","上海黄浦区中共一大会址","上海长宁区虹桥街道","上海静安区临汾路街道"],"a":2,"w":"2019年11月2日，习近平在上海市长宁区虹桥街道古北市民中心考察时首次提出“人民民主是一种全过程的民主”。"}],"rel":[{"t":"人民代表大会制度","n":"实现全过程民主的制度载体"},{"t":"窑洞对与“两个答案”","n":"人民监督政府的新时代发展"},{"t":"中国式现代化","n":"本质要求之一"},{"t":"雅典民主","n":"中西民主形态的历史对照"}],"more":"关键年份：2019年11月2日上海虹桥街道首提；2021年7月1日建党百年大会强调“发展全过程人民民主”；2022年二十大定位为“社会主义民主政治的本质属性”。","exam":[]},{"id":"b13-022","t":"新型举国体制","cid":"13f","p":2,"kind":"制度","alias":["关键核心技术攻关新型举国体制"],"one":"将社会主义集中力量办大事优势与市场机制结合、攻关关键核心技术的制度。","ans":"新型举国体制是**我国科技创新领域的重大制度创新**，指**在社会主义市场经济条件下，将国家战略统筹、集中力量办大事优势与市场机制有机结合**的攻关体系。党的二十大明确提出**健全关键核心技术攻关新型举国体制**，突出**企业创新主体地位、产学研协同与开放合作**。它为突破“卡脖子”技术、支撑航天与芯片等国家重大工程提供了制度保障。","pts":["集中力量办大事与市场机制有机结合的科创体制","二十大明确健全关键核心技术攻关新型举国体制","突出政府统筹与企业创新主体协同，破解卡脖子难题"],"mem":"拆字抓“新”字：**旧举国体制**=纯靠行政计划调动（如“两弹一星”年代）；**新型举国体制**=**有效市场 + 有为政府**，国家定方向搭台，企业与高校市场化协同攻关。","mix":"常见误解是把新型举国体制等同于回归计划经济或排斥民营企业；实际上它强调发挥市场机制和科技领军企业作用，并坚持高水平国际科技合作。","mcq":[{"q":"相较于计划经济时期的传统举国体制，“新型举国体制”最核心的特征在于","o":["完全取消市场机制，仅由行政指令配置科研资源","把集中力量办大事的制度优势与市场机制有机结合","只允许国有科研院所参与关键核心技术攻关","仅适用于体育竞技与文教宣传领域"],"a":1,"w":"新型举国体制是在社会主义市场经济条件下，将有为政府与有效市场结合以攻关关键核心技术。"}],"rel":[{"t":"社会主义市场经济体制","n":"新型举国体制运行的制度基础"},{"t":"“863计划”","n":"改革开放后高技术攻关先声"},{"t":"两弹一星精神","n":"早期集中攻关的历史传承"},{"t":"新质生产力","n":"关键核心技术突破赋能新质生产力"}],"more":"关键节点：2022年9月中央深改委第二十七次会议审议通过《关于健全社会主义市场经济条件下关键核心技术攻关新型举国体制的意见》。","exam":[]},{"id":"b13-023","t":"共同富裕","cid":"13b","p":2,"kind":"概念","alias":["全体人民共同富裕"],"one":"社会主义本质要求与中国式现代化重要特征，强调共建共享、逐步实现，非平均主义。","ans":"共同富裕是**社会主义的本质要求**，也是**中国式现代化的重要特征**。它指**全体人民**通过辛勤劳动和相互帮助共同迈向物质与精神双富裕，旨在缩小城乡区域差距、消除两极分化。实现路径上以高质量发展做大“蛋糕”，借三次分配协调分好“蛋糕”，坚持**分阶段逐步推进**，并非**同时同步同等富裕**。2021年中央支持**浙江**建设示范区，为全国探路。","pts":["社会主义本质要求，中国式现代化五个特征之一","全体人民富裕，物质与精神双富裕，非同时同步同等富裕","三次分配协同发力，2021年浙江建共同富裕示范区"],"mem":"“做大蛋糕 + 分好蛋糕”逻辑线：高质量发展做大蛋糕 → 三次分配（市场、政府税收社保、公益慈善）分好蛋糕 → 浙江先行示范。牢记“三非”：非同时、非同步、非同等。","mix":"共同富裕绝不等于“劫富济贫”或平均主义，也并非同时同步同等富裕；全国首个省级共同富裕示范区是**浙江**（2021年），勿与广东、江苏混淆。","mcq":[{"q":"2021年中共中央、国务院发文支持高质量发展建设共同富裕示范区的省份是","o":["广东省","浙江省","江苏省","福建省"],"a":1,"w":"2021年中共中央、国务院印发《关于支持浙江高质量发展建设共同富裕示范区的意见》，支持浙江率先探路。"}],"rel":[{"t":"中国式现代化五个特征","n":"五大特征中的第二条"},{"t":"精准扶贫与脱贫攻坚","n":"迈向共同富裕的坚实基础"},{"t":"基尼系数","n":"衡量收入分配差距的指标"},{"t":"恩格尔系数","n":"衡量居民生活富裕程度"}],"more":"关键节点：1992年邓小平南方谈话将“最终达到共同富裕”写入社会主义本质；2021年5月印发、6月公布支持浙江建设共同富裕示范区的意见。","exam":[]},{"id":"b13-024","t":"绿色转型","cid":"13c","p":3,"kind":"概念","alias":["全面绿色转型","绿色低碳转型"],"one":"产业、能源、交通、消费向节约低碳循环转变的过程，以“双碳”为核心目标。","ans":"绿色转型指**产业、能源、交通、消费**等领域向**节约、低碳、循环**转变的系统过程。它以**“双碳”**为核心目标，协同推进**降碳、减污、扩绿、增长**，涵盖污染防治与生态保护。2024年中央首次作全面绿色转型部署，赋能高质量发展。","pts":["产业能源交通消费向低碳循环转变","以“双碳”为核心目标，协同降碳减污","2024年中央首次作全面绿色转型系统部署"],"mem":"四字抓手记“降减扩增”：降碳、减污、扩绿、增长，串联起能源、产业、交通和消费四大转型领域。","mix":"绿色转型涵盖节能减排、污染防治、生态修复和循环经济，范围大于单一的碳减排或环保治理。","mcq":[{"q":"2024年中共中央、国务院印发关于加快经济社会发展全面绿色转型的意见，明确以哪项目标为引领","o":["工业化目标","城镇化目标","对外开放目标","碳达峰碳中和目标"],"a":3,"w":"全面绿色转型以碳达峰碳中和（“双碳”）工作为引领，协同推进降碳、减污、扩绿、增长。"}],"rel":[{"t":"碳达峰碳中和","n":"绿色转型的核心引领目标"},{"t":"“绿水青山就是金山银山”","n":"绿色发展的理念源头"},{"t":"高质量发展","n":"绿色是高质量发展的底色"},{"t":"生态环境法典","n":"绿色转型的法治保障"}],"more":"2024年7月《中共中央 国务院关于加快经济社会发展全面绿色转型的意见》提出，到2030年非化石能源消费比重提高到25%左右，到2035年美丽中国目标基本实现。","exam":[]},{"id":"b13-025","t":"《生成式人工智能服务管理暂行办法》","cid":"13g","p":2,"kind":"制度","alias":["生成式AI暂行办法","AIGC暂行办法"],"one":"2023年8月15日起施行，我国第一部专门规范生成式人工智能服务的部门规章。","ans":"《生成式人工智能服务管理暂行办法》由**国家网信办等七部门**于2023年7月联合公布，自**2023年8月15日起施行**，是**我国第一部专门规范生成式AI的部门规章**。办法坚持**发展和安全并重**，实行**包容审慎和分类分级监管**，对训练数据合法性、知识产权保护、内容标识及安全评估备案作出规定，为国内大模型规范发展确立了制度框架。","pts":["国家网信办等七部门公布，2023年8月15日施行","我国第一部专门规范生成式AI的部门规章","确立发展与安全并重、包容审慎分类分级监管"],"mem":"时间链条记AI三规章：**2023年1月深度合成规定→2023年8月生成式AI暂行办法（七部门）→2025年9月内容标识办法（四部门）**，按时间顺序逐层补全监管拼图。","mix":"注意区分层级与时间：《暂行办法》是**部门规章**而非全国人大法律，2023年8月15日施行；欧盟《人工智能法》2024年8月1日生效，是全球首部全面监管AI的法律。","mcq":[{"q":"我国第一部专门规范生成式人工智能服务的部门规章《生成式人工智能服务管理暂行办法》自何时起施行","o":["2023年1月10日","2023年8月15日","2024年8月1日","2025年9月1日"],"a":1,"w":"该办法于2023年8月15日施行；其余三项分别为深度合成规定、欧盟AI法、标识办法日期。"}],"rel":[{"t":"《人工智能生成合成内容标识办法》","n":"2025年配套内容标识规章"},{"t":"深度合成与深度伪造","n":"2023年1月深度合成规定"},{"t":"ChatGPT与生成式人工智能（AIGC）","n":"规章直接规范的技术对象"},{"t":"人工智能治理","n":"国内AI治理体系的关键支柱"}],"more":"发布部门：国家网信办、国家发改委、教育部、科技部、工信部、公安部、国家广电总局（七部门），2023年7月13日公布。","exam":[]},{"id":"b13-026","t":"《人工智能生成合成内容标识办法》","cid":"13g","p":2,"kind":"制度","alias":["AI内容标识办法","生成合成内容标识办法"],"one":"2025年3月四部门发布、9月1日施行，确立显式标识与隐式标识双重制度。","ans":"《人工智能生成合成内容标识办法》由**国家网信办、工信部、公安部、广电总局四部门**于**2025年3月发布**，**2025年9月1日起施行**，属AI内容溯源治理核心规章。办法规定两类标识：**显式标识**以文字、声音、图形呈现，让**用户明显感知**；**隐式标识**以技术措施嵌入**文件数据**，便于核验溯源，并严禁恶意篡改删除，有力遏制虚假信息传播。","pts":["国家网信办等四部门2025年3月发、9月1日施行","显式标识让用户明显感知，隐式标识嵌入文件数据","禁止篡改隐匿标识，完善AI内容溯源治理"],"mem":"二元对照记法：**显式=给人看**（角标、文字、语音提示，一眼识破AI）；**隐式=给机器查**（藏在文件元数据里的“数字水印”，供平台与监管溯源）。时间：**25年3月发，9月开学日施行**。","mix":"《标识办法》针对文本、图片、音视频、虚拟场景等全形态AI生成合成内容，不仅约束AI生成服务提供者，也要求微博、短视频等**网络信息内容传播平台**核验并向用户显著提示。","mcq":[{"q":"2025年9月1日起施行的《人工智能生成合成内容标识办法》规定，采取技术措施添加在生成合成内容文件数据中、不易被用户明显感知但用于溯源核验的标识称为","o":["显式标识","强制备案号","数字签名","隐式标识"],"a":3,"w":"该办法将标识分为让用户明显感知的显式标识和嵌入文件数据的隐式标识。"}],"rel":[{"t":"《生成式人工智能服务管理暂行办法》","n":"2023年生成式AI基础规章"},{"t":"深度合成与深度伪造","n":"标识办法重点防范的伪造风险"},{"t":"人工智能治理","n":"2025年国内AI治理新规"},{"t":"算法治理","n":"同属平台与内容治理体系"}],"more":"发布日期：2025年3月14日四部门联合印发，配套强制性国家标准《网络安全技术 人工智能生成合成内容标识方法》（GB 45438-2025）。","exam":[]},{"id":"b13-027","t":"人工智能拟人化互动服务","cid":"13g","p":3,"kind":"时事","alias":["AI情感陪伴服务","拟人化互动服务"],"one":"模拟人格提供持续情感陪伴的AI服务，专项管理办法2026年7月15日施行。","ans":"人工智能拟人化互动服务指利用AI模拟人格、提供**持续情感互动（陪伴）**的服务。**《人工智能拟人化互动服务管理暂行办法》**自**2026年7月15日**施行，明确**AI身份提示与防沉迷**（普通客服除外），填补情感陪伴AI监管空白。","pts":["模拟人格提供持续情感互动的AI服务","专项暂行办法2026年7月15日起施行","明确AI身份提示与防沉迷；普通客服不适用"],"mem":"边界口诀“重情感、要提醒、防沉迷、除客服”：专门管AI伴侣和情感陪伴，连续聊超2小时要提醒，普通问答客服不算在内。","mix":"核心考点在于排除边界：提供智能客服、知识问答、工作助手、学习教育等服务，凡不涉及持续性情感互动的，均不适用该办法。","mcq":[{"q":"根据2026年7月15日起施行的《人工智能拟人化互动服务管理暂行办法》，下列哪类服务不适用该办法","o":["虚拟恋人情感陪伴应用","模拟逝者语音的持续情感慰藉服务","仅提供商品查询的普通智能问答客服","面向老年人的拟人化日常情感陪护AI"],"a":2,"w":"该办法针对持续性情感互动（陪伴）服务，不涉及持续情感互动的普通智能问答客服不适用。"}],"rel":[{"t":"《生成式人工智能服务管理暂行办法》","n":"2023年生成式AI基础规章"},{"t":"《人工智能生成合成内容标识办法》","n":"2025年内容标识配套规章"},{"t":"人工智能治理","n":"中国AI分级分类监管体系一环"},{"t":"科技伦理","n":"涉及人机情感依恋与伦理边界"}],"more":"办法由国家网信办、发改委、工信部、公安部、市场监管总局五部门于2026年4月10日联合公布，规定连续使用每超2小时须弹窗或对话提醒。","exam":[]},{"id":"b13-028","t":"基础大模型","cid":"13e","p":2,"kind":"概念","alias":["基础模型","Foundation Model","大模型"],"one":"在海量数据上预训练、可微调适配多种下游任务的通用人工智能模型。","ans":"基础大模型是当代人工智能的核心算法底座，指**在海量数据上通过自监督预训练、能适配多种下游任务的超大规模神经网络模型**。它多基于**Transformer架构**，涵盖**大语言模型与多模态模型**，可通过微调或提示快速迁移至问答、翻译与编程等场景。它改变了“一任务一模型”模式，正成为各行业智能化的**通用基础设施**。","pts":["在海量数据上预训练的超大规模通用模型","多基于Transformer，可适配多种下游任务","打破专有模型局限，成智能化通用基础设施"],"mem":"类比记法：基础大模型像**“通才本科生”**，先读海量资料打牢通识底子（预训练），毕业后稍加培训（微调）就能去写代码、做翻译、画图（适配下游任务）。","mix":"基础大模型是大类概念，包含大语言模型（处理文本为主）以及视觉、语音、多模态大模型；大语言模型（LLM）只是基础大模型中最具代表性的分支之一。","mcq":[{"q":"关于人工智能领域的“基础大模型”，下列说法最准确的是","o":["只能针对单一固定任务进行专门训练","不依赖大规模数据与算力支撑","仅能处理纯文本而无法扩展至多模态","在海量数据上预训练并能适配多种下游任务"],"a":3,"w":"基础大模型的核心特征是在海量数据上预训练，并通过迁移或微调适配多种下游任务。"}],"rel":[{"t":"大语言模型与Transformer","n":"核心架构与文本分支"},{"t":"ChatGPT与生成式人工智能（AIGC）","n":"基础大模型的代表应用"},{"t":"DeepSeek","n":"国产开源基础大模型代表"},{"t":"算力","n":"大模型训练推理的硬件底座"}],"more":"术语来源：2021年斯坦福大学以人为本人工智能研究院（HAI）正式推广“Foundation Models”（基础模型）这一概念。","exam":[]},{"id":"b13-029","t":"算力","cid":"13e","p":2,"kind":"概念","alias":["计算力","Computing Power"],"one":"计算系统处理数据的能力，与数据、算法并称人工智能与数字经济三大底座。","ans":"算力即计算力，指**计算系统处理数据的能力**，是数字经济时代的新型生产力。它以**芯片、服务器与数据中心集群**为基础，分通用算力、**智能算力与超算算力**三类，与数据、算法并称人工智能三大底座。我国于**2022年全面启动“东数西算”工程**统筹布局，算力基础设施已成为支撑大模型研发与产业数字化转型的关键引擎。","pts":["计算系统处理数据的能力，数字时代新型生产力","以芯片、服务器和数据中心为基础，分通算/智算/超算","与数据、算法并称AI底座，2022年启动东数西算"],"mem":"类比记法：工业时代看**电力**，数字时代看**算力**；AI三件套记成**“数据是食材、算法是菜谱、算力是灶火”**，缺一不可。","mix":"注意区分三类算力：日常业务用**通用算力**（CPU为主），大模型训练用**智能算力**（GPU/AI芯片为主），气象模拟与核物理计算用**超算算力**。","mcq":[{"q":"在人工智能三大核心底座中，以芯片、服务器和数据中心集群为硬件基础、衡量计算系统数据处理能力的是","o":["算力","算法","数据要素","带宽"],"a":0,"w":"数据、算力、算法是AI三大底座，算力指计算系统处理数据的能力。"}],"rel":[{"t":"“东数西算”工程","n":"国家算力东西协同布局工程"},{"t":"云计算","n":"按需提供算力的服务模式"},{"t":"基础大模型","n":"驱动智能算力爆发的应用"},{"t":"摩尔定律","n":"芯片算力增长的经验规律"}],"more":"常用度量单位：FLOPS（每秒浮点运算次数），智能算力规模常以EFLOPS（百亿亿次每秒）计。","exam":[]},{"id":"b13-030","t":"开源生态","cid":"13e","p":3,"kind":"概念","alias":["开源社区","开放源代码生态"],"one":"围绕开放代码、模型权重及开源许可证形成的全球开发者协作体系。","ans":"开源生态指围绕**开放代码、模型权重及开源许可证**形成的开发者协作体系。它依托Linux及**DeepSeek**等开源社区与大模型，打破技术壁垒、降低研发门槛，成为推动全球**软件与人工智能**协同创新的重要力量。","pts":["依托开放代码、模型权重与开源许可证","通过全球社区协作降低创新门槛","AI时代涵盖开源大模型权重与工具链"],"mem":"三要素公式“代码/权重 + 许可证 + 社区”：开源并非无规则免费，它靠开源许可证约定共享与二次开发权利，形成协作生态。","mix":"注意区分“开源”与“免费”：开源强调代码或权重公开并遵循特定许可证（如MIT、Apache），部分商业使用仍需遵守协议条款。","mcq":[{"q":"在大模型时代，下列哪一项不属于构成“开源生态”的核心要素","o":["开放源代码","开放模型权重","开源许可证","闭源专利垄断壁垒"],"a":3,"w":"开源生态围绕开放代码、模型权重、开源许可证和开发者社区形成，与闭源垄断相对。"}],"rel":[{"t":"DeepSeek","n":"中国开源大模型的典型代表"},{"t":"基础大模型","n":"开源与闭源路线竞争的前沿"},{"t":"数字经济","n":"开源生态降低数字产业创新成本"}],"exam":[]},{"id":"b13-031","t":"算法治理","cid":"13g","p":3,"kind":"概念","one":"对算法推荐与自动化决策实施规则约束，防范歧视、茧房与大数据杀熟。","ans":"算法治理是对算法设计、推荐与自动化决策实施**规则约束与监督**，属**网络与人工智能治理**核心议题。它重点防范**算法歧视、“信息茧房”与大数据杀熟**。我国《互联网信息服务算法推荐管理规定》**2022年3月1日**施行，引导算法向善。","pts":["约束算法推荐与自动化决策","防范算法歧视、信息茧房与杀熟","2022年算法推荐管理规定施行"],"mem":"抓“三防一规”：防歧视、防茧房、防杀熟，2022年3月1日《算法推荐管理规定》落地。","mix":"算法治理针对推荐排序和自动化决策，数据治理侧重数据采集、流通与安全。","mcq":[{"q":"我国《互联网信息服务算法推荐管理规定》正式施行于","o":["2020年1月1日","2021年9月1日","2022年3月1日","2023年8月15日"],"a":2,"w":"该规定自2022年3月1日起施行，是国内首个专门规范算法推荐的部门规章。"}],"rel":[{"t":"信息茧房","n":"算法治理重点防范现象"},{"t":"人工智能治理","n":"同簇上位治理框架"},{"t":"《生成式人工智能服务管理暂行办法》","n":"2023年配套监管规章"},{"t":"大数据","n":"算法运行的底层基础"}],"exam":[],"alias":[]},{"id":"b13-032","t":"科技伦理","cid":"13g","p":3,"kind":"概念","one":"科技活动应遵循的价值理念与行为规范，我国确立五项科技伦理原则。","ans":"科技伦理是科技活动应遵循的**价值理念与行为规范**，属现代**科技治理**基石。**2022年3月**中办、国办印发《关于加强科技伦理治理的意见》，提出**增进人类福祉、尊重生命权利、坚持公平公正、合理控制风险、保持公开透明**五原则，引导科技向善。","pts":["科技活动的价值理念与行为规范","2022年3月印发加强科技伦理治理意见","福祉、生命、公平、风险、透明五原则"],"mem":"五原则口诀“福命公风透”：增进人类福祉、尊重生命权利、坚持公平公正、合理控制风险、保持公开透明。","mix":"科技伦理重价值底线与前置审查，不同于事后追责的科技法律规范，二者相辅相成。","mcq":[{"q":"2022年《关于加强科技伦理治理的意见》提出的原则不包括","o":["增进人类福祉","尊重生命权利","保持公开透明","追求效率优先"],"a":3,"w":"五项原则是增进人类福祉、尊重生命权利、坚持公平公正、合理控制风险、保持公开透明。"}],"rel":[{"t":"人工智能治理","n":"科技伦理重点落地领域"},{"t":"算法治理","n":"同簇技术伦理约束"},{"t":"《全球人工智能治理倡议》","n":"以人为本与智能向善呼应"}],"exam":[],"alias":[]},{"id":"b13-033","t":"习近平党建思想","cid":"13a","p":2,"kind":"时事","alias":["新时代党建思想","习近平关于党的建设的重要思想"],"one":"2026年提出的习近平新时代思想“党建篇”，核心要义概括为“十四个坚持”。","ans":"习近平党建思想是新时代党的建设系统理论，属**习近平新时代中国特色社会主义思想“党建篇”**，回答如何建设**长期执政的马克思主义政党**课题。**2026年6月15日全国党建工作座谈会**将其概括为**“十四个坚持”**，首条强调党的领导是本质特征；8月中央纪委六次全会、10月**二十届五中全会**公报相继写入。它为自我革命提供根本遵循。","pts":["习近平新时代中国特色社会主义思想的“党建篇”","2026年6月全国党建工作座谈会概括“十四个坚持”","回答长期执政马克思主义政党建设的时代课题"],"mem":"时间线串联2026年三件大事：6月全国党建工作座谈会提出“十四个坚持” → 8月二十届中央纪委六次全会写入 → 10月二十届五中全会公报写入。记住“党建篇”和首条“党的领导”。","mix":"注意区分“十四个坚持”：十九大报告提出新时代坚持和发展中国特色社会主义基本方略“十四个坚持”，2026年全国党建工作座谈会则将习近平党建思想核心要义也概括为“十四个坚持”，二者第一条均强调党的领导。","mcq":[{"q":"2026年6月全国党建工作座谈会将“习近平党建思想”的核心要义概括为","o":["“六个必须坚持”","“十个明确”","“十四个坚持”","“九个坚持”"],"a":2,"w":"2026年6月15日全国党建工作座谈会将习近平党建思想概括为“十四个坚持”，第一条是坚持党的领导是中国特色社会主义最本质的特征。"}],"rel":[{"t":"习近平新时代中国特色社会主义思想","n":"所属母体理论体系"},{"t":"全面从严治党","n":"党建实践的核心主线"},{"t":"二十届五中全会","n":"2026年10月写入公报"},{"t":"二十届中央纪委六次全会","n":"2026年8月写入公报"}],"more":"2026年适逢中国共产党成立105周年，6月15日全国党建工作座谈会、8月22日二十届中央纪委六次全会、10月26日至29日二十届五中全会构成2026年党建时政主线。","exam":[]},{"id":"b13-034","t":"全面从严治党","cid":"13a","p":2,"kind":"概念","alias":["从严治党"],"one":"“四个全面”战略布局之一，2026年二十届五中全会作出持之以恒推进的决定。","ans":"全面从严治党是**“四个全面”战略布局**之一，2014年12月提出，**基础在全面、关键在严、要害在治**。主要举措有落实**中央八项规定精神**、纠治“四风”，一体推进**不敢腐、不能腐、不想腐**，2018年组建国家监察委员会实现监察全覆盖。**2026年10月二十届五中全会**通过专题决定。它以自我革命给出跳出历史周期率的**“第二个答案”**。","pts":["“四个全面”之一，基础在全面、关键在严、要害在治","中央八项规定、“三不腐”与2018年国家监察委","2026年二十届五中全会通过专题决定，推进自我革命"],"mem":"三字定位口诀：“全、严、治”（基础在全、关键在严、要害在治）；反腐三连：“不敢、不能、不想”（不敢靠震慑、不能靠制度、不想靠觉悟）；2026年五中全会主题直指全面从严治党。","mix":"“四个全面”在2020年十九届五中全会调整过第一项（由全面建成小康社会改为全面建设社会主义现代化国家），其余三项（深化改革、依法治国、从严治党）始终未变。","mcq":[{"q":"2026年10月审议通过《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》的会议是","o":["二十届五中全会","二十届四中全会","二十届三中全会","十九届六中全会"],"a":0,"w":"二十届五中全会于2026年10月26日至29日召开，专题研究持之以恒推进全面从严治党；四中全会定“十五五”规划建议，三中全会定进一步全面深化改革。"}],"rel":[{"t":"“四个全面”","n":"所属战略布局"},{"t":"二十届五中全会","n":"2026年专题作出决定"},{"t":"窑洞对与“两个答案”","n":"自我革命的理论渊源"},{"t":"国家监察委员会","n":"2018年组建的监察机构"}],"more":"“四风”指形式主义、官僚主义、享乐主义和奢靡之风。2026年10月二十届五中全会同时决定党的二十一大将于2027年下半年在北京召开。","exam":[]},{"id":"b13-035","t":"中美建设性战略稳定关系","cid":"13j","p":2,"kind":"时事","alias":["中美关系新定位"],"one":"2026年5月中美元首北京会谈确立的中美关系新定位。","ans":"中美建设性战略稳定关系是**2026年5月14日**习近平同来华国事访问的美国总统**特朗普在北京会谈**中确立的**中美关系新定位**，为未来3年乃至更长时期的中美关系提供指引。其内涵包括**合作为主的积极稳定、竞争有度的良性稳定、分歧可控的常态稳定、和平可期的持久稳定**。会谈中习近平还提出中美能否跨越**“修昔底德陷阱”**之问。","pts":["2026年5月14日习近平同特朗普北京会谈确立","四大内涵：积极、良性、常态、持久四种稳定","为未来中美关系定调，回应修昔底德陷阱之问"],"mem":"四个“稳定”口诀：“合积、竞良、分常、和持”，即合作为主积极稳定、竞争有度良性稳定、分歧可控常态稳定、和平可期持久稳定，抓住动词“合、竞、分、和”。","mix":"注意区分不同时期表述：此前强调“相互尊重、和平共处、合作共赢”三原则，2026年5月北京会谈在此基础上进一步将构建“中美建设性战略稳定关系”确立为中美关系新定位。","mcq":[{"q":"2026年5月14日中美元首北京会谈确立的中美关系新定位是构建","o":["中美建设性战略稳定关系","中美全面战略协作伙伴关系","中美全天候战略合作伙伴关系","中美军事安全同盟关系"],"a":0,"w":"2026年5月14日习近平同特朗普在北京会谈，双方赞同将构建“中美建设性战略稳定关系”作为中美关系新定位。"}],"rel":[{"t":"修昔底德陷阱","n":"会谈中重点提出的大国之问"},{"t":"中美三个联合公报","n":"中美关系的政治基础"},{"t":"新型国际关系","n":"中国特色大国外交理念"},{"t":"尼克松访华","n":"中美破冰的历史起点"}],"exam":[]},{"id":"b13-036","t":"二十届中央纪委六次全会","cid":"13a","p":3,"kind":"时事","alias":["二十届中纪委六次全会"],"one":"2026年8月北京举行，公报明确习近平党建思想是新时代思想的“党建篇”。","ans":"二十届中央纪委六次全会于**2026年8月22日**在北京举行，由中央纪委常委会主持。公报明确**习近平党建思想**是习近平新时代中国特色社会主义思想的**“党建篇”**，部署深化正风肃纪反腐，推进**全面从严治党**。","pts":["2026年8月22日在北京举行","明确习近平党建思想是“党建篇”","部署正风肃纪反腐与纪检铁军建设"],"mem":"记“2026.8.22 + 党建篇”：二十届中纪委第六次全会在8月下旬召开，核心提法是将习近平党建思想定位为新时代思想的“党建篇”。","mix":"易与2026年10月召开的二十届五中全会混淆：前者是中纪委全会、聚焦“党建篇”，后者是中央全会、审议全面从严治党决定。","mcq":[{"q":"2026年8月召开的二十届中央纪委六次全会公报指出，习近平党建思想是习近平新时代中国特色社会主义思想的","o":["“党建篇”","“法治篇”","“改革篇”","“治理篇”"],"a":0,"w":"全会公报明确将习近平党建思想定位为习近平新时代中国特色社会主义思想的“党建篇”。"}],"rel":[{"t":"习近平党建思想","n":"全会重点阐述的核心理论"},{"t":"二十届五中全会","n":"同年10月部署全面从严治党"},{"t":"全面从严治党","n":"全会推进的根本主题"}],"more":"中共中央政治局常委、中央纪委书记李希出席会议并讲话；全会选举赵世勇、张忠为二十届中央纪委常委、副书记。","exam":[]},{"id":"b13-037","t":"2026年政府工作报告","cid":"13c","p":2,"kind":"时事","alias":["2026政府工作报告"],"one":"2026年3月5日李强作报告，GDP预期目标4.5%至5%，开启“十五五”。","ans":"2026年《政府工作报告》由总理**李强**于**2026年3月5日**在**十四届全国人大四次会议**上作，是**“十五五”开局**施政纲领。报告总结2025年GDP增5%、达**140.19万亿元**；定2026年**经济增长4.5%至5%**、新增就业1200万人以上、CPI涨幅2%左右，继续实施**更加积极财政政策**与**适度宽松货币政策**，部署新兴支柱与未来产业。","pts":["2026年3月5日十四届全国人大四次会议李强作报告","GDP目标4.5%至5%，2025年破140万亿","更加积极财政政策与适度宽松货币政策"],"mem":"数字卡片速记2026两会：GDP目标“4.5%至5%”（区间目标），赤字率“4%左右”，CPI“2%左右”，新增就业“1200万+”，2025年经济总量“140万亿台阶”。","mix":"2024与2025年GDP预期目标均为“5%左右”，2026年调整为区间目标**“4.5%至5%”**；本次人大会议同步审查批准“十五五”规划纲要并通过《国家发展规划法》。","mcq":[{"q":"2026年《政府工作报告》确定的全年经济增长预期目标是","o":["5%左右","4.5%至5%","5%至5.5%","4%左右"],"a":1,"w":"2026年3月5日李强作的《政府工作报告》将当年经济增长预期目标定为4.5%至5%，在实际工作中努力争取更好结果。"}],"rel":[{"t":"“十五五”规划","n":"同期人大批准开局蓝图"},{"t":"国家发展规划法","n":"2026年3月同期表决通过"},{"t":"宏观调控四大目标","n":"报告预期指标的理论框架"},{"t":"低空经济","n":"报告列入新兴支柱产业"}],"more":"同次会议（十四届全国人大四次会议，2026年3月5日至12日）批准《“十五五”规划纲要》，并表决通过《中华人民共和国国家发展规划法》；2026年赤字率拟按4%左右安排。","exam":[]},{"id":"b13-038","t":"联合国秘书长遴选","cid":"13h","p":2,"kind":"时事","alias":["联合国秘书长选举","第十任联合国秘书长遴选"],"one":"安理会推荐、联大任命的联合国行政首长产生程序，2026年聚焦古特雷斯继任者。","ans":"联合国秘书长遴选是产生联合国**最高行政首长**的法定程序。依**《联合国宪章》第97条**，秘书长由**安理会推荐**（需至少9票赞成且五常不否决）、**联大任命**，任期**5年**，可连任。现任古特雷斯任期至2026年12月31日，新任定于2027年1月1日就职。2026年遴选程序更趋透明，拉美轮换与推举首位女性秘书长的呼声突出。","pts":["《联合国宪章》第97条：安理会推荐、联大任命","任期5年可连任；五常对推荐人选具否决权","古特雷斯任期至2026年底，新任2027年上任"],"mem":"程序口诀：“安推联任，九票无否，五年可连”。先过安理会“推荐关”（五常一票否决），再过联大“任命关”。时间锚点：古特雷斯2017上任、干满两届到2026年底。","mix":"秘书长由联合国大会任命，非安理会直接任命；但安理会推荐是必要前置条件，常任理事国在闭门意向性投票中的态度起决定作用。历史上9任秘书长均为男性，无一来自五常。","mcq":[{"q":"根据《联合国宪章》规定，联合国秘书长的法定产生方式是","o":["由联合国大会直接差额选举产生","由安理会五个常任理事国轮流指派","由联合国大会提名、安理会批准任命","由安理会推荐、联合国大会任命"],"a":3,"w":"《联合国宪章》第97条规定秘书长由大会经安全理事会推荐委派之，即安理会推荐、联大任命。"}],"rel":[{"t":"联合国","n":"秘书长为最高行政首长"},{"t":"联合国安理会与五个常任理事国","n":"手握推荐与否决权"},{"t":"联合国六大主要机关","n":"秘书长领导秘书处"}],"more":"惯例：地区轮换、不从五常产生。截至2026年11月中旬，安理会已举行多轮闭门意向性投票，尚未最终锁定推荐人选。","exam":[]},{"id":"b13-039","t":"南方谈话","cid":"13a","p":1,"kind":"事件","exam":["2013名解"],"alias":["邓小平南方谈话","南巡讲话","南巡"],"one":"1992年邓小平视察南方发表谈话，推动十四大确立市场经济目标。","ans":"南方谈话是**1992年1月18日至2月21日邓小平视察武昌、深圳、珠海、上海等地时发表的重要谈话**，发生在改革开放面临“姓资姓社”争论的关头。谈话提出**“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕”**，指出**计划多一点还是市场多一点，不是社会主义与资本主义的本质区别**，并提出**“三个有利于”判断标准**和**“发展才是硬道理”**。它推动了**1992年党的十四大确立社会主义市场经济体制的改革目标**。","pts":["1992年邓小平视察武昌、深圳、珠海、上海","社会主义本质论，计划与市场不是本质区别","三个有利于；推动十四大确立市场经济目标"],"mem":"逻辑线：1989至1991年改革一度犹疑，争论“姓资姓社”，所以邓小平88岁南下“打破僵局”，谈话后十四大（1992年10月）定下市场经济目标。地名首字“武深珠沪”，自北向南再回上海。数字：“三个有利于”看生产力、综合国力、生活水平。","mix":"南方谈话是1992年，十一届三中全会是1978年；十二大提出“有中国特色的社会主义”，十三大才讲初级阶段，十四大才定市场经济。","mcq":[{"q":"邓小平南方谈话发表于","o":["1978年","1984年","1992年","1997年"],"a":2,"w":"1992年初，同年十四大确立社会主义市场经济体制目标。"},{"q":"下列哪项属于南方谈话提出的内容","o":["三个有利于","三个代表","科学发展观","和平共处五项原则"],"a":0,"w":"“三个有利于”是判断改革得失的标准；“三个代表”是江泽民2000年提出。"}],"rel":[{"t":"邓小平理论","n":"谈话是理论的重要内容"},{"t":"社会主义市场经济体制","n":"十四大确立的目标"},{"t":"经济特区","n":"视察深圳、珠海"},{"t":"十一届三中全会","n":"改革开放的起点"}],"more":"名句：社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。\n名句：发展才是硬道理。\n1992年10月党的十四大确立社会主义市场经济体制的改革目标。"},{"id":"b13-040","t":"一带一路","cid":"13h","p":1,"kind":"概念","exam":["2019名解"],"alias":["一带一路","“一带一路”","丝绸之路经济带","21世纪海上丝绸之路","共建一带一路"],"one":"“丝绸之路经济带”与“21世纪海上丝绸之路”的简称，2013年提出。","ans":"“一带一路”是**“丝绸之路经济带”和“21世纪海上丝绸之路”的简称**，**2013年9月和10月习近平分别在哈萨克斯坦、印度尼西亚提出**。它秉持**共商共建共享**原则，以**政策沟通、设施联通、贸易畅通、资金融通、民心相通“五通”**为主要内容，并成立**亚洲基础设施投资银行和丝路基金**提供资金支持。2023年举办第三届“一带一路”国际合作高峰论坛，迎来倡议十周年。它是**人类命运共同体理念的重要实践平台**，推动沿线国家基础设施建设和经贸往来。","pts":["2013年9月、10月分别在哈萨克斯坦、印尼提出","共商共建共享，五通","亚投行、丝路基金；2023年十周年"],"mem":"“一带”对陆（哈萨克斯坦，9月），“一路”对海（印尼，10月），先陆后海，先9后10。五通记“政设贸资民”：政策、设施、贸易、资金、民心。","mix":"“一带”指陆上丝绸之路经济带，“一路”指海上丝绸之路；亚投行是国际多边银行，丝路基金是中国出资的投资基金，两者不是同一机构。","mcq":[{"q":"“丝绸之路经济带”倡议提出的国家是","o":["印度尼西亚","俄罗斯","巴基斯坦","哈萨克斯坦"],"a":3,"w":"2013年9月在哈萨克斯坦提出；“海上丝绸之路”10月在印尼提出。"},{"q":"下列不属于“五通”的是","o":["政策沟通","设施联通","贸易畅通","军事互通"],"a":3,"w":"五通是政策沟通、设施联通、贸易畅通、资金融通、民心相通。"}],"rel":[{"t":"“一带一路”五通","n":"主要内容"},{"t":"亚洲基础设施投资银行","n":"配套金融机构"},{"t":"丝绸之路","n":"历史渊源"},{"t":"人类命运共同体","n":"理念与实践"}],"more":"2023年举办第三届“一带一路”国际合作高峰论坛，倡议提出十周年。"},{"id":"b13-041","t":"马歇尔计划","cid":"13i","p":2,"kind":"事件","exam":["2019名解"],"alias":["欧洲复兴计划","Marshall Plan"],"one":"1947年美国提出的西欧经济援助计划，冷战政策在经济上的体现。","ans":"马歇尔计划正式名称**“欧洲复兴计划”**，由美国国务卿**马歇尔于1947年6月在哈佛大学演讲**提出。1948至1952年美国向西欧提供约**130亿美元**援助，助西欧恢复战后经济，同时加强对西欧控制并遏制苏联。它是**美国冷战政策在经济上的体现**，苏联随即以“莫洛托夫计划”和**经济互助委员会**回应。","pts":["正式名称欧洲复兴计划，1947年马歇尔提出","1948至1952年向西欧提供约130亿美元援助","冷战经济手段，苏联以经互会回应"],"mem":"冷战“三板斧”对比记：政治上杜鲁门主义（1947.3），经济上马歇尔计划（1947.6），军事上北约（1949）。记作“政杜、经马、军北约”。","mix":"杜鲁门主义（政治宣言）与马歇尔计划（经济援助）同在1947年出台，杜鲁门称二者是“一个胡桃的两半”；苏联对应的经济组织是经互会（1949），军事组织是华约（1955）。","mcq":[{"q":"1947年6月在哈佛大学发表演讲、正式提出“欧洲复兴计划”的美国国务卿是","o":["杜鲁门","马歇尔","基辛格","凯南"],"a":1,"w":"美国国务卿乔治·马歇尔1947年6月在哈佛大学提出“欧洲复兴计划”，世称马歇尔计划。"}],"rel":[{"t":"冷战","n":"冷战在经济领域核心举措"},{"t":"杜鲁门主义","n":"同年出台的冷战政治宣言"},{"t":"北约","n":"随后的冷战军事同盟"},{"t":"哈佛大学","n":"1947年计划演讲发表地"}]},{"id":"b13-042","t":"地缘政治","cid":"13i","p":2,"kind":"概念","exam":["2019名解"],"alias":["地缘政治学","Geopolitics"],"one":"结合地理要素与政治格局分析国家战略和国际关系的理论与现实。","ans":"地缘政治指依据**位置、资源、交通、人口**等地理要素和政治格局分析**国家战略与国际关系**的理论与现实。19世纪末瑞典学者**契伦**首创“地缘政治学”，代表理论有美国马汉**“海权论”**、英国麦金德**“心脏地带说”**和斯皮克曼**“边缘地带说”**。该理论长期影响大国战略布局，至今仍广泛用于分析大国竞争与地区冲突。","pts":["结合地理要素与政治格局分析国家战略","瑞典学者契伦首创“地缘政治学”一词","三大理论：海权论、心脏地带说、边缘地带说"],"mem":"人物理论配对口诀：“契伦起名字，马汉管大海，麦金德守心脏，斯皮克曼控边缘”。心脏地带指欧亚大陆腹地，谁控制东欧就控制心脏地带。","mix":"选择题常考理论与学者对应：海权论是马汉（美国），陆权论（心脏地带说）是麦金德（英国），边缘地带说是斯皮克曼（美国），切勿张冠李戴。","mcq":[{"q":"近代地缘政治学中提出“心脏地带说”（陆权论）的英国地理学家是","o":["麦金德","马汉","契伦","斯皮克曼"],"a":0,"w":"英国麦金德提出“心脏地带说”；马汉提出海权论，契伦首创地缘政治学，斯皮克曼提出边缘地带说。"}],"rel":[{"t":"冷战","n":"两极格局中的地缘对抗"},{"t":"马六甲海峡","n":"典型地缘战略咽喉水道"},{"t":"霍尔木兹海峡","n":"中东能源地缘咽喉"},{"t":"威斯特伐利亚体系","n":"主权领土政治的历史起点"}]},{"id":"b13-043","t":"多极化","cid":"13i","p":2,"kind":"概念","exam":["2016名解"],"alias":["世界多极化","平等有序的世界多极化"],"one":"世界格局从少数大国主导向多个力量中心并存演变的趋势。","ans":"多极化指世界格局由少数大国主导向**多个力量中心并存、相互制约**演变的趋势。冷战时期为美苏两极格局，**1991年苏联解体**后形成**“一超多强”**并向多极化演进，美、欧、中、俄、日及新兴经济体共同影响国际事务。中国明确主张**平等有序的世界多极化**和普惠包容的经济全球化，推动国际关系民主化。","pts":["世界格局由少数大国向多力量中心演变的趋势","从美苏两极经“一超多强”向多极化发展","中国主张平等有序的世界多极化"],"mem":"三段演变线：二战后“两极”→1991后“一超多强”→当今加速“多极化”。配对记中国两大主张：“平等有序”配多极化，“普惠包容”配全球化。","mix":"多极化是一种“正在演进的趋势”，并非已经完全定型的结果；两极格局结束后形成的是“一超多强”过渡形态，而非立即实现均衡多极。","mcq":[{"q":"面对当今世界百年变局，中国明确倡导的世界多极化方向是","o":["霸权主导的世界多极化","零和博弈的世界多极化","阵营对抗的世界多极化","平等有序的世界多极化"],"a":3,"w":"中国明确主张平等有序的世界多极化和普惠包容的经济全球化。"}],"rel":[{"t":"两极格局与“一超多强”","n":"多极化之前与过渡形态"},{"t":"全球南方","n":"推动多极化的新兴力量"},{"t":"全球化与逆全球化","n":"与多极化并行的经济趋势"},{"t":"苏联解体","n":"终结两极、开启格局重塑"}]},{"id":"b13-044","t":"冷战","cid":"13i","p":2,"kind":"事件","alias":["冷战时期","Cold War"],"one":"1947至1991年美苏两大阵营间除直接大规模热战外的全面对抗。","ans":"冷战指二战后美苏分别主导的**资本主义与社会主义两大阵营**之间，除直接大规模战争外的全面对抗。1946年丘吉尔**“铁幕演说”**揭幕，1947年**“杜鲁门主义”**标志开始；双方形成**北约（1949）与华约（1955）**对峙，爆发柏林危机、古巴导弹危机。**1991年苏联解体**标志冷战终结，深刻塑造战后近半个世纪国际秩序。","pts":["美苏两大阵营除直接大战外的全面对抗","铁幕演说揭幕、杜鲁门主义开始、北约华约对峙","1991年苏联解体标志冷战结束"],"mem":"时间轴口诀：“46铁幕、47杜马、49北约、55华约、62古巴、89推墙、91解体”。串联七个标志节点，冷战整条历史线一眼看全。","mix":"冷战虽未引发美苏直接核大战，但局部热战不断（朝鲜战争、越南战争等）；注意区分序幕（1946铁幕演说）与正式开始标志（1947杜鲁门主义）。","mcq":[{"q":"通常被史学界视为美苏冷战正式开始标志的事件是","o":["1945年雅尔塔会议召开","1949年北大西洋公约组织成立","1947年“杜鲁门主义”出台","1961年柏林墙修建"],"a":2,"w":"1946年铁幕演说被视为冷战序幕，1947年3月“杜鲁门主义”出台标志冷战正式开始。"}],"rel":[{"t":"铁幕演说","n":"1946年冷战序幕"},{"t":"杜鲁门主义","n":"1947年冷战正式开始标志"},{"t":"古巴导弹危机","n":"1962年冷战核危机顶点"},{"t":"苏联解体","n":"1991年冷战终结标志"}],"exam":[]},{"id":"b13-045","t":"自由贸易试验区","cid":"13c","p":2,"kind":"制度","exam":["2015名解"],"alias":["自贸试验区","自贸区","中国自由贸易试验区"],"one":"国境内制度创新试验田，2013年上海设首个，2026年内蒙古获批后增至23个。","ans":"自由贸易试验区是在国境内划出实行开放便利贸易投资金融政策的区域，承担**制度创新试验田**功能。**2013年9月29日**，**中国（上海）自由贸易试验区**挂牌，为全国首个，首创**外商投资准入前国民待遇加负面清单**模式。此后多批扩围，**2026年4月**国务院批复**中国（内蒙古）自由贸易试验区**后增至**23个**。它以制度创新推动我国对接国际高标准经贸规则。","pts":["国境内制度创新试验田，2015年交大真题名解","2013年9月上海设立全国首个，首创负面清单模式","2026年4月内蒙古获批后全国增至23个"],"mem":"时间两头抓：“2013上海首个（负面清单）→ 2023新疆第22个 → 2026年4月内蒙古第23个（北部沿边新支点）”。上海自贸区+临港新片区是交大本土高频关联点。","mix":"国内的“自由贸易试验区”（FTZ，一国内部划定）不同于国与国之间签订的“自由贸易协定/自由贸易区”（FTA，如RCEP）；**海南自由贸易港**则属于更高水平的海关监管特殊区域，2025年12月已全岛封关运作。","mcq":[{"q":"2026年4月国务院批复设立后，使我国自由贸易试验区总数增至23个的是","o":["新疆自贸试验区","西藏自贸试验区","青海自贸试验区","内蒙古自贸试验区"],"a":3,"w":"2026年4月国务院印发《中国（内蒙古）自由贸易试验区总体方案》，全国自贸试验区由22个（第22个为2023年新疆）增至23个。"}],"rel":[{"t":"上海自贸试验区与临港新片区","n":"2013年全国首个自贸区"},{"t":"海南自由贸易港","n":"更高水平对外开放形态"},{"t":"经济特区","n":"改革开放初期的试验田"},{"t":"区域全面经济伙伴关系协定（RCEP）","n":"多边自贸协定的对照"}],"more":"上海自贸试验区2013年9月29日挂牌，2019年8月增设临港新片区，2023年迎来设立10周年。内蒙古自贸试验区含呼和浩特、满洲里、二连浩特三个片区。"},{"id":"b13-046","t":"首次公开募股（IPO）","cid":"13d","p":2,"kind":"概念","exam":["2015名解"],"alias":["IPO","首次公开募股","首次公开发行"],"one":"企业首次向社会公众发行股票并在交易所上市，2023年A股全面实行注册制。","ans":"首次公开募股（**IPO**，Initial Public Offering）指企业**首次向社会公众公开发行股票**并在交易所上市交易，属典型**直接融资**。企业借此募集长期资金、提升知名度并规范治理，早期投资人借此退出获利。中国A股历经审批制、核准制，2019年在**科创板**试点，**2023年全面实行股票发行注册制**，强化了资本市场资源配置功能。","pts":["IPO即首次向公众公开发行股票上市","实现直接融资、规范治理与早期投资人退出","A股经审批制、核准制，2023年全面实行注册制"],"mem":"英文拆字记含义：I=Initial（首次）、P=Public（公众）、O=Offering（发行）。A股发行三步走：“审批制 → 核准制 → 注册制（2019科创板试点、2023全面推开）”。","mix":"IPO是企业**第一次**面向公众发行股票（一级市场向二级市场过渡）；已上市公司后续再融资发股称为“增发”或“配股”，不再称IPO。","mcq":[{"q":"中国A股市场正式全面实行股票发行注册制的时间是","o":["2019年","2020年","2023年","2021年"],"a":2,"w":"2019年科创板率先试点注册制，2023年2月17日中国证监会发布实施全面实行股票发行注册制相关制度规则。"}],"rel":[{"t":"股票发行注册制","n":"2023年A股全面推行的制度"},{"t":"科创板","n":"首个试点注册制的板块"},{"t":"风险投资","n":"借IPO实现退出的早期资本"},{"t":"证券市场基本概念","n":"同簇资本市场基础知识"}],"more":"关键年份：2015年交大448真题曾考“IPO”名词解释；2023年2月17日A股全面实行股票发行注册制。"},{"id":"b13-047","t":"融资","cid":"13d","p":3,"kind":"概念","exam":["2015名解"],"alias":["资金融通"],"one":"企业等主体筹集资金的行为，分直接与间接、股权与债权融资。","ans":"融资指企业等经济主体**筹集资金**的金融行为。按渠道分为**直接融资**（发行股票、债券）与**间接融资**（银行贷款）；按性质分为**股权与债权融资**。创业企业股权融资常按**天使轮、A/B轮直至IPO**推进，是资本配置的核心环节。","pts":["直接融资（股债）与间接融资（银行）","股权融资与债权融资两大性质","创业企业按天使轮、A/B轮至IPO推进"],"mem":"两把尺子分清融资：看有没有银行中介（直接vs间接），看交不交公司股份（股权vs债权）；创业升级路线图“天使→A/B/C→IPO”。","mix":"常见混淆：发股票、发企业债都属于直接融资，只有通过银行等金融中介吸储放贷才是间接融资。","mcq":[{"q":"下列筹资方式中，属于间接融资的是","o":["向商业银行申请贷款","发行公司债券","首次公开募股（IPO）","引入天使投资"],"a":0,"w":"通过商业银行等金融中介借入资金为间接融资；发股、发债和天使投资均属直接融资。"}],"rel":[{"t":"首次公开募股（IPO）","n":"股权融资上市的终点阶段"},{"t":"天使投资","n":"初创企业最早期的股权融资"},{"t":"风险投资","n":"成长期创业企业重要融资来源"},{"t":"耐心资本","n":"支持硬科技的长周期融资力量"}]},{"id":"b13-048","t":"纽约证券交易所","cid":"13d","p":3,"kind":"常识","exam":["2015名解"],"alias":["纽交所","NYSE"],"one":"源于1792年《梧桐树协议》，位于华尔街，全球市值最大的证交所。","ans":"纽约证券交易所（NYSE）位于美国**纽约华尔街**，起源于**1792年**经纪人签署的**《梧桐树协议》**。其上市门槛严格，汇聚大批传统蓝筹与跨国巨头。按**上市公司总市值**计，纽交所是**全球最大的证券交易所**，是国际金融市场风向标。","pts":["起源于1792年《梧桐树协议》","位于纽约华尔街，传统蓝筹股聚集地","按上市公司总市值计为全球最大证交所"],"mem":"画面记忆：1792年华尔街一棵梧桐树下，24位经纪人签协议定规矩，长成今天全球市值第一的纽交所。","mix":"易与纳斯达克混淆：纽交所建于1792年、有交易大厅且偏传统蓝筹，纳斯达克建于1971年、纯电子化且偏科技股。","mcq":[{"q":"纽约证券交易所的历史起源于1792年签署的哪份文件","o":["《布雷顿森林协定》","《梧桐树协议》","《广场协议》","《格拉斯-斯蒂格尔法案》"],"a":1,"w":"1792年5月17日，24名证券经纪人在华尔街梧桐树下签署《梧桐树协议》，奠定了纽交所的基础。"}],"rel":[{"t":"纳斯达克","n":"同为美国核心证券市场，常对举"},{"t":"硅谷与华尔街","n":"纽交所是华尔街金融地标"},{"t":"上海证券交易所","n":"中外主板交易所对照"}]},{"id":"b13-049","t":"纳斯达克","cid":"13d","p":3,"kind":"常识","exam":["2015名解"],"alias":["NASDAQ","纳斯达克证券交易所"],"one":"1971年成立的美国电子化证券市场，全球首个电子股票市场，科技股云集。","ans":"纳斯达克（NASDAQ）是**1971年**成立的美国证券市场，为**全球第一个电子化股票市场**。它无传统人工交易大厅，上市门槛相对灵活，汇聚苹果、微软、英伟达等大批**科技与创新企业**，其综合指数已成为全球科技股行情的重要晴雨表。","pts":["1971年创立于美国","全球第一个电子化股票市场","高科技与成长型科技公司高度集中"],"mem":"对比口诀“纽老纳新，纽树纳电”：纽交所1792年梧桐树起家偏老牌蓝筹，纳斯达克1971年电子化起家偏科技新贵。","mix":"纳斯达克原为“全美证券交易商协会自动报价系统”缩写，并非单纯指代科技股指数，其本身是完整的证券交易所。","mcq":[{"q":"全球第一个电子化股票市场是1971年成立的","o":["纽约证券交易所","伦敦证券交易所","纳斯达克","东京证券交易所"],"a":2,"w":"1971年成立的纳斯达克是世界上第一个采用电子化报价与交易的证券市场。"}],"rel":[{"t":"纽约证券交易所","n":"美国两大证交所直接对比"},{"t":"创业板","n":"中国对标纳斯达克的成长板块"},{"t":"科创板","n":"聚焦硬科技的A股板块"},{"t":"硅谷与华尔街","n":"硅谷科技公司的主要上市地"}]},{"id":"b13-050","t":"创业板","cid":"13d","p":3,"kind":"常识","exam":["2015名解"],"alias":["二板市场","深交所创业板"],"one":"2009年10月30日在深交所开板，服务成长型创新创业企业。","ans":"创业板又称**二板市场**，于**2009年10月30日**在**深圳证券交易所**开板。板块股票代码以300开头，重点服务**成长型创新创业企业**；**2020年8月**启动试点**注册制**，是我国多层次资本市场的重要组成部分。","pts":["2009年10月30日在深交所开板","定位成长型创新创业企业（代码300开头）","2020年试点股票发行注册制"],"mem":"三板口诀记定位：“上科硬科技（688），深创成长创（300），北交中小新”，上交所科创板、深交所创业板、北交所一网打尽。","mix":"易与科创板混淆：创业板在深交所、2009年开板；科创板在上交所、2019年开市，是首个试点注册制的板块。","mcq":[{"q":"2009年10月30日正式开板的中国创业板隶属于","o":["上海证券交易所","北京证券交易所","香港交易所","深圳证券交易所"],"a":3,"w":"创业板于2009年10月30日在深圳证券交易所开板，科创板则设在上海证券交易所。"}],"rel":[{"t":"深圳证券交易所","n":"创业板所属交易所"},{"t":"科创板","n":"同为服务创新企业的A股板块"},{"t":"股票发行注册制","n":"创业板2020年试点改革"},{"t":"纳斯达克","n":"国际创业板市场参照"}]},{"id":"b13-051","t":"科创板","cid":"13d","p":2,"kind":"制度","alias":["科技创新板","上交所科创板"],"one":"2019年7月22日在上交所开市，我国首个试点注册制板块，面向“硬科技”企业。","ans":"科创板全称**科技创新板**，设立于**上海证券交易所**，是**上海“三大任务”**之一。2018年11月首届进博会宣布设立，**2019年7月22日**正式开市。作为我国**首个试点股票发行注册制**的板块，它面向新一代信息技术、高端装备、生物医药等**“硬科技”企业**，允许符合条件的未盈利科技企业上市，畅通科技、资本与产业循环。","pts":["2019年7月22日在上海证券交易所正式开市","我国首个试点股票发行注册制的资本市场板块","定位“硬科技”企业，落实上海“三大任务”"],"mem":"三所板块定位对照记忆：上交所**科创板**（硬科技，2019开市）、深交所**创业板**（成长型创新创业企业，2009开市）、**北交所**（服务创新型中小企业与“专精特新”，2021开市）。","mix":"科创板设在**上海证券交易所**，创业板设在**深圳证券交易所**，二者常被混淆；宣布时间是2018年11月首届进博会，开板是2019年6月陆家嘴论坛，正式开市交易是**2019年7月22日**。","mcq":[{"q":"2019年7月22日正式开市、成为我国资本市场首个试点股票发行注册制板块的是","o":["科创板","创业板","新三板","北交所"],"a":0,"w":"科创板于2019年7月22日在上海证券交易所开市，是我国首个试点股票发行注册制的板块。"}],"rel":[{"t":"上海证券交易所","n":"科创板所在交易所"},{"t":"上海“三大任务”","n":"设立科创板为其任务之一"},{"t":"创业板","n":"深交所板块（易混对照）"},{"t":"纳斯达克","n":"常被类比的美国科技板"}],"more":"上海“三大任务”：增设上海自贸试验区临港新片区、在上海证券交易所设立科创板并试点注册制、支持长三角区域一体化发展并上升为国家战略。","exam":[]},{"id":"b13-052","t":"北京证券交易所","cid":"13d","p":3,"kind":"常识","alias":["北交所","BSE"],"one":"2021年11月15日开市，我国第三家证券交易所，服务创新型中小企业。","ans":"北京证券交易所（北交所）是我国内地**第三家全国性证券交易所**，基于新三板精选层组建。北交所于**2021年11月15日**开市，实行公司制，聚焦服务**创新型中小企业**与**“专精特新”**企业，完善了多层次资本市场体系。","pts":["2021年11月15日正式开市","定位服务创新型中小企业与“专精特新”","内地继沪、深后的第三家证券交易所"],"mem":"三交所年份串记：1990年12月深交所（1日）与上交所（19日）同年开业，隔31年后2021年11月北交所开市，服务中小企业。","mix":"上交所、深交所为会员制交易所，北交所是中国内地首家实行公司制的证券交易所，且源自新三板精选层平移升级。","mcq":[{"q":"2021年11月15日正式开市的北京证券交易所，其核心市场定位是服务","o":["创新型中小企业","大型国有蓝筹企业","跨国金融机构","境外红筹回归企业"],"a":0,"w":"北京证券交易所聚焦“更早、更小、更新”，核心定位是服务创新型中小企业特别是“专精特新”企业。"}],"rel":[{"t":"上海证券交易所","n":"内地三大证交所之一"},{"t":"深圳证券交易所","n":"内地三大证交所之一"},{"t":"股票发行注册制","n":"北交所开市即全面实行注册制"}],"more":"2021年9月2日中国宣布设立北京证券交易所，9月3日注册成立，11月15日正式开市交易。","exam":[]},{"id":"b13-053","t":"风险投资","cid":"13d","p":2,"kind":"概念","alias":["VC","创业投资","Venture Capital"],"one":"简称VC，向高成长初创企业投入股权资本并参与管理，高风险高回报，晚于天使投资。","ans":"风险投资（Venture Capital，简称**VC**）又称创业投资，指专业机构向**高成长性初创企业**提供**股权资本**并参与管理的权益性投资。它晚于**天使投资**，重点支持尚未盈利的科技企业，不取固定利息，待企业成长后经**IPO或并购退出**获高回报。VC起源于20世纪中叶美国硅谷，是孵化科技企业与培育**“耐心资本”**的重要力量。","pts":["简称VC，向高成长初创企业提供股权资本并参与管理","处于天使投资之后，通过IPO或并购实现退出获利","高风险高回报，孵化科技创新与培育“耐心资本”"],"mem":"企业融资接力棒：“种子/天使投资（个人投点子，最早）→ 风险投资VC（机构投成长，A/B/C轮）→ 私募股权PE（投成熟冲刺）→ IPO上市（面向公众）”。","mix":"**天使投资**由富裕个人或天使基金在创意种子期介入，金额较小、阶段最早；**风险投资（VC）**由专业机构管理基金，在初创成长期介入、金额更大，选择题常考二者阶段先后。","mcq":[{"q":"按创业企业常规融资生命周期从早到晚排列，顺序正确的是","o":["风险投资 → 天使投资 → IPO上市","IPO上市 → 风险投资 → 天使投资","天使投资 → IPO上市 → 风险投资","天使投资 → 风险投资 → IPO上市"],"a":3,"w":"创业企业通常先获天使投资（种子期），再获风险投资VC（成长期），成熟后通过IPO公开发行股票上市。"}],"rel":[{"t":"天使投资","n":"更早阶段的个人早期投资"},{"t":"首次公开募股（IPO）","n":"风险投资的主要退出渠道"},{"t":"独角兽企业","n":"VC重点孵化的高估值企业"},{"t":"耐心资本","n":"近年强调的长期创投理念"}],"more":"关键区分：VC（Venture Capital，风险投资，偏初创成长期）与 PE（Private Equity，私募股权投资，偏中后期成熟企业）。","exam":[]},{"id":"b13-054","t":"独角兽企业","cid":"13d","p":2,"kind":"概念","alias":["独角兽","Unicorn"],"one":"成立时间短、估值超10亿美元的未上市创业公司，2013年由艾琳·李提出。","ans":"独角兽企业指**成立时间较短（通常不超过10年）**、**估值超过10亿美元**且**尚未上市**的创业公司，2013年由美国投资人**艾琳·李**提出。她借神话独角兽比喻稀有且具爆发成长力的科技新锐；估值超100亿美元称**“超级独角兽”**。独角兽多集中于AI、芯片、新能源与生物医药赛道，是衡量区域创新生态与**新质生产力**的风向标。","pts":["成立时间短、估值超10亿美元的未上市创业公司","2013年由美国风投人艾琳·李首次提出","多集中前沿科技赛道，衡量区域创新生态活跃度"],"mem":"三条件口诀：“短、十、未”（成立时间短≤10年、估值超10亿美元、尚未上市）。记住神兽升级：10亿=独角兽，100亿=超级独角兽（十角兽）。","mix":"判断是否为独角兽有两条硬杠杠：**估值超10亿美元**且**尚未上市**；一旦完成IPO上市（或成立年限过长），一般即“毕业”退出独角兽榜单，与“瞪羚企业”（高成长中小企业，估值门槛低）不同。","mcq":[{"q":"资本市场中“独角兽企业”最核心的估值与上市状态界定标准是","o":["估值超过1亿美元、已上市企业","估值超过10亿美元、未上市创业公司","估值超过100亿美元、已上市科技股","年营收超过10亿元人民币的国有企业"],"a":1,"w":"独角兽企业指成立时间较短（通常10年以内）、估值超过10亿美元且尚未上市的创业公司。"}],"rel":[{"t":"风险投资","n":"独角兽背后的主要资本"},{"t":"首次公开募股（IPO）","n":"独角兽毕业上市的主要方式"},{"t":"新质生产力","n":"独角兽集中的前沿方向"},{"t":"科创板","n":"服务硬科技独角兽上市"}],"more":"相关概念区分：独角兽（估值>10亿美元未上市）、超级独角兽（估值>100亿美元未上市）、瞪羚企业（跨过创业初期后高速成长的中小企业）。","exam":[]},{"id":"b13-055","t":"中国加入世贸组织","cid":"13h","p":1,"kind":"事件","alias":["中国入世","加入世贸组织","入世"],"one":"2001年12月11日中国成为世贸组织第143个成员，2026年25周年。","ans":"中国加入世贸组织是**2001年12月11日中国正式成为世界贸易组织第143个成员**，结束了自1986年申请恢复关贸总协定缔约国地位以来**长达15年的谈判**。入世后中国按承诺大幅降低关税、开放服务业市场，同时推动国内法律法规与国际规则接轨。入世释放了**出口和外资增长的红利，促成中国融入全球产业链、成为“世界工厂”**，对外贸易总额和国内生产总值快速上升，中国成为世界第二大经济体。2026年是入世25周年。","pts":["2001年12月11日成为第143个成员","1986年申请复关，谈判15年","降关税开放市场，融入全球产业链"],"mem":"数字“一四三”，日期“十二月十一日”，口诀“零一年十二月，一四三”。谈判时间“八六到零一，十五年”。","mix":"世界贸易组织1995年成立，不是1947年；1947年的是关贸总协定（GATT），前身。入世谈判通过是2001年11月多哈会议，正式成员是12月11日。","mcq":[{"q":"中国正式加入世界贸易组织的时间是","o":["2001年12月","1995年1月","1999年11月","2008年8月"],"a":0,"w":"2001年12月11日，第143个成员。"},{"q":"中国加入世贸组织时是第几个成员","o":["第100个","第143个","第152个","第164个"],"a":1,"w":"第143个成员。"}],"rel":[{"t":"世界贸易组织","n":"所加入的组织"},{"t":"区域全面经济伙伴关系协定（RCEP）","n":"此后的区域自贸安排"},{"t":"世界第二大经济体","n":"入世后的成就"},{"t":"中国国际进口博览会","n":"对外开放平台"}],"more":"2026年为中国入世25周年；2001年11月10日多哈部长级会议通过中国入世决定。","exam":[]},{"id":"b13-056","t":"联合国第2758号决议","cid":"13h","p":2,"kind":"事件","alias":["联大第2758号决议","恢复中国在联合国合法席位"],"one":"1971年10月25日第26届联大通过，恢复中国在联合国一切合法权利。","ans":"联合国第2758号决议是**1971年10月25日第26届联大**通过的历史性决议。它决定**恢复中华人民共和国在联合国的一切合法权利**，承认中华人民共和国政府代表是**中国在联合国的唯一合法代表**，并驱逐台湾当局代表。该决议从政治、法律和程序上彻底解决全中国在联合国的代表权问题，体现了**一个中国原则**，2026年正值通过55周年。","pts":["1971年10月25日第26届联大通过","恢复中国在联合国一切合法权利","承认唯一合法代表，体现一个中国原则"],"mem":"数字串联法：“71年，26届，2758号，恢复而非重返”。注意措辞是“恢复”合法权利，因为中国本就是1945年联合国创始会员国。2026年恰逢该决议通过55周年。","mix":"选择题常设陷阱：把“恢复合法权利”偷换成“新加入联合国”，或把时间1971年与中美建交（1979年）、尼克松访华（1972年）混淆。","mcq":[{"q":"1971年10月25日第26届联合国大会通过第2758号决议，其核心内容是","o":["批准中华人民共和国正式加入联合国","恢复中华人民共和国在联合国的一切合法权利","将中文正式列为联合国工作语言","决定在纽约设立联合国总部"],"a":1,"w":"中国是联合国创始会员国，第2758号决议是“恢复”中华人民共和国的一切合法权利。"}],"rel":[{"t":"联合国","n":"中国为创始会员国"},{"t":"尼克松访华","n":"次年1972年中美破冰"},{"t":"中美三个联合公报","n":"同涉一个中国原则"},{"t":"《开罗宣言》与《波茨坦公告》","n":"战后台湾归属法理源头"}],"more":"表决结果：76票赞成、35票反对、17票弃权。2026年10月25日为该决议通过55周年。","exam":[]},{"id":"b13-057","t":"金砖国家","cid":"13h","p":2,"kind":"制度","alias":["BRICS","金砖国家合作机制","大金砖合作"],"one":"新兴市场和发展中国家合作机制，初为巴俄印中，经2024至2025年扩员至11国。","ans":"金砖国家（BRICS）是**新兴市场国家和发展中国家**合作机制，2006年开启外长会晤。初为**巴西、俄罗斯、印度、中国**，2010年南非加入；2024年1月沙特、埃及、阿联酋、伊朗、埃塞俄比亚加入，2025年1月**印度尼西亚**成为正式成员，达**11个正式成员国**并设“伙伴国”机制。其**新开发银行**总部在上海，推动全球治理改革。","pts":["初为巴俄印中，2010年南非加入成五国","2024至2025年扩员至11个正式成员国","设伙伴国机制，新开发银行总部在上海"],"mem":"英文首字母口诀：B巴西、R俄罗斯、I印度、C中国、S南非（2010）；2024扩员记“中东三强加非二”（沙特、阿联酋、伊朗，埃及、埃塞俄比亚）；2025加东南亚首位印尼，合共11国。","mix":"阿根廷虽在2023年获邀但随后撤回入会申请，不属于金砖成员；沙特曾慎重评估入会程序，按中国外交部口径位列11个正式成员国；马来西亚、泰国、越南等为2024年底后增设的“伙伴国”。","mcq":[{"q":"2025年1月正式成为金砖国家成员国、也是首个加入该机制的东南亚国家是","o":["印度尼西亚","越南","马来西亚","泰国"],"a":0,"w":"2025年1月印度尼西亚成为金砖正式成员国；马来西亚、泰国、越南为金砖伙伴国。"}],"rel":[{"t":"全球南方","n":"金砖扩员代表其崛起"},{"t":"二十国集团","n":"同为重要国际经济机制"},{"t":"七国集团","n":"与发达国家机制对照"},{"t":"亚洲基础设施投资银行","n":"同为新兴多边金融机构"}],"more":"2026年恰逢金砖合作机制成立20周年；2026年9月12日至13日，印度新德里举办第十八次金砖国家领导人峰会。","exam":[]},{"id":"b13-058","t":"二十国集团","cid":"13h","p":2,"kind":"制度","alias":["G20","二十国集团峰会"],"one":"1999年成立的国际经济合作主要论坛，由19国加欧盟、非盟组成。","ans":"二十国集团（G20）是**国际经济合作主要论坛**，**1999年**成立时为财长和央行行长会议。**2008年国际金融危机**后升格为领导人峰会，成员含中、美、俄等**19国加欧盟与非洲联盟**（2023年新德里峰会加入），兼顾发达与新兴经济体。**2016年杭州峰会**推动世界经济结构性改革，G20在全球宏观经济协调中发挥核心作用。","pts":["1999年成立，2008年升格为领导人峰会","成员为19国加欧盟与2023年加入的非盟","2016年杭州峰会；国际经济合作主要论坛"],"mem":"数字演化法：名字叫G20，最初是19国+1欧盟=20；2023年非盟加入后变成“19国+2盟”=21席，名字沿用G20。记住三大年份：1999成立、2008升格、2016杭州。","mix":"G20由19个主权国家加欧盟、非盟两个区域组织共同构成，切勿误以为全是主权国家；G7只含西方七个发达国家，G20则囊括中印巴等主要新兴市场国家。","mcq":[{"q":"2023年新德里峰会正式接纳为二十国集团（G20）永久成员的区域组织是","o":["东南亚国家联盟","上海合作组织","非洲联盟","阿拉伯国家联盟"],"a":2,"w":"2023年9月G20新德里峰会接纳非洲联盟为永久成员，使其成为继欧盟后的第二个区域组织成员。"}],"rel":[{"t":"二十国集团杭州峰会","n":"2016年中国主场峰会"},{"t":"2026年二十国集团峰会","n":"2026年美国迈阿密主办"},{"t":"七国集团","n":"发达国家机制对照"},{"t":"2008年国际金融危机","n":"促成峰会机制升格"}],"more":"2025年南非约翰内斯堡举办非洲首次G20峰会；2026年12月美国在迈阿密主办G20峰会。","exam":[]},{"id":"b13-059","t":"北约","cid":"13i","p":2,"kind":"制度","alias":["北大西洋公约组织","NATO"],"one":"1949年成立的西方军事同盟，总部布鲁塞尔，2024年瑞典加入后达32国。","ans":"北大西洋公约组织（简称北约，NATO）是**1949年4月**美、英、法等12国签约成立的**西方军事政治同盟**，总部在**比利时布鲁塞尔**。其核心为公约**第五条集体防御条款**，即攻击一国视同攻击全体。冷战后北约多轮东扩，**2023年芬兰、2024年瑞典**先后加入，截至2026年共**32个成员国**，深刻影响欧洲安全格局。","pts":["1949年成立的西方军事同盟，总部布鲁塞尔","核心机制为第五条集体防御条款","冷战后持续东扩，2024年瑞典加入后共32国"],"mem":"数字记忆：“49年12国起家，核心第5条，23芬兰31、24瑞典32”。顺便打包记：欧盟总部与北约总部都在比利时布鲁塞尔。","mix":"北约是1949年成立的军事同盟（32国），欧盟是1993年成立的政治经济一体化组织（27国）；成员并不完全重合，如美国、加拿大、英国、土耳其属北约而不属欧盟。","mcq":[{"q":"2024年3月正式加入北大西洋公约组织，使其成员国总数达到32个的国家是","o":["瑞典","芬兰","乌克兰","瑞士"],"a":0,"w":"芬兰于2023年4月成为第31个北约成员国，瑞典于2024年3月成为第32个成员国。"}],"rel":[{"t":"冷战","n":"冷战军事对抗产物"},{"t":"欧盟","n":"总部同在布鲁塞尔"},{"t":"马歇尔计划","n":"美国对西欧的经军配合"},{"t":"雅尔塔体系","n":"战后欧洲格局演进背景"}],"exam":[]},{"id":"b13-060","t":"欧盟","cid":"13h","p":2,"kind":"制度","alias":["欧洲联盟","EU"],"one":"1993年依《马斯特里赫特条约》成立的欧洲政治经济一体化组织，总部布鲁塞尔。","ans":"欧洲联盟（EU）由欧共体演进为**区域性政治经济一体化组织**，总部在**布鲁塞尔**。**1993年11月《马斯特里赫特条约》生效**后正式成立，**1999年欧元启用**、2002年现钞流通。2020年英国脱欧后现有**27个成员国**，2026年保加利亚加入欧元区后共21国用欧元。欧盟是一体化程度最高的区域组织，也是世界多极化重要一极。","pts":["1993年马斯特里赫特条约生效成立，总部布鲁塞尔","1999年启用欧元；2026年欧元区增至21国","英国脱欧后现27国，一体化程度最高区域组织"],"mem":"时间链串联：1951煤钢共同体→1967欧共体→1993马约建欧盟→1999欧元上账→2020英国脱欧剩27国→2026保加利亚进欧元区满21国。","mix":"欧盟27国并非全用欧元，瑞典、波兰、丹麦等6国仍用本币；欧洲理事会、欧盟理事会、欧盟委员会和欧洲议会职能各异，且欧盟总部与北约总部同在布鲁塞尔。","mcq":[{"q":"标志欧洲联盟正式成立的法律文件是1993年生效的","o":["《罗马条约》","《申根协定》","《里斯本条约》","《马斯特里赫特条约》"],"a":3,"w":"1992年签署、1993年11月生效的《马斯特里赫特条约》（《欧洲联盟条约》）标志欧盟正式成立。"}],"rel":[{"t":"欧元与英国脱欧","n":"货币统一与成员变动"},{"t":"北约","n":"总部同在布鲁塞尔"},{"t":"欧盟《人工智能法》","n":"欧盟数字治理立法"},{"t":"多极化","n":"多极世界中的重要一极"}],"more":"2026年1月1日保加利亚正式采用欧元，成为第21个欧元区成员国。","exam":[]},{"id":"b13-061","t":"共和党","cid":"13j","p":3,"kind":"制度","exam":["2016名解"],"alias":["GOP","老大党"],"one":"美国两大政党之一，1854年成立，林肯为首任总统，以大象为象征。","ans":"共和党是**美国两党制**主要政党之一，又称**“老大党”（GOP）**，象征为**大象**。该党**1854年**以反奴隶制扩张成立，**林肯**是首位共和党总统，与以驴为象征的民主党轮替执政。当代立场偏保守，主张**小政府、低税收与强国防**，深刻影响美国政治。","pts":["1854年成立，又称老大党（GOP），象征大象","林肯为第一位共和党总统","立场偏保守，主张小政府、低税收、强国防"],"mem":"“驴象之争”记对应：民主党=驴（蓝），共和党=象（红、GOP）；林肯出身共和党，1854建党反奴隶制。","mix":"历史上共和党最初是北方反奴隶制政党，20世纪中期后两党基本盘重组，共和党转为右翼保守、民主党偏自由派。","mcq":[{"q":"关于美国共和党，下列表述不正确的是","o":["党徽象征为驴","成立于1854年","林肯是第一位共和党总统","又称“老大党”（GOP）"],"a":0,"w":"共和党象征为大象，民主党象征才是驴。"}],"rel":[{"t":"民主党与两党制","n":"美国另一执政党与两党体制"},{"t":"美国南北战争与林肯","n":"首位共和党总统林肯"},{"t":"艾森豪威尔","n":"战后著名共和党总统"}]},{"id":"b13-062","t":"艾森豪威尔","cid":"13j","p":3,"kind":"人物","exam":["2016名解"],"alias":["德怀特·艾森豪威尔"],"one":"美国第34任总统、二战欧洲盟军最高统帅，卸任时警告“军工复合体”。","ans":"艾森豪威尔是**美国第34任总统**（1953–1961，共和党）与著名军事家。二战时任**欧洲盟军最高统帅**，指挥**诺曼底登陆**；总统任内结束朝鲜战争，推行“艾森豪威尔主义”并修建州际公路网。其卸任演说警告**“军工复合体”**，影响深远。","pts":["二战欧洲盟军最高统帅，指挥诺曼底登陆","美国第34任共和党总统，任内结束朝鲜战争","建州际公路网，卸任警告“军工复合体”"],"mem":"三段身份线：战时指挥诺曼底 → 任内停朝战修高速 → 卸任留金句“警惕军工复合体”。","mix":"“杜鲁门主义”针对欧洲冷战遏制（1947），“艾森豪威尔主义”则于1957年针对中东填补英法退出的权力真空。","mcq":[{"q":"二战中指挥诺曼底登陆、卸任美国总统时警告警惕“军工复合体”的是","o":["富兰克林·罗斯福","哈里·杜鲁门","肯尼迪","艾森豪威尔"],"a":3,"w":"艾森豪威尔曾任欧洲盟军最高统帅，1961年卸任演说中提出警惕“军工复合体”。"}],"rel":[{"t":"第二次世界大战","n":"指挥诺曼底登陆的战场"},{"t":"共和党","n":"所属政党"},{"t":"抗美援朝战争","n":"1953年其任内签署停战协定"},{"t":"杜鲁门主义","n":"前任总统冷战政策对照"}]},{"id":"b13-063","t":"孤立主义","cid":"13j","p":3,"kind":"概念","exam":["2016名解"],"one":"主张不卷入欧洲政治纷争与军事同盟的美国外交传统，珍珠港事件后衰落。","ans":"孤立主义是美国历史重要**外交传统**，主张**不卷入欧洲政治纷争与军事同盟**。它源于**华盛顿告别演说**和**1823年门罗主义**，一战后美国拒入**国际联盟**、30年代通过《中立法》。**1941年珍珠港事件**后美国参战，孤立主义随之衰落。","pts":["不卷入欧洲纷争与军事同盟的外交传统","源于华盛顿告别演说、门罗主义，拒入国联","1941年珍珠港事件后衰落"],"mem":"兴衰四节点：华盛顿告别演说开端 → 门罗主义巩固 → 拒入国联达顶峰 → 1941珍珠港事件终结主流地位。","mix":"孤立主义并非“闭关锁国”，美国同期仍积极扩大海外贸易并干涉拉美与亚太事务，只是回避卷入欧洲同盟战事。","mcq":[{"q":"导致美国传统孤立主义迅速衰落并全面投入第二次世界大战的直接事件是","o":["凡尔赛和约签署","1929年经济大危机","1941年珍珠港事件","古巴导弹危机"],"a":2,"w":"1941年12月日本偷袭珍珠港后美国正式对日宣战，传统孤立主义随之衰落。"}],"rel":[{"t":"门罗主义","n":"孤立主义的重要理论渊源"},{"t":"珍珠港事件","n":"孤立主义衰落的转折点"},{"t":"门户开放政策","n":"美国同期在亚太的扩张政策"}],"alias":[]},{"id":"b13-064","t":"鹰鸽之争","cid":"13j","p":3,"kind":"概念","exam":["2017名解"],"alias":["鹰派与鸽派"],"one":"政治上指强硬与温和之争，货币政策上指紧缩抗通胀与宽松稳增长之争。","ans":"鹰鸽之争是**政治外交与货币政策**常用分析概念，以鹰、鸽象征两种对立立场。政治上**鹰派**主强硬动武、**鸽派**主温和谈判；经济上鹰派重抗通胀、倾向**加息紧缩**，鸽派重就业增长、倾向**宽松降息**，常用于预判大国政策走向。","pts":["政治层面：鹰派主强硬动武，鸽派主谈判妥协","货币层面：鹰派抗通胀加息，鸽派稳增长宽松","用于分析外交与央行政策分歧"],"mem":"形象记忆：鹰凶猛（外交强硬、金融狠手加息压通胀）；鸽温顺（外交讲和、金融放水降息护就业）。","mix":"名解作答切忌只写外交军事含义，务必补足美联储等央行货币政策中“鹰派加息、鸽派宽松”的第二层含义。","mcq":[{"q":"在中央银行货币政策语境下，“鹰派”官员通常更倾向于","o":["降息刺激就业","加息抑制通货膨胀","扩大财政赤字","放松金融监管"],"a":1,"w":"货币政策中鹰派重视控制通胀、倾向收紧与加息；鸽派重视增长就业、倾向宽松。"}],"rel":[{"t":"货币政策","n":"经济领域鹰鸽之争核心场域"},{"t":"通货膨胀与通货紧缩","n":"鹰派货币政策主要针对通胀"},{"t":"地缘政治","n":"外交领域鹰鸽博弈背景"}]},{"id":"b13-065","t":"参议院与众议院","cid":"13j","p":2,"kind":"制度","exam":["2017名解"],"alias":["美国国会两院","参众两院"],"one":"美国国会两院：参议院100席任期6年，众议院435席任期2年。","ans":"参议院与众议院共同组成**美国国会**，体现**1787年宪法**大小州妥协与权力制衡。**参议院**每州2名共100名议员，任期**6年**，每两年改选三分之一，副总统兼议长，有权**批准条约和高级官员任命**；**众议院**按人口分配共435名议员，任期**2年**，议员选议长，有权**提出财政法案和弹劾案**。两院相互制约，构成美国联邦立法核心。","pts":["参议院每州2名共100席，任期6年，副总统兼议长","众议院按人口分共435席，任期2年，议员选议长","参院批条约与任命，众院提财政法案与弹劾案"],"mem":"对比口诀：“参小稳，众大频”。参院人少（100）任期长（6年），管对外条约与人事大权；众院人多（435）换得勤（2年一改选），管钱袋子（财政案）和起诉弹劾。","mix":"弹劾程序两院分工常考：众议院负责“提出弹劾案”（起诉），参议院负责“审理弹劾案”（定罪需三分之二赞成）；人数和任期切忌颠倒。","mcq":[{"q":"关于美国国会参议院与众议院的职权与构成，下列说法正确的是","o":["参议院议员按各州人口比例分配，共435名","众议院议长由美国副总统兼任","参议院议员任期2年，每两年全部改选","参议院拥有批准条约和高级官员任命的权力，众议院拥有提出财政法案和弹劾案的权力"],"a":3,"w":"参议院每州2名共100人、任期6年、副总统兼议长、批条约与任命；众议院435人、任期2年、提财政与弹劾案。"}],"rel":[{"t":"三权分立","n":"国会行使联邦立法权"},{"t":"美国宪法","n":"确立两院制的法律依据"},{"t":"美国中期选举","n":"每两年改选全众院及1/3参院"},{"t":"英国议会的起源","n":"英美两院制历史源流对照"}]},{"id":"b13-066","t":"国务卿","cid":"13j","p":3,"kind":"制度","exam":["2013名解"],"alias":["美国国务卿"],"one":"美国国务院首长，相当于外交部长，居内阁之首、总统继任顺序第四。","ans":"国务卿是**美国国务院最高首长**，属联邦政府行政体系核心内阁成员。其职责相当于他国**外交部长**，主管对外事务，位居**内阁各部长之首**，在总统继任顺序中排**第四位**。马歇尔、基辛格等著名国务卿均深刻影响了美国外交走向。","pts":["美国国务院首长，相当于外交部长","位居内阁排名第一，总统继任顺序第四","著名人物有马歇尔、基辛格等"],"mem":"顺位口诀“副众参国”：总统继任顺位1副总统、2众议长、3参议院临时议长、4国务卿，记住是“外交部长”非“总理”。","mix":"中文直译易让人误以为美国“国务院”像中国国务院一样管内政，其实美国国务院专管外交，国务卿即外长。","mcq":[{"q":"美国国务卿的职能主要相当于其他国家的","o":["外交部长","政府总理","国防部长","内政部长"],"a":0,"w":"美国国务院主管对外关系，国务卿相当于外交部长，是内阁排名第一的部长。"}],"rel":[{"t":"基辛格","n":"促成中美破冰的著名国务卿"},{"t":"马歇尔计划","n":"国务卿马歇尔提出的冷战计划"},{"t":"三权分立","n":"国务卿隶属美国行政分支"}]},{"id":"b13-067","t":"基辛格","cid":"13j","p":3,"kind":"人物","exam":["2013名解"],"alias":["亨利·基辛格"],"one":"美国现实主义外交家、前国务卿，1971年秘密访华推动中美关系正常化。","ans":"亨利·基辛格（1923–2023）是美国著名**现实主义外交家**，曾任国家安全事务助理和**国务卿**。他于**1971年7月秘密访华**，促成尼克松访华与**《上海公报》**，1973年获诺贝尔和平奖，著有《论中国》，是中美关系正常化关键推动者。","pts":["美国外交家，曾任国安助理与国务卿","1971年7月秘密访华，促成《上海公报》","1973年获诺贝尔和平奖，著有《论中国》"],"mem":"记“1971秘密访华→1972上海公报→1973诺贝尔和平奖”，外加百岁人生（1923–2023）和代表作《论中国》。","mix":"1971年秘密访华时基辛格的身份是总统国家安全事务助理，1973年才出任国务卿。","mcq":[{"q":"1971年7月秘密访华、为尼克松访华与中美《上海公报》铺路的美国外交家是","o":["乔治·马歇尔","乔治·凯南","亨利·基辛格","布热津斯基"],"a":2,"w":"基辛格于1971年7月秘密访华，促成次年尼克松访华与《上海公报》签署。"}],"rel":[{"t":"尼克松访华","n":"基辛格秘密访华直接促成"},{"t":"《上海公报》","n":"1972年中美破冰核心文件"},{"t":"国务卿","n":"1973至1977年担任该职"},{"t":"乒乓外交","n":"1971年中美破冰的民间前奏"}]},{"id":"b13-068","t":"尼克松访华","cid":"13j","p":2,"kind":"事件","exam":["2010选择"],"alias":["破冰之旅","1972年尼克松访华"],"one":"1972年2月美国总统尼克松访华并在上海签署《上海公报》，开启中美正常化。","ans":"尼克松访华指**1972年2月**美国总统尼克松应邀访华，成为**首位访问新中国的美国在任总统**。此前1971年“乒乓外交”和**基辛格秘密访华**铺平道路；访华期间尼克松会见毛泽东、周恩来，双方在上海签署**《中美联合公报》（《上海公报》）**，美方承认一个中国。此访打破中美隔绝，开启关系正常化，为**1979年1月1日中美建交**奠基。","pts":["1972年2月访华，首位访华美国在任总统","在上海签署《中美联合公报》（《上海公报》）","打破中美隔绝，为1979年正式建交奠基"],"mem":"中美破冰三连跳：“71乒乓+基辛格秘访→72尼克松签《上海公报》→79元旦正式建交”。上海考点绑定：《上海公报》在上海锦江小礼堂签署。","mix":"1972年尼克松访华标志中美关系开始“走向正常化”，尚未正式建交；正式建交时间是1979年1月1日（卡特总统时期，签署《建交公报》）。","mcq":[{"q":"1972年2月尼克松访华期间，中美两国政府在上海发表的重要外交文件是","o":["《中美建交公报》","《中美联合公报》（《上海公报》）","《八一七公报》","《开罗宣言》"],"a":1,"w":"1972年2月28日双方在上海签署《上海公报》；《建交公报》为1978年底发表，《八一七公报》为1982年发表。"}],"rel":[{"t":"《上海公报》","n":"此访签署的核心文件"},{"t":"中美三个联合公报","n":"《上海公报》居首"},{"t":"基辛格","n":"1971年秘密访华铺路人"},{"t":"乒乓外交","n":"小球转动大球的前奏"}]},{"id":"b13-069","t":"罗斯福","cid":"13j","p":3,"kind":"人物","exam":["2010选择"],"alias":["富兰克林·罗斯福","小罗斯福","FDR"],"one":"美国唯一连任四届的总统（1933–1945），推行“新政”并领导二战反法西斯。","ans":"富兰克林·罗斯福（1882–1945）是**美国第32任总统**（民主党），俗称**“小罗斯福”**，为美国唯一**连任四届总统**（1933–1945）。他推行**“罗斯福新政”**应对大萧条，领导美国二战胜利，战后美修宪限制总统连任不超两届。","pts":["富兰克林·罗斯福，美国唯一连任四届总统","实行“罗斯福新政”应对1929年大萧条","领导美国二战胜利，战后修宪限任两届"],"mem":"数字“32与4”：第32任、唯一连任4届（1933–1945，第四任刚开局便病逝）；“新政救危机、炉边谈话稳民心”。","mix":"注意区分“老罗斯福”（西奥多·罗斯福，第26任，共和党，大棒政策）与“小罗斯福”（富兰克林·罗斯福，第32任，民主党，新政与四连任）。","mcq":[{"q":"美国历史上唯一连续当选四届的总统是","o":["乔治·华盛顿","西奥多·罗斯福","富兰克林·罗斯福","伍德罗·威尔逊"],"a":2,"w":"富兰克林·罗斯福（小罗斯福）在1932、1936、1940、1944年四次当选美国总统。"}],"rel":[{"t":"大萧条与罗斯福新政","n":"应对经济大危机的核心举措"},{"t":"雅尔塔体系","n":"与丘吉尔、斯大林共塑战后格局"},{"t":"1929至1933年经济大危机","n":"就任总统时的历史背景"}]},{"id":"b13-070","t":"门罗主义","cid":"13j","p":3,"kind":"概念","one":"1823年美国总统门罗提出“美洲是美洲人的美洲”，反对欧洲干涉美洲。","ans":"门罗主义是**1823年**美国第5任总统**门罗**在国情咨文中提出的外交原则，属美国早期**外交思想基石**。核心口号为**“美洲是美洲人的美洲”**，反对欧洲在美洲殖民干涉，同时声明不卷入欧洲事务。后逐渐演变为美国独霸西半球的扩张工具。","pts":["1823年美国总统门罗在国情咨文中提出","核心口号“美洲是美洲人的美洲”","先反对欧洲干涉，后沦为美国控制拉美工具"],"mem":"一句话抓内核：“欧洲别管美洲，美国也不管欧洲”，1823年门罗画下西半球红线，实为美国把拉美视作后院。","mix":"门罗主义（1823）针对拉丁美洲，主张排斥欧洲势力；门户开放政策（1899）针对中国，主张列强利益均沾。","mcq":[{"q":"1823年提出“美洲是美洲人的美洲”、反对欧洲列强干涉美洲事务的美国外交原则是","o":["门户开放政策","门罗主义","马歇尔计划","杜鲁门主义"],"a":1,"w":"1823年美国总统詹姆斯·门罗提出门罗主义，反对欧洲列强干涉西半球事务。"}],"rel":[{"t":"孤立主义","n":"与门罗主义一脉相承"},{"t":"门户开放政策","n":"19世纪美国两大标志外交政策"},{"t":"拉丁美洲独立运动","n":"门罗主义提出的历史背景"}],"exam":[],"alias":[]},{"id":"b13-071","t":"伊斯兰国","cid":"13i","p":3,"kind":"事件","exam":["2016名解"],"alias":["ISIS","ISIL"],"one":"中东极端恐怖组织，2014年在伊叙宣布“建国”，2017至2019年被基本击溃。","ans":"伊斯兰国（ISIS/ISIL）是中东**极端恐怖组织**，源于伊拉克“基地”分支。**2014年**该组织趁伊拉克和叙利亚战乱夺地宣布“建国”，制造多起恐袭。经多国联合反恐，**2017至2019年**其武装据点被基本击溃，残余仍威胁安全。","pts":["中东极端恐怖组织，简称ISIS或ISIL","2014年在伊拉克、叙利亚宣布“建国”","2017至2019年主力据点被基本击溃"],"mem":"时间三点记：2014乱中“建国” → 2016成热点入真题 → 2017至2019被联军清剿击溃。","mix":"“伊斯兰国”是联合国和国际社会普遍认定的极端恐怖组织，不具备主权国家地位，与正常伊斯兰教信仰截然不同。","mcq":[{"q":"极端恐怖组织“伊斯兰国”宣布在伊拉克和叙利亚境内“建国”的年份是","o":["2001年","2011年","2014年","2019年"],"a":2,"w":"该组织2014年宣布“建国”，2017至2019年其控制区被基本收复。"}],"rel":[{"t":"“9·11”事件","n":"同簇国际反恐关键事件"},{"t":"伊斯兰教","n":"需严格区分正常宗教与极端组织"},{"t":"地缘政治","n":"中东动荡与大国博弈产物"}]},{"id":"b13-072","t":"加利福尼亚","cid":"13j","p":3,"kind":"地理","exam":["2017名解"],"alias":["加州","加利福尼亚州"],"one":"美国人口与经济第一大州，1848年归美、1850年建州，坐拥硅谷与好莱坞。","ans":"加利福尼亚简称**加州**，位于美国西海岸，是美国**人口最多、经济总量第一**的州，首府萨克拉门托。**1848年美墨战争**后归美，1850年建州，因**淘金热**兴起。境内汇聚**硅谷**与**好莱坞**，是美国科技、文化与贸易高地。","pts":["美国人口最多、经济总量第一的州","1848年美墨战争后归美，1850年建州","淘金热兴起，坐拥硅谷与好莱坞"],"mem":"加州三张名片“金、硅、影”：19世纪淘金热（别称“金州”）、北加州硅谷、南加州洛杉矶好莱坞。","mix":"加州首府是萨克拉门托，并非洛杉矶或旧金山；美国面积最大州是阿拉斯加，人口最多州才是加利福尼亚。","mcq":[{"q":"关于美国加利福尼亚州，下列表述正确的是","o":["1848年美墨战争后归属美国","美国面积最大的州","首府为洛杉矶","由美国从俄国购得"],"a":0,"w":"加州1848年美墨战争后归美、1850年建州，人口全美第一；面积最大且购自俄国的是阿拉斯加。"}],"rel":[{"t":"硅谷与华尔街","n":"硅谷位于加州旧金山湾区"},{"t":"阿拉斯加","n":"同届真题并考的美国大州"},{"t":"奥斯卡金像奖","n":"加州好莱坞电影产业标志"}]},{"id":"b13-073","t":"阿拉斯加","cid":"13j","p":3,"kind":"地理","exam":["2017名解"],"alias":["阿拉斯加州"],"one":"1867年美国720万美元购自俄国，1959年成第49州，美国面积最大州。","ans":"阿拉斯加位于北美西北端，是美国**面积最大的州**，属本土外飞地，隔白令海峡望俄罗斯。**1867年**美国以**720万美元**从沙俄购得，**1959年**成为美国**第49个州**。该州油气与渔业资源丰厚，在北极航道与大国地缘博弈中战略地位突出。","pts":["1867年美国以720万美元购自沙俄","1959年成为美国第49州","美国面积最大的州，具北极战略价值"],"mem":"故事记忆：1867年国务卿西沃德花720万美元买下，当时被嘲笑为“西沃德的大冰箱”，后来挖出黄金与石油成大赢家。","mix":"美国两个非本土州同于1959年建州：阿拉斯加第49州（面积最大），夏威夷第50州。","mcq":[{"q":"1867年美国以720万美元购得阿拉斯加时，出售方是","o":["英国","法国","西班牙","沙皇俄国"],"a":3,"w":"沙皇俄国因克里米亚战争后财政拮据，于1867年将阿拉斯加售予美国。"}],"rel":[{"t":"加利福尼亚","n":"同届真题常与人口第一州对照"},{"t":"地缘政治","n":"北极圈与白令海峡战略要地"}]},{"id":"b13-074","t":"哈佛大学","cid":"13j","p":3,"kind":"常识","exam":["2013名解"],"alias":["哈佛"],"one":"1636年建于马萨诸塞州剑桥市，美国最古老高校、常春藤盟校核心成员。","ans":"哈佛大学位于美国马萨诸塞州剑桥市，创立于**1636年**，是美国**历史最悠久的高等学府**，属**常春藤盟校**核心成员。校名源于捐赠者约翰·哈佛，以校训**“真理”**闻名。该校培养了多位美国总统与诺奖得主，在全球科研与高教界享有崇高声誉。","pts":["1636年建立，美国历史最悠久的高等学府","位于马萨诸塞州剑桥市，常春藤盟校成员","校训“真理”，培养多位美总统与诺奖得主"],"mem":"年份挂钩：1636年比美国1776年建国还早140年（中国正值皇太极改国号为清），故称“先有哈佛，后有美国”。","mix":"哈佛大学位于美国马萨诸塞州的剑桥市（波士顿大都会区），不要与英国剑桥市的剑桥大学混淆。","mcq":[{"q":"美国历史最悠久、创立于1636年的常春藤盟校是","o":["哈佛大学","耶鲁大学","普林斯顿大学","哥伦比亚大学"],"a":0,"w":"哈佛大学建于1636年，早于耶鲁（1701）、普林斯顿（1746）和哥伦比亚（1754）。"}],"rel":[{"t":"常春藤盟校","n":"八大常春藤高校之首"},{"t":"中世纪大学","n":"欧美高校传统源头对照"},{"t":"上海交通大学","n":"中美著名研究型高校对照"}]},{"id":"b13-075","t":"大数据","cid":"13e","p":3,"kind":"概念","alias":["Big Data"],"one":"具备大规模、高速度、多样性、低价值密度4V特征的数据集合及技术。","ans":"大数据指难以用常规软件处理的**海量数据集合**及其分析技术。其典型特征概括为**“4V”**：**规模大、生成快、类型多、价值密度低**。它与算力、算法并称AI三大底座，是**数据要素**配置与**数字中国**建设的基础支撑。","pts":["海量数据集合及配套处理分析技术","4V特征：规模大、速度快、类型多、价值密度低","与算力、算法并称AI三大底座"],"mem":"英文4V口诀记特征：Volume海量、Velocity高速、Variety多样、Value低密度，就像沙里淘金，沙多但纯金占比低。","mix":"常见考坑：大数据第四个V常被误记为“价值密度高”，实际是“价值密度低”（海量原始数据中有效信息稀疏，需经挖掘提纯）。","mcq":[{"q":"关于大数据“4V”特征的表述，下列哪项是正确的","o":["规模大、类型多、生成快、价值密度低","规模大、类型少、生成快、价值密度高","规模小、类型多、生成慢、价值密度高","规模大、类型多、生成慢、价值密度低"],"a":0,"w":"大数据4V特征为规模大、类型多、生成快、价值密度低（需通过挖掘提炼高价值信息）。"}],"rel":[{"t":"数据要素","n":"大数据转化为生产要素的政策提法"},{"t":"云计算","n":"处理海量数据的分布式算力平台"},{"t":"数字中国","n":"国家层面的数字化战略统摄"}],"more":"4V英文对应：Volume（大量）、Velocity（高速）、Variety（多样）、Value（低价值密度）。","exam":[]},{"id":"b13-076","t":"云计算","cid":"13e","p":3,"kind":"概念","alias":["Cloud Computing"],"one":"通过网络按需提供弹性计算、存储与软件服务的资源交付模式。","ans":"云计算是通过互联网**按需提供计算、存储和软件服务**的分布式计算模式。其服务模式分为**IaaS、PaaS、SaaS**三层，具弹性扩展与按量计费特征，大幅降低企业IT成本，是支撑大数据与**大模型算力调度**的基础设施。","pts":["经网络按需提供计算、存储与软件服务","三大服务模式：IaaS、PaaS、SaaS","具弹性扩展特点，支撑算力与大模型"],"mem":"用水电类比云计算：以前企业要自建发电厂（买服务器），云计算让你像拧水龙头一样按需买算力；三层模式由底到顶记“I-P-S（爱批萨）”。","mix":"易与边缘计算混淆：云计算把数据集中到远程数据中心处理，边缘计算在靠近终端设备的一侧就近处理以降低时延。","mcq":[{"q":"在云计算的三大经典服务模式中，直接向终端用户提供在线办公软件等应用的层级是","o":["IaaS（基础设施即服务）","SaaS（软件即服务）","PaaS（平台即服务）","DaaS（数据即服务）"],"a":1,"w":"SaaS（Software as a Service）直接通过网络向用户交付成品应用软件。"}],"rel":[{"t":"算力","n":"云计算池化调度的核心资源"},{"t":"“东数西算”工程","n":"国家统筹云计算数据中心布局"},{"t":"大数据","n":"常与云计算协同部署"}],"more":"三层全称：IaaS基础设施即服务、PaaS平台即服务、SaaS软件即服务。","exam":[]},{"id":"b13-077","t":"区块链","cid":"13e","p":3,"kind":"概念","alias":["Blockchain"],"one":"去中心化分布式记账技术，具不可篡改、可追溯特征，为比特币底层技术。","ans":"区块链是一种**分布式记账技术**，最早于2008年作为**比特币的底层技术**出现。它融合密码学哈希与共识机制，具备**去中心化、不可篡改、可追溯**等特征，除数字货币外已广泛应用于**司法存证、供应链溯源与政务共享**。","pts":["去中心化分布式账本，比特币底层技术","核心特征：不可篡改、可追溯、共识机制","应用于司法存证、供应链溯源与政务"],"mem":"形象记法“全村一起记账本”：每笔账全村人同步抄一份，且每一页盖上上一页的密码防伪印章（链式相连），谁想偷偷改账立刻露馅。","mix":"常见误解是把区块链等同于比特币或加密货币：比特币只是区块链的一种应用，我国禁止虚拟货币交易炒作，但积极支持区块链技术创新。","mcq":[{"q":"关于区块链技术的特点与应用，下列说法错误的是","o":["采用分布式账本记录数据","数据具有不可篡改和可追溯特征","仅能用于发行虚拟货币，无法用于实体经济","是比特币的底层核心技术"],"a":2,"w":"区块链不仅用于比特币，在商品溯源、版权存证、供应链金融、政务共享等领域均有广泛应用。"}],"rel":[{"t":"数字人民币","n":"法定数字货币借鉴部分分布式技术"},{"t":"隐私计算","n":"常与区块链结合保障数据可信流通"},{"t":"大数据","n":"同属新一代信息技术集群"}],"exam":[]},{"id":"b13-078","t":"隐私计算","cid":"13e","p":3,"kind":"概念","alias":["隐私增强计算"],"one":"在不泄露原始数据前提下实现联合计算分析的技术，即“数据可用不可见”。","ans":"隐私计算指在**不泄露原始数据**前提下实现多方联合计算分析的技术体系。主流路线包括**联邦学习、多方安全计算与可信执行环境**，核心价值为**“数据可用不可见”**，为金融、医疗及**数据要素安全流通**提供关键支撑。","pts":["不泄露原始数据前提下的联合计算技术","核心特征：“数据可用不可见”","主流路线：联邦学习、多方安全计算、TEE"],"mem":"金句口诀“可用不可见，算完不搬家”：原始数据留在各自库里不外传，只交换加密参数或梯度，代表技术记“联邦（学习）+ 多方（安全计算）”。","mix":"隐私计算有别于简单的数据脱敏或静态加密，后者重在存储保护，隐私计算重在“计算使用过程中”兼顾流通价值与隐私安全。","mcq":[{"q":"下列哪项技术路线属于实现“数据可用不可见”的隐私计算代表技术","o":["光刻曝光技术","量子纠缠通信","超导磁悬浮技术","联邦学习与多方安全计算"],"a":3,"w":"联邦学习、多方安全计算（MPC）和可信执行环境（TEE）是隐私计算的三大主流技术路线。"}],"rel":[{"t":"数据要素","n":"隐私计算破解数据流通安全瓶颈"},{"t":"《个人信息保护法》","n":"隐私计算支撑数据合规落地"},{"t":"《数据安全法》","n":"数据安全治理的法律依据"},{"t":"跨境数据流动","n":"隐私计算助力安全合规跨境分析"}],"exam":[]},{"id":"b13-079","t":"世界第二大经济体","cid":"13d","p":3,"kind":"常识","exam":["2012选择"],"one":"2010年中国GDP超过日本，成为仅次于美国的世界第二大经济体。","ans":"世界第二大经济体是改革开放以来中国经济跃升的标志性地位。**2010年**，中国**国内生产总值（GDP）**首次超过**日本**，成为仅次于美国的全球第二大经济体。这一跨越体现了中国工业化与对外开放的成果，使中国成为**世界经济增长重要引擎**。","pts":["2010年中国GDP首次超过日本","跃居仅次于美国的世界第二大经济体","标志着中国国际经济影响力的重大跃升"],"mem":"时间锚点记“2010上海世博会年超日本”：2001入世→2008奥运→2010上海世博会，同年中国经济总量超越日本居世界第二。","mix":"注意年份常被设干扰项为2008年或2012年；此外中国是按名义GDP总量居世界第二，人均GDP仍属中等偏上收入国家水平。","mcq":[{"q":"中国国内生产总值（GDP）首次超过日本、成为世界第二大经济体是在哪一年","o":["2008年","2010年","2012年","2015年"],"a":1,"w":"2010年中国名义GDP超过日本，跃升为仅次于美国的世界第二大经济体。"}],"rel":[{"t":"国内生产总值（GDP）","n":"衡量经济体规模的核心指标"},{"t":"中国加入世贸组织","n":"2001年入世加速经济腾飞"},{"t":"2010年上海世博会","n":"同在2010年的标志性事件"}],"alias":[]},{"id":"b13-080","t":"大韩民国","cid":"13i","p":3,"kind":"常识","exam":["2012选择"],"alias":["韩国"],"one":"1948年8月15日成立于朝鲜半岛南部，1992年8月24日与中国建交。","ans":"大韩民国简称**韩国**，是朝鲜半岛南部的**东亚发达国家**，首都首尔。二战后半岛分治，韩国于**1948年8月15日**成立，战后经济腾飞跻身**“亚洲四小龙”**。**1992年8月24日**中韩建交，两国经贸与人文交流紧密。","pts":["1948年8月15日成立，首都首尔","战后工业化跻身“亚洲四小龙”","1992年8月24日中韩正式建交"],"mem":"记住两个八月纪念日：1948年8月15日建国（日本投降三周年同日），1992年8月24日中韩建交。","mix":"注意区分南北建国时间：大韩民国1948年8月15日成立，朝鲜民主主义人民共和国1948年9月9日成立。","mcq":[{"q":"中华人民共和国与大韩民国正式建立外交关系的日期是","o":["1972年9月29日","1979年1月1日","1992年8月24日","2001年12月11日"],"a":2,"w":"1972年中日建交、1979年中美建交、1992年8月24日中韩建交。"}],"rel":[{"t":"抗美援朝战争","n":"半岛分治后的冷战局部战争"},{"t":"区域全面经济伙伴关系协定（RCEP）","n":"中韩共同参与的自贸协定"},{"t":"冷战","n":"朝鲜半岛南北分治的历史背景"}]},{"id":"c-064","t":"新发展理念","cid":"13b","p":1,"kind":"合称","alias":["创新协调绿色开放共享","五大发展理念"],"one":"创新、协调、绿色、开放、共享，2015年十八届五中全会提出。","ans":"新发展理念是**2015年党的十八届五中全会提出的发展思想**，包括**创新、协调、绿色、开放、共享**五个方面，又称五大发展理念。**创新**是发展的第一动力，**协调**是持续健康发展的内在要求，**绿色**是永续发展的必要条件和人民对美好生活追求的重要体现，**开放**是国家繁荣发展的必由之路，**共享**是中国特色社会主义的本质要求。新发展理念**回答了“实现什么样的发展、怎样发展”的问题**，是“十三五”以来贯穿经济社会发展的指导原则。","pts":["2015年十八届五中全会提出","创新、协调、绿色、开放、共享","创新是第一动力，共享是本质要求"],"members":[["创新","发展的第一动力"],["协调","持续健康发展的内在要求"],["绿色","永续发展的必要条件"],["开放","国家繁荣发展的必由之路"],["共享","中国特色社会主义的本质要求"]],"mem":"首字串联“创协绿开共”。配套记性质：创新=动力，协调=要求，绿色=条件，开放=必由之路，共享=本质，对应“力、求、件、路、质”。","mix":"新发展理念（2015）不同于新发展格局（双循环，2020），也不同于“五位一体”（2012）。","mcq":[{"q":"新发展理念提出于","o":["十八大","十九大","十八届五中全会","十九届五中全会"],"a":2,"w":"2015年十八届五中全会。十九届五中全会（2020）是新发展格局写入“十四五”建议。"},{"q":"下列不属于新发展理念的是","o":["创新","协调","安全","共享"],"a":2,"w":"“安全”不在五大理念内，五大理念是创新、协调、绿色、开放、共享。"}],"rel":[{"t":"“五位一体”","n":"同为总布局类表述"},{"t":"双循环","n":"新发展格局"},{"t":"高质量发展","n":"以其为内涵"},{"t":"“绿水青山就是金山银山”","n":"“绿色”理念的体现"}],"more":"2015年十八届五中全会提出；2017年十九大报告将贯彻新发展理念作为基本方略之一。","exam":[]},{"id":"c-065","t":"“五位一体”","cid":"13b","p":1,"kind":"合称","alias":["五位一体","五位一体总体布局"],"one":"经济、政治、文化、社会、生态文明建设，十八大提出的总体布局。","ans":"“五位一体”是**2012年党的十八大提出的中国特色社会主义总体布局**，即**经济建设、政治建设、文化建设、社会建设、生态文明建设**五个方面的协调推进。此前十六大讲经济、政治、文化“三位一体”，十七大加入社会建设成为“四位一体”，**十八大首次把生态文明建设纳入总体布局**，形成五位一体。它是理论思想的大发展，使**中国特色社会主义事业总体布局更加完整**，强调**把生态文明建设融入各方面和全过程**。","pts":["2012年十八大提出的总体布局","经济、政治、文化、社会、生态文明建设","新增生态文明，由四位一体发展而来"],"members":[["经济建设","物质基础"],["政治建设","民主政治"],["文化建设","精神支撑"],["社会建设","民生保障"],["生态文明建设","十八大新增"]],"mem":"口诀“经政文社生”，最后一个“生”代表生态，也是十八大新添的。演变线：三（十六大：经政文）→四（十七大：加社会）→五（十八大：加生态），每次加一块。","mix":"“五位一体”是总布局，“四个全面”是总战略，“新发展理念”是发展理念，选择题常让三者互相作选项。","mcq":[{"q":"“五位一体”总体布局中，十八大新增的内容是","o":["经济建设","政治建设","生态文明建设","文化建设"],"a":2,"w":"此前十七大已是经济、政治、文化、社会“四位一体”。"},{"q":"“五位一体”提出于","o":["2007年","2012年","2015年","2017年"],"a":1,"w":"2012年党的十八大。"}],"rel":[{"t":"“四个全面”","n":"总布局与总战略对举"},{"t":"新发展理念","n":"同簇表述"},{"t":"“绿水青山就是金山银山”","n":"生态文明理念"},{"t":"科学发展观","n":"前期发展思想"}],"more":"2012年党的十八大报告提出。","exam":[]},{"id":"c-066","t":"“四个全面”","cid":"13b","p":1,"kind":"合称","alias":["四个全面","四个全面战略布局"],"one":"2014至2015年形成的治国理政总战略，现以全面建设社会主义现代化国家为第一项。","ans":"“四个全面”是**习近平提出的治国理政战略布局**。**2014年首次提出，2015年形成战略布局**，最初为**全面建成小康社会、全面深化改革、全面依法治国、全面从严治党**；**2020年十九届五中全会后，第一项改为全面建设社会主义现代化国家**。现在通行的表述是全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党。它明确了**目标和三大举措**，回答“往哪里去、怎么去”，是新时代的战略布局。","pts":["2014年提出，2015年形成战略布局","最初：全面小康、深化改革、依法治国、从严治党","2020年后第一项改为建设社会主义现代化国家"],"members":[["全面建设社会主义现代化国家","目标（最初为全面建成小康社会）"],["全面深化改革","动力"],["全面依法治国","保障"],["全面从严治党","根本保证"]],"mem":"一句话：一个目标，三个举措。“建、改、法、党”首字串联。记变化：小康→现代化国家，只有第一项换了，其余三项不变。顺序线索：先定目标，再改革（动力）、法治（保障）、从严治党（保证）。","mix":"“四个全面”是总战略，不同于“五位一体”（总布局）、“四个自信”（道路理论制度文化）、“四个意识”；第一项在2020年前后表述不同。","mcq":[{"q":"当前表述的“四个全面”中，第一项是","o":["全面建成小康社会","全面深化改革","全面依法治国","全面建设社会主义现代化国家"],"a":3,"w":"2020年十九届五中全会后，第一项改为全面建设社会主义现代化国家。"},{"q":"下列不属于“四个全面”的是","o":["全面深化改革","全面依法治国","全面从严治党","全面对外开放"],"a":3,"w":"不含“全面对外开放”。"}],"rel":[{"t":"“五位一体”","n":"总布局与总战略对举"},{"t":"全面从严治党","n":"其一"},{"t":"依法治国与十八届四中全会","n":"全面依法治国的会议"},{"t":"“四个自信”","n":"同为“四个”类表述"}],"more":"2014年12月习近平在江苏调研时首次完整提出；2015年形成战略布局。","exam":[]},{"id":"c-067","t":"“三个代表”","cid":"13a","p":2,"kind":"合称","alias":["三个代表重要思想","“三个代表”重要思想"],"one":"江泽民2000年提出、十六大写入党章：先进生产力、先进文化、人民根本利益。","ans":"“三个代表”重要思想是以**江泽民同志为主要代表**形成的科学理论，属**中国特色社会主义理论体系**。**2000年2月**广东考察时完整提出，**2002年中共十六大**写入党章。内容是党始终代表中国**先进生产力的发展要求**、**先进文化的前进方向**、**最广大人民的根本利益**。它回答“建设什么样的党、怎样建设党”，推进党的建设新的伟大工程。","pts":["江泽民2000年广东提出，2002年十六大写入党章","先进生产力、先进文化、最广大人民根本利益","回答“建设什么样的党、怎样建设党”的问题"],"members":[["代表中国先进生产力的发展要求","发展是党执政兴国的第一要务，立足经济基础"],["代表中国先进文化的前进方向","加强社会主义精神文明建设，提供思想保证"],["代表中国最广大人民的根本利益","出发点和落脚点，坚持立党为公、执政为民"]],"mem":"三词串记：“力、文、民”（生产力、文化、人民），对应经济、文化、群众三个维度。党代会顺口溜：“七毛十五邓，十六三代表，十七写科发，十九习思想”。","mix":"“三个代表”回答的是“建设什么样的党、怎样建设党”；邓小平理论回答“什么是社会主义、怎样建设社会主义”；科学发展观回答“实现什么样的发展、怎样发展”，选择题常互换考查。","mcq":[{"q":"将“三个代表”重要思想确立为党的指导思想并写入党章的会议是","o":["中共十四大","中共十五大","中共十七大","中共十六大"],"a":3,"w":"2002年中共十六大把“三个代表”重要思想确立为党的指导思想并写入党章；十五大写入邓小平理论，十七大写入科学发展观。"}],"rel":[{"t":"江泽民与“三个代表”","n":"人物与理论专条"},{"t":"邓小平理论","n":"前序指导思想"},{"t":"科学发展观","n":"后继指导思想"},{"t":"中国共产党历次全国代表大会","n":"十六大写入党章"}],"more":"关键年份：2000年2月广东考察提出；2002年11月十六大写入党章；2004年十届全国人大二次会议写入宪法。","exam":[]},{"id":"c-068","t":"中国式现代化五个特征","cid":"13b","p":1,"kind":"合称","alias":["五个特征","中国式现代化的五个特征"],"one":"人口规模巨大、共同富裕、物质精神协调、人与自然和谐、和平发展。","ans":"中国式现代化五个特征是**2022年党的二十大报告概括的中国式现代化的中国特色**，分别是**人口规模巨大的现代化、全体人民共同富裕的现代化、物质文明和精神文明相协调的现代化、人与自然和谐共生的现代化、走和平发展道路的现代化**。其中**人口规模巨大**强调十四亿多人口整体迈进现代化，**共同富裕**是本质要求，**和平发展**区别于西方殖民扩张的老路。五个特征揭示了**中国式现代化的国情基础和价值取向**。","pts":["人口规模巨大","共同富裕、物质精神协调","人与自然和谐共生、和平发展"],"members":[["人口规模巨大","十四亿多人口整体迈入现代化"],["全体人民共同富裕","本质要求"],["物质文明和精神文明相协调","物质富足与精神富有"],["人与自然和谐共生","绿色发展"],["走和平发展道路","区别于殖民掠夺"]],"mem":"首字串联“人、共、物、人、和”，谐音“人共物人和”，念成“人共物，人和”。顺序是“人口→富裕→物质精神→自然→和平”，由内到外。第四项“人与自然”和新发展理念“绿色”呼应。","mix":"五个特征与五大发展理念、五位一体都是“五”，互相别混：特征管现代化的样子，理念管发展的原则，五位一体管布局。","mcq":[{"q":"中国式现代化的特征不包括","o":["人口规模巨大","对外扩张增长","物质文明和精神文明相协调","走和平发展道路"],"a":1,"w":"强调走和平发展道路，不走殖民掠夺老路。"},{"q":"“全体人民共同富裕”在中国式现代化中属于","o":["本质要求之一","战略步骤","发展阶段","具体指标"],"a":0,"w":"二十大报告把共同富裕列为五个特征之一，同时是社会主义的本质要求。"}],"rel":[{"t":"中国式现代化","n":"总概念"},{"t":"共同富裕","n":"特征之一"},{"t":"新发展理念","n":"同为“五”类表述"},{"t":"“五位一体”","n":"同为“五”类表述"}],"more":"2022年党的二十大报告概括。","exam":[]},{"id":"c-069","t":"全球四大倡议","cid":"13h","p":2,"kind":"合称","alias":["四大全球倡议"],"one":"中国2021至2025年先后提出的全球发展、安全、文明、治理四大倡议。","ans":"全球四大倡议是中国为构建**人类命运共同体**提出的系统性国际公共产品，包括**全球发展倡议、全球安全倡议、全球文明倡议与全球治理倡议**。四项倡议依次于**2021年联大、2022年博鳌论坛、2023年政党对话会、2025年上合天津峰会**提出，从发展、安全、文明、治理四维回应世界之问，为完善全球治理体系贡献**中国方案**。","pts":["发展、安全、文明、治理四大倡议","2021至2025年提出，2025年天津峰会补齐","构建人类命运共同体的四大支撑"],"members":[["全球发展倡议","2021年9月第76届联大提出，聚焦落实2030年可持续发展议程"],["全球安全倡议","2022年4月博鳌亚洲论坛提出，坚持共同、综合、合作、可持续安全观"],["全球文明倡议","2023年3月中共与世界政党高层对话会提出，倡导文明交流互鉴"],["全球治理倡议","2025年9月1日上合天津峰会提出，秉持主权平等、国际法治等五大核心理念"]],"mem":"顺口溜按年记：“21发展、22安全、23文明、25治理”，四字简称“发安文治”。逻辑线：先解决饭碗（发展），再保和平（安全），再促交心（文明），最后立规矩（治理）。","mix":"2021至2023年曾称“三大全球倡议”；2025年9月1日提出“全球治理倡议”后正式升级为“全球四大倡议”，注意2024年没有新增第五项，别错选年份。","mcq":[{"q":"2025年9月1日，中国在上合组织天津峰会“上海合作组织+”会议上提出的倡议是","o":["全球文明倡议","全球治理倡议","全球安全倡议","全球发展倡议"],"a":1,"w":"全球治理倡议于2025年9月1日在上合组织天津峰会提出，与此前三大倡议合称全球四大倡议。"}],"rel":[{"t":"人类命运共同体","n":"四大倡议的统领理念"},{"t":"2025年上海合作组织天津峰会","n":"全球治理倡议提出场合"},{"t":"联合国2030年可持续发展议程","n":"全球发展倡议对接目标"},{"t":"文明冲突论","n":"与全球文明倡议对照"}],"more":"全球治理倡议五大核心理念：奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向。","exam":[]},{"id":"c-070","t":"“一带一路”五通","cid":"13h","p":3,"kind":"合称","alias":["一带一路五通"],"one":"政策沟通、设施联通、贸易畅通、资金融通、民心相通，共建核心框架。","ans":"“一带一路”五通是共建“一带一路”的核心合作重点，属**中国特色大国外交**重要表述。内容为**政策沟通、设施联通、贸易畅通、资金融通、民心相通**，覆盖战略对接、基建经贸与人文交流。五通协同推进，构成共建国家**互联互通**系统路径。","pts":["政策沟通、设施联通、贸易畅通","资金融通、民心相通","共建“一带一路”的核心合作内容"],"members":[["政策沟通","加强政府间战略对接与规则协调，是重要保障"],["设施联通","推进交通、能源、通信基础设施互联，是优先领域"],["贸易畅通","消除投资贸易壁垒，促进自由便利化，是重点内容"],["资金融通","深化金融合作与投融资支持，是重要支撑"],["民心相通","开展文化、教育、旅游等人文交流，是社会根基"]],"mem":"口诀“政设贸资民”对应“沟联畅融通”：政策要沟通、设施要联通、贸易要畅通、资金要融通、民心要相通。","mix":"注意五个动词不可混用：政策“沟通”、设施“联通”、贸易“畅通”、资金“融通”、民心“相通”。","mcq":[{"q":"下列各项中，不属于“一带一路”五通内容的是","o":["政策沟通","设施联通","民心相通","技术互通"],"a":3,"w":"“五通”指政策沟通、设施联通、贸易畅通、资金融通、民心相通，不含“技术互通”。"}],"rel":[{"t":"一带一路","n":"上位倡议与核心框架"},{"t":"人类命运共同体","n":"共建“一带一路”的实践目标"},{"t":"丝绸之路","n":"历史文化渊源"}],"exam":[]},{"id":"a13-001","t":"党的三个历史决议","cid":"13a","p":1,"kind":"合称","alias":["三个历史决议","三个历史问题决议","历史决议","第三个历史决议"],"one":"1945、1981、2021年三份总结党史的决议。","ans":"党的三个历史决议是**中国共产党在不同历史关口通过的三份总结党史的决议**。**1945年六届七中全会**通过《关于若干历史问题的决议》，**确立毛泽东思想的指导地位**，为七大作准备；**1981年十一届六中全会**通过《关于建国以来党的若干历史问题的决议》，**否定“文化大革命”，科学评价毛泽东**；**2021年十九届六中全会**通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》，总结**“十个坚持”**历史经验。三份决议统一了全党认识，为向前看提供依据。","pts":["1945六届七中全会：确立毛泽东思想地位","1981十一届六中全会：否定“文革”，评价毛泽东","2021十九届六中全会：百年成就，十个坚持"],"members":[["《关于若干历史问题的决议》","1945年六届七中全会，为七大作准备"],["《关于建国以来党的若干历史问题的决议》","1981年十一届六中全会，否定“文革”"],["《中共中央关于党的百年奋斗重大成就和历史经验的决议》","2021年十九届六中全会，“十个坚持”"]],"mem":"年份口诀“45、81、21”，间隔分别是36年、40年，每次都在党面临转折时出现。对应关键词“毛泽东思想、否定文革、十个坚持”，一个决议一个关键词。2024届选择题考的就是第三个。","mix":"前两个决议标题带“若干历史问题”，第三个标题是“百年奋斗重大成就和历史经验”；第三个决议是十九届六中全会，不是二十大。","mcq":[{"q":"总结“十个坚持”历史经验的是","o":["1945年《关于若干历史问题的决议》","1981年《关于建国以来党的若干历史问题的决议》","2021年《关于党的百年奋斗重大成就和历史经验的决议》","二十届三中全会《决定》"],"a":2,"w":"十个坚持出自第三个历史决议，2024届选择题考过。"},{"q":"否定“文化大革命”的历史决议通过于","o":["1945年","1981年","1978年","2021年"],"a":1,"w":"1981年十一届六中全会通过。"}],"rel":[{"t":"毛泽东思想","n":"1945决议确立其地位"},{"t":"十一届三中全会","n":"1981决议的前提"},{"t":"“两个确立”","n":"第三个决议提出"},{"t":"《共产党宣言》","n":"党史理论源头"}],"more":"1945年4月六届七中全会通过，同年七大召开。\n1981年6月十一届六中全会通过。\n2021年11月十九届六中全会通过。","exam":[]},{"id":"a13-002","t":"中国共产党历次全国代表大会","cid":"13a","p":1,"kind":"合称","alias":["历次党代会","党代会","历次全国代表大会"],"one":"一大到二十大，七大及十五至十九大涉及党章中指导思想的确立。","ans":"中国共产党全国代表大会是**党的最高领导机关**，历次党代会各有主题。**一大1921年在上海召开，闭幕于嘉兴南湖**；**七大1945年在延安召开，毛泽东思想写入党章**；八大1956年在北京召开；**十三大1987年阐述社会主义初级阶段理论**；**十四大1992年确立社会主义市场经济体制目标**；**十五大邓小平理论、十六大“三个代表”、十七大科学发展观、十九大习近平新时代中国特色社会主义思想**先后写入党章，十八大将科学发展观确立为党的指导思想；二十大2022年召开，二十一大定于2027年下半年在北京召开。","pts":["一大1921上海，闭幕嘉兴南湖；七大毛泽东思想入党章","十三大初级阶段，十四大市场经济","十五至十九大依次写入四个指导思想"],"members":[["一大（1921）","上海召开，闭幕于嘉兴南湖"],["七大（1945）","延安，毛泽东思想写入党章"],["八大（1956）","北京"],["十三大（1987）","社会主义初级阶段理论"],["十四大（1992）","确立社会主义市场经济体制目标"],["十五大（1997）","邓小平理论写入党章"],["十六大（2002）","“三个代表”写入党章"],["十七大（2007）","科学发展观写入党章"],["十九大（2017）","习近平新时代中国特色社会主义思想写入党章"],["二十大（2022）","中国式现代化"],["二十一大（2027年下半年，北京）","已定于2027年下半年召开"]],"mem":"指导思想入党章可用“七、十五、十六、十七、十九”一串：七毛、十五邓、十六三（个代表）、十七科（学发展观）、十九习。注意中间没有十八大：十七大将科学发展观写入党章，十八大将其确立为党的指导思想。整数年份有规律：1997、2002、2007、2017，每五年一届，逢2和7。","mix":"十八大把已写入党章的科学发展观确立为党的指导思想，但提出“五位一体”和社会主义核心价值观；十五大写入的是邓小平理论，不是“三个代表”。","mcq":[{"q":"“三个代表”重要思想写入党章是在","o":["十六大","十五大","十七大","十九大"],"a":0,"w":"2002年十六大。十五大是邓小平理论，十七大是科学发展观。"},{"q":"毛泽东思想被写入党章的是","o":["七大","一大","八大","十一大"],"a":0,"w":"1945年七大在延安召开，确立毛泽东思想为党的指导思想。"}],"rel":[{"t":"中国共产党第一次全国代表大会","n":"一大"},{"t":"毛泽东思想","n":"七大写入党章"},{"t":"邓小平理论","n":"十五大写入党章"},{"t":"科学发展观","n":"十七大写入党章"},{"t":"习近平新时代中国特色社会主义思想","n":"十九大写入党章"}],"more":"二十大（2022年）：提出中国式现代化，概括“新时代三件大事”。\n二十一大定于2027年下半年在北京召开（二十届五中全会宣布）。","exam":[]},{"id":"a13-003","t":"十一届三中全会","cid":"13a","p":1,"kind":"事件","alias":["十一届三中全会","1978年三中全会","党的十一届三中全会"],"one":"1978年12月召开，开启改革开放，工作重心转向经济建设。","ans":"十一届三中全会是**1978年12月中国共产党召开的十一届中央委员会第三次全体会议**，是**改革开放的起点**。会议**停止使用“以阶级斗争为纲”的口号**，**把全党工作重心转移到经济建设上来**，作出**实行改革开放的决策**。会议此前经历了关于真理标准问题的大讨论，坚持**解放思想、实事求是**的思想路线，并在领导层中实际确立了邓小平的核心地位。它**实现了新中国成立以来党的历史上具有深远意义的伟大转折**。","pts":["1978年12月，十一届中央委员会第三次全体会议","停止“以阶级斗争为纲”，重心转向经济建设","作出改革开放决策，伟大转折"],"mem":"1978=改革开放元年，“三中全会”三个字挂着“转折”。画面：一张会议桌上把“阶级斗争”换成“经济建设”。后来“三中全会”几乎每次都管改革：十一届（开启）、十八届（全面深化）、二十届（进一步全面深化），选择题常顺着这条线出。","mix":"1978年十一届三中全会是改革开放起点；1981年十一届六中全会才是通过历史决议；十二大1982年。","mcq":[{"q":"开启改革开放历史新时期的会议是","o":["十一届六中全会","十一届三中全会","十二大","十三大"],"a":1,"w":"1978年12月十一届三中全会。"},{"q":"十一届三中全会作出的核心转变是","o":["把工作重心转移到经济建设","确立社会主义市场经济体制","提出科学发展观","确立毛泽东思想地位"],"a":0,"w":"停止“以阶级斗争为纲”，转向经济建设。"}],"rel":[{"t":"十八届三中全会","n":"全面深化改革，同为三中全会"},{"t":"二十届三中全会","n":"进一步全面深化改革"},{"t":"邓小平理论","n":"改革开放的理论成果"},{"t":"党的三个历史决议","n":"1981年决议随后通过"}],"more":"1978年12月召开；此前有真理标准问题大讨论。","exam":[]},{"id":"a13-004","t":"十八届三中全会","cid":"13a","p":2,"kind":"事件","alias":["中共十八届三中全会"],"one":"2013年11月召开，开启全面深化改革，确立市场在资源配置中起“决定性作用”。","ans":"中共十八届三中全会于**2013年11月**在北京召开，开启新时代**全面深化改革**。全会通过**《关于全面深化改革若干重大问题的决定》**，确立总目标是完善和发展中国特色社会主义制度，推进**国家治理体系和治理能力现代化**。会议首次提出使市场在资源配置中起**“决定性作用”**和更好发挥政府作用，决定设中央深改组与国安委，成为改革重要坐标。","pts":["2013年11月召开，通过全面深化改革决定","总目标：国家治理体系和治理能力现代化","市场在资源配置中由“基础性”改为“决定性作用”"],"mem":"记住“三次关键三中全会”时间跳步：1978十一届（开启改革）→ 2013十八届（全面深化改革、市场“决定性作用”）→ 2024二十届（进一步全面深化改革、300多项举措）。","mix":"十四大（1992）表述为市场起“基础性作用”，十八届三中全会（2013）改为“决定性作用”；“国家治理体系和治理能力现代化”常被误记为十九大或二十届三中全会首次提出。","mcq":[{"q":"首次明确“使市场在资源配置中起决定性作用”的中央全会是","o":["十一届三中全会","十八届三中全会","十九届四中全会","二十届三中全会"],"a":1,"w":"2013年11月召开的十八届三中全会首次将市场在资源配置中的作用从“基础性作用”提升为“决定性作用”。"}],"rel":[{"t":"十一届三中全会","n":"1978年开启改革开放"},{"t":"二十届三中全会","n":"2024年接续深化改革"},{"t":"社会主义市场经济体制","n":"确立市场“决定性作用”"},{"t":"依法治国与十八届四中全会","n":"次年配套推进法治建设"}],"more":"全会召开日期：2013年11月9日至12日。会议提出“六个紧紧围绕”，开启系统整体设计推进改革的新时代。","exam":[]},{"id":"a13-005","t":"二十届三中全会","cid":"13a","p":1,"kind":"事件","exam":["2025选择"],"alias":["二十届三中全会","党的二十届三中全会"],"one":"2024年7月，作出进一步全面深化改革决定，提出300多项改革举措。","ans":"二十届三中全会是**2024年7月召开的中共二十届中央委员会第三次全体会议**，审议通过**《中共中央关于进一步全面深化改革、推进中国式现代化的决定》**。《决定》确定**继续完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化**的总目标，提出**300多项重要改革举措**，要求**到2029年新中国成立80周年时完成**。它承接1978年十一届三中全会、2013年十八届三中全会的改革传统，是新时代**以改革推进中国式现代化**的总部署。","pts":["2024年7月，《关于进一步全面深化改革、推进中国式现代化的决定》","300多项改革举措","2029年新中国成立80周年时完成"],"mem":"数字：“三百多、二九年”。2024年7月通过，2029年完成，五年任务期；2029=新中国成立80周年。三中全会线：1978（开启）→2013（全面深化）→2024（进一步全面深化），“进一步”三个字是区分标志。","mix":"十八届三中全会（2013）的《决定》是“全面深化改革若干重大问题”，二十届三中全会多了“进一步”和“推进中国式现代化”；四中全会才是“十五五”建议。","mcq":[{"q":"提出300多项改革举措并要求2029年完成的是","o":["十八届三中全会","二十届四中全会","十一届三中全会","二十届三中全会"],"a":3,"w":"2024年7月二十届三中全会《决定》，2025届选择题考过。"},{"q":"二十届三中全会召开的年份是","o":["2024年","2022年","2023年","2025年"],"a":0,"w":"2024年7月。"}],"rel":[{"t":"十八届三中全会","n":"2013年，全面深化改革"},{"t":"十一届三中全会","n":"1978年，改革开放起点"},{"t":"二十届四中全会","n":"后续“十五五”建议"},{"t":"中国式现代化","n":"《决定》的主题"}],"more":"2025届选择题考过其《决定》。\n全会时间：2024年7月；改革任务到2029年新中国成立80周年时完成。"},{"id":"a13-006","t":"二十届四中全会","cid":"13a","p":2,"kind":"事件","alias":["中共二十届四中全会"],"one":"2025年10月召开，审议通过《中共中央关于制定“十五五”规划的建议》。","ans":"中共二十届四中全会于**2025年10月20日至23日**在北京举行，谋划**2026至2030年**发展蓝图。全会通过**《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》**，系统部署高质量发展、科技创新、改革、绿色与民生安全，定位**“十五五”**为基本实现现代化**夯实基础、全面发力**关键期，为2026年两会批准纲要奠定基础。","pts":["2025年10月20日至23日在北京举行","审议通过制定“十五五”规划的建议","定位“十五五”为夯实基础、全面发力关键期"],"mem":"二十届后三次全会节奏好记：三中（2024.7，进一步全面深化改革）→ 四中（2025.10，定“十五五”规划建议）→ 五中（2026.10，持之以恒推进全面从严治党）。","mix":"往届通常由五中全会审议五年规划建议（如十九届五中全会定“十四五”），二十届则由**四中全会**（2025年10月）审议“十五五”规划建议，五中全会（2026年10月）聚焦全面从严治党，切勿按惯性错选。","mcq":[{"q":"审议通过《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》的会议是","o":["二十届四中全会","二十届三中全会","二十届五中全会","十九届五中全会"],"a":0,"w":"2025年10月20日至23日召开的二十届四中全会审议通过“十五五”规划建议；十九届五中全会定的是“十四五”规划建议。"}],"rel":[{"t":"“十五五”规划","n":"全会审议通过规划建议"},{"t":"二十届三中全会","n":"前一次中央全会"},{"t":"二十届五中全会","n":"次年聚焦全面从严治党"},{"t":"五年规划","n":"国家中长期规划制度"}],"more":"2025年10月28日《建议》全文公布，共三大板块、15个部分；2026年3月12日十四届全国人大四次会议正式批准“十五五”规划纲要。","exam":[]},{"id":"a13-007","t":"毛泽东思想","cid":"13a","p":2,"kind":"概念","one":"马克思主义中国化第一次历史性飞跃，活的灵魂是实事求是、群众路线、独立自主。","ans":"毛泽东思想是**马克思列宁主义在中国的运用和发展**，是中国共产党**集体智慧的结晶**，实现马克思主义中国化第一次历史性飞跃。它在抗日战争时期成熟，**1945年中共七大**确立为党的指导思想并写入党章。内容涵盖新民主主义革命与社会主义建设理论，**活的灵魂是实事求是、群众路线、独立自主**。它指导中国建立新中国并确立社会主义基本制度。","pts":["马克思主义中国化第一次历史性飞跃，集体智慧结晶","活的灵魂：实事求是、群众路线、独立自主","1945年中共七大确立为党的指导思想并写入党章"],"mem":"活的灵魂三词口诀：“实、群、独”（实事求是是精髓、群众路线是根本工作路线、独立自主是立足点）。记住1945年延安双节点：六届七中全会过首个历史决议，七大把毛泽东思想写入党章。","mix":"毛泽东思想凝聚全党集体智慧，切勿等同于毛泽东个人思想；1981年十一届六中全会第二个历史决议将毛泽东晚年错误与毛泽东思想科学体系严格区分开来。","mcq":[{"q":"毛泽东思想“活的灵魂”的三个基本方面是","o":["统一战线、武装斗争、党的建设","解放思想、实事求是、与时俱进","理论联系实际、密切联系群众、批评与自我批评","实事求是、群众路线、独立自主"],"a":3,"w":"实事求是、群众路线、独立自主是毛泽东思想活的灵魂；A项是“三大法宝”，C项是“三大优良作风”。"}],"rel":[{"t":"党的三个历史决议","n":"1945与1981决议核心"},{"t":"邓小平理论","n":"改革开放后的继承发展"},{"t":"遵义会议","n":"确立毛泽东领导地位"},{"t":"《共产党宣言》","n":"马克思主义理论源头"}],"more":"常考并列区别：三大法宝（统一战线、武装斗争、党的建设）；三大优良作风（理论联系实际、密切联系群众、批评与自我批评）；活的灵魂（实事求是、群众路线、独立自主）。","exam":[],"alias":[]},{"id":"a13-008","t":"邓小平理论","cid":"13a","p":2,"kind":"概念","alias":["建设有中国特色社会主义理论"],"one":"回答“什么是社会主义、怎样建设社会主义”，1997年十五大命名并写入党章。","ans":"邓小平理论是以**邓小平同志为主要代表**创立的科学理论，是**中国特色社会主义理论体系的开篇之作**。它以**“解放思想、实事求是”为精髓**，围绕**“什么是社会主义、怎样建设社会主义”**形成初级阶段、改革开放、社会主义市场经济和“一国两制”等理论。1992年南方谈话标志其成熟，**1997年中共十五大**命名并写入党章，开创了现代化建设新道路。","pts":["回答“什么是社会主义、怎样建设社会主义”","精髓是解放思想、实事求是，1992年南方谈话成熟","1997年中共十五大正式命名并写入党章"],"mem":"时间四步走：1978十一届三中全会（起步）→ 1982十二大（提出“中国特色社会主义”）→ 1992南方谈话（成熟）→ 1997十五大（命名并写入党章）。","mix":"十二大提出“建设有中国特色的社会主义”，十四大系统概括“建设有中国特色社会主义的理论”，直到**十五大（1997年）**才正式使用“邓小平理论”这一名称并写入党章。","mcq":[{"q":"正式提出“邓小平理论”这一科学概念并将其确立为党的指导思想的会议是","o":["中共十二大","中共十三大","中共十五大","中共十四大"],"a":2,"w":"1997年9月召开的中共十五大正式使用“邓小平理论”这一称谓，并将其确立为党的指导思想写入党章。"}],"rel":[{"t":"南方谈话","n":"理论成熟的标志（2013名解）"},{"t":"十一届三中全会","n":"改革开放的起点"},{"t":"“一国两制”","n":"国家统一的独创构想"},{"t":"社会主义市场经济体制","n":"经济体制改革成果"}],"more":"关键名言：“发展才是硬道理”“科学技术是第一生产力”“摸着石头过河”。1999年九届全国人大二次会议将其写入宪法。","exam":[]},{"id":"a13-009","t":"科学发展观","cid":"13a","p":2,"kind":"概念","one":"2003年提出、十七大写入党章：发展为要义、以人为本为核心、统筹兼顾为方法。","ans":"科学发展观是以**胡锦涛同志为主要代表**形成的重大战略思想，属**中国特色社会主义理论体系**。**2003年十六届三中全会**提出，**2007年十七大**写入党章，2012年十八大确立为指导思想。核心内涵是**第一要义是发展，核心是以人为本，基本要求全面协调可持续，根本方法统筹兼顾**，回答“实现什么样的发展、怎样发展”，推动经济社会协调可持续发展。","pts":["2003年十六届三中全会提出，十七大写入党章","要义发展、核心以人为本、全面协调可持续、统筹兼顾","回答“实现什么样的发展、怎样发展”"],"mem":"四句定位口诀：“义发、核人、基全协可、本统筹”（第一要义发展、核心以人为本、基本要求全面协调可持续、根本方法统筹兼顾）。记法：十七大写进党章，十八大升格为指导思想。","mix":"选择题常把“第一要义（发展）”与“核心（以人为本）”互换设陷阱；另注意十七大（2007）写入党章，十八大（2012）才同马列主义、毛泽东思想、邓小平理论、“三个代表”并列确立为指导思想。","mcq":[{"q":"科学发展观的核心立场是","o":["统筹兼顾","以人为本","全面协调可持续","推动经济社会发展"],"a":1,"w":"科学发展观第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。"}],"rel":[{"t":"“三个代表”","n":"前序指导思想"},{"t":"新发展理念","n":"新时代发展理念跃升"},{"t":"习近平新时代中国特色社会主义思想","n":"后继指导思想"},{"t":"绿色转型","n":"可持续发展的当代延续"}],"more":"2018年十三届全国人大一次会议通过宪法修正案，将科学发展观与习近平新时代中国特色社会主义思想一同写入宪法序言。","exam":[],"alias":[]},{"id":"a13-010","t":"习近平新时代中国特色社会主义思想","cid":"13a","p":1,"kind":"概念","alias":["习近平新时代中国特色社会主义思想","习近平思想","习思想"],"one":"党的指导思想，十九大写入党章，2018年写入宪法。","ans":"习近平新时代中国特色社会主义思想是**当代中国马克思主义、二十一世纪马克思主义**，是**党和国家必须长期坚持的指导思想**。**2017年党的十九大将其写入党章，2018年宪法修正案将其写入宪法**。它的核心内容概括为**“十个明确”“十四个坚持”“十三个方面成就”**，涵盖坚持党的全面领导、以人民为中心、新发展理念、全面从严治党等。它接续**毛泽东思想、邓小平理论、“三个代表”、科学发展观**，推进了马克思主义中国化时代化。","pts":["十九大写入党章，2018年写入宪法","“十个明确”“十四个坚持”“十三个方面成就”","接续毛泽东思想、邓小平理论等指导思想序列"],"mem":"数字串“10-14-13”：十个明确（讲是什么）、十四个坚持（讲怎么做）、十三个方面成就（讲做成什么）。时间线：2017党章、2018宪法，各一次。指导思想序列“毛邓三科习”：毛泽东思想、邓小平理论、三个代表、科学发展观、习近平思想。","mix":"“十个坚持”是第三个历史决议的历史经验，“十四个坚持”是十九大报告的基本方略，二者不要混；科学发展观在十七大写入党章，十八大确立为党的指导思想。","mcq":[{"q":"习近平新时代中国特色社会主义思想写入党章是在","o":["十八大","二十大","十九届六中全会","十九大"],"a":3,"w":"2017年十九大写入党章，2018年写入宪法。"},{"q":"下列关于习近平新时代中国特色社会主义思想的表述正确的是","o":["2012年写入宪法","核心内容包括“十四个坚持”","核心内容为“十个坚持”","十七大写入党章"],"a":1,"w":"十四个坚持是基本方略，十个坚持是历史经验。"}],"rel":[{"t":"毛泽东思想","n":"指导思想序列之一"},{"t":"邓小平理论","n":"指导思想序列之一"},{"t":"科学发展观","n":"指导思想序列之一"},{"t":"“两个结合”","n":"马克思主义中国化时代化途径"}],"more":"指导思想序列：毛泽东思想（七大）、邓小平理论（十五大）、“三个代表”（十六大）、科学发展观（十七大）、习近平新时代中国特色社会主义思想（十九大）。","exam":[]},{"id":"a13-011","t":"社会主义初级阶段与“一个中心、两个基本点”","cid":"13a","p":2,"kind":"概念","alias":["社会主义初级阶段","一个中心两个基本点","党的基本路线"],"one":"1987年十三大核心成果：定位我国处于初级阶段，确立经济建设与两项基本点路线。","ans":"社会主义初级阶段理论与**“一个中心、两个基本点”**由**1987年中共十三大**系统确立，构成**党在社会主义初级阶段的基本路线**。初级阶段特指我国在生产力落后条件下建设社会主义必经的历史阶段。基本路线指**以经济建设为中心**，**坚持四项基本原则**，**坚持改革开放**，目标是建成社会主义现代化强国。它构成党和国家的生命线与人民的幸福线。","pts":["1987年中共十三大系统阐述初级阶段与基本路线","一个中心：以经济建设为中心","两个基本点：坚持四项基本原则、坚持改革开放"],"mem":"画面记法：经济建设是“船身方向盘”（中心），四项基本原则是“压舱石”（立国之本），改革开放是“发动机”（强国之路），三者合称“一中心、两基本点”，一起出现在1987年十三大。","mix":"社会主义初级阶段特指中国在生产力落后条件下建设社会主义的历史阶段，切勿泛指一切国家进入社会主义的起始阶段；基本路线奋斗目标随党代会不断充实，十九大增写“美丽”并提升为“现代化强国”。","mcq":[{"q":"系统阐述社会主义初级阶段理论并完整概括“一个中心、两个基本点”基本路线的会议是","o":["中共十一届三中全会","中共十二大","中共十三大","中共十四大"],"a":2,"w":"1987年中共十三大系统阐述社会主义初级阶段理论，并明确提出“一个中心、两个基本点”的基本路线。"}],"rel":[{"t":"四项基本原则","n":"两个基本点之一"},{"t":"“三步走”发展战略","n":"同在十三大提出"},{"t":"邓小平理论","n":"初级阶段理论为其基石"},{"t":"社会主要矛盾的转化","n":"初级阶段国情未变"}],"more":"十三大同时提出社会主义初级阶段至少需要上百年时间（从1956年社会主义改造基本完成算起）。十九大强调，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变。","exam":[]},{"id":"a13-012","t":"四项基本原则","cid":"13a","p":2,"kind":"合称","alias":["立国之本"],"one":"1979年邓小平提出的立国之本：社会主义道路、人民民主专政、党领导、马列毛。","ans":"四项基本原则是**1979年3月邓小平**在党的理论工作务虚会上提出的政治准则，被称为**立国之本**，是基本路线“两个基本点”之一。内容包括：**坚持社会主义道路**，**坚持人民民主专政**（最初称无产阶级专政），**坚持中国共产党的领导**，**坚持马列主义、毛泽东思想**。四者划定改革开放的政治底线，保障现代化建设沿着正确方向前进。","pts":["1979年3月邓小平提出，被称为立国之本","社会主义道路、人民民主专政、党的领导、马列毛思想","与改革开放并列为“两个基本点”，锚定政治方向"],"members":[["坚持社会主义道路","指明国家发展的社会制度与方向"],["坚持人民民主专政","确立我国国体，最初表述为无产阶级专政"],["坚持中国共产党的领导","四项基本原则的核心，提供政治领导保证"],["坚持马列主义、毛泽东思想","确立全党全国的根本指导思想"]],"mem":"四字顺口溜：“道、政、党、思”（社会主义道路、人民民主专政、党的领导、马列毛思想），对应“走什么路、什么国体、谁来领导、用什么指导”。记住“立国之本”对“强国之路”（改革开放）。","mix":"1979年最初第二项表述为“无产阶级专政”，1982年宪法和十二大后通行表述为“人民民主专政”；注意勿将“坚持改革开放”混入四项基本原则，改革开放是与之并列的另一基本点。","mcq":[{"q":"下列各项中，不属于邓小平1979年提出的“四项基本原则”的是","o":["坚持社会主义道路","坚持人民民主专政","坚持中国共产党的领导","坚持改革开放"],"a":3,"w":"四项基本原则是社会主义道路、人民民主专政、党的领导、马列主义毛泽东思想；坚持改革开放是与之并列的另一个基本点。"}],"rel":[{"t":"社会主义初级阶段与“一个中心、两个基本点”","n":"构成两个基本点之一"},{"t":"邓小平理论","n":"邓小平提出的核心准则"},{"t":"现行宪法","n":"1982年宪法写入序言"},{"t":"毛泽东思想","n":"第四项基本原则内容"}],"more":"提出场合：1979年3月30日邓小平在党的理论工作务虚会上发表《坚持四项基本原则》讲话。","exam":[]},{"id":"a13-013","t":"“三步走”发展战略","cid":"13a","p":2,"kind":"合称","alias":["三步走战略","现代化建设三步走"],"one":"1987年十三大提出：第一步温饱、第二步小康、第三步21世纪中叶基本实现现代化。","ans":"“三步走”发展战略是邓小平构想、**1987年中共十三大**确立的现代化分步蓝图。第一步GNP翻一番，**解决人民温饱问题**；第二步20世纪末再翻一番，**达到小康水平**；第三步到**21世纪中叶**达到中等发达国家水平，**基本实现现代化**。前两步已如期实现，十九大与二十大接续作出新时代**“两步走”战略安排**，将基本实现现代化提前到2035年。","pts":["1987年中共十三大确立的现代化建设蓝图","第一步温饱、第二步小康、第三步中叶基本现代化","前两步已实现，新时代接续为“两步走”安排"],"members":[["第一步（20世纪80年代）","GNP比1980年翻一番，解决人民温饱问题"],["第二步（20世纪末）","GNP再翻一番，人民生活达到小康水平"],["第三步（21世纪中叶）","达到中等发达国家水平，基本实现现代化"]],"mem":"三词台阶：“温饱 → 小康 → 现代化”。与新时代“两步走”对照：原来“三步走”是2050年基本实现现代化，新时代“两步走”直接提速15年，2035年基本实现现代化、2050年建成现代化强国。","mix":"极易与十九大、二十大的**“两步走”战略安排**（2035年基本实现社会主义现代化，本世纪中叶建成社会主义现代化强国）混淆，选择题常把两个时间节点张冠李戴。","mcq":[{"q":"1987年中共十三大提出的“三步走”发展战略，其第二步目标是到20世纪末","o":["人民生活达到小康水平","解决人民温饱问题","全面建成小康社会","基本实现社会主义现代化"],"a":0,"w":"“三步走”第一步解决温饱，第二步到20世纪末达到小康水平，第三步到21世纪中叶基本实现现代化；全面建成小康社会是“两个一百年”的第一个目标。"}],"rel":[{"t":"“两步走”战略安排","n":"新时代提速接续战略"},{"t":"“两个一百年”奋斗目标","n":"衔接建党与建国百年"},{"t":"社会主义初级阶段与“一个中心、两个基本点”","n":"同在十三大提出"},{"t":"邓小平理论","n":"邓小平构想的发展战略"}],"more":"关键对照：十三大“三步走”（1987）→ 十五大“新三步走”与“两个一百年”（1997）→ 十九大/二十大“两步走”（2017/2022）。","exam":[]},{"id":"a13-014","t":"七届二中全会与“两个务必”","cid":"13a","p":2,"kind":"事件","alias":["西柏坡会议","两个务必","七届二中全会"],"one":"1949年3月西柏坡召开，工作重心由乡村移到城市，毛泽东提出“两个务必”。","ans":"中共七届二中全会于**1949年3月**在**河北西柏坡**召开，是全国胜利前夕的转折性会议。全会决定**党的工作重心由乡村移到城市**，制定建国后政治经济基本政策。毛泽东在会上提出**“两个务必”**：务必继续保持**谦虚、谨慎、不骄、不躁**的作风，务必继续保持**艰苦奋斗**的作风。它为新中国成立作好思想准备，也是二十大**“三个务必”**的作风源头。","pts":["1949年3月河北西柏坡召开，建国前夕重要全会","工作重心由乡村移到城市，定下建国基本政策","毛泽东提出“两个务必”：谦虚谨慎、艰苦奋斗"],"mem":"画面记法：1949年3月离开西柏坡“进京赶考”前，毛泽东叮嘱两件事，一是“不骄傲”（谦虚谨慎不骄不躁），二是“能吃苦”（艰苦奋斗）。1949从乡村进城，恰好与1927秋收起义后向农村进军形成呼应。","mix":"“两个务必”出自1949年七届二中全会；2022年**党的二十大**在此基础上提出**“三个务必”**（务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争），注意区分数量与提出时间。","mcq":[{"q":"1949年3月作出“党的工作重心由乡村移到城市”决定并提出“两个务必”的会议是","o":["中共七大","中共七届二中全会","中共八大","遵义会议"],"a":1,"w":"七届二中全会于1949年3月在西柏坡召开，决定工作重心由乡村转向城市，毛泽东在会上提出“两个务必”。"}],"rel":[{"t":"全面从严治党","n":"新时代的作风传承"},{"t":"窑洞对与“两个答案”","n":"同为执政忧患意识"},{"t":"中国共产党人精神谱系","n":"孕育西柏坡精神"},{"t":"中共八大","n":"建国后探索建设的会议"}],"more":"全会同时作出“六条规定”：不做寿、不送礼、少敬酒、少拍掌、不以人名作地名、不要把中国同志同马恩列斯平列。毛泽东离开西柏坡时提出“进京赶考”。","exam":[]},{"id":"a13-015","t":"中共八大","cid":"13a","p":3,"kind":"事件","alias":["中国共产党第八次全国代表大会","党的八大"],"one":"1956年北京召开，探索社会主义建设道路，正确分析国内主要矛盾。","ans":"中共八大是**1956年9月**在北京召开的党在全国执政后**首次全国代表大会**。大会指出社会主义改造基本完成后，国内主要矛盾转为**人民经济文化迅速发展需要同当前落后状况之间的矛盾**，确立**集中力量发展生产力**，开启建设道路探索。","pts":["1956年9月北京，执政后首次党代会","正确判断社会主义改造后国内主要矛盾","确定集中力量发展生产力的主要任务"],"mem":"数字口诀“56八大改矛盾”：1956年三大改造基本完成，八大顺势宣告进入全面社会主义建设阶段；2026年恰逢召开70周年。","mix":"注意区分三次主要矛盾表述：1956年八大、1981年十一届六中全会、2017年十九大（美好生活需要和不平衡不充分的发展）。","mcq":[{"q":"中国共产党在全国执政后召开的第一次全国代表大会是","o":["中共七大","中共八大","中共九大","中共十二大"],"a":1,"w":"中共七大召开于1945年抗战胜利前夕，1956年召开的中共八大是党在全国执政后的首次党代会。"}],"rel":[{"t":"社会主要矛盾的转化","n":"八大首次提出建设期主要矛盾"},{"t":"中国共产党历次全国代表大会","n":"同属党代会主线"},{"t":"党的三个历史决议","n":"1981年决议高度肯定八大路线"}],"more":"召开时间：1956年9月15日至27日；2026年为中共八大召开70周年。","exam":[]},{"id":"a13-016","t":"古田会议","cid":"13a","p":3,"kind":"事件","alias":["红四军第九次党代表大会"],"one":"1929年12月福建上杭古田召开，确立“思想建党、政治建军”原则。","ans":"古田会议是**1929年12月**在**福建上杭古田**召开的**红四军第九次党代表大会**。会议通过毛泽东起草的《古田会议决议》（含《关于纠正党内的错误思想》），确立**“思想建党、政治建军”**原则，奠定了新型人民军队建设的基石。","pts":["1929年12月福建上杭古田，红四军九大","确立“思想建党、政治建军”原则","奠定党对军队绝对领导的建军基石"],"mem":"口诀“二九古田，思党政军”：1929年去古田，解决“党指挥枪”的根本问题，即思想建党、政治建军。","mix":"易与1927年三湾改编（支部建在连上）、1935年遵义会议（确立毛泽东在党中央和红军的领导地位）混淆。","mcq":[{"q":"确立中国共产党“思想建党、政治建军”原则的重要会议是","o":["八七会议","遵义会议","古田会议","瓦窑堡会议"],"a":2,"w":"1929年12月古田会议确立了“思想建党、政治建军”的建党建军原则。"}],"rel":[{"t":"遵义会议","n":"同为党史军史关键转折会议"},{"t":"八一建军节","n":"同属人民军队创建主线"},{"t":"毛泽东思想","n":"古田会议决议是重要文献"}],"more":"2014年10月全军政治工作会议在福建古田召开，被称为“新古田会议”。","exam":[]},{"id":"a13-017","t":"伟大建党精神","cid":"13a","p":1,"kind":"概念","alias":["伟大建党精神","建党精神"],"one":"2021年建党百年大会概括：坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民。","ans":"伟大建党精神是**2021年7月1日庆祝中国共产党成立一百周年大会上提出的精神概括**，是**中国共产党人精神谱系的源头**。其内涵为**坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民**，共四句十六字。它凝结了建党时期的革命品格，之后的长征精神、延安精神、“两弹一星”精神等都由此生发。它是**中国共产党的精神之源**，也是党永葆先进性的精神支撑。","pts":["2021年7月1日建党百年大会提出","坚持真理、坚守理想，践行初心、担当使命等四句","中国共产党人精神谱系的源头"],"mem":"四句十六字，每句前半抓动词：坚持真理（想法）、践行初心（动机）、不怕牺牲（勇气）、对党忠诚（立场）。画面：1921年嘉兴南湖红船，是所有精神的“出发点”。后面的长征、延安、“两弹一星”精神都排在它后面。","mix":"“红船精神”是习近平2005年概括的“首创、奋斗、奉献”，是建党精神的一个侧面；“两弹一星”精神出现在建党精神之后的谱系里。","mcq":[{"q":"“坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民”概括的是","o":["伟大建党精神","红船精神","延安精神","长征精神"],"a":0,"w":"2021年建党百年大会提出，是精神谱系的源头。"},{"q":"伟大建党精神提出的场合是","o":["庆祝建党一百周年大会","党的十九大","党的二十大","十九届六中全会"],"a":0,"w":"2021年7月1日。"}],"rel":[{"t":"中国共产党人精神谱系","n":"建党精神是源头"},{"t":"两弹一星精神","n":"谱系中的精神之一"},{"t":"长征精神","n":"谱系中的精神之一"},{"t":"中国共产党第一次全国代表大会","n":"建党的起点"}],"more":"2021年7月1日庆祝中国共产党成立一百周年大会。\n中国共产党人精神谱系以伟大建党精神为源头。","exam":[]},{"id":"a13-018","t":"中国共产党人精神谱系","cid":"13a","p":2,"kind":"合称","alias":["精神谱系","第一批伟大精神"],"one":"以伟大建党精神为源头的精神体系，2021年9月公布第一批伟大精神共46种。","ans":"中国共产党人精神谱系是党百年奋斗形成的精神财富总和，以**伟大建党精神**为**精神之源**。**2021年9月**，党中央批准公布**第一批伟大精神共46种**。它贯通革命、建设、改革与新时代四个时期，涵盖**井冈山精神、长征精神、延安精神、西柏坡精神、“两弹一星”精神、载人航天精神、脱贫攻坚精神**等，构成激励民族复兴的精神支柱。","pts":["以伟大建党精神为源头的百年精神体系","2021年9月公布第一批伟大精神共46种","贯通四个历史时期，含长征、两弹一星、脱贫攻坚等精神"],"members":[["伟大建党精神（源头）","32字精神之源，2021年建党百年大会首次概括"],["新民主主义革命时期","含井冈山、长征、遵义会议、延安、西柏坡等精神"],["社会主义革命和建设时期","含抗美援朝、红旗渠、大庆、雷锋、焦裕禄、“两弹一星”、西迁等精神"],["改革开放和现代化建设新时期","含改革开放、特区、抗洪、女排、载人航天、青藏铁路等精神"],["中国特色社会主义新时代","含脱贫攻坚、抗疫、探月、新时代北斗、科学家等精神"]],"mem":"按“1个源头 + 4段历史 + 46种”建框架：源头是伟大建党精神；革命期记“井长延西”（井冈山、长征、延安、西柏坡）；建设期记“两弹西迁”；改革期记“特区女排航天”；新时代记“脱贫抗疫北斗”。","mix":"第一批伟大精神数量是**46种**，常被混淆为50种或100种；“西迁精神”与上海交通大学西迁直接相关，属于社会主义革命和建设时期精神，也是交大校史关联考点。","mcq":[{"q":"2021年9月公布的党中央批准第一批纳入中国共产党人精神谱系的伟大精神共有","o":["30种","36种","50种","46种"],"a":3,"w":"2021年9月29日，第一批纳入中国共产党人精神谱系的伟大精神正式发布，共计46种，以伟大建党精神为源头。"}],"rel":[{"t":"伟大建党精神","n":"精神谱系的源头"},{"t":"长征精神","n":"2026年胜利90周年"},{"t":"两弹一星精神","n":"建设时期科技精神代表"},{"t":"西迁精神","n":"与交大校史密切相关"}],"more":"2026年周年关联：中国共产党成立105周年（1921）、红军长征胜利90周年（1936）、交通大学西迁70周年（1956）。","exam":[]},{"id":"a13-019","t":"窑洞对与“两个答案”","cid":"13a","p":2,"kind":"概念","alias":["窑洞对","历史周期率两个答案","跳出历史周期率"],"one":"1945年延安窑洞毛泽东以人民监督答黄炎培；新时代党给出第二个答案“自我革命”。","ans":"“窑洞对”指**1945年7月**民主人士**黄炎培**在延安窑洞，就如何跳出**“其兴也勃焉，其亡也忽焉”**历史周期率向毛泽东发问的著名对话。毛泽东给出**第一个答案**：**让人民来监督政府**，政府才不敢松懈。新时代党在全面从严治党实践中给出**第二个答案**，即**党的自我革命**。“两个答案”内外结合，成为百年大党永葆生机活力的制度保障。","pts":["1945年延安窑洞黄炎培问历史周期率","第一个答案：让人民来监督政府（外靠人民监督）","第二个答案：党的自我革命（内靠全面从严治党）"],"mem":"内外对照记法：“窑洞对”一外一内两个答案，外靠“人民监督”（1945毛泽东），内靠“自我革命”（新时代习近平）。名句“其兴也勃焉，其亡也忽焉”化自《左传》“禹、汤罪己，其兴也勃焉；桀、纣罪人，其亡也忽焉”。","mix":"提问者是职业教育家、民主人士**黄炎培**（不是梁漱溟、张澜或陈嘉庚）；“第一个答案”强调人民民主监督，“第二个答案”强调自我革命，二者不可颠倒顺序。","mcq":[{"q":"1945年在延安窑洞与毛泽东展开“历史周期率”对话的民主人士是","o":["梁漱溟","张澜","黄炎培","章伯钧"],"a":2,"w":"1945年7月4日，黄炎培在延安与毛泽东讨论历史周期率问题，史称“窑洞对”，载于黄炎培《延安归来》。"}],"rel":[{"t":"全面从严治党","n":"第二个答案的实践载体"},{"t":"七届二中全会与“两个务必”","n":"同显执政忧患意识"},{"t":"全过程人民民主","n":"第一个答案的当代制度"},{"t":"《左传》","n":"“其兴也勃焉”典籍出处"}],"more":"黄炎培访延安记录见《延安归来》；“其兴也勃焉，其亡也忽焉”语出《左传·庄公十一年》。","exam":[]},{"id":"a13-020","t":"中央八项规定","cid":"13a","p":3,"kind":"制度","alias":["八项规定"],"one":"2012年12月4日中央政治局通过，全面从严治党作风建设的切入口。","ans":"中央八项规定是**2012年12月4日**中央政治局会议通过的作风建设制度。它聚焦**改进工作作风、密切联系群众**，从调研、精简会文、勤俭节约等方面立规，成为新时代**全面从严治党**的破题之举，2025年全党开展了专项学习教育。","pts":["2012年12月4日中央政治局会议通过","核心为改进工作作风、密切联系群众","新时代全面从严治党标志性制度"],"mem":"日期巧记：2012年12月4日与“国家宪法日”（12月4日）同月同日，记作“十八大后宪法日定规矩”。","mix":"中央八项规定直接规范中央政治局成员；各级党员干部执行的是“中央八项规定精神”，表述上常作区分。","mcq":[{"q":"中共中央政治局审议通过“中央八项规定”的时间是","o":["2012年11月","2013年11月","2014年10月","2012年12月"],"a":3,"w":"2012年12月4日，中共中央政治局召开会议审议通过关于改进工作作风、密切联系群众的八项规定。"}],"rel":[{"t":"全面从严治党","n":"作风建设的重要抓手"},{"t":"国家宪法日","n":"同为12月4日便于记忆"},{"t":"二十届五中全会","n":"2026年深化全面从严治党"}],"more":"2025年3月中共中央办公厅印发通知，自2025年全国两会后至7月底在全党开展深入贯彻中央八项规定精神学习教育。","exam":[]},{"id":"a13-021","t":"“两个确立”","cid":"13a","p":2,"kind":"概念","alias":["两个确立的决定性意义"],"one":"2021年十九届六中全会提出：确立习近平核心地位、确立习近平新时代思想指导地位。","ans":"“两个确立”是**2021年11月党的十九届六中全会**第三个历史决议正式提出的重大政治论断，属新时代党建核心表述。内容是：**确立习近平同志党中央的核心、全党的核心地位**，**确立习近平新时代中国特色社会主义思想的指导地位**。它对新时代党和国家事业发展、推进民族复兴具有**决定性意义**，是做到**“两个维护”**的思想政治前提。","pts":["2021年11月十九届六中全会第三个历史决议提出","确立核心地位、确立科学思想指导地位","对新时代党和国家事业与民族复兴具决定性意义"],"mem":"二元对应记法：“两个确立”= 人（核心地位）+ 思想（指导地位）；与“两个维护”的逻辑线：先有“两个确立”（客观历史选择），再有“两个维护”（自觉政治行动）。","mix":"易与**“两个维护”**（坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导）及**“两个结合”**（马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合）混淆。","mcq":[{"q":"正式提出“两个确立”这一重大政治论断的会议是","o":["十九届六中全会","党的十九大","党的二十大","十八届六中全会"],"a":0,"w":"2021年11月十九届六中全会审议通过第三个历史决议，正式提出“两个确立”及其决定性意义。"}],"rel":[{"t":"党的三个历史决议","n":"第三个历史决议核心"},{"t":"“四个意识”与“两个维护”","n":"紧密衔接的政治要求"},{"t":"习近平新时代中国特色社会主义思想","n":"第二项确立的指导思想"},{"t":"“两个结合”","n":"易混的“两个”表述"}],"more":"关键年份：2021年11月8日至11日十九届六中全会审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》。","exam":[]},{"id":"a13-022","t":"经济特区","cid":"13a","p":2,"kind":"制度","alias":["中国经济特区","五大经济特区"],"one":"1980年首批设深圳、珠海、汕头、厦门，1988年设海南，对外开放窗口与试验田。","ans":"经济特区是改革开放初期国家划定实行**特殊经济政策和管理体制**的地区，构成对外开放格局的起点。**1980年8月**首批设立**深圳、珠海、汕头、厦门**四个经济特区；**1988年4月**海南建省并设立**海南经济特区**（面积最大）。特区通过吸引外资、引进技术与管理经验率先突破计划经济，发挥对外开放**“窗口”**和改革**“试验田”**作用，带动全方位开放。","pts":["1980年首批设立深圳、珠海、汕头、厦门四特区","1988年设海南经济特区（面积最大）","对外开放“窗口”与体制改革“试验田”"],"mem":"地理串记首批4个特区：广东占3个（深、珠、汕，紧邻港澳与侨乡），福建占1个（厦门，面向台湾），8年后再加全岛的海南。记住“1980四城、1988海南”。","mix":"上海**浦东新区**（1990年开发开放）和**喀什、霍尔果斯**（2010年设经济开发区）均不属于1980至1988年传统五大经济特区；上海2013年设立的是中国首个**自由贸易试验区**，勿与经济特区混同。","mcq":[{"q":"1980年我国批准设立的第一批经济特区包括深圳、珠海、汕头和","o":["海南","厦门","浦东","青岛"],"a":1,"w":"1980年首批四个经济特区是深圳、珠海、汕头、厦门；海南经济特区设立于1988年，浦东开发开放始于1990年。"}],"rel":[{"t":"南方谈话","n":"1992年视察深圳珠海"},{"t":"海南自由贸易港","n":"海南特区的新时代跃升"},{"t":"自由贸易试验区","n":"新时代制度开放试验田"},{"t":"浦东开发开放","n":"1990年开放新里程碑"}],"more":"关键年份：1980年8月26日五届全国人大常委会第十五次会议批准《广东省经济特区条例》；2025年为深圳等首批经济特区建立45周年。","exam":[]},{"id":"a13-023","t":"社会主义市场经济体制","cid":"13a","p":2,"kind":"制度","alias":["社会主义市场经济"],"one":"1992年十四大确立的经济体制改革目标，十八届三中全会明确市场起“决定性作用”。","ans":"社会主义市场经济体制是将**社会主义基本制度与市场经济**结合的经济体制，是改革开放重大创新。1992年邓小平**南方谈话**破除计划与市场姓资姓社束缚；同年**中共十四大**确立该改革目标，明确市场对资源配置起**基础性作用**。2013年**十八届三中全会**提升为**“决定性作用”**和更好发挥政府作用。它极大解放生产力，助推中国成为世界第二大经济体。","pts":["1992年南方谈话破除束缚，十四大正式确立改革目标","从“基础性作用”发展到十八届三中全会“决定性作用”","把社会主义基本制度与市场经济结合，解放生产力"],"mem":"逻辑链：“南方谈话松绑（1992春）→ 十四大定目标（1992秋，基础性）→ 十八届三中全会升级（2013，决定性）→ 二十届三中全会构建高水平体制（2024）”。记住两词变化：“基础”变“决定”。","mix":"十四大（1992）确立目标是建立社会主义市场经济体制，十四届三中全会（1993）勾画基本框架；勿把提出确立目标的会议错选为十一届三中全会或十三大。","mcq":[{"q":"正式把“建立社会主义市场经济体制”确立为我国经济体制改革目标的会议是","o":["中共十二大","中共十三大","中共十五大","中共十四大"],"a":3,"w":"1992年10月召开的中共十四大明确提出，我国经济体制改革的目标是建立社会主义市场经济体制。"}],"rel":[{"t":"南方谈话","n":"破除姓资姓社束缚"},{"t":"十八届三中全会","n":"提升为市场“决定性作用”"},{"t":"世界第二大经济体","n":"体制改革的重大成就"},{"t":"凯恩斯主义","n":"西方政府干预经济参照"}],"more":"关键演进：十二届三中全会（1984）提出“有计划的商品经济” → 十四大（1992）确立“社会主义市场经济体制” → 二十届三中全会（2024）提出构建高水平社会主义市场经济体制。","exam":[]},{"id":"a13-024","t":"“一国两制”","cid":"13a","p":1,"kind":"制度","alias":["一国两制","一国两制方针"],"one":"邓小平提出，解决台湾、香港、澳门问题的基本国策。","ans":"“一国两制”是**邓小平提出的和平统一祖国的构想**，即**在一个中国的前提下，国家主体坚持社会主义制度，香港、澳门、台湾保持原有资本主义制度长期不变**。它最初是为**解决台湾问题**设想的，后首先运用于香港、澳门。**1997年7月1日香港回归，1999年12月20日澳门回归**，两地依据基本法实行“港人治港”“澳人治澳”、高度自治。“一国两制”**实现了国家主权统一与区域制度差异的结合**，2027年是香港回归祖国30周年。","pts":["邓小平提出，一个中国前提下两种制度并存","1997年香港、1999年澳门回归","高度自治，“港人治港”；服务国家统一"],"mem":"回归口诀：“97香、99澳”，7月1日、12月20日。逻辑线：为台湾设想，却先在港澳落地。2027年7月1日是香港回归30周年，值得提前挂号。","mix":"“一国两制”与“一个中国原则”不同：前者是制度安排，后者是前提；香港由中英联合声明（1984）、澳门由中葡联合声明（1987）确认回归安排。","mcq":[{"q":"澳门回归祖国的时间是","o":["1999年12月20日","1997年7月1日","1999年10月1日","2000年1月1日"],"a":0,"w":"1999年12月20日；香港是1997年7月1日。"},{"q":"“一国两制”构想的提出者是","o":["毛泽东","邓小平","周恩来","江泽民"],"a":1,"w":"邓小平最初为解决台湾问题提出。"}],"rel":[{"t":"特别行政区基本法","n":"港澳两地的宪制文件"},{"t":"邓小平理论","n":"构想出自邓小平"},{"t":"九二共识","n":"同属对台政策表述"},{"t":"《开罗宣言》与《波茨坦公告》","n":"台湾回归的国际法依据"}],"more":"1984年中英联合声明，1987年中葡联合声明。\n1997年7月1日香港回归，1999年12月20日澳门回归；2027年香港回归30周年。","exam":[]},{"id":"a13-025","t":"九二共识","cid":"13a","p":3,"kind":"概念","one":"1992年海协会与海基会达成的两岸同属一个中国的政治共识。","ans":"九二共识是**1992年**大陆**海协会**与台湾**海基会**经香港会谈与函电往来达成的共识。双方各自以口头方式表述**海峡两岸同属一个中国**、共同谋求国家统一。它界定了两岸关系根本性质，是两岸对话协商的**共同政治基础**。","pts":["1992年海协会与海基会达成","核心是海峡两岸同属一个中国","两岸关系和平发展的共同政治基础"],"mem":"机构对照记：大陆是“海协会”（汪道涵任首任会长），台湾是“海基会”（辜振甫任董事长），1992年达成共识，促成1993年新加坡“汪辜会谈”。","mix":"不可混淆两个机构归属：海协会设在大陆，海基会设在台湾；九二共识核心是“一个中国原则”，而非“两个中国”或“一中一台”。","mcq":[{"q":"1992年达成“九二共识”的两个两岸授权民间团体是","o":["海协会与海基会","台盟与海基会","国台办与陆委会","海协会与台盟"],"a":0,"w":"1992年由大陆海协会（海峡两岸关系协会）与台湾海基会（海峡交流基金会）达成九二共识。"}],"rel":[{"t":"“一国两制”","n":"解决台湾问题的基本方针"},{"t":"汪道涵","n":"海协会首任会长，促成汪辜会谈"},{"t":"郑成功收复台湾","n":"台湾历史主权脉络"}],"more":"海协会全称海峡两岸关系协会，海基会全称海峡交流基金会；1993年4月双方在新加坡举行首次“汪辜会谈”。","exam":[],"alias":[]},{"id":"a13-026","t":"精准扶贫与脱贫攻坚","cid":"13a","p":2,"kind":"事件","alias":["精准扶贫","脱贫攻坚战","脱贫攻坚"],"one":"2013年湘西十八洞村首提精准扶贫，2021年宣告9899万贫困人口全部脱贫。","ans":"精准扶贫与脱贫攻坚是新时代中国开展的**人类史上规模最大的反贫困斗争**。**2013年11月**，习近平在**湖南湘西十八洞村**首提**“精准扶贫”**，确立因户施策方略。**2021年2月25日**表彰大会宣告全面胜利：现行标准下**9899万农村贫困人口全部脱贫**、**832个贫困县摘帽**、12.8万个贫困村出列，消除绝对贫困，写入**新时代三件大事**。","pts":["2013年11月湖南湘西十八洞村首提“精准扶贫”","2021年宣告9899万人脱贫、832县摘帽","历史性消除绝对贫困，写入新时代三件大事"],"mem":"地名+三组数字口诀：“湘西十八洞，九八八三十二八”（2013湘西十八洞村首提；9899万人、832个县、12.8万个村）。两不愁三保障：不愁吃穿，保障义务教育、基本医疗、住房安全。","mix":"脱贫攻坚消除的是**绝对贫困**和区域性整体贫困，相对贫困仍长期存在，因此之后转入巩固拓展脱贫攻坚成果同乡村振兴有效衔接阶段；首提地是湖南湘西**十八洞村**，勿与安徽凤阳**小岗村**（家庭联产承包责任制）混淆。","mcq":[{"q":"2013年11月习近平总书记首次提出“精准扶贫”重要理念的考察地点是","o":["湖南湘西十八洞村","安徽凤阳小岗村","浙江安吉余村","福建宁德下党村"],"a":0,"w":"2013年11月3日习近平在湖南湘西十八洞村首次提出“精准扶贫”；小岗村是农村改革起点，安吉余村是“两山”理念发源地。"}],"rel":[{"t":"新时代三件大事","n":"二十大概括的三大成就之一"},{"t":"“两个一百年”奋斗目标","n":"助力实现第一个百年目标"},{"t":"共同富裕","n":"脱贫之后的接续愿景"},{"t":"联合国2030年可持续发展议程","n":"提前10年完成减贫目标"}],"more":"国际贡献：中国提前10年实现《联合国2030年可持续发展议程》减贫目标，对全球减贫贡献率超过70%。","exam":[]},{"id":"a13-027","t":"乡村振兴战略","cid":"13c","p":3,"kind":"概念","alias":["乡村振兴"],"one":"2017年十九大提出，总要求为产业兴旺、生态宜居、乡风文明、治理有效、生活富裕。","ans":"乡村振兴战略是**2017年党的十九大**提出的“三农”工作总抓手。总要求为**产业兴旺、生态宜居、乡风文明、治理有效、生活富裕**，2021年出台**《乡村振兴促进法》**。它有效衔接脱贫攻坚，是建设**农业强国**与实现共同富裕的关键路径。","pts":["2017年党的十九大正式提出","总要求：产业、生态、乡风、治理、生活","接续脱贫攻坚，推进农业农村现代化"],"mem":"二十字口诀按“五位一体”对应记：产业兴旺（经济）、生态宜居（生态）、乡风文明（文化）、治理有效（政治）、生活富裕（社会），一秒不漏。","mix":"易与十六届五中全会“社会主义新农村建设”二十字方针（生产发展、生活宽裕、乡风文明、村容整洁、管理民主）混淆。","mcq":[{"q":"党的十九大提出乡村振兴战略，下列哪项不属于其二十字总要求","o":["村容整洁","产业兴旺","生态宜居","治理有效"],"a":0,"w":"“村容整洁”是社会主义新农村建设的方针，乡村振兴对应表述为“生态宜居”。"}],"rel":[{"t":"精准扶贫与脱贫攻坚","n":"乡村振兴有效衔接的前序任务"},{"t":"“五位一体”","n":"二十字总要求与五大建设对应"},{"t":"共同富裕","n":"推进城乡融合与共同富裕"},{"t":"平民教育与乡村建设运动","n":"近代乡村探索的历史对照"}],"more":"“五个振兴”：产业振兴、人才振兴、文化振兴、生态振兴、组织振兴。","exam":[]},{"id":"a13-028","t":"社会主义核心价值观","cid":"13b","p":1,"kind":"合称","alias":["核心价值观","24字核心价值观","二十四字"],"one":"国家、社会、公民三个层面共24字，十八大提出。","ans":"社会主义核心价值观是**2012年党的十八大提出的当代中国价值观念的集中表达**，共24个字、三个层面。**国家层面是富强、民主、文明、和谐，社会层面是自由、平等、公正、法治，公民个人层面是爱国、敬业、诚信、友善**。它把国家的价值目标、社会的价值取向和公民的价值准则结合起来，是**社会主义核心价值体系的内核**，是中华民族“最持久、最深层的力量”。2013年中央办公厅印发意见，培育和践行核心价值观成为精神文明建设的重点。","pts":["2012年十八大提出，三个层面24字","国家：富强民主文明和谐","社会：自由平等公正法治；公民：爱国敬业诚信友善"],"members":[["国家层面","富强、民主、文明、和谐"],["社会层面","自由、平等、公正、法治"],["公民个人层面","爱国、敬业、诚信、友善"]],"mem":"“国家四、社会四、公民四”，各四个词，共12词24字。记法：国家层面像“建设目标”，社会层面像“社会规则”，个人层面像“做人底线”。“富民文和，自平公法，爱敬诚友”。","mix":"“富强”“民主”“文明”“和谐”属于国家层面，不要与社会层面的“自由、平等”混；“爱国”属于个人层面，不属于国家层面。","mcq":[{"q":"属于社会主义核心价值观社会层面的是","o":["富强","爱国","敬业","自由"],"a":3,"w":"社会层面：自由、平等、公正、法治。"},{"q":"社会主义核心价值观由哪次会议提出","o":["党的十七大","党的十九大","十八届三中全会","党的十八大"],"a":3,"w":"2012年党的十八大。"}],"rel":[{"t":"“五位一体”","n":"同年十八大提出"},{"t":"《爱国主义教育法》","n":"个人层面“爱国”的法律体现"},{"t":"中国式现代化五个特征","n":"同簇表述"},{"t":"“四个自信”","n":"文化自信的内核"}],"more":"2012年十八大提出；2013年中办印发《关于培育和践行社会主义核心价值观的意见》。","exam":[]},{"id":"a13-029","t":"中国梦","cid":"13b","p":2,"kind":"概念","alias":["中华民族伟大复兴中国梦"],"one":"2012年11月参观《复兴之路》展览提出，内涵是国家富强、民族振兴、人民幸福。","ans":"中国梦是**2012年11月29日**习近平在国家博物馆参观**《复兴之路》**展览时提出的重大理念，核心是**实现中华民族伟大复兴**。其基本内涵是**国家富强、民族振兴、人民幸福**，归根到底是人民的梦。实现中国梦必须**走中国道路、弘扬中国精神、凝聚中国力量**。它把国家追求与人民期盼融为一体，成为凝聚中华儿女的精神旗帜。","pts":["2012年11月29日参观《复兴之路》展览时提出","本质是国家富强、民族振兴、人民幸福","走中国道路、弘扬中国精神、凝聚中国力量"],"mem":"三层同心圆记法：国（国家富强）→ 族（民族振兴）→ 民（人民幸福）；三大路径：“道、精、力”（中国道路、中国精神、中国力量）。场合锁定国家博物馆《复兴之路》展览。","mix":"中国梦的“基本内涵”是国家富强、民族振兴、人民幸福；“实现路径”才是中国道路、中国精神、中国力量，选择题常将内涵与路径混考。","mcq":[{"q":"2012年11月29日习近平首次提出“中国梦”时参观的展览是","o":["《伟大变革》","《百年征程》","《奋进新时代》","《复兴之路》"],"a":3,"w":"2012年11月29日，习近平在国家博物馆参观《复兴之路》展览时首次提出实现中华民族伟大复兴的“中国梦”。"}],"rel":[{"t":"“两个一百年”奋斗目标","n":"实现中国梦的阶段坐标"},{"t":"中国式现代化","n":"实现伟大复兴的必由之路"},{"t":"社会主义核心价值观","n":"凝聚中国精神的价值内核"},{"t":"习近平新时代中国特色社会主义思想","n":"引领复兴的指导思想"}],"more":"关键引语：“实现中华民族伟大复兴，就是中华民族近代以来最伟大的梦想。”（2012年11月29日）","exam":[]},{"id":"a13-030","t":"“两个一百年”奋斗目标","cid":"13b","p":1,"kind":"合称","alias":["两个一百年","两个一百年奋斗目标"],"one":"建党百年全面建成小康社会，建国百年建成现代化强国。","ans":"“两个一百年”奋斗目标是**党的十八大明确提出的奋斗目标**：**在中国共产党成立一百年时全面建成小康社会，在新中国成立一百年时建成富强民主文明和谐美丽的社会主义现代化强国**。**第一个百年奋斗目标已于2021年实现**，中国宣布全面建成小康社会、消除绝对贫困；第二个百年奋斗目标正在推进，按“两步走”部署，2035年基本实现现代化，本世纪中叶建成强国。它把**中华民族伟大复兴的中国梦**落到具体时间表上。","pts":["建党百年，全面建成小康社会（2021年实现）","建国百年，建成现代化强国","与“两步走”“中国梦”衔接"],"members":[["第一个百年（建党一百年，2021）","全面建成小康社会，已实现"],["第二个百年（建国一百年，2049）","建成富强民主文明和谐美丽的社会主义现代化强国"]],"mem":"“一党一国”：第一个百年对党（建党100年，2021）、第二个百年对国（建国100年，2049）。第一个叫“小康”，第二个叫“强国”，一个已完成，一个在路上。与新时代三件大事连起来：第三件大事就是实现第一个百年目标。","mix":"“两个一百年”是目标，“两步走”是第二个百年的时间安排；“三步走”是邓小平提出的上一代战略。","mcq":[{"q":"第一个百年奋斗目标的内容是","o":["建成现代化强国","基本实现现代化","全面建成小康社会","实现共同富裕"],"a":2,"w":"在建党一百年时全面建成小康社会，2021年已实现。"},{"q":"第二个百年奋斗目标的时间节点是","o":["中国共产党成立一百年","新中国成立一百年","改革开放一百年","香港回归一百年"],"a":1,"w":"新中国成立一百年，即本世纪中叶（2049年）。"}],"rel":[{"t":"“两步走”战略安排","n":"第二个百年的时间表"},{"t":"新时代三件大事","n":"其一实现第一个百年目标"},{"t":"中国梦","n":"目标落脚点"},{"t":"“三步走”发展战略","n":"邓小平时期的前一个战略"}],"more":"2021年建党百年大会宣布第一个百年奋斗目标已经实现。","exam":[]},{"id":"a13-031","t":"“两步走”战略安排","cid":"13b","p":1,"kind":"合称","alias":["两步走","“两步走”","两步走战略"],"one":"2035年基本实现现代化，本世纪中叶建成现代化强国。","ans":"“两步走”战略安排是**党的十九大提出、二十大重申的第二个百年奋斗阶段的时间表**。第一步是**从2020年到2035年基本实现社会主义现代化**，第二步是**从2035年到本世纪中叶，把我国建成富强民主文明和谐美丽的社会主义现代化强国**。它在邓小平“三步走”设想的基础上增设2035年节点，**把基本实现现代化的时间提前约15年**，并分两个阶段落实。二十大报告在此基础上明确以中国式现代化全面推进中华民族伟大复兴。","pts":["2020至2035年基本实现社会主义现代化","2035至本世纪中叶建成现代化强国","十九大提出，二十大重申"],"members":[["第一步","2020至2035年，基本实现社会主义现代化"],["第二步","2035至本世纪中叶，建成社会主义现代化强国"]],"mem":"“二〇三五，本世纪中”：35年是基本，49年是强国，一前一后。画面：2020年起跑，2035年过半场，本世纪中叶冲线。“两步走”与“三步走”别混，后者是小平版的1990年、2000年、21世纪中叶。","mix":"“两步走”属于新时代，“三步走”属于邓小平时期；“两个一百年”是目标，“两步走”是路径。","mcq":[{"q":"“两步走”战略安排中第一步的时间节点是","o":["2020年","2030年","2035年","2049年"],"a":2,"w":"到2035年基本实现社会主义现代化。"},{"q":"“两步走”战略安排首次提出于","o":["十八大","二十大","十九大","十九届五中全会"],"a":2,"w":"十九大提出，二十大重申。"}],"rel":[{"t":"“三步走”发展战略","n":"邓小平时期的前一战略"},{"t":"“两个一百年”奋斗目标","n":"其具体时间表"},{"t":"中国式现代化","n":"二十大报告中的主题"},{"t":"“十五五”规划","n":"迈向2035的第一步"}],"more":"十九大提出，二十大重申；2020年全面建成小康社会后，开启全面建设社会主义现代化国家新征程。","exam":[]},{"id":"a13-032","t":"“四个自信”","cid":"13b","p":2,"kind":"合称","alias":["四个自信"],"one":"道路自信、理论自信、制度自信、文化自信，2016年增补文化自信为更深厚的自信。","ans":"“四个自信”是中国特色社会主义核心表述，包括**道路自信、理论自信、制度自信、文化自信**。2012年十八大提出前“三个自信”；**2016年7月1日**习近平在庆祝建党95周年大会上增补**文化自信**，指出它是**更基础、更广泛、更深厚的自信**。四者筑牢国家发展底气，**2017年党的十九大**写入党章，成为坚定历史主动的重要支撑。","pts":["道路自信、理论自信、制度自信、文化自信","2016年建党95周年大会由三自信扩为四自信","文化自信是更基础、更广泛、更深厚的自信"],"members":[["道路自信","对中国特色社会主义发展方向与未来命运的自信"],["理论自信","对中国特色社会主义理论体系科学性与真理性自信"],["制度自信","对中国特色社会主义制度先进性与优越性的自信"],["文化自信","更基础、更广泛、更深厚的自信，2016年增补"]],"mem":"四字口诀：“道、理、制、文”（讲“道理”、立“制度”、兴“文化”）。牢记升级年份：2012十八大（三个自信）→ 2016建党95周年（加文化自信变四个）。","mix":"易与“四个意识”（政治、大局、核心、看齐意识）、“四个全面”和“四个伟大”混淆；文化自信是后加入的第四项，却被定位为“更基础、更广泛、更深厚”。","mcq":[{"q":"在“四个自信”中，被定位为“更基础、更广泛、更深厚的自信”的是","o":["文化自信","道路自信","理论自信","制度自信"],"a":0,"w":"2016年7月1日习近平在庆祝建党95周年大会上指出，文化自信是更基础、更广泛、更深厚的自信。"}],"rel":[{"t":"“四个意识”与“两个维护”","n":"同属新时代数字政治表述"},{"t":"“四个伟大”","n":"易混的“四个”合称"},{"t":"“两个结合”","n":"筑牢文化自信的理论路径"},{"t":"创造性转化、创新性发展","n":"弘扬传统文化的方法论"}],"more":"关键年份：2012年十八大提出“三个自信”；2016年7月1日扩充为“四个自信”；2017年十九大写入党章。","exam":[]},{"id":"a13-033","t":"“四个意识”与“两个维护”","cid":"13b","p":3,"kind":"合称","alias":["四个意识","两个维护"],"one":"新时代党的政治建设核心要求，分别于2016年与2018年正式提出。","ans":"二者是新时代**党的政治建设**核心要求。“四个意识”于2016年提出，指**政治、大局、核心、看齐意识**；“两个维护”于2018年正式提出，指坚决维护习近平总书记**党中央的核心、全党的核心地位**，坚决维护**党中央权威和集中统一领导**。","pts":["四个意识：政治、大局、核心、看齐","两个维护：维护核心地位与党中央权威","新时代党的政治建设核心规范"],"members":[["政治意识","坚定政治立场与政治方向"],["大局意识","自觉从党和国家大局出发想问题"],["核心意识","坚决拥护党中央领导核心"],["看齐意识","经常主动向党中央和党的理论路线看齐"],["维护核心地位","坚决维护习近平总书记党中央的核心、全党的核心地位"],["维护党中央权威","坚决维护党中央权威和集中统一领导"]],"mem":"口诀“政大核齐，维核维权”：先记住四个意识首字“政、大、核、齐”（像“政大合齐”），再记两个维护紧扣“核心”与“权威”。","mix":"易与“四个自信”（道路、理论、制度、文化）和“两个确立”（确立核心地位、确立指导地位）混淆：“确立”是历史结论，“维护”是行动要求。","mcq":[{"q":"下列各项中，不属于“四个意识”内容的是","o":["政治意识","创新意识","核心意识","看齐意识"],"a":1,"w":"“四个意识”是政治意识、大局意识、核心意识、看齐意识，不含“创新意识”。"}],"rel":[{"t":"“两个确立”","n":"“两个维护”的理论与历史前提"},{"t":"“四个自信”","n":"常与四个意识、两个维护并提"},{"t":"“四个全面”","n":"同属新时代数字合称"}],"exam":[]},{"id":"a13-034","t":"“四个伟大”","cid":"13b","p":3,"kind":"合称","alias":["四个伟大"],"one":"十九大报告提出：伟大斗争、伟大工程、伟大事业、伟大梦想。","ans":"“四个伟大”是**2017年党的十九大报告**系统阐述的新时代历史使命，包括**伟大斗争、伟大工程、伟大事业、伟大梦想**。其中**伟大工程**指**党的建设新的伟大工程**，在四者中起**决定性作用**，统揽全局并指向民族复兴。","pts":["伟大斗争、伟大工程、伟大事业、伟大梦想","2017年党的十九大报告系统阐述","伟大工程（党的建设）起决定性作用"],"members":[["伟大斗争","进行具有许多新的历史特点的伟大斗争（手段）"],["伟大工程","推进党的建设新的伟大工程（起决定性作用）"],["伟大事业","推进中国特色社会主义伟大事业（主题）"],["伟大梦想","实现中华民族伟大复兴的中国梦（目标）"]],"mem":"口诀“斗工事梦，工程决定”：先斗争、建工程、干事业、圆梦想；选择题最常考“起决定性作用的是伟大工程（党建）”。","mix":"常把“伟大事业”（中国特色社会主义）与“伟大工程”（党的建设）设作干扰项互换；“伟大工程”才是起决定性作用的一项。","mcq":[{"q":"党的十九大报告提出“四个伟大”，其中起决定性作用的是","o":["伟大斗争","伟大梦想","党的建设新的伟大工程","中国特色社会主义伟大事业"],"a":2,"w":"“四个伟大”中，起决定性作用的是党的建设新的伟大工程。"}],"rel":[{"t":"中国梦","n":"对应“伟大梦想”"},{"t":"“四个全面”","n":"同属新时代重要数字合称"},{"t":"全面从严治党","n":"对应“伟大工程”的核心要求"}],"exam":[]},{"id":"a13-035","t":"总体国家安全观","cid":"13b","p":2,"kind":"概念","one":"2014年4月15日提出，以人民安全为宗旨，统筹发展和安全，4月15日为国安日。","ans":"总体国家安全观是新时代国家安全工作指导思想，由习近平于**2014年4月15日**在**中央国安委第一次会议**上首提。它强调**以人民安全为宗旨**、**以政治安全为根本**、以经济安全为基础，核心是**统筹发展和安全**。2015年《国家安全法》将每年**4月15日**定为**全民国家安全教育日**。它覆盖政治、经济、数据与AI等领域，构建起系统国家安全体系。","pts":["2014年4月15日中央国安委首次会议提出","人民安全为宗旨、政治安全为根本、统筹发展和安全","每年4月15日为全民国家安全教育日"],"mem":"三句核心排序：“民宗、政根、经基”（人民安全是宗旨，政治安全是根本，经济安全是基础）。日期挂钩：2014年4月15日提出，所以每年4月15日就是全民国家安全教育日。","mix":"选择题常把“宗旨（人民安全）”与“根本（政治安全）”互换设陷阱；全民国家安全教育日是**4月15日**，勿与国家宪法日（12月4日）或全国生态日（8月15日）混淆。","mcq":[{"q":"总体国家安全观的提出日期，也是我国“全民国家安全教育日”的是每年的","o":["3月15日","4月15日","8月15日","12月4日"],"a":1,"w":"2014年4月15日习近平首次提出总体国家安全观，2015年《国家安全法》将每年4月15日定为全民国家安全教育日。"}],"rel":[{"t":"《国家安全法》","n":"2015年确立国安教育日"},{"t":"《网络安全法》","n":"网络空间安全配套立法"},{"t":"《数据安全法》","n":"数据安全领域专项立法"},{"t":"全球四大倡议","n":"含2022年全球安全倡议"}],"more":"关键日期对比：4月15日全民国家安全教育日；8月15日全国生态日；12月4日国家宪法日。","exam":[],"alias":[]},{"id":"a13-036","t":"社会主要矛盾的转化","cid":"13b","p":2,"kind":"概念","alias":["新时代社会主要矛盾","我国社会主要矛盾"],"one":"2017年十九大论断：人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。","ans":"社会主要矛盾的转化是**2017年中共十九大**作出的全局性论断，标志中国特色社会主义进入新时代。报告指出，我国社会主要矛盾已由1981年概括的物质文化需要同落后社会生产之间的矛盾，转化为**人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾**。同时明确我国仍处**社会主义初级阶段**和**最大发展中国家**的定位不变，为高质量发展提供依据。","pts":["2017年党的十九大作出社会主要矛盾转化论断","美好生活需要与不平衡不充分的发展之间的矛盾","“两个没有变”：初级阶段国情与最大发展中国家地位"],"mem":"前后替换对比：“物质文化需要”升级为“美好生活需要”（要得更丰富），“落后的社会生产”升级为“不平衡不充分的发展”（总量大了但分布与质量不均）。记“一变两不变”。","mix":"注意三次关键表述：1956年**中共八大**首次分析社会主义主要矛盾（先进工业国要求同落后农业国现实等）；1981年**十一届六中全会**定型为“物质文化需要同落后的社会生产”；2017年**十九大**作出新时代转化论断。","mcq":[{"q":"作出“我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾”论断的会议是","o":["中共八大","中共十八大","中共十九大","中共二十大"],"a":2,"w":"2017年10月召开的中共十九大明确提出我国社会主要矛盾发生历史性转化。"}],"rel":[{"t":"中共八大","n":"1956年首次分析主要矛盾"},{"t":"社会主义初级阶段与“一个中心、两个基本点”","n":"基本国情没有改变"},{"t":"高质量发展","n":"破解不平衡不充分的路径"},{"t":"共同富裕","n":"回应美好生活需要的目标"}],"more":"关键时间线：1956年中共八大 → 1981年十一届六中全会（第二个历史决议）→ 2017年中共十九大。","exam":[]},{"id":"a13-037","t":"高质量发展","cid":"13c","p":2,"kind":"概念","one":"十九大提出我国经济转向高质量发展阶段，二十大明确其为现代化国家建设的首要任务。","ans":"高质量发展是体现**新发展理念**的发展方式，即创新为第一动力、协调为内生特点、绿色为普遍形态、开放为必由之路、共享为根本目的。**2017年中共十九大**判断我国经济由**高速增长转向高质量发展阶段**；**2022年中共二十大**明确它是**全面建设社会主义现代化国家的首要任务**。它依托**新质生产力**实现质的有效提升和量的合理增长。","pts":["十九大判断：由高速增长阶段转向高质量发展阶段","二十大定位：全面建设社会主义现代化国家的首要任务","以新发展理念为指引，追求质的有效提升和量的合理增长"],"mem":"两届党代会递进记忆：“十九大换挡（高速→高质量），二十大置顶（首要任务）”。与五大新发展理念一一挂钩：创新动力、协调特点、绿色形态、开放之路、共享目的。","mix":"高质量发展追求的是**质的有效提升和量的合理增长**，并非放弃经济增长速度；注意区分“首要任务”（高质量发展）与“战略支撑”（教育、科技、人才，二十大表述）。","mcq":[{"q":"党的二十大报告明确指出，全面建设社会主义现代化国家的首要任务是","o":["高质量发展","构建新发展格局","实现共同富裕","推进全面依法治国"],"a":0,"w":"党的二十大报告明确提出：“高质量发展是全面建设社会主义现代化国家的首要任务。”"}],"rel":[{"t":"新发展理念","n":"高质量发展的评价标准"},{"t":"新质生产力","n":"推动高质量发展的内在要求"},{"t":"社会主要矛盾的转化","n":"转向高质量发展的现实依据"},{"t":"双循环","n":"支撑高质量发展的新格局"}],"more":"关键表述：2023至2024年进一步提出“发展新质生产力是推动高质量发展的内在要求和重要着力点”。","exam":[],"alias":[]},{"id":"a13-038","t":"供给侧结构性改革","cid":"13c","p":2,"kind":"概念","alias":["供给侧改革","三去一降一补"],"one":"2015年提出，主线是提高供给质量，重点任务为“三去一降一补”。","ans":"供给侧结构性改革是**2015年11月**提出的重大经济政策，旨在适应和引领经济发展新常态。它从**提高供给质量**出发，用改革办法推进结构调整，减少无效低端供给、扩大中高端有效供给，矫正要素配置扭曲。重点任务概括为**“三去一降一补”**，即**去产能、去库存、去杠杆、降成本、补短板**。它同扩大内需有机结合，成为推动我国经济转向**高质量发展**的主线。","pts":["2015年提出，立足提高供给质量与优化要素配置","核心任务“三去一降一补”：去产能库存杠杆降本补短","与扩大内需结合，推动经济转向高质量发展"],"mem":"“三去一降一补”画面拆解：先做减法（去钢铁煤炭过剩产能、去三四线房产库存、去企业过高债务杠杆、降税费融资成本），再做加法（补科技民生基础设施短板）。","mix":"供给侧结构性改革不同于西方20世纪80年代侧重减税和放松管制的**供给学派**，它强调政府与市场协同发力、把深化供给侧改革同扩大内需有机结合。","mcq":[{"q":"我国供给侧结构性改革“三去一降一补”重点任务中的“三去”指的是","o":["去行政化、去冗余、去泡沫","去垄断、去壁垒、去赤字","去产能、去库存、去杠杆","去通胀、去库存、去依赖"],"a":2,"w":"“三去一降一补”指去产能、去库存、去杠杆、降成本、补短板。"}],"rel":[{"t":"高质量发展","n":"结构性改革的目标方向"},{"t":"“三驾马车”","n":"需求侧拉动的对照概念"},{"t":"双循环","n":"供需高水平动态平衡"},{"t":"凯恩斯主义","n":"侧重需求侧管理的学派"}],"more":"关键年份：2015年11月10日首次提出；2015年12月中央经济工作会议正式部署“三去一降一补”五大任务。","exam":[]},{"id":"a13-039","t":"五年规划","cid":"13c","p":2,"kind":"制度","alias":["五年计划","国民经济和社会发展五年规划"],"one":"我国中长期规划制度，1953年“一五”起步，“十一五”改称规划，十五五开局。","ans":"五年规划全称**国民经济和社会发展五年规划**，是我国中长期战略制度，由中央提建议、国务院编纲要、**全国人大审查批准**。**1953至1957年“一五”计划**奠定工业化初步基础；2006年**“十一五”**起“计划”改称**“规划”**。**“十五五”（2026至2030年）**纲要2026年3月获批，同期通过**《国家发展规划法》**，规划步入法治化轨道。","pts":["1953至1957年“一五”起步，全国人大审查批准","2006年“十一五”起由“计划”改称“规划”","“十五五”2026开局，同年通过《国家发展规划法》"],"mem":"三个里程碑年份：“1953一五起（计划）→ 2006十一五改名（规划）→ 2026十五五入法（《国家发展规划法》）”。流程口诀：“党提建议、院编纲要、人大批准”。","mix":"“计划”改称“规划”始于**“十一五”**（2006至2010年），常被误记为“十五”或“十二五”；编制程序上，中央全会通过的是《建议》，全国人大审查批准的才是《纲要》。","mcq":[{"q":"我国国民经济和社会发展五年蓝图正式将“计划”改称为“规划”始于","o":["“九五”时期","“十五”时期","“十二五”时期","“十一五”时期"],"a":3,"w":"从“十一五”（2006至2010年）起，我国将延续半个多世纪的五年“计划”改称五年“规划”。"}],"rel":[{"t":"“十五五”规划","n":"2026至2030年最新一期"},{"t":"国家发展规划法","n":"2026年3月将规划法治化"},{"t":"二十届四中全会","n":"2025年通过十五五建议"},{"t":"全国人民代表大会","n":"规划纲要的法定批准机关"}],"more":"关键年份对照：“一五”（1953至1957）；“十一五”（2006至2010，改称规划）；“十四五”（2021至2025）；“十五五”（2026至2030，2026年3月12日批准纲要）。","exam":[]},{"id":"a13-040","t":"区域重大战略","cid":"13c","p":2,"kind":"合称","alias":["五大区域重大战略"],"one":"京津冀、长江经济带、粤港澳大湾区、长三角一体化、黄河流域生态保护五大战略。","ans":"区域重大战略是新时代优化国土空间布局的**五大国家级战略**，包括**京津冀协同发展**（2017年4月设**雄安新区**疏解北京非首都功能）、**长江经济带发展**（共抓大保护、不搞大开发）、**粤港澳大湾区建设**、**长三角一体化发展**（上海为龙头）和**黄河流域生态保护和高质量发展**。五大战略覆盖三大城市群与两大流域，构筑高质量发展动力源。","pts":["五大战略：京津冀、长江、粤港澳、长三角、黄河流域","2017年4月设立雄安新区服务京津冀协同发展","三大城市群加两大流域，上海为长三角一体化龙头"],"members":[["京津冀协同发展","疏解北京非首都功能，2017年4月设立雄安新区"],["长江经济带发展","坚持“共抓大保护、不搞大开发”，横贯东中西"],["粤港澳大湾区建设","香港、澳门与珠三角9市共建国际一流湾区"],["长三角一体化发展","沪苏浙皖联动，上海发挥龙头带动作用"],["黄河流域生态保护和高质量发展","统筹上中下游生态保护与流域振兴"]],"mem":"地理归类口诀：“三群加两河”。三大城市群从北到南：京津冀、长三角、粤港澳；两条母亲河：长江经济带、黄河流域。一下记住全部五个，绝不漏项。","mix":"注意区分**区域重大战略**（上述5项）与**区域协调发展战略**（西部大开发、东北全面振兴、中部地区崛起、东部率先发展“四大板块”），选择题常将“西部大开发”等混作干扰项。","mcq":[{"q":"下列各项中，不属于新时代我国五大“区域重大战略”的是","o":["东北全面振兴","京津冀协同发展","长三角一体化发展","黄河流域生态保护和高质量发展"],"a":0,"w":"东北全面振兴属于“区域协调发展战略”四大板块之一；五大区域重大战略是京津冀、长江经济带、粤港澳大湾区、长三角、黄河流域。"}],"rel":[{"t":"长三角一体化发展","n":"五大战略之一与上海考点"},{"t":"上海“三大任务”","n":"长三角一体化列于其中"},{"t":"长江","n":"长江经济带自然载体"},{"t":"黄河","n":"黄河流域战略自然载体"}],"more":"关键年份：2014年京津冀协同发展上升为国家战略；2017年4月1日宣布设立雄安新区；2018年11月首届进博会宣布长三角一体化上升为国家战略；2019年2月印发粤港澳大湾区规划纲要、9月提出黄河流域战略。","exam":[]},{"id":"a13-041","t":"海南自由贸易港","cid":"13c","p":2,"kind":"制度","alias":["海南自贸港"],"one":"我国最高水平开放形态，2020年公布方案，2025年12月18日全岛封关运作。","ans":"海南自由贸易港是我国在海南全岛探索建设的**最高水平对外开放形态**。**2020年6月**公布**《海南自由贸易港建设总体方案》**，实行**零关税、低税率、简税制**政策。**2025年12月18日**正式启动**全岛封关运作**，全面实施**“一线”放开、“二线”管住、岛内自由**的政策制度，全岛成为海关监管特殊区域，标志着我国制度型开放迈上新台阶。","pts":["2020年6月公布总体方案，实行零关税低税率简税制","2025年12月18日正式启动全岛封关运作","核心特征：“一线”放开、“二线”管住、岛内自由"],"mem":"空间拆解“一线二线”：海南岛与境外之间是“一线”（放开、零关税进出），海南岛与内地之间是“二线”（精准管住货物税收），岛内要素自由流动。日期记“12·18”，呼应1978年12月18日十一届三中全会开幕日。","mix":"“封关运作”代表更高水平对外开放，并非封岛或封闭，普通居民和游客进出海南无需额外证件；海南1988年设经济特区、2018年设全岛自贸试验区、2025年底自贸港封关，层次逐级跃升。","mcq":[{"q":"2025年12月18日海南自由贸易港正式启动全岛封关运作，其核心政策制度特征是","o":["准入前国民待遇加负面清单","境内关内、全岛免税","“一线”放开、“二线”管住、岛内自由","前店后厂、两头在外"],"a":2,"w":"海南自贸港全岛封关运作全面实施以“一线”放开、“二线”管住、岛内自由为基本特征的自由化便利化政策制度。"}],"rel":[{"t":"自由贸易试验区","n":"同簇更高阶的开放升级"},{"t":"经济特区","n":"1988年设立海南经济特区"},{"t":"上海自贸试验区与临港新片区","n":"制度型开放的沪琼呼应"},{"t":"一带一路","n":"面向太平洋印度洋枢纽"}],"more":"选定2025年12月18日封关恰逢1978年党的十一届三中全会召开纪念日；全岛8个对外开放口岸与10个“二线口岸”同步启用。","exam":[]},{"id":"a13-042","t":"“绿水青山就是金山银山”","cid":"13c","p":2,"kind":"概念","alias":["两山理念","两山论","绿水青山就是金山银山"],"one":"2005年8月15日习近平在浙江安吉余村提出，是习近平生态文明思想的标志性论断。","ans":"“绿水青山就是金山银山”（简称**“两山”理念**）是**习近平生态文明思想**的标志性论断。**2005年8月15日**，习近平在**浙江安吉余村**考察时首提，揭示生态环境保护与经济发展的辩证统一。2017年党的十九大将其写入党章；**2023年起**每年**8月15日**设为**全国生态日**。它引领我国推进“双碳”目标与全面绿色转型，并获国际社会广泛认可。","pts":["2005年8月15日浙江安吉余村首提，简称两山理念","习近平生态文明思想的标志性论断，阐明生态与发展统一","十九大写入党章，每年8月15日为全国生态日"],"mem":"地点日期双锁定：“2005·8·15，安吉余村竹海绿”。8月15日即是全国生态日，和4月15日（总体国家安全观→全民国安教育日）的“提出日变纪念日”规律完全相同。","mix":"首提地是**浙江安吉余村**，勿与湖南湘西十八洞村（精准扶贫）或安徽凤阳小岗村（包产到户）混淆；2025年为“两山”理念提出20周年。","mcq":[{"q":"2005年8月15日首次提出“绿水青山就是金山银山”理念的地点是","o":["福建长汀","浙江安吉余村","江苏昆山","江西婺源"],"a":1,"w":"2005年8月15日习近平在浙江湖州安吉县余村考察时首次提出“绿水青山就是金山银山”，2023年起每年8月15日定为全国生态日。"}],"rel":[{"t":"全国生态日","n":"以提出日期8月15日设立"},{"t":"碳达峰碳中和","n":"绿色转型的量化目标"},{"t":"生态环境法典","n":"生态文明建设的法治化"},{"t":"道法自然与无为而治","n":"传统自然观的历史呼应"}],"more":"关键节点：2005年8月15日提出；2017年写入党章；2023年6月全国人大常委会决定设8月15日为全国生态日；2025年迎提出20周年。","exam":[]},{"id":"a13-043","t":"《巴黎协定》","cid":"13c","p":1,"kind":"事件","alias":["巴黎协定","巴黎气候协定"],"one":"2015年通过的全球气候协定，目标是将升温控制在远低于2℃，并努力限制在1.5℃以内。","ans":"《巴黎协定》是**2015年12月在巴黎气候大会上通过、2016年11月4日生效的全球气候治理协定**，是《联合国气候变化框架公约》下继1997年《京都议定书》之后的重要成果。其目标是**把全球平均气温升幅控制在较工业化前水平高出远低于2℃的范围，并努力限制在1.5℃以内**，各缔约方以**国家自主贡献**方式承担减排责任，每五年盘点一次。它**打破了只有发达国家承担减排义务的模式**，中国2016年批准，并据此提出“双碳”目标。","pts":["2015年12月通过，2016年11月4日生效","升温远低于2℃，努力限制在1.5℃以内","国家自主贡献；继《京都议定书》之后"],"mem":"数字线：1992框架公约→1997京都→2015巴黎，三个气候里程碑。巴黎“2℃与1.5℃”：远低于2℃，努力限制在1.5℃以内。京都议定书只管发达国家，巴黎协定“人人自主”，做法一一对照。","mix":"《京都议定书》（1997）规定发达国家量化减排，《巴黎协定》（2015）所有缔约方以国家自主贡献参与；《联合国气候变化框架公约》是1992年。","mcq":[{"q":"《巴黎协定》的温控目标是","o":["1℃以内","1.5℃以内","3℃以内","远低于2℃并努力限制在1.5℃以内"],"a":3,"w":"相对工业化前水平，升温远低于2℃，并努力限制在1.5℃以内。"},{"q":"《巴黎协定》通过于","o":["1997年","2009年","2020年","2015年"],"a":3,"w":"2015年12月；1997年是《京都议定书》。"}],"rel":[{"t":"碳达峰碳中和","n":"中国双碳的国际背景"},{"t":"联合国气候变化大会第三十一次缔约方大会（COP31）","n":"气候大会延续"},{"t":"全国碳排放权交易市场","n":"落实手段"},{"t":"联合国","n":"气候公约的体系"}],"more":"1992年《联合国气候变化框架公约》，1997年《京都议定书》，2015年《巴黎协定》。","exam":[]},{"id":"a13-044","t":"全国碳排放权交易市场","cid":"13c","p":3,"kind":"制度","alias":["全国碳市场"],"one":"2021年7月上线交易，2025年扩围至钢铁、水泥、铝冶炼行业。","ans":"全国碳排放权交易市场是我国控制温室气体排放的核心市场机制。市场于**2021年7月16日**上线交易，首批纳入**发电行业**，为全球覆盖排放规模最大碳市场。**2025年3月**印发扩围方案，新增**钢铁、水泥、铝冶炼**行业，助力实现**“双碳”目标**。","pts":["2021年7月16日上线，首批仅含发电行业","2025年扩围纳入钢铁、水泥、铝冶炼","以配额交易倒逼高耗能行业减碳"],"mem":"行业口诀“先发电，后钢水铝”：2021年发电行业先打头阵，2025年“钢铁、水泥、铝冶炼”三兄弟集体入场。","mix":"全国碳市场交易系统设在上海，注册登记系统设在武汉；除强制配额市场外，2024年1月还重启了全国温室气体自愿减排交易市场（CCER）。","mcq":[{"q":"2021年7月全国碳排放权交易市场启动上线交易时，首批纳入的行业是","o":["钢铁行业","发电行业","水泥行业","航空行业"],"a":1,"w":"全国碳市场2021年7月16日启动上线交易，首批仅纳入发电行业，2025年扩围至钢铁、水泥、铝冶炼。"}],"rel":[{"t":"碳达峰碳中和","n":"实现“双碳”的核心市场机制"},{"t":"绿色转型","n":"市场化推动高碳行业转型"},{"t":"《巴黎协定》","n":"国际气候治理背景"}],"more":"2025年扩围后新增重点排放单位约1500家，覆盖全国二氧化碳当量排放总量占比由约40%提升至约60%。","exam":[]},{"id":"a13-045","t":"联合国气候变化大会第三十一次缔约方大会（COP31）","cid":"13c","p":3,"kind":"时事","alias":["COP31","安塔利亚气候大会"],"one":"2026年11月在土耳其安塔利亚举行，土耳其主办、澳大利亚主持谈判。","ans":"COP31是**《联合国气候变化框架公约》**第31次缔约方大会，**2026年11月9日在土耳其安塔利亚开幕**，原定20日结束，**实际于11月22日闭幕**。大会首创联合机制，由**土耳其任主席国并主办**、**澳大利亚主持谈判**，在公正转型、气候融资、适应等议题上作出决定，主席牵头的总括决定没有达成一致。","pts":["2026年11月9日至22日，土耳其安塔利亚","土耳其主办兼主席国，澳大利亚主持谈判","公正转型、气候融资、适应取得进展"],"mem":"画面记忆“土澳分工办COP31”：土耳其出场地在海滨城市安塔利亚当东道主，澳大利亚拿着话筒在台上主持谈判。","mix":"易与前几届混淆：COP28在阿联酋迪拜（2023）、COP29在阿塞拜疆巴库（2024）、COP30在巴西贝伦（2025）、COP31在土耳其安塔利亚（2026）。","mcq":[{"q":"2026年11月举行的联合国气候变化大会（COP31）的主办地位于","o":["巴西贝伦","澳大利亚阿德莱德","土耳其安塔利亚","阿塞拜疆巴库"],"a":2,"w":"COP31于2026年11月在土耳其安塔利亚举办，由土耳其任主席国并主办、澳大利亚主持谈判。"}],"rel":[{"t":"《巴黎协定》","n":"COP21达成的核心气候条约"},{"t":"碳达峰碳中和","n":"中国参与全球气候治理的目标"},{"t":"温室效应","n":"气候变化大会应对的科学背景"},{"t":"臭氧层与《蒙特利尔议定书》","n":"同属国际环境治理条约"},{"t":"三大里约公约","n":"所属公约体系"}],"more":"会期：2026年11月9日开幕，原定20日闭幕，实际11月22日闭幕。COP即Conference of the Parties（缔约方大会）。","exam":[]},{"id":"a13-046","t":"全国统一大市场","cid":"13c","p":2,"kind":"概念","alias":["建设全国统一大市场"],"one":"2022年4月发文部署，破除地方保护与分割，2025年明确“五统一、一开放”。","ans":"全国统一大市场指在全国实行**统一市场规则、破除地方保护与分割**、畅通商品要素流动的现代市场体系，是**新发展格局**的基础支撑。**2022年4月**中央印发**《关于加快建设全国统一大市场的意见》**；**2025年7月**中央财经委会议明确**“五统一、一开放”**要求（统一制度、设施、政府行为、监管与要素市场并扩大开放），成为“十五五”重点任务。","pts":["2022年4月中央发文部署，破除地方保护与市场分割","2025年明确“五统一、一开放”基本要求","畅通国内大循环、构建新发展格局的基础支撑"],"mem":"“破立结合”逻辑记忆：破掉地方保护和无序内卷，立起“五统一、一开放”（制度、设施、政府行为、监管执法、要素市场五统一 + 对内对外开放）。","mix":"建设全国统一大市场面向全球充分开放，兼顾有效市场与有为政府，绝非搞封闭小循环或回归计划经济。","mcq":[{"q":"2025年中央财经委员会会议明确纵深推进全国统一大市场建设的基本要求是","o":["“五统一、一开放”","“三去一降一补”","“一线放开、二线管住”","“六个稳、六个保”"],"a":0,"w":"2025年7月中央财经委员会会议将纵深推进全国统一大市场建设的基本要求概括为“五统一、一开放”。"}],"rel":[{"t":"双循环","n":"畅通国内大循环的根基"},{"t":"社会主义市场经济体制","n":"高水平市场体制关键举措"},{"t":"“十五五”规划","n":"规划纲要高频部署任务"},{"t":"《民营经济促进法》","n":"保障公平竞争的法治配套"}],"more":"关键节点：2022年4月10日印发《关于加快建设全国统一大市场的意见》；2025年1月国家发改委发布《全国统一大市场建设指引（试行）》。","exam":[]},{"id":"a13-047","t":"低空经济","cid":"13c","p":2,"kind":"概念","one":"以无人机与eVTOL等低空飞行牵引的综合经济形态，2024年首入政府工作报告。","ans":"低空经济是以**民用有人和无人驾驶航空器**（无人机、**电动垂直起降飞行器eVTOL**等）低空飞行活动为牵引，带动制造、基建与服务的**综合性经济形态**，属**新质生产力**代表。**2024年**首入《政府工作报告》，同年12月国家发改委**低空经济发展司**亮相；**2026年报告**列为**新兴支柱产业**。它广泛用于物流配送、应急救援与文旅，成为新增长引擎。","pts":["无人机、eVTOL等低空飞行牵引的综合性经济形态","2024年首入报告，年底发改委设低空经济发展司","2026年报告列为新兴支柱产业，代表新质生产力"],"mem":"三年三级跳记政策演进：2024首入报告（新增长引擎）+年底设“低空司” → 2025报告（安全健康发展）→ 2026报告（新兴支柱产业）。核心装备记“无人机 + eVTOL（飞行汽车）”。","mix":"低空经济涵盖**有人驾驶与无人驾驶**两类民用航空器，并不等同于单纯的“无人机产业”；同时需区分于主要在近地轨道开展的“商业航天”。","mcq":[{"q":"“低空经济”首次被写入国务院《政府工作报告》的年份是","o":["2021年","2022年","2023年","2024年"],"a":3,"w":"2024年《政府工作报告》首次写入“低空经济”，将其与生物制造、商业航天并列为新增长引擎；2026年报告进一步将其列为新兴支柱产业。"}],"rel":[{"t":"新质生产力","n":"低空经济所属战略赛道"},{"t":"未来产业","n":"同属新兴与前沿产业布局"},{"t":"2026年政府工作报告","n":"2026年列为新兴支柱产业"},{"t":"中国商飞与C919","n":"同属航空产业（干线客机）"}],"more":"eVTOL 全称 electric Vertical Take-Off and Landing（电动垂直起降飞行器），常被通俗称为“空中出租车”或“飞行汽车”。","exam":[],"alias":[]},{"id":"a13-048","t":"未来产业","cid":"13c","p":2,"kind":"概念","alias":["未来产业六大方向"],"one":"前沿技术驱动的先导产业，布局未来制造、信息、材料、能源、空间、健康六大方向。","ans":"未来产业是由**前沿技术创新驱动**、处于孕育或产业化初期的先导产业，是培育**新质生产力**的重要阵地。**2024年1月**工信部等七部门发文明确**未来制造、信息、材料、能源、空间、健康**六大方向，涵盖**量子科技、具身智能、类脑智能、基因技术、6G**等领域。**2026年《政府工作报告》**部署建立投入增长和风险分担机制，推动成果加速产业化。","pts":["前沿技术驱动的先导产业，新质生产力重要阵地","六大方向：制造、信息、材料、能源、空间、健康","2026年报告部署建立投入增长和风险分担机制"],"mem":"六大方向口诀：“制、信、材、能、空、健”（造机器、传信息、换材料、新能源、闯空间、护健康）。高频代表技术记四个热词：量子、具身智能、脑机接口、6G。","mix":"注意区分“战略性新兴产业”（已具一定规模，如新能源车、光伏）与**“未来产业”**（尚处孕育或产业化初期，不确定性高、需长期“耐心资本”支持）。","mcq":[{"q":"2024年工信部等七部门文件明确的我国未来产业六大重点方向不包括","o":["未来制造与未来信息","未来农业与未来金融","未来材料与未来能源","未来空间与未来健康"],"a":1,"w":"七部门《实施意见》明确的六大方向是未来制造、未来信息、未来材料、未来能源、未来空间、未来健康，不含未来农业与未来金融。"}],"rel":[{"t":"新质生产力","n":"未来产业的核心战略指向"},{"t":"具身智能","n":"未来制造重点前沿赛道"},{"t":"量子科技","n":"未来信息底层核心技术"},{"t":"耐心资本","n":"支撑未来产业的长期资金"}],"more":"2024年文件目标：到2025年突破百项前沿关键核心技术、形成百项标志性产品；到2027年成为世界未来产业重要策源地。","exam":[]},{"id":"a13-049","t":"银发经济","cid":"13c","p":3,"kind":"概念","alias":["老龄经济"],"one":"向老年人提供产品服务及为老龄阶段做准备的经济活动总和。","ans":"银发经济指**向老年人提供产品或服务**，以及**为老龄阶段做准备**的经济活动总和。**2024年1月**国办印发**《关于发展银发经济增进老年人福祉的意见》**，部署老年助餐、适老化改造与养老金融，既应对**人口老龄化**又培育新增长点。","pts":["服务老年群体及备老阶段的全链条经济","2024年1月国办印发我国首个专项文件","涵盖养老服务、适老化与抗衰老等产业"],"mem":"抓住定义两半段：“给老人花钱（当下养老）”+“为变老攒钱准备（备老经济）”，2024年国办1号文件就是它。","mix":"银发经济不仅面向已步入老年的群体，也包含中青年群体为未来老龄阶段所做的养老金融、健康管理等准备。","mcq":[{"q":"2024年1月国务院办公厅印发“国办发〔2024〕1号”文件，专门部署发展的经济形态是","o":["低空经济","首发经济","总部经济","银发经济"],"a":3,"w":"国办发〔2024〕1号为《关于发展银发经济增进老年人福祉的意见》，是我国首个银发经济专门文件。"}],"rel":[{"t":"人口老龄化","n":"银发经济兴起的人口背景"},{"t":"适老化","n":"银发经济的重要改造方向"},{"t":"15分钟社区生活圈","n":"社区居家养老服务载体"},{"t":"数字鸿沟","n":"数字适老化着力破解的难题"}],"more":"国办发〔2024〕1号文件提出4个方面26项举措，覆盖民生事业、产品供给、潜力产业与要素保障。","exam":[]},{"id":"a13-050","t":"耐心资本","cid":"13d","p":3,"kind":"概念","alias":["长期资本"],"one":"着眼长期价值、高容忍短期波动的资本，主投硬科技与早期创新。","ans":"耐心资本指**着眼长期回报**、对短期波动容忍度较高的中长期资本。**2024年4月**中央政治局会议首提**“壮大耐心资本”**，二十届三中全会部署**“投早、投小、投长期、投硬科技”**，为培育**新质生产力**提供稳定金融支撑。","pts":["着眼长期价值、容忍短期波动的资本","2024年4月中央政治局会议首提壮大","投早、投小、投长期、投硬科技"],"mem":"四投口诀“早小长硬”：耐心资本不赚快钱，专门“投早、投小、投长期、投硬科技”，陪跑新质生产力。","mix":"耐心资本并非单一金融产品，涵盖了养老基金、保险资金、政府引导基金与创业投资基金等具备长期投资属性的资金。","mcq":[{"q":"2024年中央重要会议多次强调“壮大耐心资本”，其重点投资方向被概括为","o":["投大、投稳、投短期、投地产","投快、投热、投消费、投外贸","投早、投小、投长期、投硬科技","投旧、投重、投基建、投能源"],"a":2,"w":"党的二十届三中全会明确提出完善长期资本“投早、投小、投长期、投硬科技”的支持政策。"}],"rel":[{"t":"风险投资","n":"耐心资本的重要市场载体"},{"t":"天使投资","n":"对应“投早、投小”的早期资本"},{"t":"新质生产力","n":"耐心资本赋能的核心目标"},{"t":"二十届三中全会","n":"明确提出发展耐心资本"}],"exam":[]},{"id":"a13-051","t":"国内生产总值（GDP）","cid":"13d","p":1,"kind":"概念","alias":["GDP","国内生产总值","国民生产总值（GNP）"],"one":"一国或地区一定时期内生产的最终产品和服务的市场价值。","ans":"国内生产总值（GDP）是**一个国家或地区在一定时期内，所有常住单位生产的最终产品和服务的市场价值**，是衡量经济总量和增长的核心指标。它的核算有**生产法、收入法、支出法**三种方法，支出法对应**消费、投资、净出口**三大需求。GDP按国土原则统计，与**按国民原则统计的GNP（国民生产总值）**不同。**2010年中国GDP超过日本，成为世界第二大经济体**。GDP不反映收入分配、环境成本和非市场活动，需要与其他指标结合。","pts":["一定时期内常住单位生产的最终产品和服务的市场价值","生产法、收入法、支出法；对应消费投资净出口","与GNP区别：国土原则与国民原则"],"mem":"“三法三驾”：三种核算方法，对应三驾马车。一句话区分：GDP看“地盘”（在国内生产的都算），GNP看“国籍”（本国居民在哪里赚的都算）。画面：GDP像“这块田里一年收了多少粮”。","mix":"GDP是流量，不是存量；GDP统计的是最终产品价值，避免重复计算；GDP增长不等于福祉提高。","mcq":[{"q":"GDP与GNP的主要区别在于统计原则，GDP按","o":["国民原则","收入原则","国土原则","支出原则"],"a":2,"w":"GDP是国土原则，GNP是国民原则。"},{"q":"下列不属于GDP核算方法的是","o":["生产法","收入法","支出法","价格法"],"a":3,"w":"核算方法为生产法、收入法、支出法。"}],"rel":[{"t":"“三驾马车”","n":"支出法三大需求"},{"t":"世界第二大经济体","n":"2010年中国GDP位居第二"},{"t":"居民消费价格指数（CPI）与生产者价格指数（PPI）","n":"同为宏观指标"},{"t":"通货膨胀与通货紧缩","n":"总量与物价对照"}],"more":"2012选择考过中国GDP。","exam":[]},{"id":"a13-052","t":"居民消费价格指数（CPI）与生产者价格指数（PPI）","cid":"13d","p":1,"kind":"概念","alias":["CPI","PPI","居民消费价格指数","生产者价格指数"],"one":"CPI衡量消费价格，是通胀常用指标；PPI衡量工业出厂价格。","ans":"居民消费价格指数（CPI）是**反映居民家庭购买消费品和服务价格水平变动情况的宏观经济指标**，是**衡量通货膨胀的常用指标**，涵盖食品烟酒、衣着、居住、交通通信、教育文化娱乐、医疗保健等八大类。生产者价格指数（PPI）是**反映工业生产者出厂价格变动趋势的指标**，处于产业链上游。二者由国家统计局按月发布，PPI变动常**传导至CPI**，因此被当作物价的先行指标。**CPI连续下降可能指向通缩风险，持续上升则指向通胀压力**。","pts":["CPI：居民购买消费品和服务的价格变动","PPI：工业生产者出厂价格变动，上游","CPI衡量通胀，PPI常先行并传导至CPI"],"mem":"“C管老百姓，P管工厂”：C=Consumer（消费者），P=Producer（生产者）。传导线：工厂出厂价（PPI）→商店零售价（CPI），上游先动，下游后动。","mix":"CPI是消费端，PPI是生产端；CPI上涨是通胀的表现，但CPI为负不等于一定通缩，通缩要看物价持续下降。","mcq":[{"q":"衡量通货膨胀最常用的指标是","o":["PPI","CPI","GDP","恩格尔系数"],"a":1,"w":"CPI反映居民消费价格变动，是通胀常用指标。"},{"q":"反映工业生产者出厂价格变动的是","o":["CPI","GDP","PPI","基尼系数"],"a":2,"w":"PPI是生产者价格指数。"}],"rel":[{"t":"通货膨胀与通货紧缩","n":"CPI是衡量通胀的指标"},{"t":"国内生产总值（GDP）","n":"同为宏观指标"},{"t":"货币政策","n":"调控物价的工具"},{"t":"恩格尔系数","n":"同为居民生活指标"}],"more":"CPI八大类：食品烟酒、衣着、居住、生活用品及服务、交通通信、教育文化娱乐、医疗保健、其他用品和服务。","exam":[]},{"id":"a13-053","t":"通货膨胀与通货紧缩","cid":"13d","p":1,"kind":"概念","alias":["通胀","通缩","滞胀","通货膨胀","通货紧缩"],"one":"物价持续上涨叫通胀，持续下降叫通缩，停滞加通胀叫滞胀。","ans":"通货膨胀是**一般物价水平持续上涨、货币购买力下降**的经济现象，常用CPI衡量。通货紧缩是**一般物价水平持续下降**的现象，往往伴随需求不足、企业利润下降和失业上升。**滞胀指经济停滞与通货膨胀并存**，典型是**20世纪70年代石油危机后的西方经济**，它挑战了凯恩斯主义。政府通常用**财政政策和货币政策**调控：通胀时收紧，通缩时放松。适度温和的通胀有利于增长，恶性通胀或持续通缩都会损害经济。","pts":["通胀：物价持续上涨，购买力下降","通缩：物价持续下降，需求不足","滞胀：停滞与通胀并存，20世纪70年代西方"],"mem":"“胀涨缩降”：通胀=涨，通缩=降，滞胀=不涨产出但涨价。滞胀三关键词“停滞、通胀、失业”。画面：钱“变薄”了是通胀（买得少），钱“变厚”了但没人花是通缩。","mix":"通缩不同于物价短期下跌，要“持续”；滞胀是“增长停滞+通胀”，不同于“经济衰退+通缩”。","mcq":[{"q":"“滞胀”指的是","o":["物价持续下降","经济增长停滞与通货膨胀并存","经济快速增长与通胀并存","经济衰退伴随通缩"],"a":1,"w":"典型是20世纪70年代的西方经济。"},{"q":"一般物价水平持续上涨、货币购买力下降称为","o":["通货膨胀","通货紧缩","经济衰退","金融危机"],"a":0,"w":"通货膨胀的定义。"}],"rel":[{"t":"居民消费价格指数（CPI）与生产者价格指数（PPI）","n":"衡量通胀的指标"},{"t":"货币政策","n":"调控工具"},{"t":"凯恩斯主义","n":"滞胀对其形成挑战"},{"t":"大萧条与罗斯福新政","n":"通缩与衰退的历史案例"}],"more":"滞胀：20世纪70年代石油危机后西方经济停滞与高通胀并存。","exam":[]},{"id":"a13-054","t":"货币政策","cid":"13d","p":1,"kind":"概念","alias":["货币政策","存款准备金率","公开市场操作","再贴现"],"one":"央行调节货币供应量和利率，三大传统工具是存准率、再贴现、公开市场操作。","ans":"货币政策是**中央银行通过调节货币供应量和利率，影响总需求以实现稳定物价、促进增长等目标的政策**。传统的**三大工具是存款准备金率、再贴现和公开市场操作**。中国的货币政策由**中国人民银行**实施，近年还使用中期借贷便利（MLF）、贷款市场报价利率（LPR）等工具。货币政策分为**宽松（扩张）和紧缩**两类：经济过热、通胀高时收紧，经济下行、通缩时放松。它与**财政政策**共同构成宏观调控的两大支柱。","pts":["央行调节货币供应量和利率","三大工具：存款准备金率、再贴现、公开市场操作","与财政政策并为宏观调控两大支柱"],"mem":"“准、贴、公”：准备金率、再贴现、公开市场。分工线：货币政策“央行管钱”，财政政策“政府管账”。松紧口诀：胀则紧，缩则松。","mix":"货币政策由央行实施，财政政策由政府（财政部）实施；发行国债、税收属于财政政策。","mcq":[{"q":"下列不属于货币政策传统三大工具的是","o":["存款准备金率","发行国债","再贴现","公开市场操作"],"a":1,"w":"发行国债属于财政政策。"},{"q":"在中国，实施货币政策的机构是","o":["财政部","中国人民银行","国家发改委","国家统计局"],"a":1,"w":"中国人民银行是中央银行。"}],"rel":[{"t":"财政政策","n":"宏观调控另一支柱"},{"t":"通货膨胀与通货紧缩","n":"调控的对象"},{"t":"流动性陷阱","n":"货币政策失灵的情形"},{"t":"凯恩斯主义","n":"宏观调控理论源头"}],"more":"中国近年工具：中期借贷便利（MLF）、贷款市场报价利率（LPR）。","exam":[]},{"id":"a13-055","t":"财政政策","cid":"13d","p":1,"kind":"概念","alias":["财政政策","积极财政政策"],"one":"政府用税收、财政支出和国债调节总需求。","ans":"财政政策是**政府通过税收、财政支出和发行国债等手段调节总需求，实现稳增长、稳物价、促就业等目标的政策**。它分为**扩张性（积极）财政政策和紧缩性财政政策**：经济下行时增加支出、减税降费、扩大赤字和国债发行；经济过热时则相反。财政政策在**凯恩斯主义**兴起后成为核心调控手段，美国**罗斯福新政**是典型案例。它与**货币政策**并为宏观调控的两大工具，前者“政府管账”，后者“央行管钱”。","pts":["政府通过税收、财政支出、国债调节总需求","扩张性（积极）与紧缩性两类","与货币政策并为宏观调控两大支柱"],"mem":"“税、支、债”三字：税收、支出、国债。松紧口诀：下行要“积极”（花钱、减税），过热要“紧缩”。对应货币政策“准、贴、公”，一个管账本，一个管钱袋。","mix":"财政政策由政府实施，货币政策由央行实施；存款准备金率调整属于货币政策。","mcq":[{"q":"下列属于财政政策手段的是","o":["调整存款准备金率","公开市场操作","再贴现","发行国债"],"a":3,"w":"税收、财政支出、国债属财政政策，其余三项属货币政策。"},{"q":"经济下行时通常采取的财政政策是","o":["紧缩性财政政策","提高税率","扩张性（积极）财政政策","减少财政支出"],"a":2,"w":"增加支出、减税降费。"}],"rel":[{"t":"货币政策","n":"宏观调控另一支柱"},{"t":"凯恩斯主义","n":"积极财政政策的理论根据"},{"t":"大萧条与罗斯福新政","n":"财政政策的典型案例"},{"t":"供给侧结构性改革","n":"另一类宏观调控思路"}],"exam":[]},{"id":"a13-056","t":"宏观调控四大目标","cid":"13d","p":2,"kind":"合称","alias":["宏观经济政策四大目标","宏观调控目标"],"one":"促进经济增长、增加就业、稳定物价、保持国际收支平衡，宏观经济治理核心指标。","ans":"宏观调控四大目标指国家运用**财政政策**和**货币政策**调节经济总量时追求的四项基本目标：**促进经济增长、增加就业、稳定物价、保持国际收支平衡**。四者分别对应**GDP增速**、失业率、**CPI涨幅**与对外收支均衡。目标间短期常存权衡（如菲利普斯曲线），需政策协同配合，构成宏观治理与每年《政府工作报告》预期指标框架。","pts":["促进经济增长、增加就业、稳定物价、保持国际收支平衡","分别对应GDP、失业率、CPI与国际收支等核心指标","借助财政政策与货币政策统筹平衡，构成报告预期框架"],"members":[["促进经济增长","以GDP增速衡量，体现国民经济总量扩张与质量提升"],["增加就业","降低失业率、扩大新增就业，关乎民生底线与社会稳定"],["稳定物价","以CPI等衡量，防止严重通货膨胀或通货紧缩"],["保持国际收支平衡","保持外汇收支与贸易、资本流动基本均衡"]],"mem":"四字口诀：“增、就、物、支”（增长、就业、物价、国际收支），对应四个常用英文/指标：GDP（增长）、失业率（就业）、CPI（物价）、汇率/顺逆差（国际收支）。","mix":"“稳定物价”追求的是物价总水平温和可控（如2026年目标CPI涨幅2%左右），既防高通胀也防通缩，并非物价绝对不变；“缩小收入差距”或“股市上涨”均不属于传统宏观调控四大目标。","mcq":[{"q":"下列各项中，不属于国家宏观调控四大基本目标的是","o":["促进经济增长","增加就业","稳定股票市场价格","保持国际收支平衡"],"a":2,"w":"宏观调控四大目标是促进经济增长、增加就业、稳定物价、保持国际收支平衡，其中“稳定物价”指商品和服务价格总水平，而非股票价格。"}],"rel":[{"t":"国内生产总值（GDP）","n":"衡量经济增长的核心指标"},{"t":"居民消费价格指数（CPI）与生产者价格指数（PPI）","n":"衡量物价水平核心指标"},{"t":"财政政策","n":"实现调控目标的主要工具"},{"t":"货币政策","n":"央行调控总量与物价工具"}],"more":"2026年《政府工作报告》预期目标对照：GDP增长4.5%至5%、城镇新增就业1200万人以上、CPI涨幅2%左右、国际收支基本平衡。","exam":[]},{"id":"a13-057","t":"“三驾马车”","cid":"13d","p":1,"kind":"合称","alias":["三驾马车","消费投资出口"],"one":"拉动经济增长的消费、投资、净出口三大需求。","ans":"“三驾马车”是**对拉动经济增长的三大需求的形象说法**，即**消费、投资和净出口**。三者对应支出法核算GDP的三个组成部分，其中**消费和投资合称内需**，货物和服务净出口反映外需。中国改革开放后长期依靠投资和出口拉动增长，近年**强调扩大内需、增强消费对经济发展的基础性作用**，与“**以国内大循环为主体**”的新发展格局相呼应。这一说法帮助分析经济结构，也提示要避免过度依赖单一需求。","pts":["消费、投资、净出口","对应支出法GDP三大需求","消费+投资=内需，净出口反映外需"],"members":[["消费","最终消费支出，增长基础"],["投资","固定资产投资等"],["出口（净出口）","外需，国际市场"]],"mem":"“消、投、出”三个字，像三匹马拉一辆车。内需与外需对照：消费+投资=内需，净出口反映外需。联想新发展格局：内循环为主，就是更依赖前两匹。","mix":"“三驾马车”是需求侧概念，不同于供给侧的“劳动、资本、技术”要素；“新三样”指电动汽车、锂电池、光伏产品，是出口热词，别和三驾马车混。","mcq":[{"q":"下列不属于“三驾马车”的是","o":["消费","投资","税收","净出口"],"a":2,"w":"三驾马车是消费、投资、净出口。"},{"q":"“内需”包括","o":["消费和投资","消费和出口","投资和出口","出口和净进口"],"a":0,"w":"消费+投资=内需，净出口反映外需。"}],"rel":[{"t":"国内生产总值（GDP）","n":"支出法三大组成"},{"t":"双循环","n":"强调扩大内需"},{"t":"供给侧结构性改革","n":"与需求侧对举"},{"t":"财政政策","n":"通过财政刺激需求"}],"exam":[]},{"id":"a13-058","t":"恩格尔系数","cid":"13d","p":1,"kind":"概念","alias":["恩格尔系数","恩格尔定律"],"one":"食品支出占消费支出的比重，系数越低生活水平越高。","ans":"恩格尔系数是**食品支出总额占个人消费支出总额的比重**，由**德国统计学家恩斯特·恩格尔**在19世纪根据家庭收支调查总结提出。其规律是**收入越高，食品支出占比越低，因此系数越低，生活水平越高**。联合国粮农组织曾据此划分标准：60%以上为贫困，50%至60%为温饱，40%至50%为小康，30%至40%为富裕，30%以下为最富裕。它是**衡量居民生活水平和消费结构的重要指标**，国家统计局也定期公布。","pts":["食品支出占消费支出的比重","德国统计学家恩格尔提出","系数越低，生活水平越高"],"mem":"一句话：吃饭占花销的比例越大，越穷；比例越小，越富。数字标尺“六五四三”：60%贫困、50%温饱、40%小康、30%富裕。与基尼系数区分：恩格尔看“吃”，基尼看“差距”。","mix":"恩格尔系数衡量生活水平，基尼系数衡量收入分配差距；系数低意味富裕，不是越高越富。","mcq":[{"q":"恩格尔系数是指","o":["食品支出占消费支出的比重","居民收入的差距","物价上涨幅度","储蓄占收入的比重"],"a":0,"w":"食品支出占个人消费支出总额的比重。"},{"q":"恩格尔系数越低，说明","o":["生活水平越低","收入差距越大","通货膨胀越严重","生活水平越高"],"a":3,"w":"系数越低，食品支出占比越小，生活水平越高。"}],"rel":[{"t":"基尼系数","n":"衡量收入差距，常对举"},{"t":"共同富裕","n":"生活水平提升的目标"},{"t":"居民消费价格指数（CPI）与生产者价格指数（PPI）","n":"同为民生指标"},{"t":"国内生产总值（GDP）","n":"同为宏观指标"}],"more":"联合国粮农组织标准：60%以上贫困，50%—60%温饱，40%—50%小康，30%—40%富裕，30%以下最富裕。","exam":[]},{"id":"a13-059","t":"基尼系数","cid":"13d","p":1,"kind":"概念","alias":["基尼系数","洛伦兹曲线"],"one":"衡量收入分配差距，0到1，越接近1越不平等，常以0.4为警戒线。","ans":"基尼系数是**意大利统计学家科拉多·基尼1912年提出的衡量收入分配差距的指标**，建立在美国统计学家洛伦兹提出的**洛伦兹曲线**基础上。它的取值在**0到1之间，越接近0越平等，越接近1越不平等**，国际上常以**0.4作为警戒线**。基尼系数为0表示绝对平均，为1表示绝对不平均。它被用于衡量**居民收入或财富分配的公平程度**，也是讨论**共同富裕**时的重要参照。","pts":["意大利统计学家基尼提出，衡量收入差距","取值0到1，越大越不平等","国际警戒线0.4"],"mem":"“基尼=差距”：0最均匀，1最悬殊。警戒线“0.4”：低于0.4较为合理，超过要警惕。画面：洛伦兹曲线离对角线越远，基尼越大。与恩格尔对比：恩格尔看“吃”，基尼看“差”。","mix":"恩格尔系数衡量生活水平，基尼系数衡量收入差距；0.4是国际常用警戒线，不是法定标准。","mcq":[{"q":"基尼系数越接近1，说明","o":["收入分配越平等","收入分配越不平等","物价越稳定","生活水平越高"],"a":1,"w":"0绝对平均，1绝对不平均。"},{"q":"国际上通常把基尼系数的警戒线定为","o":["0.2","0.3","0.4","0.6"],"a":2,"w":"0.4。"}],"rel":[{"t":"恩格尔系数","n":"同为生活水平与分配指标"},{"t":"共同富裕","n":"缩小差距的目标"},{"t":"帕累托法则（二八定律）","n":"同为分配规律"},{"t":"中等收入陷阱","n":"收入差距的相关概念"}],"exam":[]},{"id":"a13-060","t":"看不见的手","cid":"13d","p":2,"kind":"概念","alias":["无形之手","invisible hand"],"one":"亚当·斯密在《国富论》中提出，喻指市场价格机制自发调节资源配置。","ans":"“看不见的手”是**英国古典经济学家亚当·斯密**在**1776年《国富论》**中提出的著名比喻，属古典自由主义经济学核心概念。它指个人追求自身利益时，会通过**价格与供求机制**自发实现资源有效配置。该思想奠定了**市场经济理论**基础，常与政府干预的“看得见的手”相对照，2026年适逢《国富论》出版250周年。","pts":["亚当·斯密1776年《国富论》提出","市场价格与供求自发调节资源配置","古典经济学基石，对应政府“看得见的手”"],"mem":"对比记忆：市场机制悄无声息调节价格，是**“看不见的手”**；政府出台财政、货币政策直接调控，是**“看得见的手”**。年份锚点：1776年《国富论》与美国《独立宣言》同年，2026年正好250周年。","mix":"“看不见的手”常被误认为主张完全取消政府职能；实际上亚当·斯密承认政府需承担国防、司法与公共工程等职责。它与凯恩斯主义的政府干预主张形成经典对照。","mcq":[{"q":"提出“看不见的手”这一著名经济学比喻的著作是","o":["《就业、利息和货币通论》","《国富论》","《资本论》","《经济学原理》"],"a":1,"w":"亚当·斯密在1776年出版的《国富论》中提出“看不见的手”。"}],"rel":[{"t":"亚当·斯密与《国富论》","n":"概念出处与提出者"},{"t":"凯恩斯主义","n":"主张“看得见的手”对照"},{"t":"社会主义市场经济体制","n":"市场与政府结合的中国实践"},{"t":"美国《独立宣言》","n":"同在1776年诞生，250周年"}],"more":"2026年周年：1776年《国富论》出版250周年。\n原书全称：《国民财富的性质和原因的研究》。","exam":[]},{"id":"a13-061","t":"凯恩斯主义","cid":"13d","p":2,"kind":"流派","alias":["凯恩斯经济学","Keynesianism"],"one":"凯恩斯1936年《通论》创立，主张有效需求不足时由政府干预刺激经济。","ans":"凯恩斯主义是**英国经济学家凯恩斯**创立的现代宏观经济学流派，以**1936年《就业、利息和货币通论》**出版为标志。它针对大萧条中市场失灵，认为衰退源于**有效需求不足**，主张由政府通过**扩大公共支出与财政货币政策**刺激需求。该理论打破自由放任传统，成为战后西方宏观调控的理论支柱，2026年为其出版90周年。","pts":["凯恩斯1936年《通论》标志创立","核心判断：经济衰退源于有效需求不足","主张政府用财政与货币政策干预经济"],"mem":"逻辑线记忆：1929年大萧条爆发→市场“看不见的手”失灵→1936年凯恩斯写《通论》开药方→政府伸出“看得见的手”花钱救市。2026年正好是《通论》出版90周年。","mix":"注意区分：罗斯福新政始于1933年，《通论》出版于1936年，新政在实践上早于《通论》问世，但理念相通；20世纪70年代西方出现“滞胀”后，凯恩斯主义受到货币主义与新自由主义挑战。","mcq":[{"q":"标志着凯恩斯主义宏观经济学创立的代表著作出版于1936年，这部著作是","o":["《国富论》","《自由选择》","《就业、利息和货币通论》","《通往奴役之路》"],"a":2,"w":"凯恩斯1936年出版《就业、利息和货币通论》，奠定现代宏观经济学基础。"}],"rel":[{"t":"看不见的手","n":"自由放任与政府干预对照"},{"t":"大萧条与罗斯福新政","n":"同一时期的危机与实践"},{"t":"财政政策","n":"凯恩斯主张的核心调控工具"},{"t":"流动性陷阱","n":"凯恩斯提出的重要概念"}],"more":"2026年周年：1936年《就业、利息和货币通论》出版90周年。\n核心概念：有效需求、边际消费倾向、乘数效应、流动性陷阱。","exam":[]},{"id":"a13-062","t":"大萧条与罗斯福新政","cid":"13d","p":2,"kind":"事件","alias":["大萧条","罗斯福新政","New Deal"],"one":"1929年股市崩盘引发大萧条，1933年罗斯福推行国家干预经济的新政。","ans":"**大萧条**指**1929年10月纽约股市崩盘**引发的资本主义世界经济危机，致银行倒闭与大规模失业。**1933年富兰克林·罗斯福**就任美国总统后推行**新政**，整顿金融、颁布《全国工业复兴法》、以工代赈兴建公共工程并建立社会保障制度。新政开创了**国家大规模干预经济**先例，推动了现代福利国家与宏观调控体系的形成。","pts":["1929年10月纽约股市崩盘引发世界大萧条","1933年富兰克林·罗斯福推行新政","整顿金融、以工代赈与社保立法，开创国家干预"],"mem":"口诀**“三R”**记新政内容：Relief（救济，以工代赈）、Recovery（复兴，整顿金融与工农业）、Reform（改革，建立社保与金融监管）。年份串记：1929崩盘→1933新政→1936凯恩斯《通论》。","mix":"实行新政的是第32任总统富兰克林·罗斯福（小罗斯福，民主党），不是第26任西奥多·罗斯福（老罗斯福，共和党）；美国走出大萧条的最终推动力还包括二战战时经济需求。","mcq":[{"q":"1933年就任美国总统并推行“新政”以应对经济大萧条的是","o":["富兰克林·罗斯福","西奥多·罗斯福","赫伯特·胡佛","哈里·杜鲁门"],"a":0,"w":"富兰克林·罗斯福1933年上台推行新政，胡佛是其前任，杜鲁门是其继任。"}],"rel":[{"t":"1929至1933年经济大危机","n":"大萧条的危机本体"},{"t":"罗斯福","n":"新政的推行者"},{"t":"凯恩斯主义","n":"同期形成国家干预理论"},{"t":"2008年国际金融危机","n":"现代大危机的历史对照"}],"more":"关键年份：1929年10月“黑色星期二”股市崩盘；1933年3月罗斯福就职并开启“百日新政”；1935年《社会保障法》颁布。","exam":[]},{"id":"a13-064","t":"2008年国际金融危机","cid":"13d","p":3,"kind":"事件","alias":["次贷危机","全球金融危机"],"one":"由美国次贷危机引发、2008年9月雷曼兄弟破产后全面爆发的全球危机。","ans":"2008年国际金融危机由**美国次贷危机**引发，是1929年大萧条后最严重的全球经济危机。**2008年9月**投行**雷曼兄弟破产**后危机全面席卷全球，直接推动**二十国集团（G20）升格为领导人峰会**，重塑了国际经济治理格局。","pts":["导火索为美国次贷危机与雷曼兄弟破产","1929年大萧条后最严重的全球危机","推动G20升格为领导人峰会机制"],"mem":"因果链记“次贷→雷曼→G20升格”：美国次贷爆雷，2008年9月雷曼倒闭引发海啸，各国被迫把G20升格为首脑峰会联手救市。","mix":"注意区分两次全球大危机：1929至1933年是资本主义世界经济大危机（罗斯福新政应对），2008年是美国次贷引发的国际金融危机。","mcq":[{"q":"2008年9月哪家美国大型投资银行破产，标志着国际金融危机全面爆发","o":["高盛集团","摩根士丹利","美林证券","雷曼兄弟"],"a":3,"w":"2008年9月15日雷曼兄弟申请破产保护，引发全球信贷冻结与金融危机全面爆发。"}],"rel":[{"t":"二十国集团","n":"危机推动其升格为领导人峰会"},{"t":"1929至1933年经济大危机","n":"历史重大经济危机对照"},{"t":"国际货币基金组织与世界银行","n":"参与国际金融危机救助协调"}],"exam":[]},{"id":"a13-065","t":"人民币加入特别提款权（SDR）","cid":"13d","p":2,"kind":"事件","alias":["人民币入篮","特别提款权","SDR"],"one":"2016年10月1日人民币正式入篮IMF特别提款权，成第五种篮子货币。","ans":"**特别提款权（SDR）**是**国际货币基金组织（IMF）**创设的国际储备资产。**2016年10月1日**，人民币正式纳入SDR货币篮子，与**美元、欧元、日元、英镑**并列，初始权重10.92%，2022年上调至12.28%，稳居第三。这是**首个发展中国家货币**入篮，标志人民币获国际官方储备认可，推动了人民币国际化进程。","pts":["2016年10月1日正式生效，属IMF储备资产","与美元、欧元、日元、英镑并列，权重居第三","首个入篮的发展中国家货币，推动人民币国际化"],"mem":"五种篮子货币口诀**“美欧中日英”**（按权重顺序：美元、欧元、人民币、日元、英镑）。时间锚点：2016年国庆节（10月1日）正式入篮，2026年10月满10周年。","mix":"IMF宣布决定是在2015年11月30日，正式生效日期是2016年10月1日；SDR是国际储备补充资产与记账单位，不直接用于日常商品交易，发行机构是IMF而非世界银行。","mcq":[{"q":"2016年10月1日人民币正式加入特别提款权（SDR）货币篮子，该货币篮子由哪一国际机构创设","o":["世界银行","世界贸易组织","国际清算银行","国际货币基金组织"],"a":3,"w":"特别提款权（SDR）由国际货币基金组织（IMF）于1969年创设。"}],"rel":[{"t":"国际货币基金组织与世界银行","n":"SDR由IMF创设与管理"},{"t":"布雷顿森林体系","n":"IMF诞生的国际货币框架"},{"t":"数字人民币","n":"人民币现代化与跨境新探索"},{"t":"中国加入世贸组织","n":"中国融入全球经贸体系里程碑"}],"more":"2026年周年：2016年10月1日人民币正式入篮10周年。\n2022年5月IMF定值审查将人民币权重由10.92%上调至12.28%（2022年8月1日生效）。","exam":[]},{"id":"a13-066","t":"数字人民币","cid":"13d","p":2,"kind":"概念","alias":["e-CNY","央行数字货币","DC/EP"],"one":"中国人民银行发行的数字形式法定货币（e-CNY），采双层运营与可控匿名。","ans":"数字人民币（**e-CNY**）是**中国人民银行发行的数字形式法定货币**，属央行数字货币，具国家信用背书与法偿性。它采取**央行与指定运营机构双层运营体系**，遵循**“小额匿名、大额依法可溯”的可控匿名**原则，支持双离线支付与智能合约，并参与跨境支付探索。它有效降低交易成本，夯实了我国数字经济时代的支付基础设施。","pts":["中国人民银行发行的数字形式法定货币（e-CNY）","双层运营体系，可控匿名，支持离线支付","国家信用背书，赋能数字经济与跨境支付"],"mem":"三组关键词串记：**央行发**（法定货币、国家信用）→**双层跑**（央行发行+指定机构运营）→**可控匿**（小额保隐私，大额防洗钱）。","mix":"数字人民币与微信支付、支付宝性质不同：后者是商业支付工具和“钱包”，数字人民币本身是法定货币；它也与比特币等去中心化加密资产截然不同，由央行中心化发行。","mcq":[{"q":"关于我国发行的数字人民币（e-CNY），下列说法正确的是","o":["由商业银行独立发行并定价","是由中国人民银行发行的数字形式法定货币","属于去中心化的私人加密虚拟货币","只能在完全实名且联网条件下使用"],"a":1,"w":"数字人民币由中国人民银行发行，采双层运营，遵循可控匿名并支持双离线支付。"}],"rel":[{"t":"人民币加入特别提款权（SDR）","n":"人民币国际化进程"},{"t":"数字经济","n":"数字人民币服务的基础形态"},{"t":"货币政策","n":"央行货币发行与调控体系"},{"t":"区块链","n":"常被对比的分布式账本技术"}],"more":"2026年进展：2026年1月1日起，中国人民银行实施新一代数字人民币计量框架，推动其由现金型（1.0版）升级为存款货币型（2.0版），实名钱包余额可按规定计付利息并纳入存款保险保障。","exam":[]},{"id":"a13-067","t":"股票发行注册制","cid":"13d","p":2,"kind":"制度","alias":["全面注册制","注册制改革"],"one":"以信息披露为核心的发行制度，2019年科创板试点，2023年2月全面实行。","ans":"股票发行注册制是**以信息披露为核心**的证券发行审核制度，属我国资本市场重大基础改革。它实行**“交易所审核、证监会注册”**架构，不再由监管部门实质判断企业投资价值，把选择权交还市场并压实中介责任。我国于**2019年在上交所科创板首试点**，经创业板与北交所推进，于**2023年2月全面实行**，显著增强了资本市场服务科创的能力。","pts":["以信息披露为核心，交易所审核、证监会注册","2019年科创板首试点，2023年2月全面实行","把价值判断交还市场，服务实体经济与科创"],"mem":"时间四步走口诀：**“19科创、20创业、21北交、23全面”**。核心抓八个字：**信息披露，交还市场**。","mix":"注册制不等于“不审核”或“随便上市”，交易所仍须严格审核申报材料是否真实、准确、完整；容易混淆的“核准制”由监管机构对企业投资价值作实质审查。","mcq":[{"q":"我国资本市场率先试点股票发行注册制的板块是","o":["上海证券交易所科创板","深圳证券交易所创业板","北京证券交易所","上海证券交易所主板"],"a":0,"w":"2019年上交所科创板开板并率先试点注册制，2023年2月全市场全面实行。"}],"rel":[{"t":"科创板","n":"2019年率先试点注册制"},{"t":"首次公开募股（IPO）","n":"注册制直接规范的发行环节"},{"t":"创业板","n":"2020年推进注册制改革"},{"t":"北京证券交易所","n":"2021年设立并同步试点"}],"more":"关键日期：2023年2月17日中国证监会发布全面实行股票发行注册制相关制度规则并施行。","exam":[]},{"id":"a13-068","t":"深圳证券交易所","cid":"13d","p":3,"kind":"常识","alias":["深交所","SZSE"],"one":"1990年12月1日开始营业，主板与创业板并立，支持民营与创新企业。","ans":"深圳证券交易所（深交所）于**1990年12月1日**开始营业，是中国内地首批证券交易所之一。深交所**2009年10月**开设**创业板**，2021年将主板与中小板合并，形成**“主板+创业板”**格局，在服务民营经济与成长型创新企业中作用突出。","pts":["1990年12月1日开始营业","2009年10月开设创业板","2021年主板与中小板合并，服务创新成长企业"],"mem":"日期巧记“深1上19”：1990年12月1日深交所先试营业，12月19日上交所正式开业，同年同月拉开A股大幕。","mix":"2021年4月起深交所中小板已并入主板，当前深交所只有主板与创业板两大板块，不再单设中小板。","mcq":[{"q":"2021年4月，深圳证券交易所将哪两个板块合并，形成“主板+创业板”格局","o":["主板与中小板","主板与创业板","中小板与科创板","创业板与新三板"],"a":0,"w":"2021年4月6日深交所主板与中小板正式合并，形成简洁清晰的“主板+创业板”格局。"}],"rel":[{"t":"创业板","n":"2009年在深交所开板"},{"t":"上海证券交易所","n":"同于1990年12月开业"},{"t":"北京证券交易所","n":"中国内地第三家证交所"},{"t":"经济特区","n":"深圳特区金融改革产物"}],"exam":[]},{"id":"a13-069","t":"证券市场基本概念","cid":"13d","p":3,"kind":"概念","alias":["股票债券基金","牛市熊市"],"one":"股票表所有权、债券表债权、基金为集合投资；牛市指上涨、熊市指下跌。","ans":"证券市场核心工具包括**股票**（股份公司所有权凭证）、**债券**（还本付息的债务凭证）和**基金**（专业机构运作的集合投资工具）。行情术语中，**牛市**指持续上涨行情，**熊市**指持续下跌行情，是理解资本市场风险与收益的基础。","pts":["股票为所有权、债券为债权、基金为集合投资","牛市指持续上涨行情，熊市指持续下跌行情","三类工具风险收益与法律关系各异"],"mem":"动物动作联想记行情：牛用犄角“往上顶”（牛市上涨），熊用熊掌“往下拍”（熊市下跌）；“股是老板、债是债主、基是拼团”。","mix":"常见误区：股票持有人是股东而非债权人，无固定到期还本义务；债券持有人享有优先受偿权，一般不参与公司经营决策。","mcq":[{"q":"在证券市场中，代表投资者对股份有限公司拥有所有权份额的凭证是","o":["国债","股票","货币基金","企业债券"],"a":1,"w":"股票是股份公司所有权凭证，债券是债权债务凭证，基金是集合投资工具。"}],"rel":[{"t":"融资","n":"发行股票债券是直接融资方式"},{"t":"首次公开募股（IPO）","n":"股份公司公开发行股票上市"},{"t":"纽约证券交易所","n":"华尔街铜牛象征牛市文化"}],"exam":[]},{"id":"a13-070","t":"马太效应","cid":"13d","p":1,"kind":"概念","alias":["马太效应","累积优势","强者愈强"],"one":"默顿1968年提出，强者愈强、弱者愈弱的累积优势现象。","ans":"马太效应是**美国社会学家罗伯特·默顿1968年提出的概念**，指**强者愈强、弱者愈弱的累积优势现象**。名称借自**《圣经·马太福音》“凡有的，还要加给他，叫他有余；凡没有的，连他所有的也要夺去”**。默顿最初用它描述科学界的奖励制度：已有声望的科学家获得更多荣誉和资源。该效应广泛见于经济、教育、传播领域，如**贫富差距扩大、平台头部效应**，提示需要政策干预以避免差距固化。","pts":["默顿1968年提出，强者愈强的累积优势","出自《圣经·马太福音》","适用于科学、经济、教育等领域"],"mem":"“凡有的，还要加给他”：谁有，谁更有。画面：滚雪球，大的越滚越大。作者记忆：默顿（Merton）→“马太”（Matthew）首字母同为M。","mix":"马太效应是“强者愈强”；与“木桶效应”（短板决定容量）、“蝴蝶效应”（微小变化引发连锁反应）不要混。","mcq":[{"q":"马太效应的名称来自","o":["《旧约》","《古兰经》","《论语》","《新约·马太福音》"],"a":3,"w":"借《圣经·马太福音》“凡有的，还要加给他”。"},{"q":"马太效应的提出者是","o":["亚当·斯密","罗伯特·默顿","凯恩斯","基尼"],"a":1,"w":"美国社会学家罗伯特·默顿1968年提出。"}],"rel":[{"t":"《圣经》","n":"名称出处"},{"t":"基尼系数","n":"衡量分化的指标"},{"t":"帕累托法则（二八定律）","n":"同为分布规律"},{"t":"木桶效应","n":"常被一并考查的效应"}],"more":"《圣经·马太福音》：凡有的，还要加给他，叫他有余；凡没有的，连他所有的也要夺去。","exam":[]},{"id":"a13-071","t":"中等收入陷阱","cid":"13d","p":1,"kind":"概念","alias":["中等收入陷阱","跨越中等收入陷阱"],"one":"世界银行2007年提出：国家进入中等收入后增长乏力，长期难入高收入行列。","ans":"中等收入陷阱是**世界银行《东亚复兴》报告（2007）提出的经济学概念**，指一国人均收入达到中等水平后，**原有增长动力减弱、新动力接续不上**，经济长期停滞，难以跻身高收入国家。它与修昔底德陷阱同属“陷阱”类名词，但前者讲经济发展，后者讲大国关系。典型例子是**阿根廷、巴西等拉美国家**以及部分东南亚国家，日本、韩国则被视为成功跨越者。跨越的关键是**靠创新驱动和产业升级替代要素与资源投入**，同时缩小收入差距、改善收入分配。我国强调高质量发展，就是为避免这一陷阱。","pts":["世界银行2007年提出","进入中等收入后增长动力不足","拉美为例；靠创新、产业升级、收入分配跨越"],"mem":"画面：爬楼梯爬到半山腰的平台，旧台阶（廉价劳动力、资源投入）到头，新台阶（创新、高端产业）还没搭好，人就停在平台上。逻辑线：低收入靠人口和投资，高收入靠创新和效率，中间必须换发动机，换不成就是陷阱。","mix":"与“修昔底德陷阱”（大国冲突）、“塔西佗陷阱”（公信力）、“流动性陷阱”（货币政策失灵）、“金德尔伯格陷阱”（缺少全球公共产品提供者）区分，别只凭“陷阱”二字选。","mcq":[{"q":"“中等收入陷阱”这一概念最早出现在哪个机构的报告中","o":["世界银行","国际货币基金组织","联合国开发计划署","经济合作与发展组织"],"a":0,"w":"世界银行2007年《东亚复兴：关于经济增长的观点》提出。"},{"q":"下列国家中，常被作为“中等收入陷阱”典型案例的是","o":["日本","韩国","新加坡","阿根廷"],"a":3,"w":"阿根廷、巴西等拉美国家长期徘徊在中等收入阶段；日韩新被视为成功跨越。"}],"rel":[{"t":"修昔底德陷阱","n":"同属“陷阱”类名词"},{"t":"国内生产总值（GDP）","n":"衡量收入的总量指标"},{"t":"新质生产力","n":"以创新动力跨越陷阱"},{"t":"基尼系数","n":"收入分配差距指标"}],"more":"“陷阱”类名词对照：修昔底德陷阱（大国战争）、塔西佗陷阱（政府公信力）、流动性陷阱、金德尔伯格陷阱。","exam":[]},{"id":"a13-072","t":"塔西佗陷阱","cid":"13d","p":2,"kind":"概念","alias":["Tacitus Trap"],"one":"公权力失信后，无论说真话假话、做好事坏事都会被公众质疑的现象。","ans":"塔西佗陷阱是政治学与公共管理概念，得名于**古罗马历史学家塔西佗**。它在现代语境中指**公权力一旦失去公信力，无论说真话假话、做好事坏事，都会被公众认为在说假话、做坏事**。这一现象揭示了**政府公信力的脆弱性**，失信后修复成本远高于维系。它警示公共治理须坚持**信息公开与依法行政**，守牢政府信用底线。","pts":["得名于古罗马历史学家塔西佗","公权力失信后，做好事说真话亦遭公众质疑","警示公共治理须重视公信力建设与透明公开"],"mem":"场景记法：把“塔西佗”联想成**“他说话没人听”**。就像“狼来了”的放羊娃，信用破产后，真喊狼来了也没人信。","mix":"“四大陷阱”常被混考：**修昔底德陷阱**讲崛起国与守成国冲突；**中等收入陷阱**讲经济增速停滞；**金德尔伯格陷阱**讲大国不愿提供国际公共产品；**塔西佗陷阱**讲公权力失信。","mcq":[{"q":"指“公权力失去公信力后，无论做好事还是坏事都会被认为是在做坏事”的政治学概念是","o":["修昔底德陷阱","中等收入陷阱","塔西佗陷阱","金德尔伯格陷阱"],"a":2,"w":"塔西佗陷阱聚焦公权力公信力丧失；其余三项分别涉及大国冲突、经济转型与国际公共产品。"}],"rel":[{"t":"修昔底德陷阱","n":"同为“陷阱”类高频名解"},{"t":"中等收入陷阱","n":"经济学“陷阱”对照"},{"t":"金德尔伯格陷阱","n":"国际关系“陷阱”对照"},{"t":"网络生态治理","n":"舆情应对与公信力维护场景"}],"more":"出处背景：塔西佗在《历史》中评述罗马皇帝加尔巴时指出，一旦皇帝为民众所厌恶，善举与恶行同样招致怨恨。","exam":[]},{"id":"a13-073","t":"金德尔伯格陷阱","cid":"13d","p":3,"kind":"概念","alias":["Kindleberger Trap"],"one":"约瑟夫·奈2017年提出，指大国交替期全球公共产品供给不足导致的治理真空。","ans":"金德尔伯格陷阱由美国学者**约瑟夫·奈**于**2017年**提出，源自金德尔伯格对**20世纪30年代大萧条**的研究。它指守成大国衰落时，**新兴大国不愿或无力提供全球公共产品**，导致国际**治理真空**，与“修昔底德陷阱”形成互补视角。","pts":["约瑟夫·奈2017年提出，源自金德尔伯格大萧条研究","核心风险：全球公共产品供给不足与治理真空","与修昔底德陷阱形成“过弱”与“过强”对照"],"mem":"双陷阱对比记：修昔底德陷阱怕新兴大国“太强引发战争”，金德尔伯格陷阱怕大国“不接班导致全球没人管”（如一战后美国退回孤立主义引发大萧条）。","mix":"注意提出者与命名者不同：由约瑟夫·奈在2017年命名，借用经济史学家金德尔伯格的理论；不要误以为是金德尔伯格本人造的词。","mcq":[{"q":"“金德尔伯格陷阱”这一概念所警示的核心风险是","o":["中等收入国家增速停滞","守成国与新兴国必然开战","国际公共产品供给不足导致治理真空","利率极低导致货币政策失效"],"a":2,"w":"金德尔伯格陷阱指大国权力转移中无人提供全球公共产品，进而引发国际体系混乱。"}],"rel":[{"t":"修昔底德陷阱","n":"大国权力转移的另一著名陷阱"},{"t":"1929至1933年经济大危机","n":"金德尔伯格研究的原型事件"},{"t":"软实力","n":"同为约瑟夫·奈提出的概念"},{"t":"孤立主义","n":"两战之间美国缺位引发该陷阱"}],"exam":[]},{"id":"a13-074","t":"流动性陷阱","cid":"13d","p":3,"kind":"概念","alias":["凯恩斯陷阱"],"one":"凯恩斯提出，指利率降至极低时增发货币仍无法刺激投资与消费。","ans":"流动性陷阱由英国经济学家**凯恩斯**在《就业、利息和货币通论》中提出。它指**利率降至极低水平**时，公众倾向持有现金，央行即使**增加货币供应**也无法压低利率、刺激投资，导致**货币政策失效**，需借助积极**财政政策**破局。","pts":["由凯恩斯提出，属宏观经济学概念","利率极低、公众偏好持币，货币政策失效","破解常依赖扩张性财政政策拉动需求"],"mem":"比喻记法“推绳子”：利率见底后，央行印再多钱人们都捂在手里当现金，货币政策像推绳子使不上劲，只能靠政府财政亲自下场拉动。","mix":"易与通货膨胀混淆：流动性陷阱多伴随通货紧缩与预期低迷，尽管货币超发却难以流入实体经济推高物价。","mcq":[{"q":"提出“流动性陷阱”概念并主张在货币政策失效时采用积极财政政策的经济学家是","o":["亚当·斯密","大卫·李嘉图","米尔顿·弗里德曼","凯恩斯"],"a":3,"w":"凯恩斯在1936年《就业、利息和货币通论》中提出流动性陷阱概念。"}],"rel":[{"t":"凯恩斯主义","n":"流动性陷阱所属理论体系"},{"t":"货币政策","n":"流动性陷阱下会失效的调控工具"},{"t":"财政政策","n":"走出流动性陷阱的主要手段"},{"t":"通货膨胀与通货紧缩","n":"常伴随通缩风险出现"}],"exam":[]},{"id":"a13-075","t":"囚徒困境","cid":"13d","p":2,"kind":"概念","alias":["Prisoner's Dilemma"],"one":"博弈论经典模型，揭示个人理性选择导致集体非最优结果的悖论。","ans":"囚徒困境是**博弈论**中的经典非零和博弈模型，由**美国兰德公司学者弗勒德与德雷希尔**于**1950年**构思，数学家**塔克**以隔离审讯囚徒故事命名。模型中，每名囚徒选背叛均为占优策略，结果双双背叛，刑期重于共同沉默。它揭示了**个人理性导致集体非最优结果**的悖论，广泛用于解释价格战、军备竞赛与公地悲剧。","pts":["1950年兰德公司学者提出，塔克命名","博弈论非零和模型，双方选背叛为占优策略","揭示个人理性导致集体非最优结果"],"mem":"画面记法：两个共犯分开审，**“坦白从宽、抗拒从严”**。各自算小账都选出卖对方，结果一起重判，不如一起闭嘴，正是**个人聪明、集体吃亏**。","mix":"囚徒困境属于**非零和博弈**（总收益可变，合作能双赢），不属于“一方所得即另一方所失”的零和博弈；“双方都背叛”是纳什均衡，却不是帕累托最优。","mcq":[{"q":"博弈论经典模型“囚徒困境”所揭示的核心规律是","o":["少数关键因素决定大部分产出","初始条件的微小差异导致系统巨变","信息对称必然消除市场竞争","个人理性选择可能导致集体非最优结果"],"a":3,"w":"囚徒困境中双方按个人最优选择背叛，最终陷入比合作更差的结果。"}],"rel":[{"t":"帕累托法则（二八定律）","n":"经济学高频模型对照"},{"t":"看不见的手","n":"与市场自发和谐论形成张力"},{"t":"《巴黎协定》","n":"国际气候合作破解集体困境"}],"more":"破解思路：在“重复囚徒困境”中，以牙还牙（Tit-for-Tat）等策略和外部奖惩机制可促使双方走向长期合作。","exam":[]},{"id":"a13-076","t":"帕累托法则（二八定律）","cid":"13d","p":2,"kind":"概念","alias":["帕累托法则","二八定律","80/20法则"],"one":"帕累托观察财富分布提出，指约20%的关键因素决定约80%的结果。","ans":"帕累托法则又称**二八定律**，源自**意大利经济学家维尔弗雷多·帕累托**19世纪末对财富分布的研究，后推广至管理学领域。帕累托观察到意大利约**20%的人口占有约80%的财富**，引申为**少数关键因素（约20%）往往决定大部分结果（约80%）**。该法则揭示了资源分布的不均衡规律，指导组织聚焦核心环节、提升资源配置效率，须与**帕累托最优**区分。","pts":["意大利经济学家帕累托提出，又称二八定律","少数关键因素（约20%）决定大部分结果（约80%）","揭示分布不均衡，指导聚焦重点与资源优化"],"mem":"数字直记：**20%的关键原因→80%的主要产出**。与“长尾理论”成对记：二八定律抓**头部20%**，长尾理论挖**尾部80%**。","mix":"务必区分**帕累托法则**（二八定律，讲分布不均）与**帕累托最优**（资源配置已达理想状态，不可能在不使他人变差的情况下让某人变好）；两者虽同以帕累托命名，含义完全不同。","mcq":[{"q":"经济学与管理学中，强调“少数关键因素决定大部分产出”的规律是","o":["帕累托法则（二八定律）","木桶效应","墨菲定律","破窗效应"],"a":0,"w":"帕累托法则即二八定律，指约20%的关键因素往往带来约80%的结果。"}],"rel":[{"t":"墨菲定律与长尾理论","n":"长尾理论与二八定律互补"},{"t":"马太效应","n":"同涉资源分配不均现象"},{"t":"基尼系数","n":"衡量收入分配差距的指标"}],"more":"区分提示：帕累托最优（Pareto Optimality）是福利经济学概念，帕累托法则（Pareto Principle）是经验分布规律。","exam":[]},{"id":"a13-077","t":"边际效用递减与机会成本","cid":"13d","p":3,"kind":"概念","alias":["边际效用递减","机会成本"],"one":"微观经济学基础：多消费一单位满足感递减；选择所放弃的最高替代价值。","ans":"二者是**微观经济学**基石概念。**边际效用递减**指连续消费同种商品时，**每增一单位带来的满足感递减**；**机会成本**指因资源稀缺作出选择时，**所放弃其他选项中价值最高者**。二者共同揭示消费者行为与理性决策规律。","pts":["边际效用递减：连续消费新增满足感递减","机会成本：放弃的替代选项中价值最高者","揭示稀缺条件下的消费与决策规律"],"mem":"生活画面记：吃包子第一口最香、第五个吃不下是“边际效用递减”；周末复习考研放弃了兼职赚300元或看电影，这300元就是“机会成本”。","mix":"常见考坑：机会成本只是“被放弃选项中价值最高的那一个”，而非所有被放弃选项价值的总和；也不要与已支出且无法收回的“沉没成本”混淆。","mcq":[{"q":"某人有一笔闲置资金，存银行可获利3千元、买国债可获利5千元、投资商铺可获利8千元。若其选择投资商铺，该决策的机会成本是","o":["5千元","3千元","8千元","1.6万元"],"a":0,"w":"机会成本是被放弃选项中价值最高者；放弃存银行（3千）和买国债（5千），最高者为5千元。"}],"rel":[{"t":"亚当·斯密与《国富论》","n":"经济学基础理论源流"},{"t":"看不见的手","n":"同属市场配置基础概念"},{"t":"囚徒困境","n":"同属微观与博弈决策概念"}],"exam":[]},{"id":"a13-078","t":"木桶效应","cid":"13d","p":2,"kind":"概念","alias":["短板理论","水桶定律"],"one":"又称短板理论，指一只木桶的盛水量取决于最短的那块木板。","ans":"木桶效应又称**短板理论**或水桶定律，是**管理学与组织行为学**中的常用概念。它指出，一只木桶的**最大盛水量取决于最短的那块木板**，而非最长的木板；要提升整体容量，首要任务是**补齐短板**。该理论揭示了系统各要素间的**协同制约关系**，广泛用于企业管理、公共治理与区域发展中破解薄弱环节、促进均衡提升。","pts":["又称短板理论，管理学常用概念","木桶盛水量取决于最短的那块木板","强调系统协同与补齐薄弱环节"],"mem":"画面直记：水总会从**最低的缺口**流出去，所以决定容量的是**短板**。补记“新木桶理论”：把木桶斜过来装水，比喻靠核心长板突出优势。","mix":"选择题常将木桶效应（薄弱环节决定上限）与**马太效应**（强者愈强）、**破窗效应**（放任小错引发恶化）、**蝴蝶效应**（微小初值引发连锁巨变）混在一起辨析。","mcq":[{"q":"在脱贫攻坚和区域协调发展中常强调“补短板、强弱项”，这对应的管理学概念是","o":["蝴蝶效应","马太效应","木桶效应","鲶鱼效应"],"a":2,"w":"木桶效应又称短板理论，指系统整体水平受制于最薄弱的环节。"}],"rel":[{"t":"破窗效应","n":"同为高频管理与社会效应"},{"t":"蝴蝶效应","n":"同簇常混考的效应类概念"},{"t":"马太效应","n":"效应类概念辨析对照"},{"t":"鲶鱼效应与羊群效应","n":"管理与行为效应对照"}],"exam":[]},{"id":"a13-079","t":"蝴蝶效应","cid":"13d","p":2,"kind":"概念","alias":["Butterfly Effect"],"one":"气象学家洛伦兹提出，属混沌理论，指初始微小变化引发系统长期巨变。","ans":"蝴蝶效应是**混沌理论**的代表性概念，由**美国气象学家爱德华·洛伦兹**于20世纪60年代研究天气预报模型时发现，后以“蝴蝶扇动翅膀可能引发远方龙卷风”的比喻闻名。它指在非线性动力系统中，**初始条件的微小偏差会引发系统长期的巨大差异**。该理论揭示了复杂系统的**高度敏感性与连锁放大机制**，广泛应用于气象、金融与社会风险分析。","pts":["美国气象学家洛伦兹提出，属混沌理论","初始条件的微小变化可引发系统长期巨变","揭示复杂系统的敏感性与非线性连锁反应"],"mem":"经典画面：**巴西蝴蝶轻拍翅膀→得州卷起龙卷风**。抓住三个词：**气象学家洛伦兹、混沌理论、初始微变**。","mix":"蝴蝶效应强调**复杂系统对初始条件的敏感性**，属自然科学（气象与混沌理论）出身；**多米诺骨牌效应**侧重线性接连倒塌；**破窗效应**侧重社会心理示范与放任失范。","mcq":[{"q":"提出“蝴蝶效应”、推动混沌理论发展的美国气象学家是","o":["帕累托","洛伦兹","威尔逊","凯恩斯"],"a":1,"w":"美国气象学家爱德华·洛伦兹在研究气象模型时发现并阐述了蝴蝶效应。"}],"rel":[{"t":"破窗效应","n":"同为“以小酿大”类效应辨析"},{"t":"木桶效应","n":"同簇高频效应类词条"},{"t":"墨菲定律与长尾理论","n":"定律与效应类对照"},{"t":"2008年国际金融危机","n":"金融风险连锁放大的案例"}],"more":"发现由来：1961年洛伦兹在气象模拟中将初始数值0.506127简输为0.506，结果推演出的天气走势截然不同。","exam":[]},{"id":"a13-080","t":"破窗效应","cid":"13d","p":2,"kind":"概念","alias":["破窗理论","Broken Windows Theory"],"one":"威尔逊与凯林1982年提出，指放任环境中的微小失范会诱发更大破坏。","ans":"破窗效应又称**破窗理论**，是犯罪学与社会心理学概念，由美国学者**威尔逊与凯林**于**1982年**提出。它比喻建筑破窗若未及时修补，会传递无人管理的信号，诱使人们打碎更多窗户；引申为**环境中的不良现象若被放任，会诱发效仿并变本加厉**。该理论强调**防微杜渐与及时纠偏**，广泛用于城市管理、组织纪律与网络生态治理。","pts":["美国学者威尔逊与凯林1982年提出","放任微小失范会传递失控信号、诱发效仿","强调及时纠偏与防微杜渐，用于社会与网络治理"],"mem":"画面记法：**第一块破玻璃没人修→大家觉得没人管→整栋楼玻璃全砸光**。对应成语：**防微杜渐、千里之堤溃于蚁穴**。","mix":"破窗效应重在**社会心理暗示与监管缺位导致效仿**；蝴蝶效应重在**自然或复杂系统初始条件的客观放大**，二者在原因机制上不同。","mcq":[{"q":"1982年美国学者威尔逊与凯林提出、用来说明“放任微小不良行为会诱使他人效仿恶化”的理论是","o":["马太效应","木桶效应","蝴蝶效应","破窗效应"],"a":3,"w":"威尔逊与凯林1982年发表《破窗》，系统阐述了破窗效应。"}],"rel":[{"t":"蝴蝶效应","n":"同涉微小诱因，机制不同"},{"t":"木桶效应","n":"管理与治理效应对照"},{"t":"网络生态治理","n":"网络失范治理的常用论据"},{"t":"网络暴力治理","n":"及时纠偏防范跟风施暴"}],"more":"出处：1982年3月詹姆斯·威尔逊与乔治·凯林在《大西洋月刊》发表《破窗》（Broken Windows）。","exam":[]},{"id":"a13-081","t":"鲶鱼效应与羊群效应","cid":"13d","p":3,"kind":"概念","alias":["鲶鱼效应","羊群效应","从众效应"],"one":"鲶鱼效应指引入竞争者激活群体；羊群效应指盲目跟从多数人的从众行为。","ans":"二者是管理学与行为金融学常见概念。**鲶鱼效应**源于沙丁鱼槽放鲶鱼保活的典故，指**引入外部竞争者激活群体活力**；**羊群效应**又称从众效应，指个体**盲目跟从多数人决策**，常用来解释股市追涨杀跌与舆论跟风。","pts":["鲶鱼效应：引入竞争者打破安逸激活组织","羊群效应：盲目跟风，常见于金融投资从众","分属组织激励与群体心理分析工具"],"mem":"动物画面记：水箱丢进一条“鲶鱼”把沙丁鱼逼得游起来（激活竞争）；头羊跳沟、后面“羊群”全跟着跳（盲目从众）。","mix":"易与马太效应（强者愈强）、破窗效应（小隐患诱发大破坏）、蝴蝶效应（微小变动引发连锁巨变）混淆，做题看清“激励竞争”还是“盲目跟风”。","mcq":[{"q":"企业在成熟团队中引入外部高绩效人才以打破安逸、激发竞争活力，这一做法体现的是","o":["羊群效应","鲶鱼效应","破窗效应","马太效应"],"a":1,"w":"引入外部竞争者刺激原有成员增强紧迫感与活力，称为鲶鱼效应。"}],"rel":[{"t":"马太效应","n":"同属经济学常考效应"},{"t":"破窗效应","n":"同属管理与社会学常考效应"},{"t":"蝴蝶效应","n":"常作效应类选择题干扰项"}],"exam":[]},{"id":"a13-082","t":"墨菲定律与长尾理论","cid":"13d","p":3,"kind":"概念","alias":["墨菲定律","长尾理论"],"one":"墨菲定律指可能出错的事终将出错；长尾理论指小众需求总和可匹敌主流。","ans":"二者是风险管理与网络经济的经典原理。**墨菲定律**指**“凡有可能出错的事，终将出错”**，警示重视隐患与冗余防控；**长尾理论**由**克里斯·安德森**于**2004年**提出，指出网络时代**大量小众冷门需求的总和可匹敌主流爆款**。","pts":["墨菲定律：可能出错的事终将出错，重防患","长尾理论：克里斯·安德森2004年提出","长尾理论揭示互联网时代小众市场价值"],"mem":"形象对比记：墨菲定律记“面包掉地总是涂黄油那面朝下”（警示排错）；长尾理论画一条长尾巴曲线，尾巴虽细但够长，面积不输头部爆款。","mix":"长尾理论常与“二八定律（帕累托法则）”对举：传统经济二八定律强调抓20%头部爆款，互联网长尾理论强调挖掘80%小众长尾市场。","mcq":[{"q":"2004年提出“长尾理论”，指出互联网时代小众冷门产品累加市场可媲美主流爆款的学者是","o":["爱德华·墨菲","凯文·凯利","克里斯·安德森","约瑟夫·奈"],"a":2,"w":"《连线》杂志主编克里斯·安德森于2004年首次提出“长尾理论”。"}],"rel":[{"t":"帕累托法则（二八定律）","n":"与长尾理论形成经典对照"},{"t":"木桶效应","n":"同属常考管理与风险定律"},{"t":"数字经济","n":"长尾理论在平台经济中的体现"}],"exam":[]},{"id":"a13-083","t":"人工智能（达特茅斯会议）","cid":"13e","p":1,"kind":"概念","alias":["达特茅斯会议","Artificial Intelligence","AI概念提出"],"one":"1955年达特茅斯项目提案使用“人工智能”，1956年会议标志学科诞生。","ans":"人工智能是**研究使机器模拟人类智能行为的学科与技术**，这一名称**见于1955年达特茅斯暑期研究项目提案，会议于1956年夏举行**。会议由**麦卡锡、明斯基、香农、罗切斯特**等人发起，提案标题使用“Artificial Intelligence”一词，会议因此被视为**人工智能学科的诞生标志**。此后人工智能经历符号主义、机器学习到深度学习的发展，2016年AlphaGo战胜李世石、2022年ChatGPT发布使其两次引发全球关注。2026年是达特茅斯会议举行70周年。","pts":["1956年美国达特茅斯学院会议","麦卡锡等发起，1955年提案使用“人工智能”","学科诞生标志；2026年70周年"],"mem":"年份谐音：1956，“一就舞（午）六”，夏天（一九五六）在达特茅斯。人物记“麦”：麦卡锡命名，明斯基、香农、罗切斯特同行。2026减1956恰好70，直接记“七十周年”。","mix":"提出“图灵测试”的是1950年的图灵，不是达特茅斯会议；图灵被称为“人工智能之父”之一，麦卡锡常被称为“人工智能之父”，选择题注意设问。","mcq":[{"q":"哪次会议通常被视为人工智能学科诞生的标志","o":["1950年图灵论文发表","1997年深蓝对弈","2016年AlphaGo对弈","1956年达特茅斯会议"],"a":3,"w":"1955年提案已使用该词，1956年夏举行的达特茅斯会议是学科诞生的标志。"},{"q":"2026年是达特茅斯会议举行的","o":["50周年","60周年","70周年","80周年"],"a":2,"w":"会议于1956年举行，2026年正好70周年。"}],"rel":[{"t":"图灵与图灵测试","n":"1950年早于会议"},{"t":"AlphaGo","n":"2016年第一次引爆关注"},{"t":"ChatGPT与生成式人工智能（AIGC）","n":"2022年第二次引爆"},{"t":"《新一代人工智能发展规划》","n":"中国国家层面规划"}],"more":"会议提案提出于1955年，会议在1956年夏季举行，历时约两个月。","exam":[]},{"id":"a13-084","t":"图灵与图灵测试","cid":"13e","p":1,"kind":"人物","alias":["阿兰·图灵","图灵","图灵测试","模仿游戏"],"one":"英国数学家，计算机科学之父，1950年提出图灵测试。","ans":"阿兰·图灵（1912—1954）是**英国数学家、逻辑学家，被称为计算机科学之父、人工智能之父**。他在1936年提出抽象计算模型“图灵机”，二战期间参与破译德国“恩尼格玛”密码。**1950年他发表论文《计算机器与智能》，提出判断机器能否思考的“图灵测试”**：若人类提问者无法分辨对方是人还是机器，就可认为机器具有智能。为纪念他，**美国计算机协会1966年设立“图灵奖”，被称为计算机界的诺贝尔奖**。","pts":["英国数学家，计算机科学之父","1950年《计算机器与智能》提出图灵测试","图灵机；图灵奖是计算机界最高奖"],"mem":"三件事一条线：1936“机”（图灵机）、1950“测”（图灵测试）、1966“奖”（图灵奖）。画面：隔着帘子聊天，分不出对面是人还是机器，机器就算通过。","mix":"图灵测试1950年提出，早于1955年达特茅斯项目提案使用“人工智能”；图灵奖由美国计算机协会设立，不属于诺贝尔奖体系。","mcq":[{"q":"被称为“计算机科学之父”、提出图灵测试的是","o":["冯·诺依曼","约翰·麦卡锡","克劳德·香农","阿兰·图灵"],"a":3,"w":"图灵1950年提出图灵测试。"},{"q":"图灵测试最早出现在下列哪篇论文中","o":["《计算机器与智能》","《数学原理》","《控制论》","《人工智能的未来》"],"a":0,"w":"1950年《计算机器与智能》。"}],"rel":[{"t":"图灵奖","n":"以其命名的计算机最高奖"},{"t":"人工智能（达特茅斯会议）","n":"后续的学科命名"},{"t":"AlphaGo","n":"机器智能的里程碑"},{"t":"ChatGPT与生成式人工智能（AIGC）","n":"现代版的“图灵测试”话题"}],"more":"1954年6月逝世，终年41岁。","exam":[]},{"id":"a13-085","t":"图灵奖","cid":"13e","p":2,"kind":"常识","alias":["A.M. Turing Award","计算机界诺贝尔奖"],"one":"美国计算机协会1966年设立的计算机最高奖，姚期智于2000年成首位华人得主。","ans":"图灵奖由**美国计算机协会（ACM）**于**1966年**设立，以计算机科学先驱**艾伦·图灵**命名，被称为**“计算机界的诺贝尔奖”**。该奖每年颁发一次，表彰对计算机领域作出重大持久贡献的学者。**2000年姚期智**因计算理论贡献获奖，是**首位且迄今唯一获此奖的华人科学家**；2018年辛顿、本吉奥与杨立昆凭深度学习共享该奖。","pts":["美国计算机协会1966年设立，以艾伦·图灵命名","计算机科学最高奖，称“计算机界诺贝尔奖”","2000年姚期智成首位且迄今唯一华人得主"],"mem":"年份+人物挂钩：**1966年设立**，2026年正好60周年；**2000年姚期智**拿奖（后来回清华办“姚班”），刚好跨世纪整数年，极好记。","mix":"常见易混奖项：数学最高奖是**菲尔兹奖**（限40岁以下）和**阿贝尔奖**；建筑最高奖是**普利兹克奖**；新闻最高奖是**普利策奖**；计算机最高奖才是**图灵奖**。","mcq":[{"q":"2000年因计算理论贡献荣获图灵奖、成为首位获得该奖的华人计算机科学家是","o":["吴文俊","钱学森","姚期智","华罗庚"],"a":2,"w":"姚期智于2000年获图灵奖，是首位也是迄今唯一获图灵奖的华人学者。"}],"rel":[{"t":"图灵与图灵测试","n":"奖项命名者与AI思想先驱"},{"t":"机器学习与深度学习","n":"2018年授予深度学习三巨头"},{"t":"人工智能（达特茅斯会议）","n":"多位AI先驱曾获图灵奖"},{"t":"诺贝尔奖","n":"常与之对举的科学最高奖"}],"more":"2026年周年：1966年图灵奖设立60周年。\n首位得主为艾伦·佩利；姚期智2004年全职回国任教清华大学，创办“姚班”。","exam":[]},{"id":"a13-086","t":"机器学习与深度学习","cid":"13e","p":2,"kind":"概念","alias":["机器学习","深度学习","Deep Learning"],"one":"机器学习让机器从数据自动总结规律，深度学习以多层神经网络为核心分支。","ans":"**机器学习**是人工智能的核心方法，指计算机通过算法**从数据中自动总结规律并改进性能**。**深度学习**是其关键分支，依托**多层人工神经网络**逐层提取特征，在语音、图像与语言处理中实现突破。**辛顿、本吉奥与杨立昆**因深度学习获**2018年图灵奖**；**霍普菲尔德与辛顿**因人工神经网络奠基工作获**2024年诺贝尔物理学奖**。","pts":["机器学习从数据学规律，深度学习用多层神经网络","辛顿、本吉奥、杨立昆获2018年图灵奖","霍普菲尔德与辛顿获2024年诺贝尔物理学奖"],"mem":"同心圆记法：**人工智能 ⊃ 机器学习 ⊃ 深度学习**（从大到小包三层）。人物口诀：**18图灵“辛本杨”**（辛顿、本吉奥、杨立昆），**24诺物“霍与辛”**（霍普菲尔德、辛顿），**辛顿两奖双料王**。","mix":"2024年诺贝尔物理学奖授予霍普菲尔德与辛顿（神经网络基础）；同年**诺贝尔化学奖**一半授予预测蛋白质结构的AlphaFold团队（哈萨比斯与江珀），别把物理奖与化学奖混了。","mcq":[{"q":"2024年因人工神经网络机器学习基础性发现而荣获诺贝尔物理学奖的两位科学家是","o":["杨立昆与本吉奥","霍普菲尔德与辛顿","哈萨比斯与江珀","图灵与麦卡锡"],"a":1,"w":"约翰·霍普菲尔德与杰弗里·辛顿获2024年诺贝尔物理学奖；哈萨比斯与江珀获同年化学奖。"}],"rel":[{"t":"图灵奖","n":"2018年表彰深度学习三巨头"},{"t":"大语言模型与Transformer","n":"深度学习发展出的核心架构"},{"t":"AlphaFold","n":"同年获2024年诺贝尔化学奖"},{"t":"人工智能（达特茅斯会议）","n":"AI学科源头"}],"more":"关键奖项：2018年图灵奖（辛顿、本吉奥、杨立昆）；2024年诺贝尔物理学奖（霍普菲尔德、辛顿）。","exam":[]},{"id":"a13-087","t":"ChatGPT与生成式人工智能（AIGC）","cid":"13e","p":1,"kind":"时事","alias":["ChatGPT","AIGC","生成式人工智能","生成式AI","OpenAI"],"one":"OpenAI 2022年11月发布的对话模型，开启生成式AI热潮。","ans":"ChatGPT是**美国OpenAI公司2022年11月30日发布的对话式人工智能模型**，基于大语言模型，能理解自然语言并完成问答、写作、翻译、编程等任务，上线两个月用户即破亿。它是**生成式人工智能（AIGC）的代表**，生成式人工智能指**能够生成文本、图像、音频、视频等内容的模型与技术**。ChatGPT引发全球大模型竞赛，国内随后出现文心一言、通义千问、DeepSeek等产品。其应用同时带来虚假信息、版权、数据安全和学术诚信等问题，推动各国出台治理规则。","pts":["OpenAI 2022年11月30日发布","生成文本、图像、音频、视频的AIGC","引发大模型竞赛，也带来治理问题"],"mem":"时间锚：2016 AlphaGo（下棋的AI），2022 ChatGPT（说话的AI），“棋”后“话”，相隔六年。AIGC=AI Generated Content，中文就是“AI生成内容”，字母直接对应。","mix":"AIGC是内容生产方式，ChatGPT是具体产品；AlphaGo是决策型AI，不是生成式；DeepSeek是中国公司，ChatGPT是美国OpenAI的。","mcq":[{"q":"ChatGPT由哪家公司研发","o":["OpenAI","谷歌","微软","Meta"],"a":0,"w":"2022年11月30日由OpenAI发布。"},{"q":"下列属于生成式人工智能（AIGC）应用的是","o":["根据提示词生成一幅图像","对磁盘文件进行碎片整理","用传感器测量温度","通过杀毒软件扫描病毒"],"a":0,"w":"AIGC指能生成文本、图像、音频、视频等内容的技术。"}],"rel":[{"t":"AlphaGo","n":"上一轮AI热点"},{"t":"DeepSeek","n":"中国开源大模型"},{"t":"《生成式人工智能服务管理暂行办法》","n":"我国治理规定"},{"t":"人工智能治理","n":"应对生成式AI风险"}],"more":"我国《生成式人工智能服务管理暂行办法》2023年8月15日起施行。","exam":[]},{"id":"a13-088","t":"大语言模型与Transformer","cid":"13e","p":2,"kind":"概念","alias":["大语言模型","LLM","Transformer架构"],"one":"谷歌2017年提出Transformer，凭自注意力机制奠定当代大语言模型基础。","ans":"**Transformer**由**谷歌团队2017年**论文《Attention Is All You Need》提出，核心为**自注意力机制**，可并行计算并捕捉长距离依赖。基于它的**大语言模型（LLM）**经海量文本预训练，具备强大理解、生成与推理能力，代表如GPT与DeepSeek。它突破循环网络瓶颈，引爆**生成式人工智能**浪潮。","pts":["谷歌团队2017年提出Transformer架构","核心为自注意力机制，支持高效并行训练","当代大语言模型（GPT、DeepSeek）底层架构"],"mem":"英文缩写直记：大名鼎鼎的 **GPT** 里的 **T** 就是 **Transformer**（Generative Pre-trained Transformer）。论文名直译就是**“你只需要注意力”**，记住**自注意力机制**。","mix":"Transformer取代的是早期逐词顺序计算的循环神经网络（RNN/LSTM）；它的核心是并行计算和自注意力，最初用于机器翻译，后来才统一了大语言模型和多模态模型架构。","mcq":[{"q":"2017年谷歌团队在论文《Attention Is All You Need》中提出、成为当代大语言模型核心底层架构的是","o":["卷积神经网络","专家系统","玻尔兹曼机","Transformer"],"a":3,"w":"该论文正式提出基于自注意力机制的Transformer架构，支撑了现代大语言模型。"}],"rel":[{"t":"基础大模型","n":"LLM是最代表性的基础大模型"},{"t":"ChatGPT与生成式人工智能（AIGC）","n":"底层依托Transformer"},{"t":"DeepSeek","n":"采用改进架构的国产大模型"},{"t":"机器学习与深度学习","n":"大语言模型所属的技术脉络"}],"more":"关键论文：Vaswani et al., Attention Is All You Need (2017)。\n缩写拆解：GPT = Generative Pre-trained Transformer。","exam":[]},{"id":"a13-089","t":"DeepSeek","cid":"13e","p":1,"kind":"时事","alias":["DeepSeek","深度求索","DeepSeek-R1"],"one":"杭州深度求索公司研发的开源大模型，2025年1月R1引发关注。","ans":"DeepSeek是**杭州深度求索公司研发的大语言模型系列**，创始人为梁文锋。**2025年1月公司发布推理模型DeepSeek-R1并开源**，以较低的训练成本取得与国际先进模型相近的性能，在全球引发强烈反响，甚至冲击了相关美股芯片企业的市值。它被视为**中国开源大模型的代表**，说明在算力受限条件下，算法和工程创新同样能带来突破。DeepSeek的开源策略降低了企业和开发者使用大模型的门槛，推动了国内“人工智能+”应用落地。","pts":["杭州深度求索公司研发","2025年1月发布R1并开源","低成本取得先进性能；开源推动应用"],"mem":"一句话：“深度求索”=Deep+Seek，名字就是“深度探索”。事件挂钩：2025年1月春节前发布，成为开年最大科技新闻；记“杭州六小龙”之一。","mix":"DeepSeek是公司和模型名，不是“芯片”；它走开源路线，与OpenAI早期闭源路径形成对照；别与百度文心一言、阿里通义千问混淆。","mcq":[{"q":"2025年1月发布推理模型R1并开源的中国公司是","o":["智谱","月之暗面","深度求索","商汤"],"a":2,"w":"杭州深度求索公司发布DeepSeek-R1。"},{"q":"DeepSeek公司总部所在城市是","o":["杭州","北京","深圳","上海"],"a":0,"w":"深度求索公司位于杭州。"}],"rel":[{"t":"ChatGPT与生成式人工智能（AIGC）","n":"常被对比的美国产品"},{"t":"开源生态","n":"其重要发展路径"},{"t":"算力","n":"低算力成本取得突破"},{"t":"“人工智能+”行动","n":"推动应用落地"}],"more":"2025年1月R1发布后，一度成为多国应用商店下载榜首的应用。","exam":[]},{"id":"a13-090","t":"AlphaGo","cid":"13e","p":2,"kind":"事件","alias":["阿尔法狗","阿尔法围棋"],"one":"谷歌DeepMind研发的围棋AI，2016年击败李世石，2026年满10周年。","ans":"AlphaGo是**谷歌DeepMind团队**研发的围棋人工智能程序，属人机对弈里程碑。它融合**深度神经网络、强化学习与蒙特卡洛树搜索**，**2016年3月以4比1击败韩国棋手李世石**，**2017年5月以3比0击败中国棋手柯洁**。围棋长期被视为人类智力堡垒，其胜利点燃全球人工智能热潮，2026年正值人机大战十周年。","pts":["谷歌DeepMind研发，结合深度学习与强化学习","2016年3月4比1胜李世石，2017年胜柯洁","人机对弈里程碑，2026年满十周年"],"mem":"时间两连击：**16年胜李世石（4:1）→17年胜柯洁（3:0）**。1997年IBM“深蓝”赢国际象棋，19年后2016年AlphaGo赢围棋，2026年正好**10周年**。","mix":"易混对比：**深蓝（Deep Blue）**1997年战胜国际象棋冠军卡斯帕罗夫，靠暴力搜索；**AlphaGo**2016年胜李世石，靠深度学习；同门**AlphaFold**用于预测蛋白质三维结构。","mcq":[{"q":"2016年3月，谷歌DeepMind研发的围棋人工智能程序AlphaGo以4比1击败的韩国棋手是","o":["李世石","柯洁","卡斯帕罗夫","樊麾"],"a":0,"w":"AlphaGo于2016年3月击败李世石，2017年5月击败柯洁，此前2015年曾胜樊麾。"}],"rel":[{"t":"AlphaFold","n":"同团队的科学AI突破"},{"t":"机器学习与深度学习","n":"AlphaGo依托的核心技术"},{"t":"ChatGPT与生成式人工智能（AIGC）","n":"继其后的又一AI引爆点"},{"t":"人工智能（达特茅斯会议）","n":"AI发展史上的重要里程碑"}],"more":"2026年周年：2016年3月AlphaGo对战李世石10周年。\n后续版本：AlphaGo Zero不依赖人类棋谱，仅靠自我对弈习得围棋。","exam":[]},{"id":"a13-091","t":"AlphaFold","cid":"13e","p":3,"kind":"概念","alias":["阿尔法折叠"],"one":"DeepMind开发的AI蛋白质结构预测模型，研发者获2024年诺贝尔化学奖。","ans":"AlphaFold是**DeepMind**开发的**蛋白质三维结构预测AI模型**，属“AI用于科学”里程碑。它高精度破解了半世纪来的**蛋白质折叠难题**，主创**哈萨比斯与江珀**与贝克分享**2024年诺贝尔化学奖**，深刻推动生命科学变革。","pts":["DeepMind开发的蛋白质结构预测AI模型","破解困扰生物学界50年的蛋白质折叠难题","哈萨比斯与江珀凭此获2024年诺贝尔化学奖"],"mem":"同门兄弟对比记：DeepMind的“AlphaGo（下围棋，2016）”与“AlphaFold（折蛋白，Fold即折叠，2024夺诺贝尔化学奖）”。","mix":"2024年诺贝尔物理学奖（霍普菲尔德、辛顿，神经网络）与化学奖（哈萨比斯、江珀、贝克，蛋白质预测与设计）同年垂青AI，切勿张冠李戴。","mcq":[{"q":"DeepMind团队开发的AlphaFold模型因解决哪一科学难题而助力研发者荣获2024年诺贝尔化学奖","o":["蛋白质三维结构预测","可控核聚变约束","基因剪刀编辑","室温超导材料合成"],"a":0,"w":"哈萨比斯与江珀因开发AlphaFold实现精准蛋白质结构预测，与戴维·贝克分享2024年诺贝尔化学奖。"}],"rel":[{"t":"AlphaGo","n":"同为DeepMind代表AI"},{"t":"诺贝尔奖","n":"2024年获诺贝尔化学奖"},{"t":"人工合成牛胰岛素","n":"蛋白质研究的历史对照"},{"t":"机器学习与深度学习","n":"依托深度学习实现突破"}],"more":"2020年发布AlphaFold 2实现重大突破，2024年5月发布AlphaFold 3将预测拓展至DNA、RNA及小分子复合物。","exam":[]},{"id":"a13-092","t":"智能体（AI Agent）","cid":"13e","p":2,"kind":"概念","alias":["智能体","AI Agent","人工智能体"],"one":"能感知环境、自主规划并调用外部工具完成复杂任务的人工智能系统。","ans":"智能体（**AI Agent**）指以大模型为决策核心，能**感知环境、自主拆解规划并调用外部工具完成任务**的人工智能系统。区别于单轮问答模型，它具备**记忆、规划、工具调用与反思迭代**能力，可自主浏览网页、运行代码或协同完成业务流程。它推动AI由内容生成迈向**任务自主执行**，是“人工智能+”行动落地的关键形态。","pts":["以大模型为核，能感知环境并自主规划执行","具备记忆、规划、工具调用与多步迭代能力","推动AI从问答生成迈向自主执行任务"],"mem":"对比直记：普通聊天机器人像**“军师”**，只动嘴出主意；**AI Agent（智能体）**像**“全能助理”**，有脑子（大模型）、有记事本（记忆）、还能自己拿工具（调用软件/API）把活干完。","mix":"智能体（AI Agent）偏重数字软件环境中的自主决策与工具调用；**具身智能**则强调装上机器人、汽车等物理躯体，在真实物理世界中交互行动，二者常协同融合。","mcq":[{"q":"相较于仅能进行文本问答的基础对话模型，人工智能领域“智能体（AI Agent）”最突出的特征是","o":["无需任何算力与大模型支持","只能在完全断网的环境下运行","能够自主规划目标并调用外部工具完成多步任务","必须具备类人的物理仿生躯体"],"a":2,"w":"智能体强调感知环境、自主规划与调用工具执行任务，物理躯体属于具身智能范畴。"}],"rel":[{"t":"基础大模型","n":"智能体的决策大脑"},{"t":"具身智能","n":"软件代理与物理实体的对照"},{"t":"“人工智能+”行动","n":"智能体赋能千行百业的政策"},{"t":"人工智能时代的译者角色","n":"AI代理改变翻译工作流"}],"exam":[]},{"id":"a13-093","t":"人形机器人","cid":"13e","p":3,"kind":"概念","alias":["仿生人形机器人","双足机器人"],"one":"具身智能主要载体，模仿人体形态与运动，被视为未来产业新赛道。","ans":"人形机器人指模仿人体形态与双足运动的智能机器人，是**具身智能**的核心载体。它融合**大模型“大脑”、运控“小脑”与灵巧肢体**，适配制造与服务场景。**2025至2026年北京连办世界人形机器人运动会**，标志该产业加速落地。","pts":["具身智能主要载体，模仿人体形态运动","融合大模型“大脑”、运控“小脑”与灵巧肢体","2023年入国家指导意见，2025年起办世界运动会"],"mem":"人体三段记架构：“大脑”（AI大模型感知决策）+“小脑”（双足平衡运动控制）+“肢体”（灵巧手与关节执行器）。","mix":"具身智能是更上位概念，涵盖自动驾驶汽车、四足机器狗、工业机械臂等多种实体形态，人形机器人只是最具代表性的载体之一。","mcq":[{"q":"在人工智能前沿方向中，人形机器人通常被视为哪一概念最具代表性的物理载体","o":["隐私计算","具身智能","区块链","边缘计算"],"a":1,"w":"具身智能强调AI拥有物理身体并在真实环境中感知交互，人形机器人是其典型载体。"}],"rel":[{"t":"具身智能","n":"人形机器人所属的上位技术方向"},{"t":"未来产业","n":"人形机器人被列为未来产业赛道"},{"t":"“人工智能+”行动","n":"智能终端与制造业融合场景"}],"more":"2023年11月工信部印发《人形机器人创新发展指导意见》；2025年8月与2026年8月，首届及第二届世界人形机器人运动会在北京国家速滑馆举行。","exam":[]},{"id":"a13-094","t":"脑机接口","cid":"13e","p":2,"kind":"概念","alias":["BCI","Brain-Computer Interface"],"one":"在大脑与外部设备间建立直接信息通路的前沿技术，分侵入式与非侵入式。","ans":"脑机接口（**BCI**）指**在大脑与外部设备之间建立直接信息连接与控制通路**的前沿技术，属我国重点培育的**未来产业**。按采集方式分为**侵入式、半侵入式与非侵入式**。**2025年国家医保局首为脑机接口单独立项**，工信部等七部门印发产业创新意见。它在瘫痪康复、神经助语等医疗领域价值突出，也伴随神经隐私与伦理挑战。","pts":["建立大脑与外部设备直接信息通路的前沿技术","按方式分为侵入式、半侵入式与非侵入式","2025年国家医保单独立项并出台七部门实施意见"],"mem":"三类路线按“进不进颅骨”记：**非侵入式**戴帽子（安全但隔层壳）、**半侵入式**贴颅内脑膜、**侵入式**插电极（最准但需手术）。2025年记两件大事：**3月医保立项，7月七部委发文**。","mix":"侵入式与非侵入式各有取舍，并非侵入式全面优于非侵入式：前者信号强、创伤风险高，后者无创安全、易推广但信号受颅骨衰减。","mcq":[{"q":"关于脑机接口（BCI）技术与我国相关进展，下列说法正确的是","o":["只能单向读取脑电信号而无法控制外部设备","按采集方式可分为侵入式与非侵入式等路线","属于传统制造业，尚未列入未来产业布局","所有脑机接口均须通过开颅手术植入芯片"],"a":1,"w":"脑机接口分侵入式、半侵入式和非侵入式，可在大脑与外部设备间建立直接信息通路。"}],"rel":[{"t":"未来产业","n":"国家重点布局的前沿方向"},{"t":"具身智能","n":"同属前沿智能与人机交互领域"},{"t":"科技伦理","n":"涉及神经隐私与人体试验规范"},{"t":"新质生产力","n":"颠覆性前沿技术的代表"}],"more":"2025年政策节点：2025年3月国家医保局印发神经系统类立项指南，设立“侵入式脑机接口置入费”等项目；2025年7月工信部等七部门印发《关于推动脑机接口产业创新发展的实施意见》，提出2027年和2030年两阶段目标。","exam":[]},{"id":"a13-095","t":"元宇宙","cid":"13e","p":3,"kind":"概念","alias":["Metaverse"],"one":"源自1992年科幻小说《雪崩》，指与现实世界映射交互的虚拟数字空间。","ans":"元宇宙（Metaverse）一词出自美国作家**斯蒂芬森**1992年科幻小说**《雪崩》**。它整合**VR/AR、人工智能与区块链**等技术，构建**与现实世界映射交互的虚拟数字空间**，体现数字技术向沉浸式虚实融合演进的趋势。","pts":["词源为斯蒂芬森1992年科幻小说《雪崩》","整合VR/AR、AI等技术的虚实交互空间","2021年Meta公司更名引发全球热潮"],"mem":"词源故事记：1992年《雪崩》里送披萨的主角戴上护目镜进入“Metaverse”，记住“《雪崩》造出元宇宙，Meta改名带火它”。","mix":"不要把元宇宙词源误记为电影《头号玩家》或刘慈欣小说，其确切出处是1992年斯蒂芬森的赛博朋克小说《雪崩》。","mcq":[{"q":"“元宇宙（Metaverse）”一词最早出自1992年美国作家尼尔·斯蒂芬森的哪部科幻小说","o":["《神经漫游者》","《三体》","《雪崩》","《头号玩家》"],"a":2,"w":"尼尔·斯蒂芬森在1992年科幻小说《雪崩》（Snow Crash）中首次创造“Metaverse”一词。"}],"rel":[{"t":"区块链","n":"元宇宙数字资产确权常用底层技术"},{"t":"数字经济","n":"虚实融合的新型数字业态"},{"t":"《三体》","n":"中外科技想象与科幻文学对照"}],"exam":[]},{"id":"a13-096","t":"物联网与5G","cid":"13e","p":3,"kind":"概念","alias":["IoT","第五代移动通信技术"],"one":"物联网通过传感设备实现万物互联；2019年6月中国发放5G商用牌照。","ans":"物联网（IoT）指通过传感设备将**物品与互联网相连**以实现智能管理，概念始于1999年。**5G**即第五代移动通信技术，具**高速率、低时延、大连接**优势；**2019年6月6日**中国发放**5G商用牌照**，为万物互联与智慧城市筑牢网络底座。","pts":["物联网借传感设备连接物品实现万物互联","5G具高速率、低时延、大连接三大特性","2019年6月6日中国发放5G商用牌照"],"mem":"顺口溜记5G三特性：“快（高速率）、稳（低时延）、广（大连接）”，2019年6月6日“六六大顺”发牌照，正式开启中国5G商用元年。","mix":"中国2019年6月6日共向四家运营商发放5G商用牌照：中国电信、中国移动、中国联通和**中国广电**（容易漏掉第四家中国广电）。","mcq":[{"q":"2019年6月6日，中国工信部正式发放5G商用牌照，获牌的四家企业除移动、联通、电信外，还有","o":["中国铁塔","中国卫星","中国邮政","中国广电"],"a":3,"w":"2019年6月6日工信部向中国电信、中国移动、中国联通、中国广电四家发放5G商用牌照。"}],"rel":[{"t":"大数据","n":"物联网终端是海量数据重要来源"},{"t":"海绵城市与智慧城市","n":"物联网与5G的典型应用场景"},{"t":"数字中国","n":"新型信息基础设施核心组成部分"}],"exam":[]},{"id":"a13-097","t":"摩尔定律","cid":"13e","p":2,"kind":"概念","alias":["Moore's Law"],"one":"英特尔创始人之一戈登·摩尔1965年提出，指芯片晶体管数量约每两年翻番。","ans":"摩尔定律是半导体领域的著名经验规律，由**英特尔联合创始人戈登·摩尔**于**1965年**提出。它指价格不变时，**集成电路上可容纳的晶体管数目约每两年翻一番**，芯片性能随之倍增而算力成本下降。该规律半个多世纪来指引全球芯片制程与信息产业爆发；随着硅基工艺逼近物理极限，业界正借**先进封装与新架构**延续后摩尔时代增长。","pts":["英特尔联合创始人戈登·摩尔1965年提出","集成电路晶体管数量约每两年翻一番","经验规律而非物理定律，当代步入后摩尔时代"],"mem":"数字口诀：**摩尔“两年翻一倍”**（早期常说18个月，摩尔本人1975年修订为约2年）。记人物身份：**英特尔（Intel）创始人之一**，管的是芯片里的**晶体管**。","mix":"摩尔定律是**产业经验总结与预测**，不是严格的自然科学物理定律；另外注意区分“18个月”说法来自英特尔高管大卫·豪斯对性能翻倍的推算，摩尔本人原文为1965年“每年”、1975年修订为“每两年”。","mcq":[{"q":"1965年由英特尔联合创始人戈登·摩尔提出、描述集成电路晶体管数量约每两年翻一番的规律称为","o":["墨菲定律","二八定律","香农定理","摩尔定律"],"a":3,"w":"戈登·摩尔提出摩尔定律，揭示半导体芯片集成度呈指数级增长的经验趋势。"}],"rel":[{"t":"算力","n":"芯片演进驱动算力指数提升"},{"t":"第三次科技革命","n":"微电子与信息技术浪潮"},{"t":"墨菲定律与长尾理论","n":"同为高频“定律”类辨析"},{"t":"量子科技","n":"后摩尔时代的前沿算力探索"}],"more":"人物生卒：戈登·摩尔（Gordon Moore，1929–2023）；1975年他将周期修订为约每两年翻一番。","exam":[]},{"id":"a13-098","t":"集成电路与光刻机","cid":"13e","p":1,"kind":"概念","alias":["集成电路","芯片","光刻机","EUV光刻机","阿斯麦","ASML"],"one":"芯片是集成电路载体，光刻机是制造芯片的核心设备，属“卡脖子”技术。","ans":"集成电路是**把大量晶体管等元件集成在半导体基片上的微型电子电路**，芯片是其载体，是计算机、手机、汽车等产品的核心。光刻机是**芯片制造的核心设备**，用光把电路图案刻到硅片上，其中**极紫外（EUV）光刻机由荷兰阿斯麦（ASML）公司垄断供应**，因出口管制我国难以获得。芯片和光刻机被视为**“卡脖子”关键技术**，国家通过**新型举国体制**、集成电路产业投资基金等推动自主攻关。其发展大致遵循**摩尔定律**，即集成度约每18至24个月翻一番。","pts":["芯片是集成电路载体","光刻机是制造核心设备，EUV由阿斯麦垄断","“卡脖子”技术，新型举国体制攻关"],"mem":"一条生产线记忆：设计（图纸）→光刻（印图，光刻机）→蚀刻→封装。光刻机像“超高精度投影仪”，把图纸印在硅片上；荷兰ASML是唯一的EUV供应商，关键词“荷兰、垄断”。","mix":"光刻机属制造设备，芯片属产品，EDA软件属设计工具，三者环节不同；ASML是荷兰公司，不是美国或日本公司。","mcq":[{"q":"目前极紫外（EUV）光刻机的唯一供应商是","o":["日本尼康","美国英特尔","韩国三星","荷兰阿斯麦"],"a":3,"w":"荷兰阿斯麦（ASML）公司垄断EUV光刻机。"},{"q":"关于芯片与集成电路，说法正确的是","o":["芯片是集成电路的载体","集成电路是一种软件","光刻机用于编写程序","芯片只用于手机"],"a":0,"w":"集成电路是电路，芯片是其载体。"}],"rel":[{"t":"摩尔定律","n":"芯片发展规律"},{"t":"算力","n":"芯片是算力基础"},{"t":"“863计划”","n":"早期高技术攻关"},{"t":"人形机器人","n":"依赖芯片的新产业"}],"more":"“卡脖子”指关键领域被他人控制、难以自主获得的技术。","exam":[]},{"id":"a13-099","t":"量子科技","cid":"13e","p":1,"kind":"概念","alias":["量子科技","量子通信","量子计算","墨子号","九章","祖冲之号"],"one":"利用量子力学原理的科技，墨子号、九章是中国代表成果。","ans":"量子科技是**利用量子叠加、纠缠等量子力学原理发展的前沿科技**，主要包括量子通信、量子计算和量子精密测量。我国由**中国科学技术大学潘建伟团队**领衔取得多项成果：**2016年8月发射世界首颗量子科学实验卫星“墨子号”**，实现千公里级星地量子通信；**2020年光量子计算原型机“九章”**问世，随后有超导量子计算原型机“祖冲之号”。量子通信因原理保障，被认为难以被窃听。**2025年为联合国“国际量子科学与技术年”**。","pts":["量子叠加、纠缠；通信、计算、测量","2016年墨子号，2020年九章，祖冲之号","潘建伟团队；2025年国际量子年"],"mem":"三个名字都有典故：墨子号（墨子做小孔成像实验，光学先驱）、九章（《九章算术》，数学）、祖冲之号（圆周率）。口诀“墨通信、九章算、祖冲之超导”。","mix":"墨子号是卫星，九章是光量子计算机，祖冲之号是超导量子计算机；“天问”是火星探测，“北斗”是导航，别混。","mcq":[{"q":"世界首颗量子科学实验卫星的名字是","o":["悟空号","墨子号","慧眼号","实践十号"],"a":1,"w":"2016年8月发射“墨子号”。"},{"q":"光量子计算原型机“九章”发布于","o":["2016年","2018年","2023年","2020年"],"a":3,"w":"2020年，由中国科大潘建伟团队研制。"}],"rel":[{"t":"墨家（墨子）","n":"“墨子号”命名来源"},{"t":"《九章算术》","n":"“九章”命名来源"},{"t":"中国航天三大里程碑","n":"卫星技术背景"},{"t":"算力","n":"量子计算的潜在方向"}],"more":"2025年被联合国大会宣布为“国际量子科学与技术年”，纪念量子力学诞生100周年。","exam":[]},{"id":"a13-100","t":"数字经济","cid":"13e","p":2,"kind":"概念","alias":["Digital Economy"],"one":"以数据资源为关键要素、以现代信息网络为载体的新型经济形态。","ans":"数字经济是继农业、工业经济后的新型经济形态，指**以数据资源为关键要素、以现代信息网络为载体、以信息通信技术融合应用为动力**的经济形态。**2016年二十国集团杭州峰会**通过**《二十国集团数字经济发展与合作倡议》**，首将其列为核心议题。它含**数字产业化与产业数字化**两部分，正成为重组要素资源、培育新质生产力的关键力量。","pts":["以数据为关键要素、信息网络为载体的经济形态","2016年G20杭州峰会通过数字经济合作倡议","包含数字产业化与产业数字化两大核心部分"],"mem":"“两化”拆解：**数字产业化**=把数字技术做成产业（造芯片、写AI）；**产业数字化**=用数字技术改造老产业（智能工厂、电商农业）。锚定年份：**2016年G20杭州峰会**（2026年满10周年）。","mix":"注意区分**数字经济**（侧重经济形态与产业产出）和**数字中国**（涵盖经济、政务、文化、社会、生态“五位一体”的国家整体布局）；也勿混淆“数字产业化”与“产业数字化”。","mcq":[{"q":"2016年首次将“数字经济”列为核心议题并通过《二十国集团数字经济发展与合作倡议》的国际会议是","o":["二十国集团杭州峰会","北京APEC峰会","上海合作组织青岛峰会","博鳌亚洲论坛年会"],"a":0,"w":"2016年G20杭州峰会通过《二十国集团数字经济发展与合作倡议》，成为全球数字经济治理里程碑。"}],"rel":[{"t":"数据要素","n":"数字经济的关键生产要素"},{"t":"数字中国","n":"数字经济所属的国家大布局"},{"t":"二十国集团杭州峰会","n":"2016年通过数字经济倡议"},{"t":"数字人民币","n":"数字经济的法定支付底座"}],"more":"2026年周年：2016年G20杭州峰会《二十国集团数字经济发展与合作倡议》通过10周年。","exam":[]},{"id":"a13-101","t":"“东数西算”工程","cid":"13e","p":2,"kind":"制度","alias":["东数西算","全国一体化算力网"],"one":"2022年2月全面启动的算力调度工程，设8个国家枢纽与10个数据中心集群。","ans":"“东数西算”是**我国构建全国一体化算力网的重大战略工程**，“数”指数据、“算”指算力，即**将东部算力需求有序引导到能源充裕的西部**。**2022年2月**工程全面启动，布局京津冀、长三角、粤港澳大湾区、成渝、内蒙古、贵州、甘肃、宁夏**8个国家算力枢纽节点**，规划**10个国家数据中心集群**。该工程兼顾绿色低碳与东西协同，助力数字中国建设。","pts":["2022年2月全面启动，将东部算力需求引向西部","布局8个国家算力枢纽节点、10个数据中心集群","发挥西部绿电优势，促东西协同与绿色算力"],"mem":"数字口诀**“22年启动，8枢纽10集群”**。8枢纽分东西两组各4个：**东四圈**（京津冀、长三角、大湾区、成渝）+**西四省区**（内蒙、贵州、甘肃、宁夏）。类比**“数字时代的西电东送”**。","mix":"并不是把东部所有计算都搬去西部：对实时性要求极高的高频交易、自动驾驶等留在东部枢纽（“热数据”）；后台加工、离线分析、大模型训练等引导到西部（“温冷数据”）。","mcq":[{"q":"2022年2月我国全面启动的“东数西算”工程，在全国布局建设的国家算力枢纽节点和规划的国家数据中心集群数量分别是","o":["4个枢纽节点、8个集群","6个枢纽节点、12个集群","8个枢纽节点、10个集群","10个枢纽节点、8个集群"],"a":2,"w":"“东数西算”工程启动建设8个国家算力枢纽节点，并规划了10个国家数据中心集群。"}],"rel":[{"t":"算力","n":"工程统筹配置的核心资源"},{"t":"云计算","n":"一体化算力网的服务形态"},{"t":"大数据","n":"“东数”对应的数据资源"},{"t":"数字中国","n":"夯实数字基础设施的重要工程"}],"more":"8个国家算力枢纽节点：京津冀、长三角、粤港澳大湾区、成渝、内蒙古、贵州、甘肃、宁夏。","exam":[]},{"id":"a13-102","t":"中国航天三大里程碑","cid":"13f","p":2,"kind":"合称","alias":["航天三大里程碑"],"one":"人造地球卫星、载人航天、深空探测，构成中国航天跨越发展的三座丰碑。","ans":"中国航天三大里程碑指1956年创建以来中国航天的三大标志性跨越：**人造地球卫星、载人航天与深空探测**。**1970年“东方红一号”**发射成功，开启太空时代；**2003年“神舟五号”**送杨利伟升空，使中国成世界第三个独立掌握载人航天技术的国家；**2007年“嫦娥一号”**绕月飞行，迈出深空探测第一步，奠定了航天强国建设基石。","pts":["三大里程碑：人造地球卫星、载人航天、深空探测","代表：东方红一号、神舟五号、嫦娥一号","标志中国航天由近地轨道迈向载人空间站与深空"],"members":[["人造地球卫星","1970年4月24日“东方红一号”发射成功，4月24日定为“中国航天日”"],["载人航天","2003年10月15日“神舟五号”载杨利伟首飞，后建成天宫空间站"],["深空探测","2007年10月24日“嫦娥一号”绕月起步，延伸至探月、探火与小行星探测"]],"mem":"空间由近及远记三步：**先放星**（1970东方红一号，地球轨道）→**再送人**（2003神舟五号，载人飞天）→**向深空**（2007嫦娥一号，去月球和火星）。首字口诀：**“星、人、深”**。","mix":"注意区分“中国航天三大里程碑”（人造卫星、载人航天、深空探测）与“中国载人航天工程三步走”（载人飞船→空间实验室→空间站）以及探月工程“绕、落、回”三步走。","mcq":[{"q":"下列哪一项不属于通常所称的“中国航天三大里程碑”","o":["人造地球卫星","载人航天","深空探测","高超音速风洞"],"a":3,"w":"中国航天三大里程碑指人造地球卫星、载人航天和深空探测。"}],"rel":[{"t":"东方红一号与中国航天日","n":"第一大里程碑代表"},{"t":"神舟五号与杨利伟","n":"第二大里程碑代表"},{"t":"嫦娥工程","n":"开启第三大里程碑深空探测"},{"t":"天问一号与祝融号","n":"深空探测延伸至火星"},{"t":"中国航天事业创建","n":"1956年创建，迎70周年"}],"more":"2026年周年：1956年10月8日国防部第五研究院成立，2026年为中国航天事业创建70周年。","exam":[]},{"id":"a13-103","t":"东方红一号与中国航天日","cid":"13f","p":1,"kind":"事件","alias":["东方红一号","东方红一号卫星","中国航天日"],"one":"1970年4月24日发射的中国第一颗人造卫星；4月24日为中国航天日。","ans":"东方红一号是**中国第一颗人造地球卫星**，**1970年4月24日由长征一号运载火箭在酒泉发射成功**，使中国成为**世界上第五个独立研制并发射人造卫星的国家**，前四个依次是苏联、美国、法国、日本。卫星在轨播放《东方红》乐曲，全球可以收听。它是“两弹一星”中“一星”的标志，体现了**自力更生**的航天起步。**2016年起，国家将每年4月24日定为“中国航天日”**，以纪念东方红一号发射成功并弘扬航天精神。","pts":["1970年4月24日发射，第一颗人造卫星","第五个独立发射卫星的国家","2016年起4月24日为中国航天日"],"mem":"数字梗：“一九七〇年四月二十四，第五个”。国家顺序按发射先后“苏美法日中”，口诀“苏美法日中，东方红”。航天日就是发射日，日期一致不必另记。","mix":"“第一颗卫星”是东方红一号（1970），“第一颗载人飞船”是神舟五号（2003），“第一颗月球探测器”是嫦娥一号（2007），别按“首次”错配年份。","mcq":[{"q":"我国第一颗人造地球卫星发射于","o":["1970年","1964年","1966年","1975年"],"a":0,"w":"1970年4月24日，东方红一号。"},{"q":"东方红一号发射成功后，中国成为世界上第几个独立发射人造卫星的国家","o":["第三个","第四个","第六个","第五个"],"a":3,"w":"依次是苏联、美国、法国、日本、中国。"}],"rel":[{"t":"两弹一星精神","n":"“一星”的标志"},{"t":"中国航天三大里程碑","n":"第一座里程碑"},{"t":"中国航天事业创建","n":"航天事业起步"},{"t":"钱学森","n":"航天事业奠基人"}],"more":"2016年起设立“中国航天日”，日期为4月24日。","exam":[]},{"id":"a13-104","t":"神舟五号与杨利伟","cid":"13f","p":1,"kind":"事件","alias":["神舟五号","杨利伟","首次载人航天"],"one":"2003年10月15日发射，杨利伟成为中国首位航天员。","ans":"神舟五号是**中国首次载人航天飞行任务**，**2003年10月15日由长征二号F运载火箭在酒泉发射**，航天员**杨利伟**成为**中国首位进入太空的航天员**，飞船绕地球14圈后于次日在内蒙古主着陆场安全返回。这次飞行使中国成为**继苏联（俄罗斯）、美国之后第三个独立掌握载人航天技术的国家**，是中国航天继人造卫星之后的第二个里程碑。此后神舟六号实现多人多天飞行，神舟七号实现航天员出舱，工程逐步走向空间站时代。","pts":["2003年10月15日发射","杨利伟，中国首位航天员","第三个独立掌握载人航天技术的国家"],"mem":"数字记：神“五”对应2003年10月“15”日，“五”和“十五”都有五。国家顺序“苏美中”，对应载人航天“前三名”。杨利伟=“第一人”，神舟六号2005年费俊龙、聂海胜，神舟七号2008年翟志刚出舱。","mix":"首位出舱的航天员是翟志刚（神舟七号，2008），首位女航天员是刘洋（神舟九号，2012），别与杨利伟混；神舟五号是首次载人，神舟一号至四号为无人飞行。","mcq":[{"q":"我国首位进入太空的航天员是","o":["翟志刚","杨利伟","聂海胜","刘洋"],"a":1,"w":"2003年神舟五号，杨利伟。"},{"q":"神舟五号发射后，中国成为世界上第几个独立掌握载人航天技术的国家","o":["第三个","第二个","第四个","第五个"],"a":0,"w":"前两个是苏联和美国。"}],"rel":[{"t":"中国航天三大里程碑","n":"第二座里程碑"},{"t":"天宫空间站","n":"载人航天工程第三步"},{"t":"东方红一号与中国航天日","n":"第一座里程碑"},{"t":"嫦娥工程","n":"第三座里程碑"}],"more":"神舟六号（2005）费俊龙、聂海胜；神舟七号（2008）翟志刚出舱；神舟九号（2012）刘洋成为首位女航天员。","exam":[]},{"id":"a13-105","t":"天宫空间站","cid":"13f","p":1,"kind":"事件","alias":["天宫空间站","中国空间站","天和核心舱","问天实验舱","梦天实验舱"],"one":"2022年底全面建成的中国空间站，T字构型，三舱组成。","ans":"天宫空间站是**中国自主建造的载人空间站**，**2022年底全面建成**，由**天和核心舱、问天实验舱、梦天实验舱**组成**T字构型**。它是**载人航天工程“三步走”的第三步**，前两步是发射载人飞船、建立空间实验室。航天员乘神舟飞船往返，货物由天舟货运飞船补给，可开展空间科学实验和技术试验。中国空间站建成使中国成为**少数拥有自主空间站的国家**，并向联合国会员国开放合作，是载人航天事业的重要成就。","pts":["天和、问天、梦天三舱，T字构型","2022年底全面建成","载人航天三步走第三步"],"mem":"三个舱名连起来：“天（核心）、问（实验）、梦（实验）”，合起来是“天问梦”，T字：一个核心舱当竖，两个实验舱当横。三步走口诀“船、室、站”：飞船、实验室、空间站。","mix":"“天宫”是空间站，“天问”是火星探测，“嫦娥”是探月，别混；国际空间站由美、俄等国合建，中国空间站是自主建设。","mcq":[{"q":"下列不属于中国空间站舱段的是","o":["天和核心舱","问天实验舱","梦天实验舱","天问实验舱"],"a":3,"w":"三舱是天和、问天、梦天；“天问”是火星探测任务。"},{"q":"载人航天工程“三步走”的第三步是","o":["发射载人飞船","建立空间实验室","载人登月","建造空间站"],"a":3,"w":"第一步载人飞船，第二步空间实验室，第三步空间站。"}],"rel":[{"t":"神舟五号与杨利伟","n":"载人航天第一步"},{"t":"中国航天三大里程碑","n":"载人航天里程碑"},{"t":"载人登月计划","n":"后续目标"},{"t":"天问一号与祝融号","n":"同属深空与近地任务"}],"more":"天和核心舱2021年4月发射，问天实验舱2022年7月、梦天实验舱2022年10月发射。","exam":[]},{"id":"a13-106","t":"嫦娥工程","cid":"13f","p":1,"kind":"事件","alias":["嫦娥工程","探月工程","嫦娥四号","嫦娥五号","嫦娥六号","月背采样"],"one":"中国探月工程，“绕、落、回”三步，嫦娥六号首次月背采样返回。","ans":"嫦娥工程是**中国月球探测工程**，分**“绕、落、回”三步**：绕月、落月、采样返回。**嫦娥一号2007年**实现绕月探测；**嫦娥四号2019年1月实现人类首次月球背面软着陆**；**嫦娥五号2020年带回月壤1731克**，实现中国首次地外天体采样返回；**嫦娥六号2024年6月实现人类首次月球背面采样返回，带回1935.3克样品**。嫦娥七号任务目标为月球南极。探月工程提升了中国深空探测能力，也使月球科研成果向国际共享。","pts":["绕、落、回三步","嫦娥四号2019首次月背软着陆","嫦娥五号1731克；嫦娥六号1935.3克月背样品"],"mem":"三步口诀“绕、落、回”对应一号二号（绕）、三号四号（落）、五号六号（回），两个号一组。数字：五号1731克，六号1935.3克，“一七三一”“一九三五”，六号比五号多约200克。","mix":"嫦娥四号是“首次月背软着陆”，嫦娥六号是“首次月背采样返回”，题干中“着陆”与“采样返回”别混；嫦娥五号采样来自月球正面。","mcq":[{"q":"人类首次实现月球背面软着陆的探测器是","o":["嫦娥四号","嫦娥三号","嫦娥五号","嫦娥六号"],"a":0,"w":"嫦娥四号2019年1月着陆月背。"},{"q":"嫦娥六号2024年带回的月背样品质量为","o":["1731克","1935.3克","2000克","1000克"],"a":1,"w":"嫦娥六号带回1935.3克；1731克是嫦娥五号。"}],"rel":[{"t":"天问一号与祝融号","n":"深空探测接续"},{"t":"中国航天三大里程碑","n":"第三座里程碑"},{"t":"载人登月计划","n":"后续载人阶段"},{"t":"中国航天事业创建","n":"航天事业脉络"}],"more":"嫦娥三号2013年携“玉兔”号月球车落月；嫦娥五号采样来自月球正面，是中国首次地外天体采样返回。","exam":[]},{"id":"a13-107","t":"天问一号与祝融号","cid":"13f","p":2,"kind":"事件","alias":["天问一号","祝融号","天问二号"],"one":"我国首次火星探测任务，一次实现绕着巡，祝融号2021年着陆乌托邦平原。","ans":"**天问一号**是我国**首次自主火星探测任务**，名称取自屈原长诗《天问》，于**2020年7月23日**发射。**2021年5月**探测器着陆火星**乌托邦平原**，**“祝融号”火星车**驶上火面巡视，在世界航天史上首次通过**一次任务实现“绕、着、巡”**。它标志中国深空探测迈向行星际；**2025年5月天问二号发射**，接续小行星取样返回与彗星探测。","pts":["2020年7月发射，我国首次自主火星探测任务","2021年5月着陆乌托邦平原，一次实现绕、着、巡","2025年5月天问二号发射，探测小行星与主带彗星"],"mem":"文化意象联想法：屈原《天问》问苍天→**天问一号**去探火；火神**祝融**掌管火→**祝融号**跑火星；着陆地在**乌托邦平原**（想象理想家园）。接力记：**天问一探火星，天问二探小行星**。","mix":"易混工程命名：**嫦娥/玉兔**对应月球，**天问/祝融**对应火星，**羲和/夸父**对应太阳，**北斗**对应导航，**天宫**对应空间站。","mcq":[{"q":"2021年5月，我国首次火星探测任务“天问一号”携带“祝融号”火星车成功着陆于火星的","o":["乌托邦平原","静海平原","冯·卡门撞击坑","吕姆克山脉"],"a":0,"w":"天问一号着陆于火星乌托邦平原南部；冯·卡门撞击坑是嫦娥四号月球背面着陆点。"}],"rel":[{"t":"屈原《九歌》《九章》《天问》","n":"任务名称的文化出处"},{"t":"中国航天三大里程碑","n":"深空探测的重大突破"},{"t":"嫦娥工程","n":"探月“绕落回”与探火呼应"},{"t":"天宫空间站","n":"同期推进的国家航天重器"}],"more":"最新进展：2025年5月29日天问二号在西昌发射，于2026年7月初与近地小行星2016 HO3交会伴飞，后续执行采样返回及主带彗星311P探测任务。","exam":[]},{"id":"a13-108","t":"载人登月计划","cid":"13f","p":3,"kind":"概念","alias":["中国载人月球探测工程"],"one":"中国计划2030年前实现首次载人登月，核心装备为长征十号、梦舟与揽月。","ans":"中国载人登月计划目标在**2030年前实现中国人首次登月**，系载人航天迈向深空的新跨越。工程以**长征十号火箭、“梦舟”飞船、“揽月”着陆器**为主体，配**“望宇”登月服与“探索”月球车**，2025至2026年多项关键试验顺利推进。","pts":["目标：2030年前实现中国人首次登月","三大飞行器：长征十号、梦舟飞船、揽月着陆器","2025年命名“望宇”登月服与“探索”月球车"],"mem":"诗意命名串成画面：坐“长征十号”火箭，乘“梦舟”飞船飞向月球，换乘“揽月”着陆器降落，穿“望宇”登月服、开“探索”月球车巡月。","mix":"易与无人探月混淆：“嫦娥”系列是无人探月工程，“梦舟”“揽月”是载人登月飞行器；空间站舱外服叫“飞天”，登月服叫“望宇”。","mcq":[{"q":"在中国载人登月任务核心装备命名中，负责将航天员送往月面并起飞返回的月面着陆器名为","o":["揽月","梦舟","望宇","嫦娥"],"a":0,"w":"载人登月核心装备中，“梦舟”是载人飞船，“揽月”是月面着陆器，“望宇”是登月服。"}],"rel":[{"t":"嫦娥工程","n":"无人探月为载人登月奠定基础"},{"t":"中国航天三大里程碑","n":"载人航天与深空探测的延伸"},{"t":"天宫空间站","n":"中国载人航天前序重大工程"},{"t":"新型举国体制","n":"航天重大工程的组织优势"}],"more":"2025年2月公布“望宇”登月服、“探索”载人月球车命名；2025至2026年推进长征十号系留点火与低空演示验证、梦舟逃逸试验、揽月着陆起飞试验。","exam":[]},{"id":"a13-109","t":"北斗卫星导航系统","cid":"13f","p":1,"kind":"制度","alias":["北斗","北斗系统","北斗三号","北斗卫星导航系统"],"one":"中国自主建设的全球卫星导航系统，2020年7月北斗三号开通。","ans":"北斗卫星导航系统是**中国自主建设、独立运行的全球卫星导航系统**，按“三步走”推进：**2000年北斗一号**建成，**2012年北斗二号**覆盖亚太，**2020年7月31日北斗三号全球系统正式开通**。系统提供定位、导航、授时服务，并具有**短报文通信**特色，广泛用于交通、农业、救灾等。北斗与**美国GPS、俄罗斯格洛纳斯、欧盟伽利略**并称**全球四大卫星导航系统**，使中国摆脱对外国导航系统的依赖，增强了国家安全和产业自主性。","pts":["北斗三号2020年7月31日开通","一二三号三步走","全球四大导航系统；短报文特色"],"mem":"四大系统“美俄欧中”：GPS（美）、格洛纳斯（俄）、伽利略（欧）、北斗（中），可记成“GGGB”。三步走年份“00、12、20”：一号2000，二号2012，三号2020。","mix":"北斗一号、二号是区域系统，北斗三号才是全球系统；北斗七星是天上的星座，卫星系统以其命名；别把“伽利略”当作美国。","mcq":[{"q":"下列不属于全球四大卫星导航系统的是","o":["美国GPS","俄罗斯格洛纳斯","欧盟伽利略","日本准天顶"],"a":3,"w":"四大系统为GPS、格洛纳斯、伽利略、北斗；准天顶是日本区域系统。"},{"q":"北斗三号全球卫星导航系统正式开通的时间是","o":["2020年7月","2012年12月","2018年12月","2022年12月"],"a":0,"w":"2020年7月31日宣布开通。"}],"rel":[{"t":"中国航天三大里程碑","n":"航天成就群"},{"t":"北斗七星","n":"系统命名来源"},{"t":"“两弹一星”功勋科学家","n":"自力更生传统"},{"t":"中国天眼（FAST）","n":"同属重大科技成就"}],"more":"北斗三号开通仪式2020年7月31日举行。","exam":[]},{"id":"a13-110","t":"中国天眼（FAST）","cid":"13f","p":2,"kind":"事件","alias":["中国天眼","FAST","500米口径球面射电望远镜"],"one":"位于贵州平塘的500米口径射电望远镜，2016年落成，世界最大单口径。","ans":"中国天眼（**FAST**）全称**500米口径球面射电望远镜**，坐落于**贵州省平塘县**喀斯特洼坑，由首席科学家**南仁东**主导建成。它于**2016年9月25日落成启用**，2020年通过国家验收、2021年正式向全球开放，是**世界最大、最灵敏的单口径射电望远镜**。至2026年落成十周年，已累计发现新脉冲星超1300颗，引领世界射电天文观测。","pts":["贵州平塘500米口径球面射电望远镜，南仁东主导","2016年9月落成，世界最大单口径射电望远镜","2026年满十周年，发现新脉冲星已超1300颗"],"mem":"英文缩写拆字记：**F**ive-hundred-meter（500米）**A**perture（口径）**S**pherical（球面）radio **T**elescope（射电望远镜）。记住三元素：**贵州平塘大锅、南仁东、2016落成十周年**。","mix":"FAST接收的是宇宙**无线电波（射电信号）**，不是可见光光学望远镜；它是世界最大**单口径**射电望远镜（区别于由多台天线组成的阵列式望远镜）。","mcq":[{"q":"被誉为“中国天眼”的500米口径球面射电望远镜（FAST）位于我国哪个省份，其首席科学家兼总工程师是谁","o":["云南省、潘建伟","贵州省、南仁东","青海省、孙家栋","四川省、程开甲"],"a":1,"w":"FAST坐落于贵州省平塘县，由“人民科学家”南仁东主持设计与建设。"}],"rel":[{"t":"新型举国体制","n":"大科学装置建成的制度支撑"},{"t":"天问一号与祝融号","n":"同期国家深空与天文重器"},{"t":"国家勋章和国家荣誉称号","n":"南仁东获“人民科学家”称号"}],"more":"2026年周年：2016年9月25日FAST落成启用10周年。\n南仁东（1945–2017），2019年被追授“人民科学家”国家荣誉称号。","exam":[]},{"id":"a13-111","t":"蛟龙号与奋斗者号","cid":"13f","p":2,"kind":"事件","alias":["蛟龙号","奋斗者号","全海深载人潜水器"],"one":"中国载人深潜两大重器：蛟龙号潜7062米，奋斗者号坐底10909米。","ans":"**蛟龙号**与**奋斗者号**是我国自主研制的标志性**载人潜水器**，代表中国从深海进入迈向全海深科考的跨越。**2012年6月**，蛟龙号在马里亚纳海沟下潜**7062米**；**2020年11月**，万米级**奋斗者号**在马里亚纳海沟成功坐底**10909米**，刷新中国载人深潜纪录。两大重器使我国具备了覆盖全球海洋全深度的载人科考能力。","pts":["我国自主研制的两代标志性载人潜水器","蛟龙号2012年下潜7062米，突破大深度作业","奋斗者号2020年马里亚纳海沟坐底10909米"],"mem":"深潜三步阶梯口诀：**“蛟龙7000（2012）→深海勇士4500（国产化）→奋斗者10909（2020万米坐底）”**。记数字巧法：**10909**像对称回文“一零九零九”。","mix":"易混深海装备：**蛟龙号、深海勇士号、奋斗者号**是**载人**潜水器；“海斗一号”是**无人**潜水器；“雪龙号”“雪龙2号”是极地科考破冰船。","mcq":[{"q":"2020年11月在马里亚纳海沟成功坐底、创下10909米中国载人深潜纪录的全海深载人潜水器是","o":["蛟龙号","深海勇士号","奋斗者号","海斗一号"],"a":2,"w":"奋斗者号2020年11月10日坐底10909米；蛟龙号2012年创7062米纪录。"}],"rel":[{"t":"交大海洋智能装备","n":"同属中国海洋装备重器"},{"t":"世界海洋之最","n":"马里亚纳海沟为世界最深海沟"},{"t":"中国天眼（FAST）","n":"“上天入海”重大科技成就对照"},{"t":"联合国海洋法公约的海域划分","n":"深海科考与国际海底区域法理"}],"more":"关键时间：2012年6月27日蛟龙号达7062米；2020年11月10日奋斗者号在马里亚纳海沟“挑战者深渊”坐底10909米。","exam":[]},{"id":"a13-112","t":"“两弹一星”功勋科学家","cid":"13f","p":2,"kind":"合称","alias":["两弹一星功勋奖章获得者","两弹一星元勋"],"one":"1999年国家表彰的23位科技专家，为原子弹、氢弹、导弹与卫星研制奠基。","ans":"“两弹一星”功勋科学家指**1999年9月**国家隆重表彰并授予“两弹一星功勋奖章”的**23位科技专家**（含7位追授者），代表人物有**钱学森、邓稼先、钱三强、于敏、郭永怀、王淦昌、孙家栋**等。他们攻克了**1964年原子弹、1967年氢弹与1970年“东方红一号”卫星**等重大难关，奠定了新中国国防科技基石，铸就“两弹一星”精神。","pts":["1999年9月表彰23位科技专家（含7位追授）","代表人物：钱学森、邓稼先、钱三强、于敏、郭永怀等","1964原子弹、1967氢弹、1970东方红一号"],"members":[["于敏","核物理学家，氢弹理论主要贡献者，获共和国勋章"],["王大珩","应用光学奠基人，“863计划”倡议人之一"],["王希季","返回式卫星与空间技术专家"],["王淦昌","核物理学家，原子弹与氢弹研制领导者（追授）"],["邓稼先","“两弹元勋”，主持原子弹与氢弹理论设计（追授）"],["朱光亚","核物理学家，核武器研制主要组织领导者"],["任新民","液体火箭发动机与航天技术奠基人之一"],["孙家栋","“东方红一号”技术总负责人，获共和国勋章"],["吴自良","材料冶金学家，铀浓缩分离膜攻关主持者"],["陈芳允","无线电电子学家，卫星测控与“863计划”倡议人"],["陈能宽","金属物理与爆轰物理学家，核武器引爆攻关者"],["杨嘉墀","自动控制专家，“863计划”倡议人之一"],["周光召","理论物理学家，核武器理论设计重要贡献者"],["赵九章","地球与空间物理学家，人造卫星事业倡议者（追授）"],["姚桐斌","航天材料与工艺专家（追授）"],["钱骥","空间技术专家，“东方红一号”总体设计主要负责人（追授）"],["钱三强","核物理学家，中国原子能科学事业奠基人（追授）"],["钱学森","“中国航天之父”“中国导弹之父”"],["郭永怀","力学家，核弹、导弹与卫星三领域均有贡献并殉职（追授）"],["屠守锷","火箭总体设计专家"],["黄纬禄","固体潜地战略导弹总设计师"],["程开甲","核武器试验技术开拓者"],["彭桓武","理论物理学家，原子弹与氢弹理论奠基人之一"]],"mem":"年份与人数口诀：**“64原、67氢、70星，99年奖23人”**。代表人物记“三钱两核一氢”：**钱学森、钱三强、钱骥**，**邓稼先、王淦昌**，**于敏（氢弹）**，加**郭永怀、孙家栋**。","mix":"“两弹一星”最初指原子弹、导弹和人造卫星，后来演变为核弹（原子弹、氢弹）、导弹和人造卫星；**袁隆平、屠呦呦、李四光、华罗庚**均不在23位“两弹一星”功勋科学家之列。","mcq":[{"q":"1999年国家表彰了23位“两弹一星”功勋科学家，下列科学家中不在该名单之列的是","o":["钱学森","邓稼先","郭永怀","袁隆平"],"a":3,"w":"袁隆平是杂交水稻专家，不属于“两弹一星”功勋奖章获得者。"}],"rel":[{"t":"两弹一星精神","n":"23位元勋铸就的精神财富"},{"t":"邓稼先","n":"23位功勋科学家代表"},{"t":"钱学森","n":"23位功勋科学家代表"},{"t":"东方红一号与中国航天日","n":"“一星”的历史突破"}],"more":"关键日期：1964年10月16日第一颗原子弹爆炸；1967年6月17日第一颗氢弹爆炸；1970年4月24日“东方红一号”发射；1999年9月18日表彰23位元勋。","exam":[]},{"id":"a13-113","t":"邓稼先","cid":"13f","p":2,"kind":"人物","alias":["两弹元勋","娃娃博士"],"one":"著名核物理学家、“两弹元勋”，主持中国原子弹与氢弹理论设计。","ans":"邓稼先（1924–1986），安徽怀宁人，**中国著名核物理学家**，被誉为**“两弹元勋”**。他1950年留美获博士学位后毅然回国，1958年起隐姓埋名28年投身核武器事业，**主持了中国第一颗原子弹和第一颗氢弹的理论设计**，多次亲赴试验一线。1999年被追授**“两弹一星功勋奖章”**，其以身许国、无私奉献的品格影响深远。","pts":["核物理学家，被誉为“两弹元勋”","1950年留美归国，隐姓埋名28年攻关核武器","主持原子弹、氢弹理论设计，1999年追授功勋奖章"],"mem":"人物三标签：**“娃娃博士”**（26岁获博士回国）+**“隐姓埋名28年”**（1958–1986）+**“两弹元勋”**（原子弹+氢弹理论设计）。杨振宁写《邓稼先》一文纪念这位挚友。","mix":"易混称谓：**邓稼先**称“两弹元勋”（主持原子弹、氢弹理论设计）；**钱学森**称“中国航天之父”“中国导弹之父”；**钱三强**称“中国原子能科学之父”；**于敏**被称“中国氢弹之父”。","mcq":[{"q":"隐姓埋名28年、主持我国第一颗原子弹和第一颗氢弹理论设计、被誉为“两弹元勋”的核物理学家是","o":["邓稼先","钱学森","孙家栋","南仁东"],"a":0,"w":"邓稼先主持中国原子弹与氢弹理论设计，被誉为“两弹元勋”。"}],"rel":[{"t":"“两弹一星”功勋科学家","n":"1999年获追授功勋奖章"},{"t":"钱学森","n":"同为“两弹一星”领军人物"},{"t":"两弹一星精神","n":"其一生践行的精神典范"}],"more":"关键年份：1924年生于安徽怀宁；1950年回国；1958年受命研制核武器；1986年逝世；1999年追授“两弹一星功勋奖章”。","exam":[]},{"id":"a13-115","t":"袁隆平与杂交水稻","cid":"13f","p":2,"kind":"人物","alias":["袁隆平","杂交水稻之父"],"one":"“杂交水稻之父”，2000年度首届国家最高科学技术奖与共和国勋章得主。","ans":"袁隆平（1930–2021），**中国工程院院士、杂交水稻开创者**，被誉为**“杂交水稻之父”**。他打破水稻无杂交优势定论，**1973年实现三系法籼型杂交水稻配套**，后持续推进两系法与超级稻研究，大幅提升亩产。他于**2000年度与吴文俊同获首届国家最高科学技术奖**，**2019年获共和国勋章**，为中国与世界粮食安全作出历史性贡献。","pts":["“杂交水稻之父”，1973年实现三系法配套","2000年度与吴文俊获首届国家最高科学技术奖","2019年获共和国勋章，惠及中国与世界粮食安全"],"mem":"三组高频考点串联：**身份**“杂交水稻之父”→**两个梦想**“禾下乘凉梦、杂交水稻覆盖全球梦”→**两项顶奖**“2000首届最高科技奖（与吴文俊）+2019共和国勋章”。","mix":"选择题常考**首届（2000年度）国家最高科学技术奖**两位得主：**袁隆平**（农学）与**吴文俊**（数学），2001年2月正式颁奖；切勿把屠呦呦（2015诺奖、2016年度最高科技奖）混为首届。","mcq":[{"q":"2000年度与数学家吴文俊共同荣获我国首届“国家最高科学技术奖”的科学家是","o":["屠呦呦","于敏","袁隆平","王选"],"a":2,"w":"袁隆平与吴文俊同获2000年度首届国家最高科学技术奖。"}],"rel":[{"t":"吴文俊","n":"同获首届国家最高科学技术奖"},{"t":"国家最高科学技术奖","n":"2000年度首届得主之一"},{"t":"屠呦呦与青蒿素","n":"同获共和国勋章的民生科学家"},{"t":"国家勋章和国家荣誉称号","n":"2019年获颁共和国勋章"}],"more":"关键荣誉：2000年度首届国家最高科学技术奖（2001年2月颁奖）；2004年世界粮食奖；2019年“共和国勋章”。","exam":[]},{"id":"a13-116","t":"人工合成牛胰岛素","cid":"13f","p":3,"kind":"事件","alias":["人工全合成结晶牛胰岛素"],"one":"1965年9月中国科学家在世界上首次人工合成具有生物活性的蛋白质。","ans":"人工合成牛胰岛素是**1965年9月17日**中国取得的生命科学里程碑。由**中科院上海生化所、有机化学所与北京大学**协同攻关，在**世界上首次人工合成具有生物活性的蛋白质结晶牛胰岛素**，开创了人类人工合成蛋白质的新纪元。","pts":["1965年9月17日中国科学家攻关成功","世界首次人工合成具生物活性的蛋白质","中科院上海生化所、有机所与北大协作"],"mem":"时间与地标记：“1965年，上海+北大，世界首次造出活蛋白（结晶牛胰岛素）”，和1964年原子弹仅差一年，同属新中国60年代硬核突破。","mix":"注意严谨表述：它是世界上首次人工全合成“具有生物活性的蛋白质”，而非首次合成简单有机物（1828年维勒人工合成尿素）。","mcq":[{"q":"1965年9月，中国科学家在世界上首次人工全合成具有生物活性的蛋白质是","o":["青蒿素","结晶牛胰岛素","血红蛋白","重组干扰素"],"a":1,"w":"1965年9月17日中国科学家在世界上首次人工合成具有生物活性的结晶牛胰岛素。"}],"rel":[{"t":"屠呦呦与青蒿素","n":"同为新中国重大生物医药成就"},{"t":"袁隆平与杂交水稻","n":"同为当代中国世界级生命科学成果"},{"t":"AlphaFold","n":"蛋白质合成与AI预测跨代对照"},{"t":"“两弹一星”功勋科学家","n":"同为60年代大协作科技丰碑"}],"exam":[]},{"id":"a13-117","t":"《新一代人工智能发展规划》","cid":"13g","p":2,"kind":"制度","alias":["新一代AI发展规划"],"one":"2017年7月国务院印发，确立2020、2025、2030年AI“三步走”目标。","ans":"《新一代人工智能发展规划》由**国务院于2017年7月印发**，是我国首个面向2030年的**国家级AI顶层战略规划**。规划提出**“三步走”战略目标**：**2020年**总体技术与应用与世界先进水平同步，**2025年**基础理论实现重大突破，**2030年**总体达世界领先、使中国成为**世界主要人工智能创新中心**，为我国AI产业发展与治理体系奠定长远布局。","pts":["2017年7月国务院印发，首个国家级AI顶层规划","2020同步、2025突破、2030主要创新中心","统筹技术创新、产业赋能与AI伦理法规建设"],"mem":"三步走关键词压缩成六个字：**2020同步→2025突破→2030领先（创新中心）**。核心产业规模目标对应记：**1500亿→4000亿→1万亿**。","mix":"《新一代人工智能发展规划》是2017年确立长期目标的**顶层战略规划**；2024年起写入政府工作报告的**“人工智能+”行动**则是大模型时代推进AI深度赋能千行百业的专项行动。","mcq":[{"q":"2017年7月国务院印发的《新一代人工智能发展规划》提出“三步走”目标，其2030年的远景目标是使中国成为","o":["世界主要人工智能创新中心","全球唯一的算力供应中心","人工智能技术与世界先进水平同步的国家","首个禁止通用人工智能的国家"],"a":0,"w":"规划明确2020年同步、2025年重大突破、2030年成为世界主要人工智能创新中心。"}],"rel":[{"t":"“人工智能+”行动","n":"大模型时代接续推进的行动"},{"t":"人工智能治理","n":"规划已前瞻部署AI伦理法规"},{"t":"《生成式人工智能服务管理暂行办法》","n":"规划中法规建设的落地成果"},{"t":"数字中国","n":"同年提出的国家级数字布局"}],"more":"关键日期：2017年7月国务院印发并公开发布（国发〔2017〕35号）。","exam":[]},{"id":"a13-118","t":"《全球人工智能治理倡议》","cid":"13g","p":2,"kind":"制度","alias":["全球AI治理倡议"],"one":"2023年10月第三届“一带一路”高峰论坛中方提出，倡导以人为本、智能向善。","ans":"《全球人工智能治理倡议》是**2023年10月18日**中方在**第三届“一带一路”国际合作高峰论坛**上提出的国际治理方案。倡议围绕**发展、安全、治理**三维度提出11项主张，倡导**“以人为本、智能向善”**，反对意识形态划线与技术壁垒，支持在**联合国框架下讨论成立国际AI治理机构**，为弥合全球“智能鸿沟”贡献了中国方案。","pts":["2023年10月第三届“一带一路”高峰论坛中方提出","核心理念：以人为本、智能向善，统筹发展安全治理","反对技术壁垒，支持联合国框架下全球AI治理"],"mem":"三词定锚：**2023一带一路论坛** + **以人为本、智能向善** + **发展、安全、治理三维度**。记住它反“小院高墙”、挺“联合国框架”与“全球南方”。","mix":"注意区分三份重要文件：**2023年10月《全球人工智能治理倡议》**（中方在“一带一路”高峰论坛提出）；**2024年7月《人工智能全球治理上海宣言》**（世界人工智能大会发布）；**2024年欧盟《人工智能法》**（欧盟立法）。","mcq":[{"q":"2023年10月，中方在哪一重要国际会议上正式提出《全球人工智能治理倡议》","o":["二十国集团杭州峰会","世界互联网大会乌镇峰会","第三届“一带一路”国际合作高峰论坛","上海合作组织天津峰会"],"a":2,"w":"2023年10月18日，中方在第三届“一带一路”国际合作高峰论坛开幕式上提出该倡议。"}],"rel":[{"t":"一带一路","n":"第三届高峰论坛上正式提出"},{"t":"《人工智能全球治理上海宣言》","n":"2024年上海大会接续发布宣言"},{"t":"全球四大倡议","n":"人类命运共同体理念的AI延伸"},{"t":"欧盟《人工智能法》","n":"全球AI治理不同路径对照"}],"more":"核心维度：发展（平等互利、反对壁垒）、安全（分类分级、人类可控）、治理（联合国框架、增强发展中国家代表性）。","exam":[]},{"id":"a13-119","t":"欧盟《人工智能法》","cid":"13g","p":2,"kind":"制度","alias":["欧盟AI法案","EU AI Act"],"one":"2024年8月1日生效，全球首部全面监管人工智能的法律，按风险四级分类。","ans":"欧盟《人工智能法》于**2024年通过**、**2024年8月1日正式生效**，是**全球首部全面监管人工智能的综合性法律**。该法实行**基于风险的四级分类监管**，划分为不可接受风险（禁止）、高风险、有限透明度风险与极低风险，并对**通用人工智能模型**单设义务。法案自2025年起分阶段落地禁令、通用模型及透明度等规则，高风险AI合规期经2026年修订延至2027年底，深刻塑造了全球AI立法范式。","pts":["2024年通过、8月1日生效，全球首部全面AI法律","按风险分四级监管，单设通用人工智能模型规范","2025年起分阶段落地禁令、通用模型及透明度规则"],"mem":"“一首四级”口诀：**全球首部**全面AI法，风险**四级**由重到轻：**禁（不可接受）→严（高风险）→告（有限透明）→放（极低风险）**。记住生效日：**2024年8月1日**。","mix":"易混对比：欧盟《人工智能法》重**统一立法与四级风险分类**；中国采取**敏捷治理与专项规章先行**（如深度合成规定、生成式AI暂行办法、内容标识办法），兼顾创新与安全。","mcq":[{"q":"2024年8月1日正式生效、以风险等级对人工智能系统实行四级分类监管的全球首部全面AI法律是","o":["美国《人工智能权利法案》","欧盟《人工智能法》","联合国《全球数字契约》","英国《在线安全法》"],"a":1,"w":"欧盟《人工智能法》于2024年8月1日生效，开创了基于风险等级的全面AI立法模式。"}],"rel":[{"t":"欧盟","n":"法案制定与施行的区域主体"},{"t":"人工智能治理","n":"国际AI监管代表性范式"},{"t":"《生成式人工智能服务管理暂行办法》","n":"中欧AI监管路径对照"},{"t":"《全球人工智能治理倡议》","n":"全球AI治理的多元方案"}],"more":"关键时间表：2024年8月1日生效；2025年2月2日禁用不可接受风险AI；2025年8月2日通用AI（GPAI）规则适用；2026年8月2日透明度义务落地；独立高风险AI规则经2026年7月欧盟数字综合法案（(EU) 2026/1744）推迟至2027年12月2日适用。违规最高可罚3500万欧元或全球年营业额7%。","exam":[]},{"id":"a13-120","t":"深度合成与深度伪造","cid":"13g","p":2,"kind":"概念","alias":["深度合成","深度伪造","Deepfake"],"one":"借深度学习生成编辑音视频文本的技术及其滥用，我国2023年1月施行专门规定。","ans":"**深度合成**指利用**深度学习等算法**生成或编辑文本、图像与音视频的中性技术，可用于影视与数字人。**深度伪造（Deepfake）**则特指滥用该技术进行**AI换脸、拟声诈骗与编造虚假信息**的违法侵权行为。我国国家网信办等三部门发布的**《互联网信息服务深度合成管理规定》**于**2023年1月10日施行**，与2025年标识办法共筑内容防伪防线。","pts":["深度合成是中性生成编辑技术，深度伪造指恶意滥用","常见风险包括AI换脸、拟声诈骗与虚假新闻","《深度合成管理规定》2023年1月10日起施行"],"mem":"二词辨析：**深度合成=菜刀（中性技术，能拍电影做数字人）**；**深度伪造（Deepfake）=拿刀伤人（换脸诈骗、造假新闻）**。记住英文合成词：**Deep**（深度学习）+**fake**（伪造）。","mix":"“深度合成”覆盖合法合规的AI内容生成与编辑，本身并不违法；“深度伪造”才带有欺骗和恶意滥用含义，是网络治理与《标识办法》重点打击的对象。","mcq":[{"q":"国家网信办、工信部、公安部联合发布、旨在防范AI换脸与拟声诈骗等风险的《互联网信息服务深度合成管理规定》自何时起施行","o":["2021年11月1日","2023年8月15日","2025年9月1日","2023年1月10日"],"a":3,"w":"《互联网信息服务深度合成管理规定》自2023年1月10日起正式施行。"}],"rel":[{"t":"《人工智能生成合成内容标识办法》","n":"2025年强化防伪溯源新规"},{"t":"《生成式人工智能服务管理暂行办法》","n":"同年施行的生成式AI规章"},{"t":"网络生态治理","n":"防范虚假信息与AI诈骗场景"},{"t":"《个人信息保护法》","n":"人脸声纹等生物信息法律保护"}],"more":"规定颁布：国家网信办、工信部、公安部令第12号，2023年1月10日施行，早于2023年8月施行的《生成式人工智能服务管理暂行办法》。","exam":[]},{"id":"a13-121","t":"信息茧房","cid":"13g","p":1,"kind":"概念","alias":["信息茧房","茧房效应"],"one":"桑斯坦提出：人只关注自己感兴趣的信息，被禁锢在封闭空间。","ans":"信息茧房是**美国学者凯斯·桑斯坦在《信息乌托邦》（2006）中提出的概念**，指人们在信息传播中只关注自己选择的、使自己愉悦的领域，久而久之**像蚕一样被禁锢在自己编织的“茧房”之中**。在算法推荐普遍应用的平台环境下，系统按用户兴趣推送内容，易使人视野窄化、观点极化。它常与**回音室效应、过滤气泡**并提，是网络生态治理的重要议题。应对办法包括**优化算法推荐、保障用户选择权、提升媒介素养和主动拓宽信息来源**。","pts":["桑斯坦《信息乌托邦》提出","只看自己感兴趣的信息，被禁锢","算法推荐加剧；治理靠算法优化与媒介素养"],"mem":"画面：蚕吐丝把自己裹进茧里，丝就是你点过的内容，越点越窄。桑斯坦=“桑”（蚕吃桑叶）+“茧”，借谐音把“桑斯坦”和“茧房”连起来。","mix":"回音室效应指相似观点在封闭圈子里反复回响强化；过滤气泡由帕里泽提出，强调算法过滤；三者近义，选择题注意提出者和关键词。","mcq":[{"q":"“信息茧房”概念的提出者是","o":["桑斯坦","麦克卢汉","约瑟夫·奈","波兹曼"],"a":0,"w":"桑斯坦在《信息乌托邦》中提出。"},{"q":"下列做法中，有助于缓解信息茧房的是","o":["只关注固定的几个账号","完全依赖算法推送","主动拓宽信息来源","屏蔽所有不同观点"],"a":2,"w":"主动拓宽信息来源，并提升媒介素养。"}],"rel":[{"t":"回音室效应","n":"近义概念"},{"t":"算法治理","n":"治理手段"},{"t":"网络生态治理","n":"所属议题"},{"t":"数字鸿沟","n":"数字时代另一问题"}],"more":"桑斯坦2001年《网络共和国》已讨论“回音室”类问题。","exam":[]},{"id":"a13-122","t":"回音室效应","cid":"13g","p":3,"kind":"概念","alias":["回声室效应"],"one":"封闭网络环境中相近意见不断重复强化，使人误以为这就是全部事实。","ans":"回音室效应是**传播学与网络生态**概念，指在相对封闭的信息环境中，**相近观点不断重复强化**、排斥异见的现象。它由社群同质化与**算法推荐**共同加剧，使受众产生误判。该效应易导致**群体极化与舆论撕裂**，是网络生态治理重点对象。","pts":["封闭环境中相近意见不断重复强化","受社群同质化与算法推荐推动","易引发群体极化与社会舆论撕裂"],"mem":"画面联想：走进四周封闭的回音谷喊话，听到的全是自己声音的回响，久而久之便以为全世界都同意自己。","mix":"信息茧房强调个人因兴趣与算法被束缚在狭窄信息里；回音室效应强调同质群体内部观点互相放大。","mcq":[{"q":"在封闭网络社群中，相近观点反复强化并排斥异见的现象称为","o":["回音室效应","破窗效应","马太效应","鲶鱼效应"],"a":0,"w":"回音室效应指相近意见在封闭空间内不断回响放大，易导致群体极化。"}],"rel":[{"t":"信息茧房","n":"同簇相近传播概念"},{"t":"算法治理","n":"打破算法闭环的治理手段"},{"t":"后真相","n":"同簇情绪极化舆论现象"}],"exam":[]},{"id":"a13-123","t":"数字鸿沟","cid":"13g","p":2,"kind":"概念","alias":["信息鸿沟","Digital Divide"],"one":"不同群体、地区在信息技术获取和使用能力上的差距。","ans":"数字鸿沟又称**信息鸿沟**，指不同国家、地区及群体在**信息技术接入机会与使用能力上的差距**。它涵盖**接入沟、使用沟与知识沟**三个层次，既体现在发达国家与发展中国家及城乡之间，也突出表现在老年人、残障人士面对智能终端时的困难。缩小数字鸿沟是推进数字中国建设和**适老化改造**的关键议题，直接关系社会公平与公共服务均等化。","pts":["不同地区与群体在信息接入和使用上的差距","分接入沟、使用沟、知识沟三层次","老年人数字鸿沟是适老化改造重点"],"mem":"三阶梯记法：先看有没有网（接入沟），再看会不会用（使用沟），最后看能不能借此获益（知识沟）。日常画面：老人扫不了码、挂不上号，就是身边的数字鸿沟。","mix":"信息茧房指算法推荐让人只看同质内容，是“用得太深”带来的窄化；数字鸿沟是“接不上、用不好”带来的排斥，一宽一窄，切勿混淆。","mcq":[{"q":"下列做法中，直接针对老年人“数字鸿沟”问题的是","o":["加强平台算法备案管理","推进互联网应用适老化改造","限制跨境数据自由流动","开展网络暴力信息专项治理"],"a":1,"w":"适老化改造通过大字版、简化流程等方式降低老年人使用门槛，直接弥合数字鸿沟。"}],"rel":[{"t":"适老化","n":"弥合老年群体数字鸿沟"},{"t":"银发经济","n":"老年数字消费新场景"},{"t":"信息茧房","n":"同属数字社会治理概念"},{"t":"数字中国","n":"数字包容的宏观框架"}],"exam":[]},{"id":"a13-124","t":"网络暴力治理","cid":"13g","p":2,"kind":"制度","alias":["《网络暴力信息治理规定》","网暴治理"],"one":"以2024年8月施行的《网络暴力信息治理规定》为核心的网暴防控机制。","ans":"网络暴力治理是国家针对网络侮辱谩骂、造谣诽谤、**“人肉搜索”**等行为建立的法治防控机制。**2024年8月1日**，国家网信办、公安部、文旅部、广电总局四部门联合发布的**《网络暴力信息治理规定》**正式施行。该规定要求平台建立**预警预防、一键防护、溯源关闭**与优先保护未成年人等制度，推动网络暴力治理迈入**专门立法与全链条监管**阶段。","pts":["针对侮辱谩骂、造谣诽谤与人肉搜索等","《网络暴力信息治理规定》2024年8月1日施行","四部门联合发布，压实平台预警与防护责任"],"mem":"时间与部门口诀：“24八一四部门，一键防护治网暴”。2024年8月1日施行，网信、公安、文旅、广电四部门齐上阵，把“防、护、查、罚”做成闭环。","mix":"《未成年人网络保护条例》2024年1月1日施行，《网络暴力信息治理规定》2024年8月1日施行，二者同年落地但侧重不同；后者是专门针对网暴信息的部门规章。","mcq":[{"q":"由国家网信办等四部门联合发布的《网络暴力信息治理规定》开始施行的时间是","o":["2023年8月15日","2024年1月1日","2024年8月1日","2025年9月1日"],"a":2,"w":"《网络暴力信息治理规定》自2024年8月1日起施行；2023年8月15日为生成式AI暂行办法施行日。"}],"rel":[{"t":"网络生态治理","n":"上位治理框架"},{"t":"《未成年人网络保护条例》","n":"同年施行的网络保护法规"},{"t":"《网络安全法》","n":"网络治理的基础法律"},{"t":"算法治理","n":"同属平台内容治理环节"}],"exam":[]},{"id":"a13-125","t":"网络强国","cid":"13g","p":2,"kind":"概念","alias":["网络强国战略"],"one":"2014年提出的国家战略，强调“没有网络安全就没有国家安全”。","ans":"网络强国是新时代中国网信事业的**顶层国家战略**，由习近平于**2014年2月中央网络安全和信息化领导小组第一次会议**正式提出。会议确立**“没有网络安全就没有国家安全，没有信息化就没有现代化”**的核心论断，统筹信息基建、核心技术自主创新与网络空间治理。该战略引领中国从**网络大国迈向网络强国**，为数字中国建设提供根本指引。","pts":["2014年2月中央网信领导小组首次会议提出","核心论断：无网络安全则无国家安全","推动中国从网络大国迈向网络强国"],"mem":"因果逻辑线：中国网民多、体量大已是“网络大国”，要升级为“网络强国”，必须两手抓，一手“安全”（网络安全），一手“发展”（信息化），记住2014年2月这个起点。","mix":"网络强国2014年提出，侧重网信安全与信息化统筹；数字中国2015年第二届世界互联网大会提出，侧重数字技术全面赋能经济社会；二者常配套出现。","mcq":[{"q":"“没有网络安全就没有国家安全，没有信息化就没有现代化”及建设网络强国战略正式提出于","o":["2014年2月中央网络安全和信息化领导小组第一次会议","2015年第二届世界互联网大会","2017年党的十九大报告","2021年《数据安全法》颁布大会"],"a":0,"w":"2014年2月27日中央网络安全和信息化领导小组第一次会议正式提出建设网络强国。"}],"rel":[{"t":"数字中国","n":"协同推进的国家战略"},{"t":"总体国家安全观","n":"同年提出，含网络安全"},{"t":"《网络安全法》","n":"网络强国的法律基石"},{"t":"网络生态治理","n":"网络强国的内容治理维度"}],"exam":[]},{"id":"a13-126","t":"《未成年人网络保护条例》","cid":"13g","p":3,"kind":"制度","alias":["未成年人网络保护条例"],"one":"2024年1月1日施行，我国第一部专门性的未成年人网络保护综合立法。","ans":"《未成年人网络保护条例》是国务院行政法规，**2024年1月1日**施行，为我国**首部专门性未成年人网络保护综合立法**。条例涵盖**网络素养促进、信息规范、个人信息保护与防沉迷**四大块，为未成年人清朗上网提供坚实法治保障。","pts":["2024年1月1日起正式施行","我国首部专门性未成年人网络保护综合立法","涵盖素养、内容、隐私与防沉迷四大块"],"mem":"时间锚点：2023年10月出台、2024年元旦生效；记住“首部专门综合立法”与“素养、内容、隐私、防沉迷”四支柱。","mix":"《未成年人保护法》2020年修订增设“网络保护”专章，本条例则是国务院出台的首部专门行政法规。","mcq":[{"q":"我国第一部专门性的未成年人网络保护综合立法《未成年人网络保护条例》施行于","o":["2021年6月1日","2022年3月1日","2023年10月16日","2024年1月1日"],"a":3,"w":"该条例于2023年10月公布，2024年1月1日起正式施行。"}],"rel":[{"t":"《网络安全法》","n":"我国网络治理基础法律"},{"t":"《个人信息保护法》","n":"同属网络权益保护立法"},{"t":"网络生态治理","n":"清朗网络空间治理目标"}],"exam":[]},{"id":"a13-127","t":"后真相","cid":"13g","p":3,"kind":"概念","alias":["后真相时代"],"one":"《牛津词典》2016年度词汇，指情感与信念比客观事实更能影响舆论。","ans":"后真相（Post-truth）是当代**政治传播与网络舆论**概念，当选**《牛津词典》2016年度词汇**。它指塑造舆论时，**情感与个人信念比客观事实更具影响力**。该词随英国脱欧公投和美国大选走红，凸显社交媒体时代**情绪先于事实**的传播困境。","pts":["《牛津词典》2016年度词汇","情感与信念比客观事实更能左右舆论","反映社交媒体时代情绪极化与事实弱化"],"mem":"2016年两大黑天鹅事件（英国脱欧公投+美国大选）把“后真相”送上《牛津词典》年度词，核心即“立场压倒事实”。","mix":"后真相不同于纯粹假新闻，它侧重受众在明知客观事实的情况下仍更受情感与立场所左右。","mcq":[{"q":"当选《牛津词典》2016年度词汇、指情感信念比客观事实更能影响舆论的词是","o":["后真相","信息茧房","深度伪造","数字鸿沟"],"a":0,"w":"Post-truth（后真相）为《牛津词典》2016年度词汇。"}],"rel":[{"t":"回音室效应","n":"同簇情绪共振机制"},{"t":"深度合成与深度伪造","n":"技术放大事实失真风险"},{"t":"欧元与英国脱欧","n":"2016年推动该词走红的事件"}],"exam":[]},{"id":"a13-128","t":"和平共处五项原则","cid":"13h","p":1,"kind":"合称","alias":["和平共处五项原则","五项原则"],"one":"1953至1954年周恩来提出的五条处理国际关系的基本准则。","ans":"和平共处五项原则是**中国处理国际关系的基本准则**，**1953年12月周恩来接见印度政府代表团时首次完整提出**，**1954年写入中印、中缅联合声明**。内容为**互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处**。1955年万隆会议上周恩来倡导“求同存异”，原则精神被亚非国家广泛接受，并在此基础上形成万隆会议十项原则。它**超越社会制度与意识形态差异**，成为新中国外交的基石，也是国际法基本原则的重要来源，2014年举行了提出60周年纪念活动。","pts":["1953年12月周恩来提出，1954年写入联合声明","互尊主权、互不侵犯、互不干涉、平等互利、和平共处","万隆会议接受，新中国外交基石"],"members":[["互相尊重主权和领土完整","国家平等与领土不可侵犯"],["互不侵犯","不使用武力或武力威胁"],["互不干涉内政","尊重各国自主选择道路"],["平等互利","经贸关系平等，利益兼顾"],["和平共处","制度不同国家和平相处"]],"mem":"口诀“尊侵干利和”：尊（互相尊重主权和领土完整）、侵（互不侵犯）、干（互不干涉内政）、利（平等互利）、和（和平共处）。年份“五三年提出，五四年写进声明，五五年万隆发扬”。","mix":"五项原则的最后一项是“和平共处”，不是“和平发展”；它是1953至1954年的事，万隆会议“求同存异”是1955年，不是同一次。","mcq":[{"q":"和平共处五项原则首次被完整提出是在周恩来接见哪国代表团时","o":["印度","缅甸","印度尼西亚","巴基斯坦"],"a":0,"w":"1953年12月接见印度政府代表团，1954年写入中印、中缅联合声明。"},{"q":"下列不属于和平共处五项原则的是","o":["互不干涉内政","平等互利","互不侵犯","互相结盟"],"a":3,"w":"五项为尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。"}],"rel":[{"t":"万隆会议","n":"原则被发扬"},{"t":"不结盟运动","n":"同期亚非外交潮流"},{"t":"三个世界划分","n":"新中国外交理论"},{"t":"人类命运共同体","n":"当代外交理念"}],"more":"2014年为和平共处五项原则提出60周年；2024年为提出70周年。","exam":[]},{"id":"a13-129","t":"万隆会议","cid":"13h","p":2,"kind":"事件","alias":["亚非会议","万隆精神"],"one":"1955年印尼万隆召开的亚非会议，周恩来提出“求同存异”方针。","ans":"万隆会议又称**亚非会议**，于**1955年4月在印度尼西亚万隆**举行，29个亚非国家和地区出席，是**首次没有西方殖民国家参加**的亚非国际会议。面对分歧，中国代表团团长**周恩来提出“求同存异”方针**，推动亚非国家团结反殖。会议通过**处理国际关系的十项原则**，形成团结、友谊、合作的万隆精神，提升新中国国际威望并催生不结盟运动。","pts":["1955年4月印尼万隆，29个亚非国家参加","周恩来提出“求同存异”方针化解分歧","通过十项原则，推动亚非团结与不结盟运动"],"mem":"画面记忆：29个亚非新独立国家坐一起起争执，周恩来站起来表示中国代表团是来求团结的，抛出四字金句“求同存异”，全场鼓掌定下十项原则。","mix":"和平共处五项原则是1953至1954年中印、中缅谈判提出，万隆会议十项原则是在五项原则基础上的引申与发展，二者时间和场合不可互换。","mcq":[{"q":"1955年万隆会议上，周恩来为推动会议达成共识提出的重要方针是","o":["求同存异","一边倒","另起炉灶","搁置争议、共同开发"],"a":0,"w":"周恩来在1955年万隆会议上提出“求同存异”方针，促成亚非会议圆满成功。"}],"rel":[{"t":"和平共处五项原则","n":"十项原则的理论源头"},{"t":"不结盟运动","n":"承接万隆精神兴起"},{"t":"全球南方","n":"发展中国家团结的延续"},{"t":"三个世界划分","n":"同属第三世界外交脉络"}],"exam":[]},{"id":"a13-130","t":"新型国际关系","cid":"13h","p":2,"kind":"概念","alias":["推动建设新型国际关系"],"one":"以相互尊重、公平正义、合作共赢为内涵的中国特色大国外交理念。","ans":"新型国际关系是新时代中国特色大国外交的核心理念之一。2013年习近平在莫斯科首次提出建立**以合作共赢为核心**的新型国际关系，**2017年党的十九大**将其完整概括为**“相互尊重、公平正义、合作共赢”**。其中相互尊重是前提、公平正义是原则、合作共赢是核心，它摒弃冷战思维和零和博弈，为推动构建**人类命运共同体**奠定了基本路径。","pts":["2013年首提，2017年十九大完整定型","核心内涵：相互尊重、公平正义、合作共赢","摒弃零和博弈，服务人类命运共同体"],"mem":"三词递进法：先平等相待（相互尊重），再按规矩办事（公平正义），最后一起把蛋糕做大（合作共赢）。口诀：“尊、公、赢”。","mix":"注意区分“新型国际关系”（相互尊重、公平正义、合作共赢）与中美“相互尊重、和平共处、合作共赢”三原则，中间四字一为“公平正义”，一为“和平共处”。","mcq":[{"q":"党的十九大报告将中国推动建设的新型国际关系的内涵概括为","o":["相互尊重、和平共处、合作共赢","互信、互利、平等、协商","相互尊重、公平正义、合作共赢","亲诚惠容、真实亲诚"],"a":2,"w":"党的十九大正式概括为“相互尊重、公平正义、合作共赢”；A项是中美相处三原则，B项是“上海精神”。"}],"rel":[{"t":"人类命运共同体","n":"外交总目标与核心理念"},{"t":"和平共处五项原则","n":"新中国外交的历史传承"},{"t":"单边主义与多边主义","n":"新型国际关系坚持多边"},{"t":"中美建设性战略稳定关系","n":"大国相处的新实践"}],"exam":[]},{"id":"a13-131","t":"三个世界划分","cid":"13h","p":3,"kind":"概念","alias":["三个世界","三个世界理论"],"one":"1974年毛泽东提出，将美苏、日欧、亚非拉分别划为第一、二、三世界。","ans":"三个世界划分是**1974年2月毛泽东**会见赞比亚总统时提出的国际战略，属**新中国外交理论**经典。**美苏**为第一世界，**日欧发达国家**为第二世界，**亚非拉发展中国家**为第三世界，中国属第三世界。同年4月邓小平在联大阐明此说，拓展外交新局。","pts":["1974年毛泽东提出，邓小平在联大阐述","美苏第一、日欧第二、亚非拉第三世界","明确中国属于第三世界，团结反霸"],"mem":"按实力梯队记“123”：1是美苏两霸，2是日欧中间派，3是亚非拉广大发展中国家（中国在内），1974年提出。","mix":"西方冷战语境的“三个世界”常指美西方、苏联阵营和不结盟国家；毛泽东的划分则以霸权与经济地位区分，将美苏同列第一世界。","mcq":[{"q":"1974年毛泽东提出“三个世界”划分战略中，日本和欧洲发达国家属于","o":["第一世界","第二世界","第三世界","独立阵营"],"a":1,"w":"美苏为第一世界，日本、欧洲、加拿大等发达国家为第二世界，亚非拉发展中国家为第三世界。"}],"rel":[{"t":"万隆会议","n":"团结亚非国家的早期实践"},{"t":"全球南方","n":"当代发展中国家群体新表述"},{"t":"和平共处五项原则","n":"新中国外交基本准则"},{"t":"冷战","n":"提出该战略的国际格局背景"}],"exam":[]},{"id":"a13-133","t":"联合国六大主要机关","cid":"13h","p":1,"kind":"合称","alias":["联合国六大机关","联合国主要机关"],"one":"大会、安理会、经社理事会、托管理事会、国际法院、秘书处。","ans":"联合国是**1945年10月成立的普遍性政府间国际组织**，总部设在**纽约**，其《宪章》规定设立**六大主要机关**：**大会**是主要审议机关，每国一票；**安全理事会**负责维护国际和平与安全；**经济及社会理事会**协调经济社会事务；**托管理事会**监督托管领土，1994年起暂停运作；**国际法院**是主要司法机关，设在荷兰海牙；**秘书处**由秘书长领导，处理日常行政事务。六大机关中国际法院是**唯一不在纽约**的机关。","pts":["大会、安理会、经社理事会、托管理事会、国际法院、秘书处","国际法院在海牙，其余在纽约","托管理事会1994年暂停运作"],"members":[["大会","主要审议机关，一国一票"],["安全理事会","维护国际和平与安全，五常有否决权"],["经济及社会理事会","协调经济社会事务"],["托管理事会","监督托管领土，1994年暂停"],["国际法院","主要司法机关，设在海牙"],["秘书处","秘书长领导，行政事务"]],"mem":"口诀“大安经托法秘”：大会、安理会、经社会、托管会、法院、秘书处。海牙是例外：六个里五个在纽约，只有法院去了荷兰，记“法在海牙”。","mix":"联合国教科文组织、世界卫生组织是专门机构，不属于六大主要机关；国际刑事法院是独立机构，设在海牙，也不属于联合国主要机关。","mcq":[{"q":"下列机构中，属于联合国六大主要机关之一的是","o":["世界卫生组织","国际刑事法院","国际货币基金组织","托管理事会"],"a":3,"w":"托管理事会是六大机关之一，其余为专门机构或独立机构。"},{"q":"联合国六大机关中，唯一不设在纽约的是","o":["秘书处","国际法院","安全理事会","大会"],"a":1,"w":"国际法院设在荷兰海牙。"}],"rel":[{"t":"联合国","n":"所属组织"},{"t":"联合国安理会与五个常任理事国","n":"最重要机关之一"},{"t":"联合国教科文组织","n":"专门机构，非主要机关"},{"t":"《联合国家宣言》","n":"联合国名称来源"}],"more":"联合国1945年10月24日正式成立，总部在纽约。","exam":[]},{"id":"a13-134","t":"联合国安理会与五个常任理事国","cid":"13h","p":1,"kind":"合称","alias":["联合国安理会","安理会","安全理事会","常任理事国","五常","否决权"],"one":"15个理事国，中法俄英美为常任理事国，享有否决权。","ans":"联合国安全理事会是**联合国负责维护国际和平与安全的主要机关**，共有**15个理事国**：**5个常任理事国（中国、法国、俄罗斯、英国、美国）和10个任期两年的非常任理事国**。实质性问题的决议须**9票赞成，且常任理事国均不投反对票**，即五大国拥有**一票否决权**。安理会决议对会员国具有约束力，可授权制裁、派遣维和部队。中国1945年是联合国创始会员国，**1971年联大通过第2758号决议，恢复在联合国的合法席位**，并取得安理会常任理事国席位。","pts":["15国：5常任加10非常任","实质性决议需9票且五常不否决","1971年中国恢复席位"],"members":[["中国","1971年恢复合法席位"],["法国","常任理事国"],["俄罗斯","继承苏联席位"],["英国","常任理事国"],["美国","常任理事国"]],"mem":"常任理事国顺序“中法俄英美”（按中文名通行排序）。数字“5+10=15，9票通过”。画面：五位常任理事手里各有一张“否决牌”，一张亮出就通不过。","mix":"非常任理事国任期两年，不得连选连任，每年改选五个；常任理事国不是“永久成员”，是“常任”；五常的否决权不适用于程序性事项。","mcq":[{"q":"安理会实质性问题的决议通过，至少需要几票赞成且常任理事国不否决","o":["7票","8票","10票","9票"],"a":3,"w":"15国中需9票赞成，五常不投否决票。"},{"q":"下列国家中，不是联合国安理会常任理事国的是","o":["德国","法国","英国","俄罗斯"],"a":0,"w":"五常为中、法、俄、英、美。"}],"rel":[{"t":"联合国第2758号决议","n":"恢复中国席位"},{"t":"联合国六大主要机关","n":"所属机关体系"},{"t":"联合国","n":"所属组织"},{"t":"联合国维和行动","n":"安理会授权的行动"},{"t":"雅尔塔体系","n":"战后国际秩序"}],"more":"1971年10月25日联大通过第2758号决议。","exam":[]},{"id":"a13-136","t":"联合国中文日","cid":"13h","p":2,"kind":"常识","alias":["UN Chinese Language Day"],"one":"2010年联合国设立的语言日，定于每年4月20日前后谷雨节气纪念仓颉。","ans":"联合国中文日是联合国为推动**六种正式语言**（中、英、法、俄、西、阿）平等使用和文化多样性而设立的纪念日，**2010年**由联合国新闻部正式启动。中文日选定在农历二十四节气之**“谷雨”**（公历**4月20日前后**），以纪念相传造字时“天雨粟、鬼夜哭”的**“中华文字始祖”仓颉**。该纪念日是向国际社会展示汉字魅力与中华文化的重要窗口。","pts":["2010年联合国启动，推动六种正式语言平等","定在农历谷雨（4月20日前后）","纪念中华文字始祖仓颉造字"],"mem":"传说画面：《淮南子》记载“昔者仓颉作书，而天雨粟”，谷雨就是“老天下谷子雨”，所以4月20日谷雨天然绑定仓颉与联合国中文日。","mix":"联合国六种正式语言各自有语言日：英文日与西文日均为4月23日（莎士比亚与塞万提斯逝世纪念日），俄文日6月6日（普希金诞辰），法文日3月20日，阿文日12月18日，别与中文日混记。","mcq":[{"q":"联合国中文日定于每年公历4月20日前后的“谷雨”节气，主要是为了纪念","o":["许慎编纂《说文解字》","王懿荣发现甲骨文","李斯推行“书同文”","“中华文字始祖”仓颉"],"a":3,"w":"相传仓颉造字感天动地，“天雨粟”，故联合国中文日定在谷雨以纪念仓颉。"}],"rel":[{"t":"联合国语言日","n":"六种正式语言纪念日总称"},{"t":"联合国六种正式语言","n":"中文为六大正式语言之一"},{"t":"二十四节气","n":"选定春季最后节气谷雨"},{"t":"甲骨文","n":"汉字早期成熟形态"}],"exam":[]},{"id":"a13-137","t":"联合国教科文组织","cid":"13h","p":1,"kind":"制度","alias":["教科文组织","联合国教科文组织","UNESCO","教科文"],"one":"联合国专门机构，总部巴黎，主管世界遗产与非遗名录。","ans":"联合国教科文组织是**联合国负责教育、科学和文化事务的专门机构**，**1945年11月通过《组织法》，1946年正式成立，总部设在巴黎**，宗旨是通过教育、科学和文化合作促进和平。它主管**《世界遗产名录》和人类非物质文化遗产代表作名录**，通过1972年《保护世界文化和自然遗产公约》和2003年《保护非物质文化遗产公约》开展工作，并设有“世界记忆名录”。中国是创始会员国之一，**故宫、长城、秦始皇陵兵马俑等被列入世界遗产**。","pts":["联合国专门机构，总部巴黎","1945年《组织法》，1946年成立","主管世界遗产、非遗、世界记忆名录"],"mem":"UNESCO三个字母对应三个领域：教育（Educational）、科学（Scientific）、文化（Cultural）。一句话“巴黎的遗产管家”：世界遗产、非遗、世界记忆都归它管。","mix":"世界遗产委员会、世界记忆名录都隶属教科文组织；世界卫生组织（日内瓦）、世界贸易组织（日内瓦）总部不在巴黎。","mcq":[{"q":"联合国教科文组织总部所在城市是","o":["日内瓦","纽约","巴黎","罗马"],"a":2,"w":"总部设在法国巴黎。"},{"q":"下列名录中，由联合国教科文组织主管的是","o":["《世界遗产名录》","《财富》世界500强","诺贝尔奖名单","《福布斯》富豪榜"],"a":0,"w":"教科文组织主管世界遗产名录、非遗名录和世界记忆名录。"}],"rel":[{"t":"世界文化遗产","n":"主管类别"},{"t":"《保护世界文化和自然遗产公约》","n":"核心公约"},{"t":"非物质文化遗产","n":"主管类别"},{"t":"世界记忆名录","n":"主管名录"}],"more":"1972年《保护世界文化和自然遗产公约》；2003年《保护非物质文化遗产公约》。","exam":[]},{"id":"a13-138","t":"世界卫生组织","cid":"13h","p":2,"kind":"制度","alias":["世卫组织","WHO"],"one":"1948年4月7日成立的联合国公共卫生专门机构，总部设在瑞士日内瓦。","ans":"世界卫生组织（简称世卫组织，WHO）是联合国系统内负责**国际公共卫生事务的专门机构**，总部设在**瑞士日内瓦**。**1948年4月7日**《世界卫生组织组织法》生效后正式成立，该日被定为**“世界卫生日”**。世卫组织最高权力机构为世界卫生大会，主要职能包括协调全球传染病防控、制定国际卫生标准和推动全民健康覆盖，是全球公共卫生治理的核心平台。","pts":["1948年4月7日成立，该日为世界卫生日","联合国专门机构，总部瑞士日内瓦","负责全球疫情协调与国际卫生标准制定"],"mem":"日内瓦“三总”挂钩：世界卫生组织（WHO）、世界贸易组织（WTO）、红十字国际委员会总部全在瑞士日内瓦。成立日4月7日=世界卫生日，记一次顶两个考点。","mix":"世卫组织是联合国“专门机构”，不属于《联合国宪章》规定的联合国六大主要机关；总部在日内瓦，别与联合国教科文组织（巴黎）、联合国总部（纽约）混淆。","mcq":[{"q":"世界卫生组织（WHO）正式成立并被定为“世界卫生日”的日期是","o":["4月7日","5月8日","10月24日","12月1日"],"a":0,"w":"1948年4月7日世卫组织正式成立，4月7日定为世界卫生日；10月24日为联合国日。"}],"rel":[{"t":"联合国","n":"隶属联合国专门机构体系"},{"t":"联合国教科文组织","n":"同为联合国专门机构"},{"t":"国际红十字运动","n":"总部同在日内瓦"},{"t":"世界贸易组织","n":"总部同在日内瓦"}],"more":"2025年1月美国宣布再次退出世卫组织，满一年退出期后于2026年1月22日正式生效。","exam":[]},{"id":"a13-139","t":"国际货币基金组织与世界银行","cid":"13h","p":2,"kind":"制度","alias":["IMF与世界银行","布雷顿森林机构"],"one":"依1944年布雷顿森林协定设立的两大国际金融机构，总部均在华盛顿。","ans":"国际货币基金组织（IMF）与世界银行（WB）是依**1944年布雷顿森林会议协定**于1945年成立的国际金融机构，总部均在**美国华盛顿**，合称**“布雷顿森林机构”**。**IMF**侧重稳定国际汇率并向国际收支失衡国提供**短期贷款**；**世界银行**则侧重向发展中国家提供**中长期发展贷款与减贫援助**，二者共同构成战后国际金融治理支柱。","pts":["1944年布雷顿森林会议决定设立，总部华盛顿","IMF管汇率稳定与短期国际收支急救","世界银行管中长期发展贷款与减贫基建"],"mem":"类比记分工：IMF像“急诊室”，哪个国家汇率崩盘、外汇见底就给短期输血救命；世界银行像“长期扶植基金”，给穷国修桥修路、中长期贷款脱贫。","mix":"选择题常考二者职能互换：切记IMF管短期收支失衡与汇率、创设特别提款权（SDR），世界银行管长期建设与减贫；且二者均与世界贸易组织（WTO）并称战后世界经济三大支柱（WTO总部在日内瓦）。","mcq":[{"q":"关于国际货币基金组织（IMF）与世界银行（WB）的职能分工，下列说法正确的是","o":["两者总部均设在瑞士日内瓦","IMF侧重短期国际收支援助，世界银行侧重中长期发展贷款","世界银行负责稳定国际汇率并发行特别提款权","两者均在1995年乌拉圭回合谈判后正式成立"],"a":1,"w":"两者总部均在华盛顿，1945年成立；IMF管短期收支与汇率、发行SDR，世界银行管中长期发展与减贫。"}],"rel":[{"t":"布雷顿森林体系","n":"两大机构的创设源头"},{"t":"世界贸易组织","n":"共为战后世界经济三支柱"},{"t":"亚洲基础设施投资银行","n":"新兴多边开发银行对照"},{"t":"货币政策","n":"IMF重点监测领域"}],"exam":[]},{"id":"a13-140","t":"世界贸易组织","cid":"13h","p":1,"kind":"制度","alias":["世界贸易组织","世贸组织","WTO"],"one":"1995年成立，总部日内瓦，前身是1947年关贸总协定。","ans":"世界贸易组织是**当今最重要的多边贸易组织**，**1995年1月1日成立，总部设在日内瓦**，前身是**1947年的关税与贸易总协定（GATT）**。它以**最惠国待遇、国民待遇、关税减让、透明度**为基本原则，设有**争端解决机制**，最高决策机构是部长级会议。成员约占世界贸易的绝大部分，**中国2001年12月11日成为第143个成员**。近年单边主义和贸易保护主义抬头，其上诉机构因成员分歧自2019年起陷入停摆。","pts":["1995年1月1日成立，总部日内瓦","前身是1947年关贸总协定","最惠国、国民待遇；争端解决；中国第143个成员"],"mem":"年份“四七总协定，九五世贸”：1947GATT，1995WTO。总部“日内瓦”与世卫组织同城，别与联合国纽约、教科文巴黎混。","mix":"WTO与国际货币基金组织、世界银行并称战后三大国际经济组织（后两者在华盛顿）；WTO不是联合国专门机构，是独立的国际组织。","mcq":[{"q":"世界贸易组织的前身是","o":["关税与贸易总协定","国际货币基金组织","世界银行","经济合作与发展组织"],"a":0,"w":"1947年的关税与贸易总协定（GATT）。"},{"q":"世界贸易组织总部设在","o":["纽约","巴黎","华盛顿","日内瓦"],"a":3,"w":"总部在瑞士日内瓦。"}],"rel":[{"t":"中国加入世贸组织","n":"中国2001年加入"},{"t":"全球化与逆全球化","n":"多边贸易体制背景"},{"t":"联合国教科文组织","n":"总部城市对照"},{"t":"区域全面经济伙伴关系协定（RCEP）","n":"区域自贸对照"}],"more":"成立于1995年1月1日，取代GATT。","exam":[]},{"id":"a13-141","t":"联合国2030年可持续发展议程","cid":"13h","p":2,"kind":"制度","alias":["2030年议程","可持续发展目标","SDGs"],"one":"2015年9月联合国通过的全球发展纲领，确立17项可持续发展目标。","ans":"联合国2030年可持续发展议程由**2015年9月联合国发展峰会**通过，接替2000年**千年发展目标（MDGs）**。议程统筹**经济、社会与环境**三大维度，提出消除贫困、优质教育、气候行动等**17项可持续发展目标（SDGs）**与169项具体目标，是指导2016至2030年全球共同发展的行动纲领，也是中国**全球发展倡议**重点对接的国际议程。","pts":["2015年9月联合国峰会通过，接替千年发展目标","确立17项可持续发展目标及169项具体目标","统筹经济、社会与环境三大发展维度"],"mem":"两代目标对比记：2000年“千年发展目标”MDGs共8项，主攻发展中国家减贫；2015年升级为“可持续发展目标”SDGs共17项，覆盖全人类，数字记“2015定2030，17大项169小项”。","mix":"2015年联合国在两个月内落地两份重磅文件：9月在纽约通过《2030年可持续发展议程》，12月在巴黎达成《巴黎协定》，前者管全面发展，后者专攻气候变化。","mcq":[{"q":"2015年9月联合国发展峰会通过的《2030年可持续发展议程》共确立了多少项可持续发展目标（SDGs）","o":["8项","10项","12项","17项"],"a":3,"w":"2030年可持续发展议程确立了17项可持续发展目标和169项具体目标；8项是2000年千年发展目标。"}],"rel":[{"t":"全球四大倡议","n":"全球发展倡议与之对接"},{"t":"《巴黎协定》","n":"同年达成的气候行动纲领"},{"t":"精准扶贫与脱贫攻坚","n":"中国提前10年实现减贫目标"},{"t":"联合国","n":"议程通过与协调平台"}],"exam":[]},{"id":"a13-142","t":"联合国维和行动","cid":"13h","p":3,"kind":"制度","alias":["联合国维和","蓝盔部队"],"one":"安理会授权的多国维和机制，中国是安理会五常第一大出兵国。","ans":"联合国维和行动是经**安理会授权**派驻冲突区维和的安全机制，人员俗称**“蓝盔部队”**。行动始于**1948年**，遵循同意、中立、非自卫不动武三原则。中国是**安理会五常第一大出兵国**和**第二大维和出资国**，为世界和平作出重要贡献。","pts":["安理会授权，俗称蓝盔部队，始于1948年","遵循同意、中立、非自卫不动武三原则","中国系五常第一大出兵国、第二大出资国"],"mem":"“蓝盔三原则+中国两排名”：同意、中立、非自卫不动武；五常出兵第一，全球出资第二（仅次于美国）。","mix":"中国是“安理会五常”中派出维和人员最多的国家，而非联合国全体会员国中总出兵人数第一（南亚非洲部分国家总兵力更多）。","mcq":[{"q":"关于中国参与联合国维和行动，下列表述正确的是","o":["中国是安理会常任理事国第一大出兵国","维和行动由联合国大会直接授权派遣","维和部队可主动进攻冲突各方","联合国维和行动始于1971年"],"a":0,"w":"维和行动由安理会授权、始于1948年、遵循非自卫不动武原则；中国是五常第一大出兵国。"}],"rel":[{"t":"联合国","n":"维和行动的主导国际组织"},{"t":"联合国安理会与五个常任理事国","n":"维和行动的授权机构"},{"t":"联合国第2758号决议","n":"中国重返联合国的历史前提"}],"exam":[]},{"id":"a13-143","t":"东南亚国家联盟","cid":"13h","p":1,"kind":"制度","alias":["东盟","东南亚国家联盟","ASEAN"],"one":"1967年在曼谷成立的东南亚区域组织，现有11个成员国。","ans":"东南亚国家联盟（东盟）是**1967年8月8日在曼谷成立的东南亚区域性政府间组织**，**创始国为印度尼西亚、马来西亚、菲律宾、新加坡和泰国**，总部设在雅加达。此后文莱、越南、老挝、缅甸、柬埔寨先后加入，**2025年10月东帝汶成为第11个成员国**。东盟奉行协商一致、互不干涉内政的“东盟方式”，是区域合作的重要平台，主导形成**东盟10+1、10+3、东亚峰会**等机制，也是**RCEP的核心**。**中国与东盟1991年开启对话进程**，现为全面战略伙伴关系。","pts":["1967年8月8日曼谷成立，创始五国","现有11个成员国，2025年东帝汶加入","中国1991年对话；RCEP核心"],"mem":"创始五国口诀“印马菲新泰”：印尼、马来西亚、菲律宾、新加坡、泰国。其后五国“文越老缅柬”，合成十国；2025年东帝汶是第十一个。成立日期“六七年八月八日，曼谷”。","mix":"东盟是东南亚国家的组织，中国、日本、韩国是“10+3”的对话伙伴，不是东盟成员；东帝汶2025年10月才加入；东盟总部在雅加达，不在曼谷。","mcq":[{"q":"下列国家中，属于东盟创始国的是","o":["越南","文莱","泰国","缅甸"],"a":2,"w":"创始五国是印尼、马来西亚、菲律宾、新加坡、泰国。"},{"q":"2025年10月成为东盟第11个成员国的是","o":["东帝汶","巴布亚新几内亚","斯里兰卡","孟加拉国"],"a":0,"w":"东帝汶2025年10月加入。"}],"rel":[{"t":"区域全面经济伙伴关系协定（RCEP）","n":"东盟为核心"},{"t":"《巴黎协定》","n":"区域气候合作背景"},{"t":"不结盟运动","n":"同类国际组织对照"},{"t":"欧盟","n":"区域一体化对照"}],"more":"中国与东盟1991年开启对话进程，2021年建立全面战略伙伴关系。","exam":[]},{"id":"a13-144","t":"区域全面经济伙伴关系协定（RCEP）","cid":"13h","p":1,"kind":"制度","alias":["RCEP","区域全面经济伙伴关系协定"],"one":"15国自贸协定，2020年签署，2022年生效，规模最大的自贸区。","ans":"区域全面经济伙伴关系协定（RCEP）是**以东盟为核心的亚太地区自由贸易协定**，**2020年11月15日签署，2022年1月1日生效**。**15个成员为东盟10国与中国、日本、韩国、澳大利亚、新西兰**，覆盖约全球三分之一的人口和经济规模，是**世界上人口最多、经贸规模最大的自贸区**。协定通过降低关税、统一原产地规则、扩大服务和投资开放，促进区域产业链供应链融合。它使中日之间首次建立自贸关系，**增强了亚太地区对多边贸易体制的信心**。印度曾参与谈判，2019年退出。","pts":["2020年11月15日签署，2022年1月1日生效","东盟10国加中日韩澳新15国","世界最大的自贸区；印度退出"],"members":[["东盟10国","印尼、马来西亚、菲律宾、新加坡、泰国、文莱、越南、老挝、缅甸、柬埔寨"],["中国","第二大经济体"],["日本","中日首次建立自贸关系"],["韩国","东亚"],["澳大利亚","大洋洲"],["新西兰","大洋洲"]],"mem":"“10+5”：东盟10国，加“中日韩”（东亚三国）和“澳新”（大洋洲两国），共15国。年份“二〇签，二二生效”。印度没来：谈判中途退出。","mix":"RCEP不含美国、印度；CPTPP、DEPA是另外的协定；2020年11月15日是签署日，2022年1月1日才是生效日。","mcq":[{"q":"下列国家中，不是RCEP成员的是","o":["日本","澳大利亚","新西兰","印度"],"a":3,"w":"印度2019年退出谈判。"},{"q":"RCEP协定正式生效的时间是","o":["2022年1月","2020年11月","2021年6月","2023年1月"],"a":0,"w":"2022年1月1日生效；2020年11月15日签署。"}],"rel":[{"t":"东南亚国家联盟","n":"协定核心"},{"t":"世界贸易组织","n":"多边贸易体制对照"},{"t":"全球化与逆全球化","n":"应对保护主义"},{"t":"上海自贸试验区与临港新片区","n":"国内对外开放平台"}],"more":"2020年11月15日签署，2022年1月1日生效。","exam":[]},{"id":"a13-145","t":"全面与进步跨太平洋伙伴关系协定（CPTPP）","cid":"13h","p":3,"kind":"制度","alias":["CPTPP"],"one":"2018年生效的高标准自贸协定，前身为TPP，英国已加入、中国已申请。","ans":"CPTPP是高标准区域自贸协定，前身为**2017年美退出的TPP**，由日、加、澳等11国于**2018年12月**生效。协定涵盖零关税、数字贸易与知识产权规则。**2024年12月英国成第12个成员国**，中国已于**2021年9月**申请加入。","pts":["前身为美国退出的TPP，2018年12月生效","2024年12月英国正式成为第12个成员国","中国于2021年9月正式申请加入"],"mem":"时间链：2017美退TPP → 2018年11国生效CPTPP → 2021中国申请 → 2024英国入群成第12员（也是首个欧洲成员）。","mix":"不要与RCEP混淆：RCEP由东盟主导、中日在内、2022年生效；CPTPP规则标准更高，目前中国在申请中、英国已正式加入。","mcq":[{"q":"2024年12月正式加入CPTPP、成为该协定首个欧洲成员国的是","o":["英国","法国","德国","瑞士"],"a":0,"w":"英国于2024年12月15日正式成为CPTPP第12个成员国，也是首个非创始成员与首个欧洲成员。"}],"rel":[{"t":"区域全面经济伙伴关系协定（RCEP）","n":"同簇亚太大型自贸协定"},{"t":"欧元与英国脱欧","n":"英国脱欧后加入CPTPP"},{"t":"世界贸易组织","n":"多边贸易体制对照"}],"more":"2026年5月，CPTPP成员就哥斯达黎加入盟完成实质性谈判。","exam":[]},{"id":"a13-146","t":"亚洲基础设施投资银行","cid":"13h","p":2,"kind":"制度","alias":["亚投行","AIIB"],"one":"中国倡议设立的首个多边金融机构，2015年成立、2016年开业，总部北京。","ans":"亚洲基础设施投资银行（简称亚投行，AIIB）是**中国倡议设立的首个多边金融机构**，总部在**北京**。**2015年12月**成立，**2016年1月**开业，首任行长金立群，2026年1月中国籍**邹加怡**接任行长。亚投行聚焦基础设施互联互通与绿色投资，成员由57个创始成员增至2026年的**111个**，成为完善全球经济治理的重要多边平台。","pts":["中国倡议设立的首个多边金融机构，总部北京","2015年12月成立、2016年1月开业","首任行长金立群，2026年邹加怡接任，111个成员"],"mem":"时间与人物双线：13倡议→15成立→16开业→26十周年换帅（金立群交棒邹加怡）。与新开发银行对比：亚投行总部北京，新开发银行（金砖银行）总部上海。","mix":"易混三家机构：亚投行（AIIB，总部北京，中国倡议，开放给全球成员）；亚洲开发银行（ADB，1966年成立，总部马尼拉，日美主导）；金砖新开发银行（NDB，总部上海）。","mcq":[{"q":"关于亚洲基础设施投资银行（AIIB），下列说法不正确的是","o":["是中国倡议设立的首个多边金融机构","于2015年12月成立、2016年1月正式开业","总部设在上海陆家嘴金融城","首任行长为金立群"],"a":2,"w":"亚投行总部设在北京；总部设在上海的是金砖国家新开发银行。"}],"rel":[{"t":"一带一路","n":"基础设施融资协同伙伴"},{"t":"金砖国家","n":"新开发银行与亚投行对照"},{"t":"国际货币基金组织与世界银行","n":"同为多边开发金融机构"},{"t":"全球南方","n":"助力发展中国家基建"}],"more":"2026年1月为亚投行开业十周年；邹加怡于2025年6月当选、2026年1月16日正式就任亚投行第二任行长，任期5年。","exam":[]},{"id":"a13-147","t":"七国集团","cid":"13h","p":2,"kind":"合称","alias":["G7","西方七国集团"],"one":"美、英、法、德、日、意、加七个西方主要发达国家的政治经济论坛。","ans":"七国集团（G7）是由**美国、英国、法国、德国、日本、意大利、加拿大**组成的**西方主要发达国家**论坛。它源于**1975年六国首脑会议**，1976年加拿大加入定名七国集团，欧盟代表列席。**1998年俄罗斯加入**后一度称八国集团（G8），2014年俄退出并恢复G7，是发达国家协调宏观经济与外交立场的主要平台。","pts":["成员：美、英、法、德、日、意、加七国","1975年六国会议起步，1976年加拿大加入成G7","1998至2014年曾为G8（含俄罗斯）"],"members":[["美国","1975年创始成员，北美经济体"],["英国","1975年创始成员，欧洲经济体"],["法国","1975年首届朗布依埃峰会东道主"],["德国","1975年创始成员（时为联邦德国）"],["日本","1975年创始成员，唯一亚洲成员"],["意大利","1975年创始成员，欧洲经济体"],["加拿大","1976年加入，使六国扩为七国"]],"mem":"地域拆分口诀：“北美两兄妹（美加）+欧洲四强（英法德意）+亚洲一独苗（日本）”。演变数字：75年6国→76年加加拿大变7→98年加俄变8→14年退俄回7。","mix":"常见选择题干扰项：澳大利亚、西班牙、韩国、俄罗斯均不属于当前七国集团；俄罗斯曾属G8，2014年后已不再参与。","mcq":[{"q":"下列国家中，属于当前七国集团（G7）正式成员国的是","o":["意大利","澳大利亚","俄罗斯","西班牙"],"a":0,"w":"G7成员为美、英、法、德、日、意、加；俄罗斯2014年退出G8，澳大利亚和西班牙从未加入G7。"}],"rel":[{"t":"二十国集团","n":"发达国家与新兴体并存对照"},{"t":"金砖国家","n":"新兴经济体合作机制对照"},{"t":"欧盟","n":"欧盟代表列席G7峰会"},{"t":"多极化","n":"全球经济重心变迁背景"}],"exam":[]},{"id":"a13-148","t":"“上海精神”","cid":"13h","p":2,"kind":"概念","alias":["上海精神"],"one":"上合组织的核心准则：互信、互利、平等、协商、尊重多样文明、谋求共同发展。","ans":"“上海精神”是**上海合作组织**确立的核心价值观与行动准则，内容为**“互信、互利、平等、协商、尊重多样文明、谋求共同发展”**。它孕育于1996年**“上海五国”**机制，2001年正式写入《上海合作组织成立宣言》。这一精神超越冷战思维与零和博弈旧范式，构成上合组织25年来保持凝聚力的**根本政治基石**。","pts":["内容：互信互利平等协商、尊重多样文明谋求共同发展","源于1996年上海五国，2001年写入上合宣言","超越冷战思维，是上合组织的核心价值观"],"mem":"结构拆解口诀：“四双两六”，即四个两字词“互信、互利、平等、协商”加两个六字短语“尊重多样文明、谋求共同发展”。四双记作“信利平协”。","mix":"别把“上海精神”（上合组织）与“上海城市精神”（海纳百川、追求卓越、开明睿智、大气谦和）混为一谈，前者是国际关系准则，后者是上海地方文化名片。","mcq":[{"q":"下列哪项不属于上海合作组织“上海精神”的完整表述内容","o":["互信、互利","结盟、威慑","平等、协商","尊重多样文明、谋求共同发展"],"a":1,"w":"上合组织奉行不结盟、不对抗、不针对第三方的原则，“上海精神”为互信、互利、平等、协商、尊重多样文明、谋求共同发展。"}],"rel":[{"t":"上海合作组织","n":"“上海精神”所属国际组织"},{"t":"“上海五国”机制","n":"“上海精神”的孕育源头"},{"t":"2026年上海合作组织比什凯克峰会","n":"25周年宣言重申该精神"},{"t":"新型国际关系","n":"同倡超越零和博弈"}],"exam":[]},{"id":"a13-149","t":"“上海五国”机制","cid":"13h","p":3,"kind":"事件","alias":["上海五国"],"one":"1996年中俄哈吉塔元首上海会晤形成的机制，2001年升级为上合组织。","ans":"“上海五国”机制是**上海合作组织的前身**，属中国参与发起的新型区域安全机制。**1996年4月**，**中、俄、哈、吉、塔**五国元首在上海会晤并签署边境军事互信协定。**2001年**吸收乌兹别克斯坦成立上合组织，开创结伴不结盟合作新模式。","pts":["1996年4月五国元首在上海会晤创立","成员为中、俄、哈、吉、塔五国","2001年加乌兹别克斯坦升级为上合组织"],"mem":"五国口诀“中俄哈吉塔”，2001年加“乌”（乌兹别克斯坦）成上合六创始国；1996到2026正好30周年。","mix":"土库曼斯坦是永久中立国，既不在“上海五国”中，也未加入上合组织；乌兹别克斯坦是2001年上合成立时才加入的。","mcq":[{"q":"下列国家中，不属于1996年“上海五国”机制成员的是","o":["哈萨克斯坦","吉尔吉斯斯坦","塔吉克斯坦","乌兹别克斯坦"],"a":3,"w":"“上海五国”为中、俄、哈、吉、塔；乌兹别克斯坦于2001年加入后共同成立上合组织。"}],"rel":[{"t":"上海合作组织","n":"2001年升级而成的区域组织"},{"t":"“上海精神”","n":"自五国机制孕育的合作理念"},{"t":"2025年上海合作组织天津峰会","n":"上合组织近年重要峰会"}],"more":"2026年为“上海五国”机制建立30周年（1996–2026），也是上海合作组织成立25周年（2001–2026）。","exam":[]},{"id":"a13-150","t":"2026年上海合作组织比什凯克峰会","cid":"13h","p":2,"kind":"时事","alias":["上合组织比什凯克峰会","2026年上合峰会"],"one":"2026年9月吉尔吉斯斯坦比什凯克召开的上合25周年峰会，发表《比什凯克宣言》。","ans":"2026年上海合作组织比什凯克峰会即上合元首理事会**第二十六次会议**，于**2026年8月31日至9月1日**在吉尔吉斯斯坦首都**比什凯克**举行，正值**上合组织成立25周年**。峰会发表**《上海合作组织二十五周年比什凯克宣言》**，重申“上海精神”与多边主义，批准安全与禁毒中心条例，并向巴基斯坦移交轮值主席国职权。","pts":["2026年8月31日至9月1日比什凯克举行","适逢上合组织成立25周年（2001至2026）","发表《上海合作组织二十五周年比什凯克宣言》"],"mem":"时间地点坐标：2001上海建组织→2025中国天津峰会（24周年）→2026吉尔吉斯斯坦比什凯克（25周年）→交棒巴基斯坦。记“26年9月1，比什凯克庆二五”。","mix":"注意区分两届连续峰会：2025年上合峰会在中国天津举办（提出全球治理倡议、通过未来10年发展战略）；2026年25周年峰会在吉尔吉斯斯坦比什凯克举办，别张冠李戴。","mcq":[{"q":"2026年上海合作组织成立25周年峰会的举办城市及发表的核心纲领性文件是","o":["天津；《天津宣言》","阿斯塔纳；《阿斯塔纳宣言》","撒马尔罕；《撒马尔罕宣言》","比什凯克；《上海合作组织二十五周年比什凯克宣言》"],"a":3,"w":"2026年8月31日至9月1日上合峰会在吉尔吉斯斯坦比什凯克举行，发表《上海合作组织二十五周年比什凯克宣言》。"}],"rel":[{"t":"上海合作组织","n":"成立25周年里程碑会议"},{"t":"“上海精神”","n":"宣言重申的核心基石"},{"t":"2025年上海合作组织天津峰会","n":"上一届轮值主席国峰会"},{"t":"丝绸之路：长安-天山廊道路网","n":"吉尔吉斯斯坦同在丝路廊道"}],"more":"截至2026年，上合组织拥有10个正式成员国（中、俄、哈、吉、塔、乌、印、巴、伊、白俄罗斯）。","exam":[]},{"id":"a13-151","t":"全球南方","cid":"13h","p":2,"kind":"概念","alias":["Global South"],"one":"泛指新兴市场国家和发展中国家的国际关系概念，强调发展阶段与共同利益。","ans":"全球南方（Global South）是国际关系中泛指**新兴市场国家和发展中国家**的集合概念，与欧美发达国家为主的“全球北方”相对。它**按发展水平划分**，而非严格地理南北（如澳大利亚在南半球却属北方）。**金砖扩员与非盟加入G20**标志着全球南方群体性崛起，已成为推动**世界多极化与全球治理变革**的重要力量，中国是其天然成员。","pts":["泛指新兴市场国家和发展中国家集合","按发展阶段而非严格地理纬线划分","金砖扩员与非盟入G20标志其群体性崛起"],"mem":"反例记忆法：抓住“澳新在南却属北，中国在北却属南”这句顺口溜，立刻明白“南北”看的是发达与发展中，与赤道无关。","mix":"“全球南方”与冷战时期的“第三世界”有历史延续性，但更少意识形态对抗色彩，更突出发展权、经济合作与全球治理代表性。","mcq":[{"q":"关于国际关系中的“全球南方”概念，下列说法正确的是","o":["严格指代地理上位于赤道以南的南半球国家","澳大利亚和新西兰因地处南半球属于全球南方","泛指新兴市场国家和发展中国家的集合","仅指非洲和拉丁美洲的欠发达国家"],"a":2,"w":"全球南方按发展阶段划分，泛指新兴市场和发展中国家，澳大利亚、新西兰属发达国家（全球北方）。"}],"rel":[{"t":"金砖国家","n":"全球南方合作的核心平台"},{"t":"不结盟运动","n":"历史上的发展中国家联合"},{"t":"三个世界划分","n":"冷战时期的历史对照概念"},{"t":"多极化","n":"全球南方推动世界多极化"}],"exam":[]},{"id":"a13-152","t":"中非合作论坛","cid":"13h","p":3,"kind":"制度","alias":["FOCAC"],"one":"2000年10月在北京成立的中国与非洲国家集体对话与务实合作机制。","ans":"中非合作论坛（FOCAC）是**2000年10月**在北京成立的集体对话机制，属**南南合作**重要多边平台。成员含**中国、53个建交非洲国家与非盟委员会**，每三年轮流举办会议。**2024年北京峰会**引领共筑新时代全天候中非命运共同体。","pts":["2000年10月在北京正式成立","成员为中国、53个建交非洲国及非盟委员会","每三年轮办，2024年举行北京峰会"],"mem":"“千禧年（2000）启动、三年一会、53国+中国+非盟”，记住2024年9月刚在北京举办过峰会。","mix":"非洲有54个联合国会员国，但中非合作论坛非方成员国为53个（未含未与中国建交的斯威士兰），另加非盟委员会共55个成员。","mcq":[{"q":"中非合作论坛（FOCAC）正式成立的时间和地点是","o":["1996年上海","2000年北京","2001年博鳌","2006年开罗"],"a":1,"w":"中非合作论坛于2000年10月在北京召开首届部长级会议并正式成立。"}],"rel":[{"t":"非洲联盟","n":"论坛重要非方机构成员"},{"t":"全球南方","n":"中非合作属南南合作典范"},{"t":"人类命运共同体","n":"新时代中非关系定位"}],"exam":[]},{"id":"a13-153","t":"欧元与英国脱欧","cid":"13h","p":3,"kind":"事件","alias":["欧元","欧元区","英国脱欧","脱欧","Brexit"],"one":"欧元1999年启用、2026年扩至21国；英国2016公投、2020年正式退欧。","ans":"欧元与英国脱欧折射**欧洲一体化**的深化与曲折。欧元**1999年**启用、**2002年**流通现钞，**2026年1月保加利亚成第21个欧元区国家**。英国一直用英镑，**2016年公投**、**2020年1月31日**正式退盟，成欧盟首个退出国。","pts":["欧元1999年启用、2002年现钞流通","2026年1月保加利亚加入，欧元区达21国","英国2016年公投、2020年1月31日正式脱欧"],"mem":"记住四个关键年：99启欧元、02用现钞、16英公投、20正式脱；外加2026元旦保加利亚成欧元区第21国。","mix":"欧盟（27国）与欧元区（21国）不重合：丹麦、瑞典、波兰等欧盟成员未使用欧元；英国脱欧前也一直保留英镑。","mcq":[{"q":"2026年1月1日正式启用欧元、成为欧元区第21个成员国的国家是","o":["克罗地亚","罗马尼亚","匈牙利","保加利亚"],"a":3,"w":"克罗地亚于2023年成为第20个欧元区成员国，保加利亚于2026年1月1日成为第21个成员国。"}],"rel":[{"t":"欧盟","n":"欧元区与脱欧的制度母体"},{"t":"全面与进步跨太平洋伙伴关系协定（CPTPP）","n":"英国脱欧后转向的贸易协定"},{"t":"全球化与逆全球化","n":"英国脱欧属逆全球化代表事件"}],"exam":[]},{"id":"a13-154","t":"国际红十字运动","cid":"13h","p":3,"kind":"制度","alias":["红十字国际委员会","ICRC"],"one":"1863年瑞士人亨利·杜南倡议创立，总部日内瓦，获1901年首届诺贝尔和平奖。","ans":"国际红十字运动是全球规模最大的**人道主义救援运动**，源于**1863年**瑞士人**亨利·杜南**倡议创立的红十字国际委员会（总部**日内瓦**）。运动秉持**人道、公正、中立**等原则，推动《日内瓦公约》体系建立。杜南于**1901年获首届诺贝尔和平奖**。","pts":["1863年亨利·杜南倡议成立，总部日内瓦","秉持人道、公正、中立等基本原则","杜南获1901年首届诺贝尔和平奖"],"mem":"标志挂钩：红十字正是瑞士国旗（红底白十字）的反色，因此创始人在瑞士、总部在瑞士日内瓦，1901年摘得首届和平奖。","mix":"红十字国际委员会（ICRC）侧重战时人道保护，红十字会与红新月会国际联合会（IFRC）侧重平时救灾，伊斯兰国家多使用红新月标志。","mcq":[{"q":"因倡议创立红十字国际委员会而获得1901年首届诺贝尔和平奖的是","o":["亨利·杜南","阿尔弗雷德·诺贝尔","伍德罗·威尔逊","南森"],"a":0,"w":"瑞士人亨利·杜南与法国人帕西共同获得1901年首届诺贝尔和平奖。"}],"rel":[{"t":"诺贝尔奖","n":"杜南获首届诺贝尔和平奖"},{"t":"世界卫生组织","n":"总部同设于瑞士日内瓦"},{"t":"联合国维和行动","n":"冲突地区人道与和平保护呼应"}],"more":"红十字国际委员会于1917年、1944年、1963年三次获得诺贝尔和平奖，为获奖次数最多的机构。","exam":[]},{"id":"a13-155","t":"国际原子能机构","cid":"13h","p":3,"kind":"制度","alias":["IAEA"],"one":"1957年成立、总部维也纳，负责原子能和平利用与核不扩散核查。","ans":"国际原子能机构（IAEA）是**1957年**成立的独立政府间组织，属**联合国系统**，总部设于**奥地利维也纳**。其职能是促进**原子能和平利用**，并依据《不扩散核武器条约》开展核查监督。该机构于**2005年获诺贝尔和平奖**，是全球核治理核心平台。","pts":["1957年成立，总部设于奥地利维也纳","推进核能和平利用与核不扩散核查","2005年获诺贝尔和平奖"],"mem":"记住“维也纳双能源机构”：国际原子能机构（1957，核能）和欧佩克（1960，石油）总部都在奥地利维也纳。","mix":"国际原子能机构虽属联合国系统、向联大和安理会报告，但法律上是独立政府间组织，不属于联合国专门机构。","mcq":[{"q":"国际原子能机构（IAEA）的总部位于","o":["瑞士日内瓦","奥地利维也纳","法国巴黎","荷兰海牙"],"a":1,"w":"国际原子能机构1957年成立，总部设于奥地利首都维也纳。"}],"rel":[{"t":"《不扩散核武器条约》","n":"核查监督的国际条约依据"},{"t":"石油输出国组织","n":"总部同设于维也纳的能源组织"},{"t":"联合国","n":"隶属联合国系统的独立机构"}],"exam":[]},{"id":"a13-156","t":"石油输出国组织","cid":"13h","p":3,"kind":"制度","alias":["欧佩克","OPEC"],"one":"简称欧佩克，1960年巴格达成立、总部维也纳，协调产油国产量与油价。","ans":"石油输出国组织简称**欧佩克（OPEC）**，**1960年**由伊朗、伊拉克、科威特、沙特、委内瑞拉在**巴格达**成立，总部在**维也纳**。它通过协调产量稳定油市。安哥拉2024年、**阿联酋2026年5月**退出后现有**11国**，仍深刻影响国际油价。","pts":["简称欧佩克，1960年巴格达成立，总部维也纳","通过产量配额协调国际油价与产油国利益","2026年5月阿联酋退出后成员减至11国"],"mem":"创始五国“两伊科沙委”（伊朗、伊拉克、科威特、沙特、委内瑞拉）；“巴格达出生，维也纳定居”。","mix":"“欧佩克+”是欧佩克与俄罗斯等非欧佩克产油国组成的扩大会议机制；美国、俄罗斯、挪威均非欧佩克正式成员。","mcq":[{"q":"石油输出国组织（OPEC）1960年成立时的会址位于","o":["巴格达","利雅得","维也纳","多哈"],"a":0,"w":"欧佩克1960年在伊拉克首都巴格达成立，1965年起总部迁至奥地利维也纳。"}],"rel":[{"t":"国际原子能机构","n":"总部同在维也纳的能源组织"},{"t":"地缘政治","n":"中东石油博弈重要载体"},{"t":"通货膨胀与通货紧缩","n":"油价波动传导至全球通胀"}],"exam":[]},{"id":"a13-157","t":"非洲联盟","cid":"13h","p":3,"kind":"制度","alias":["非盟","AU"],"one":"2002年成立、总部亚的斯亚贝巴，55个成员国，2023年成G20永久成员。","ans":"非洲联盟简称**非盟（AU）**，是**2002年**成立的非洲最高区域组织，前身为1963年**非洲统一组织**，总部在**亚的斯亚贝巴**。非盟涵盖**55个成员国**，致力非洲一体化。**2023年9月**正式加入二十国集团，提升了非洲全球治理话语权。","pts":["2002年成立，前身为1963年非统组织","总部亚的斯亚贝巴，含55个成员国","2023年9月成为二十国集团永久成员"],"mem":"三串数字记非盟：1963非统 → 2002非盟 → 55国全覆盖 → 2023入G20；总部记“非洲屋脊埃塞俄比亚的亚的斯亚贝巴”。","mix":"不要把非盟（AU，2002）与前身非洲统一组织（OAU，1963）年份混掉；非盟与欧盟现同为G20永久区域组织成员。","mcq":[{"q":"非洲联盟（AU）的总部设于哪一城市","o":["内罗毕","开罗","亚的斯亚贝巴","约翰内斯堡"],"a":2,"w":"非盟总部位于埃塞俄比亚首都亚的斯亚贝巴；内罗毕是联合国环境规划署总部。"}],"rel":[{"t":"二十国集团","n":"2023年成为其永久成员"},{"t":"中非合作论坛","n":"非盟委员会系论坛成员"},{"t":"欧盟","n":"G20另一区域组织常任成员"}],"exam":[]},{"id":"a13-158","t":"博鳌亚洲论坛与达沃斯论坛","cid":"13h","p":3,"kind":"制度","alias":["博鳌亚洲论坛","达沃斯论坛","世界经济论坛","夏季达沃斯"],"one":"分别立足海南博鳌（2001）与瑞士达沃斯（1971）的国际经济对话平台。","ans":"博鳌亚洲论坛与达沃斯论坛均为国际著名**高端经济对话平台**。**博鳌亚洲论坛**2001年成立，会址在**海南博鳌**，聚焦亚洲合作。**世界经济论坛**1971年由施瓦布创办，年会在**瑞士达沃斯**举办，并在**天津、大连**轮办“夏季达沃斯”，共促全球对话。","pts":["博鳌亚洲论坛2001年成立，会址海南博鳌","世界经济论坛1971年施瓦布创办，瑞士达沃斯","中国天津、大连轮流举办夏季达沃斯"],"mem":"对比记“一东一西”：达沃斯1971瑞士小镇施瓦布（冬），天津大连轮流办（夏）；博鳌2001海南小镇（春，2026年25周年）。","mix":"“夏季达沃斯”正式名称是世界经济论坛新领军者年会，2007年起在中国大连、天津两市轮流举办，不在海南博鳌。","mcq":[{"q":"世界经济论坛“夏季达沃斯”在中国由哪两座城市轮流举办","o":["北京与上海","天津与大连","海口与三亚","深圳与广州"],"a":1,"w":"自2007年起，夏季达沃斯论坛（新领军者年会）由中国大连和天津轮流承办。"}],"rel":[{"t":"海南自由贸易港","n":"博鳌论坛永久会址所在省"},{"t":"APEC与2026年深圳会议","n":"亚太重要多边经济平台"},{"t":"全球化与逆全球化","n":"两大论坛的核心议题背景"}],"more":"2026年3月博鳌亚洲论坛年会恰逢论坛成立25周年；2026年1月达沃斯年会主题为“对话的精神”。","exam":[]},{"id":"a13-159","t":"威斯特伐利亚体系","cid":"13i","p":2,"kind":"制度","alias":["威斯特伐利亚和约","威斯特伐利亚体系（1648）"],"one":"1648年结束三十年战争确立的国际体系，奠定国家主权与平等原则。","ans":"威斯特伐利亚体系是**1648年**欧洲各国签署**《威斯特伐利亚和约》**、结束**三十年战争**后建立的首个近代国际体系。它确立了**国家领土主权、主权平等与不干涉内政**等原则，开创**国际会议谈判解决争端**的现代外交惯例。该体系终结教皇与帝国凌驾权威，标志着以主权国家为基本单位的近代国际关系正式诞生。","pts":["1648年《威斯特伐利亚和约》结束三十年战争","确立国家主权平等与不干涉内政原则","近代国际关系体系与国际会议外交的开端"],"mem":"中西同年锚点：1648年刚好是明亡清兵入关（1644年）后四年；欧洲打完“三十年战争”（1618至1648），坐下来签和约，从此确立“主权国家”规矩。","mix":"国际关系史四大体系别混序：1648威斯特伐利亚体系（三十年战争后）→1815维也纳体系（拿破仑战争后）→1919凡尔赛-华盛顿体系（一战后）→1945雅尔塔体系（二战后）。","mcq":[{"q":"1648年《威斯特伐利亚和约》结束了欧洲的哪场战争，并确立了近代国家主权原则","o":["英法百年战争","三十年战争","七年战争","拿破仑战争"],"a":1,"w":"1648年《威斯特伐利亚和约》结束了1618至1648年的欧洲三十年战争，奠定近代主权国家体系。"}],"rel":[{"t":"凡尔赛-华盛顿体系","n":"一战后的国际关系体系"},{"t":"雅尔塔体系","n":"二战后的国际关系体系"},{"t":"宗教改革","n":"引发三十年战争的宗教背景"},{"t":"地缘政治","n":"主权国家体系下的战略分析"}],"exam":[]},{"id":"a13-162","t":"铁幕演说","cid":"13i","p":2,"kind":"事件","alias":["富尔顿演说","Iron Curtain Speech"],"one":"1946年3月丘吉尔在美国富尔顿发表的演讲，拉开美苏冷战序幕。","ans":"铁幕演说又称**富尔顿演说**，是英国前首相**温斯顿·丘吉尔**于**1946年3月5日**在美国密苏里州富尔顿威斯敏斯特学院发表的题为《和平砥柱》的著名演讲。他宣称横贯欧洲大陆的**“铁幕”已经降落下来**，呼吁英美结成特殊关系共同遏制苏联与东欧社会主义国家。该演说被普遍视为**冷战拉开序幕的标志**，2026年正值发表**80周年**。","pts":["1946年3月5日丘吉尔在美国富尔顿发表","宣称“铁幕”降落欧洲大陆，呼吁英美遏苏","被视为冷战序幕，2026年恰逢80周年"],"mem":"细节抓手：时间1946年3月5日（2026整80周年），人物已卸任的“前首相”丘吉尔（旁边坐着美国总统杜鲁门），地点密苏里州富尔顿，关键词“铁幕”。","mix":"发表演说时丘吉尔已是英国前首相（1945年大选落败），非在任首相；铁幕演说是冷战“序幕”，冷战“正式开始”一般以1947年杜鲁门主义出台为标志。","mcq":[{"q":"1946年3月在美国密苏里州富尔顿发表“铁幕演说”、拉开冷战序幕的政治家是","o":["杜鲁门","罗斯福","马歇尔","丘吉尔"],"a":3,"w":"1946年3月5日英国前首相丘吉尔在美国富尔顿发表题为《和平砥柱》的“铁幕演说”。"}],"rel":[{"t":"冷战","n":"冷战的序幕事件"},{"t":"杜鲁门主义","n":"次年冷战正式开启"},{"t":"丘吉尔获诺贝尔文学奖","n":"演说者另一高频考点"},{"t":"柏林墙","n":"冷战“铁幕”的实体象征"}],"more":"演讲原题《和平砥柱》（The Sinews of Peace）；2026年3月5日为铁幕演说发表80周年。","exam":[]},{"id":"a13-167","t":"苏联解体","cid":"13i","p":2,"kind":"事件","alias":["苏维埃社会主义共和国联盟解体"],"one":"1991年12月苏联正式解体为15个独立国家，标志冷战与两极格局终结。","ans":"苏联解体指**1991年12月**苏联正式停止存在的重大事件。受体制僵化与戈尔巴乔夫改革失误影响，1991年“八一九事件”加速瓦解；12月俄、乌、白签《别洛韦日协议》建独联体，**12月25日戈尔巴乔夫辞职**，次日最高苏维埃宣布苏联停止存在，分裂为**15个独立国家**。它标志**冷战与两极格局终结**，2026年正值**35周年**。","pts":["1991年12月25日戈尔巴乔夫辞职，次日正式解体","分裂为15个独立国家，俄继承安理会常任席位","冷战与两极格局终结，2026年35周年"],"mem":"时间三步走：1989东欧剧变推倒柏林墙→1991.8“八一九事件”→1991.12.25红旗降落克里姆林宫（圣诞夜）。1991到2026刚好35周年。","mix":"1991年12月25日戈尔巴乔夫辞职并降下苏联国旗，12月26日苏联最高苏维埃正式决议苏联停止存在；苏联由15个加盟共和国组成，俄罗斯联邦继承其联合国安理会常任理事国席位。","mcq":[{"q":"1991年12月苏联正式解体，其直接带来的世界格局变化是","o":["凡尔赛-华盛顿体系正式崩溃","美苏两极格局正式确立","冷战结束，世界格局进入“一超多强”","欧洲联盟随即宣告解散"],"a":2,"w":"1991年苏联解体标志着冷战和美苏两极格局彻底终结，世界格局进入“一超多强”并向多极化发展。"}],"rel":[{"t":"东欧剧变与苏联解体","n":"苏东剧变完整历史脉络"},{"t":"冷战","n":"冷战终结标志性事件"},{"t":"两极格局与“一超多强”","n":"解体促成格局转换"},{"t":"历史终结论","n":"冷战终结催生的西方思潮"}],"more":"2026年12月为苏联解体35周年；1991年12月21日11个前苏联共和国签署《阿拉木图宣言》扩大独联体。","exam":[]},{"id":"a13-168","t":"两极格局与“一超多强”","cid":"13i","p":2,"kind":"概念","alias":["美苏两极格局","一超多强"],"one":"二战后美苏对峙的两极格局及1991年冷战后美国一超与多强并存的过渡格局。","ans":"两极格局与“一超多强”概括了**二战后国际战略格局的演变**。**两极格局**形成于战后雅尔塔体系，以**美苏两超级大国**及北约、华约全面对峙为特征；**1991年苏联解体**后冷战结束，转入**“一超多强”**，美国为唯一超级大国，**欧盟、中国、俄罗斯、日本**等并存制约。随新兴经济体崛起，这一过渡形态正加速向**多极化**发展。","pts":["两极格局：二战后美苏及北约华约全面对峙","一超多强：1991年后美一超与欧中俄日多强并存","由两极经一超多强向多极化演变"],"mem":"数量变化记法：2（美苏两极）→1+N（一超多强，1991苏联倒下）→N（多极化趋势）。“多强”抓四大板块：欧、中、俄、日，外加金砖等新兴群体。","mix":"“一超多强”是两极格局瓦解后的“过渡形态”，并不等于单极世界，因为多强力量对唯一超级大国构成明显牵制，最终趋势是多极化。","mcq":[{"q":"标志着二战后美苏两极格局瓦解、世界进入“一超多强”局面的历史事件是","o":["1991年苏联解体","1989年柏林墙倒塌","1993年欧盟正式成立","2001年中国加入世贸组织"],"a":0,"w":"1991年苏联解体使两极中一极消失，美苏两极格局彻底瓦解，世界进入“一超多强”局面。"}],"rel":[{"t":"多极化","n":"格局演变的长期趋势"},{"t":"雅尔塔体系","n":"奠定战后两极格局"},{"t":"苏联解体","n":"两极转为一超多强的分水岭"},{"t":"北约","n":"两极格局西方军事支柱"}],"exam":[]},{"id":"a13-169","t":"全球化与逆全球化","cid":"13i","p":1,"kind":"概念","alias":["全球化","逆全球化","经济全球化"],"one":"全球化是商品、资本、技术、人员跨国流动；逆全球化是反向趋势。","ans":"全球化是指**商品、资本、技术、信息和人员在全球范围内加速流动，各国相互依存不断加深**的历史进程，冷战结束、世界贸易组织成立和互联网普及使其在20世纪90年代大幅加速。**逆全球化**指贸易保护、单边主义、供应链“脱钩”等反向趋势，**2016年英国脱欧和特朗普当选后**表现突出。中国主张**推动经济全球化朝着开放、包容、普惠、平衡、共赢的方向发展**，以高水平开放、RCEP和“一带一路”应对逆全球化。两种趋势并存，反映出全球化红利分配不均等问题。","pts":["商品、资本、技术、人员跨国流动","逆全球化：保护主义、单边主义","中国主张开放包容普惠平衡共赢"],"mem":"全球化=“五流”：商品流、资本流、技术流、信息流、人员流，一个“流”就是一条跨国管道。逆全球化记“两退一垒”：退群（退出组织）、退约（退出协定）、筑垒（关税壁垒）。","mix":"逆全球化不等于反对一切国际合作，而是反对既有全球化规则；“去全球化”“脱钩”“小院高墙”是具体表现；全球化也不是单纯的经济现象，还有文化、信息层面。","mcq":[{"q":"下列事件常被视为逆全球化思潮兴起标志的是","o":["中国加入世贸组织","英国脱欧公投","RCEP签署","亚太经合组织成立"],"a":1,"w":"2016年英国脱欧与特朗普当选是逆全球化的标志性事件。"},{"q":"中国提倡的经济全球化方向是","o":["开放、包容、普惠、平衡、共赢","封闭、排他、单边","保护、自足、竞争","自由、放任、垄断"],"a":0,"w":"开放、包容、普惠、平衡、共赢。"}],"rel":[{"t":"世界贸易组织","n":"全球化制度载体"},{"t":"区域全面经济伙伴关系协定（RCEP）","n":"应对逆全球化"},{"t":"一带一路","n":"中国方案"},{"t":"威斯特伐利亚体系","n":"国际关系史背景"}],"more":"2017年习近平在达沃斯论坛提出引导经济全球化朝开放、包容、普惠、平衡、共赢方向发展。","exam":[]},{"id":"a13-170","t":"单边主义与多边主义","cid":"13i","p":2,"kind":"概念","alias":["单边主义","多边主义","真正的多边主义"],"one":"国际事务中一国独断专行与依托多国协商、国际规则共治的两种对立路径。","ans":"单边主义与多边主义是国际关系中两种对立行为取向。**单边主义**指大国无视国际规则与他国利益，凭实力**独自采取政治、经贸或军事行动**（如滥施关税、退群）；**多边主义**主张依托**联合国等国际组织与国际法**，通过多国平等协商共治全球事务。中国倡导**真正的多边主义**，反对排他性“小圈子”，维护以联合国为核心的国际体系。","pts":["单边主义：无视规则、凭实力独自行动","多边主义：依托国际组织与国际法平等协商","中国倡导真正的多边主义，反对排他性小圈子"],"mem":"拆字直觉记忆：“单”就是一家说了算（退群、加关税、绕开安理会）；“多”就是大家商量着办（有事找联合国、按国际法走）。再记住进阶词“真正的多边主义”。","mix":"多边主义强调开放包容，拉帮结派搞排他性阵营对抗被称为“选择性多边主义”或“伪多边主义”；单边主义常与贸易保护主义、霸权主义伴生。","mcq":[{"q":"下列国际行为中，典型体现“单边主义”倾向的是","o":["通过联合国大会协商制定气候变化公约","绕开世贸组织规则对多国任意加征惩罚性关税","在二十国集团框架下协调全球宏观经济政策","依据《联合国宪章》开展多国维和行动"],"a":1,"w":"绕开多边贸易规则任意单方面加征关税属于典型单边主义与贸易保护主义。"}],"rel":[{"t":"联合国","n":"多边主义的核心平台"},{"t":"贸易保护主义","n":"单边主义在经贸领域表现"},{"t":"全球四大倡议","n":"全球治理倡议倡导多边主义"},{"t":"世界贸易组织","n":"多边贸易体制核心机构"}],"exam":[]},{"id":"a13-171","t":"软实力","cid":"13i","p":1,"kind":"概念","alias":["软实力","软权力","约瑟夫·奈","文化软实力"],"one":"约瑟夫·奈1990年提出，指文化、价值观、制度的吸引力。","ans":"软实力是**美国学者约瑟夫·奈1990年提出的国际关系概念**，指一国**通过文化、价值观和制度的吸引力影响他国的能力**，与军事、经济等强制性的硬实力相对。他在**《注定领导》（1990）中首次提出**，2004年又出版《软实力》系统阐述，认为软实力来自文化、政治价值观和外交政策。我国十七大提出“提高国家文化软实力”，此后强调**讲好中国故事，增强国际传播能力**。影视、教育、语言传播和旅游等都是软实力的重要载体。","pts":["约瑟夫·奈1990年提出","文化、价值观、制度的吸引力","与硬实力相对；中国强调文化软实力"],"mem":"软硬对照：硬实力像“拳头和钱包”（军事、经济），软实力像“磁铁”（吸引、说服）。记人名“奈”：软实力“奈”（耐）得住，靠吸引而不靠强制。三个来源“文化、价值观、外交政策”。","mix":"提出者是约瑟夫·奈，不是基辛格或亨廷顿；“巧实力”是软硬实力结合，也由奈提出；软实力不等于文化产业产值。","mcq":[{"q":"“软实力”概念的提出者是","o":["亨廷顿","福山","基辛格","约瑟夫·奈"],"a":3,"w":"哈佛学者约瑟夫·奈1990年提出。"},{"q":"下列属于软实力来源的是","o":["军队规模","文化吸引力","外汇储备","钢铁产量"],"a":1,"w":"软实力来自文化、政治价值观和外交政策。"}],"rel":[{"t":"中国文学海外传播","n":"文化软实力的载体"},{"t":"中华思想文化术语传播工程","n":"国际传播举措"},{"t":"中国女排与女排精神","n":"体育软实力例子"},{"t":"全球化与逆全球化","n":"国际关系高频概念"}],"more":"提出：约瑟夫·奈《注定领导》（1990）；《软实力》（2004）。","exam":[]},{"id":"a13-172","t":"文明冲突论","cid":"13i","p":2,"kind":"概念","alias":["文明的冲突","亨廷顿文明冲突论"],"one":"美国学者亨廷顿提出的国际关系理论，认为冷战后冲突主要发生在文明之间。","ans":"文明冲突论是美国学者**塞缪尔·亨廷顿**提出的冷战后国际关系理论。他于**1993年**发表《文明的冲突？》，**1996年**出版**《文明的冲突与世界秩序的重建》**，将世界划为七八大文明，认为冷战后冲突主要源于**不同文明间的文化与宗教断层线**。该理论影响广泛但因夸大对抗备受争议，中国**全球文明倡议**即以文明交流互鉴超越文明冲突。","pts":["美国学者亨廷顿1993年发文、1996年成书","认为冷战后主要冲突发生在文明断层线之间","与倡导文明交流互鉴的全球文明倡议对照"],"mem":"师生对照记：学生福山（1989）乐观喊“历史终结了（西方赢了）”，老师亨廷顿（1993）泼冷水喊“别高兴太早，文明要冲突了”。俩人都是冷战结束前后的哈佛系学者。","mix":"易混书名与作者：亨廷顿写《文明的冲突与世界秩序的重建》（1996），福山写《历史的终结与最后的人》（1992），格雷厄姆·艾利森提“修昔底德陷阱”，三者都是美式国际关系高频词。","mcq":[{"q":"1993年发表文章、1996年出版《文明的冲突与世界秩序的重建》并提出“文明冲突论”的学者是","o":["弗朗西斯·福山","约瑟夫·奈","塞缪尔·亨廷顿","格雷厄姆·艾利森"],"a":2,"w":"塞缪尔·亨廷顿提出文明冲突论；福山提历史终结论，约瑟夫·奈提软实力，艾利森提修昔底德陷阱。"}],"rel":[{"t":"历史终结论","n":"同期冷战后理论对照"},{"t":"全球四大倡议","n":"全球文明倡议予以超越"},{"t":"修昔底德陷阱","n":"同属西方国际关系理论"},{"t":"“上海精神”","n":"主张尊重多样文明"}],"exam":[]},{"id":"a13-173","t":"历史终结论","cid":"13i","p":2,"kind":"概念","alias":["历史的终结","福山历史终结论"],"one":"日裔美籍学者福山冷战末期提出，宣称西方自由民主制是人类制度演化终点。","ans":"历史终结论是日裔美国学者**弗朗西斯·福山**在冷战末期提出的论断。他于**1989年**发表论文《历史的终结？》，**1992年**出版**《历史的终结与最后的人》**，宣称随苏东剧变，**西方自由民主制与市场经济**将成为人类意识形态演化的终点。此后地缘冲突频发、西方治理困境与**中国式现代化**崛起令该论断广受质疑，福山本人也作出修正。","pts":["日裔美籍学者福山1989年发文、1992年成书","宣称西方自由民主制是人类制度演化的终点","冷战结束产物，此后因现实变局广受质疑"],"mem":"时间与关键词：1989年夏福山发表《历史的终结？》（数月后柏林墙倒塌）；1991苏联解体，1992出书《历史的终结与最后的人》。记住“终结”指的是意识形态之争，而非大事不再发生。","mix":"福山所说的“历史终结”指人类社会制度与意识形态进化到达终点，不代表时间停止或事件终结；注意不要把福山（历史终结论）与亨廷顿（文明冲突论）搞混。","mcq":[{"q":"1992年出版《历史的终结与最后的人》、提出“历史终结论”的学者是","o":["亨廷顿","基辛格","布热津斯基","弗朗西斯·福山"],"a":3,"w":"弗朗西斯·福山于1989年发表文章、1992年出版《历史的终结与最后的人》，提出历史终结论。"}],"rel":[{"t":"文明冲突论","n":"老师亨廷顿的对照理论"},{"t":"苏联解体","n":"催生该论断的历史背景"},{"t":"全过程人民民主","n":"中国民主实践打破单一终点论"},{"t":"德国古典哲学","n":"福山借用黑格尔历史观"}],"exam":[]},{"id":"a13-174","t":"贸易保护主义","cid":"13i","p":3,"kind":"概念","alias":["保护主义"],"one":"政府通过关税、配额等壁垒限制进口，以保护本国产业的经济政策。","ans":"贸易保护主义是与**自由贸易**相对的政策主张，属**国际贸易与逆全球化**核心概念。它主要通过**关税、进口配额、技术壁垒与补贴**等手段限制外国商品竞争，保护本国产业。过度保护易引发**贸易战与供应链扭曲**，损害世界经济效率与多边体系。","pts":["与自由贸易相对的国际贸易政策","主要手段为关税、配额与非关税壁垒","易诱发贸易战并冲击全球产业链"],"mem":"逻辑链：筑起“关税墙+配额门”挡住外国货 → 短期护本土 → 对手报复打贸易战 → 推高逆全球化浪潮。","mix":"关税壁垒直接加税，非关税壁垒包括配额、许可证、技术环保标准和反倾销调查等，当代后者使用更隐蔽广泛。","mcq":[{"q":"下列举措中，最典型地体现贸易保护主义的是","o":["大幅下调最惠国关税","对进口商品设置高额惩罚性关税与配额","签署区域全面经济伙伴关系协定","推进跨境贸易通关便利化"],"a":1,"w":"加征高额关税和设置进口配额是贸易保护主义最经典的政策工具。"}],"rel":[{"t":"全球化与逆全球化","n":"贸易保护主义是逆全球化推手"},{"t":"世界贸易组织","n":"致力于削减贸易壁垒的多边机构"},{"t":"单边主义与多边主义","n":"单边关税与多边规则的对立"}],"exam":[]},{"id":"a13-175","t":"“9·11”事件","cid":"13i","p":3,"kind":"事件","alias":["911事件","九一一事件"],"one":"2001年9月11日美国遭特大恐袭，世贸双子塔倒塌，引发反恐战争。","ans":"“9·11”事件指**2001年9月11日**“基地”组织劫机袭美的**特大恐怖袭击**。袭击致纽约**世贸中心双子塔**倒塌、五角大楼受损及近三千人遇难。事件深刻改变国际安全格局，美国随即发动**阿富汗战争与伊拉克战争**，开启全球反恐时代。","pts":["2001年9月11日“基地”组织劫机袭美","纽约世贸中心双子塔倒塌、五角大楼遭袭","引发阿富汗战争与美国全球反恐战略"],"mem":"因果链记年份：2001年9·11袭击（2026年25周年）→ 2001年底阿富汗战争 → 2003伊拉克战争 → 2014伊斯兰国坐大。","mix":"“9·11”事件由本·拉登领导的“基地”组织策划，而非2014年才“建国”的伊斯兰国；美国总统当时是小布什。","mcq":[{"q":"2001年“9·11”事件发生后，美国随即于当年发动的战争是","o":["海湾战争","科索沃战争","利比亚战争","阿富汗战争"],"a":3,"w":"“9·11”事件后，美国指认“基地”组织幕后主使，于2001年10月发动阿富汗战争。"}],"rel":[{"t":"伊斯兰国","n":"反恐战争后滋生的极端组织"},{"t":"地缘政治","n":"21世纪初国际安全转折点"},{"t":"硅谷与华尔街","n":"遇袭世贸中心紧邻华尔街"}],"more":"2026年9月11日为“9·11”事件25周年。","exam":[]},{"id":"a13-176","t":"俄乌冲突","cid":"13i","p":3,"kind":"事件","alias":["乌克兰危机"],"one":"2022年2月24日俄罗斯对乌发起“特别军事行动”，重塑欧洲安全格局。","ans":"俄乌冲突是冷战后欧洲最大规模**地缘武装冲突**，根源于北约东扩及**2014年克里米亚危机**矛盾。**2022年2月24日**俄宣布对乌采取**“特别军事行动”**，战事陷入长期消耗，近年谈判增多但分歧犹存。冲突剧烈冲击欧洲安全与全球能源粮食供应。","pts":["2022年2月24日俄发起“特别军事行动”","与北约东扩及2014年克里米亚危机相关","深刻冲击欧洲安全与全球能源粮食供应链"],"mem":"十年脉络：2014克里米亚入俄埋火种 → 2022年2月24日冲突全面爆发 → 冲击欧洲安全、油气与粮食三大板块。","mix":"2014年克里米亚危机与乌东顿巴斯冲突是前奏，2022年2月24日则是俄乌冲突全面升级的标志日期。","mcq":[{"q":"俄罗斯宣布对乌克兰采取“特别军事行动”、俄乌冲突全面升级的日期是","o":["2014年3月18日","2021年8月30日","2022年2月24日","2023年10月7日"],"a":2,"w":"2022年2月24日俄罗斯宣布对乌克兰采取“特别军事行动”。"}],"rel":[{"t":"克里米亚","n":"2014年冲突前奏与焦点地区"},{"t":"北约","n":"北约东扩系冲突核心诱因"},{"t":"东欧剧变与苏联解体","n":"俄乌历史格局渊源"},{"t":"地缘政治","n":"当代大国安全博弈案例"}],"exam":[]},{"id":"a13-178","t":"美国宪法","cid":"13j","p":2,"kind":"制度","alias":["美利坚合众国宪法","1787年宪法"],"one":"1787年费城制定的世界上第一部成文宪法，确立联邦制与三权分立。","ans":"美国宪法又称**1787年宪法**，由**1787年费城制宪会议**制定、**1789年生效**，是**世界第一部资产阶级成文宪法**。它确立了**联邦制、共和制和三权分立制衡**原则；**1791年**生效的前十条修正案称**《权利法案》**，保障公民基本权利。它奠定美国现代政治框架并影响近代宪政，但原文本保留蓄奴妥协，直至内战后修正案才予废除。","pts":["1787年费城制定、1789年生效，首部成文宪法","确立联邦制、共和制与三权分立制衡原则","1791年前十条修正案合称《权利法案》"],"mem":"三组年份链：“76独立宣言→87费城立宪→89生效上任（华盛顿）→91补十条《权利法案》”。记牢两个“第一”：世界第一部成文宪法，现存沿用最久的成文宪法。","mix":"注意区分英国《权利法案》（1689年，限制王权确立君主立宪）与美国《权利法案》（1791年，美国宪法前十条修正案，保障公民权利）；美国宪法至今共27条修正案。","mcq":[{"q":"关于1787年美国宪法及其修正案，下列说法正确的是","o":["是世界上第一部不成文宪法","由华盛顿在1776年独立战争期间独自起草","1791年生效的前十条修正案合称《权利法案》","正文直接明确废除了全美黑人奴隶制"],"a":2,"w":"美国宪法是世界首部成文宪法，1787年费城制宪会议制定，1791年前十条修正案称《权利法案》；废奴由1865年第13修正案完成。"}],"rel":[{"t":"1787年美国宪法","n":"同主题历史板块词条"},{"t":"三权分立","n":"宪法确立的核心架构"},{"t":"《权利法案》（英国）","n":"同名英美文献对照"},{"t":"新中国第一部宪法","n":"中西成文宪法对照"}],"exam":[]},{"id":"a13-179","t":"民主党与两党制","cid":"13j","p":2,"kind":"制度","alias":["驴象之争","美国两党制"],"one":"美国民主党（驴）与共和党（象）轮替执政的资产阶级政党制度。","ans":"民主党与共和党轮流执政构成美国典型**两党制**，俗称**“驴象之争”**。**民主党**1828年定名，以**驴**为标志，当代偏重社会福利、政府干预与多元平权；**共和党**成立于**1854年**，以**象**为标志，**林肯**为首位共和党总统，当代偏重减税、放松监管与保守价值。两党激烈竞争，但均在宪法框架内维护美国资本主义制度。","pts":["民主党（驴）与共和党（象）轮替执政","共和党1854年成立，林肯是首位共和党总统","俗称“驴象之争”，均在宪法框架内运作"],"mem":"动物谐音与色块记法：“民驴蓝，共象红”，即民主党是驴、代表色蓝，共和党是象、代表色红。“共象”谐音“共享”，一秒防混。","mix":"两党历史立场曾发生反转：19世纪中叶共和党（林肯）反奴隶制、民主党在南方支持蓄奴；20世纪罗斯福新政和民权运动后才演变为今天民主党偏自由派、共和党偏保守派的格局。","mcq":[{"q":"美国两党制俗称“驴象之争”，关于两大政党对应关系正确的是","o":["民主党以驴为标志，共和党以象为标志，林肯是首位共和党总统","民主党以象为标志，共和党以驴为标志，华盛顿是首位共和党总统","两党均成立于1787年费城制宪会议期间","民主党长期主张无条件废除联邦税收制度"],"a":0,"w":"民主党标志为驴，共和党1854年成立、标志为象，林肯于1861年就任首位共和党总统；华盛顿无党派。"}],"rel":[{"t":"共和党","n":"两党制另一核心政党"},{"t":"选举人团制度","n":"两党争夺总统的选举规则"},{"t":"华盛顿、杰斐逊与林肯","n":"杰斐逊与林肯分涉两党渊源"},{"t":"八个民主党派","n":"与多党合作制度对照"}],"exam":[]},{"id":"a13-180","t":"选举人团制度","cid":"13j","p":2,"kind":"制度","alias":["美国选举人团","Electoral College"],"one":"美国总统间接选举制度，共538张选举人票，获270票以上者当选。","ans":"选举人团制度是**1787年美国宪法**确立的**总统间接选举制度**。全国共设**538张选举人票**（100参院+435众院+特区3票），选民在各州选出选举人，再由选举人投选总统，获**270张及以上**者当选。除缅因和内布拉斯加外，其余各州均行**“赢者通吃”**，因此可能出现赢下全国普选票却输掉大选的情形。","pts":["美国总统间接选举制，并非全国普选直选","共538张选举人票，获270张以上当选","绝大多数州“赢者通吃”，摇摆州决定胜负"],"mem":"数学加法记死538：参院100 + 众院435 + 首都华盛顿特区3 = 538；过半数 538÷2+1 = 270。因为“赢者通吃”，候选人都死磕摇摆州。","mix":"美国总统由“间接选举”而非全民直接普选产生，历史上曾多次出现普选票领先却未赢选举人票的落选案例（如2000年戈尔、2016年希拉里）。","mcq":[{"q":"美国总统选举实行选举人团制度，全国共有538张选举人票，候选人当选总统至少需要获得","o":["218张","250张","269张","270张"],"a":3,"w":"538张选举人票过半数须至少获得270张；269平票将交由国会众议院投票决定。"}],"rel":[{"t":"参议院与众议院","n":"选举人票数按国会席位算"},{"t":"美国宪法","n":"制度确立的宪法渊源"},{"t":"民主党与两党制","n":"大选中的核心竞争主体"},{"t":"美国中期选举","n":"总统大选之间的国会选举"}],"exam":[]},{"id":"a13-181","t":"美国中期选举","cid":"13j","p":3,"kind":"制度","alias":["中期选举"],"one":"总统任期中间举行的国会改选，改选众议院全部435席和参议院约三分之一席。","ans":"美国中期选举是在总统四年任期中间举行的**国会与地方换届选举**，属**三权分立**制衡机制。选举改选**众议院全部435席**、**参议院约三分之一席**及多州州长。**2026年11月3日**中期选举民主党夺回两院控制权，结果直接牵动白宫后半程施政空间。","pts":["在总统任期中间（偶数年11月）举行","改选众议院全部435席与参议院约1/3席","2026年11月3日举行，牵动白宫施政"],"mem":"数字口诀“众全435，参1/3”：众议员任期2年每次全换，参议员任期6年每两年换三分之一，2026年11月刚举行。","mix":"中期选举不选总统，但若执政党丢掉国会控制权，总统易沦为立法受阻的“跛脚鸭”政府。","mcq":[{"q":"美国中期选举中，国会参众两院议席的改选比例分别是","o":["参议院全部、众议院三分之一","众议院全部、参议院约三分之一","两院均改选二分之一","两院均全部改选"],"a":1,"w":"众议员任期2年，每次全部改选435席；参议员任期6年，每次改选约三分之一。"}],"rel":[{"t":"参议院与众议院","n":"中期选举改选的核心机构"},{"t":"民主党与两党制","n":"两党争夺国会控制权"},{"t":"共和党","n":"2026年中期选举执政党"}],"exam":[]},{"id":"a13-182","t":"美国最高法院","cid":"13j","p":3,"kind":"制度","alias":["联邦最高法院"],"one":"美国最高司法机关，由9名终身制大法官组成，拥有宪法终审解释权。","ans":"美国最高法院是美国联邦**最高司法机关**，与总统、国会共同构成**1787年宪法**三权分立体制。法院由**9名大法官**组成，实行**总统提名、参议院批准、终身任职**制。自1803年确立**违宪审查权**以来，它对宪法解释与重大公共议题握有终裁权。","pts":["美国联邦最高司法机关，三权分立一极","9名大法官，总统提名、参议院确认、终身制","1803年确立违宪审查权，握宪法终审解释权"],"mem":"三要点“九人、提名+确认、终身制”：9人是奇数防平票，总统与参议院共选体现制衡，终身制保障司法独立。","mix":"大法官人选由总统提名、参议院（而非众议院）过半数批准；联邦宪法未写死人数，9人制自1869年延续至今。","mcq":[{"q":"关于美国联邦最高法院大法官的产生与任期，表述正确的是","o":["全民直选，任期六年","众议院提名、总统任命，任期十年","各州州长推举，连任不超两届","总统提名、参议院批准，终身任职"],"a":3,"w":"美国最高法院由9名大法官组成，由总统提名、参议院确认，除非辞职或遭弹劾则终身任职。"}],"rel":[{"t":"1787年美国宪法","n":"确立最高法院的根本法"},{"t":"三权分立","n":"司法分支最高代表"},{"t":"参议院与众议院","n":"参议院行使大法官批准权"}],"exam":[]},{"id":"a13-183","t":"华盛顿、杰斐逊与林肯","cid":"13j","p":2,"kind":"人物","alias":["美国三位代表性总统"],"one":"美国建国与统一关键总统：首任华盛顿、《独立宣言》起草人杰斐逊、废奴林肯。","ans":"华盛顿、杰斐逊与林肯是美国最具标志性的三位总统，同刻于“总统山”。**华盛顿**领导独立战争并任**首任总统**，开创两届任期先例；**杰斐逊**是**1776年《独立宣言》主要起草人**（2026年250周年）和第三任总统；**林肯**为第十六任总统，领导南北战争维护统一，1863年颁**《解放黑人奴隶宣言》**，并在葛底斯堡演说提出**“民有、民治、民享”**。","pts":["华盛顿：首任总统，领导独立并定两届先例","杰斐逊：第三任总统，《独立宣言》主要起草人","林肯：第十六任，颁废奴宣言，提民有民治民享"],"mem":"角色分工串联：“1号华盛顿打江山、3号杰斐逊写宣言、16号林肯保统一+解黑奴”。2026年《独立宣言》整250周年（1776至2026），重点盯紧杰斐逊。","mix":"《解放黑人奴隶宣言》1863年1月1日生效，先解放叛乱南方诸州黑奴，全美彻底废奴则靠1865年宪法第13修正案；注意“总统山”第四位是西奥多·罗斯福，而非推行新政的富兰克林·罗斯福。","mcq":[{"q":"1863年1月1日颁布《解放黑人奴隶宣言》，并在葛底斯堡演说中提出“民有、民治、民享”的美国总统是","o":["华盛顿","林肯","杰斐逊","富兰克林·罗斯福"],"a":1,"w":"林肯为美国第十六任总统，颁布《解放黑人奴隶宣言》并发表著名葛底斯堡演说。"}],"rel":[{"t":"华盛顿","n":"美国首任总统专条"},{"t":"美国《独立宣言》","n":"杰斐逊起草，250周年"},{"t":"美国南北战争与林肯","n":"林肯维护统一专条"},{"t":"三民主义","n":"孙中山借鉴林肯民有民治民享"}],"more":"1776年7月4日大陆会议通过《独立宣言》，2026年7月4日为美国建国及《独立宣言》发表250周年。","exam":[]},{"id":"a13-184","t":"美国南北战争","cid":"13j","p":3,"kind":"事件","alias":["南北战争","美国内战"],"one":"1861至1865年美国内战，北方联邦获胜，维护国家统一并废除奴隶制。","ans":"美国南北战争又称**美国内战**，是**1861至1865年**北方联邦与南方蓄奴州邦联间的内战。**林肯**领导北方并颁布**《解放黑人奴隶宣言》**，终获胜利。战争维护了**国家统一**，通过修宪**废除奴隶制**，为美国资本主义高速发展和崛起扫清障碍。","pts":["1861至1865年北方联邦与南方邦联内战","林肯颁布《解放黑人奴隶宣言》扭转战局","维护国家统一、废除奴隶制，促美崛起"],"mem":"对照记美国两次资产阶级革命：第一次1775–1783独立战争（赶英国），第二次1861–1865南北战争（保统一、废奴隶制）。","mix":"1862年颁布、1863年生效的《解放黑人奴隶宣言》仅先解放叛乱州奴隶；全美彻底废奴是在1865年宪法第13修正案。","mcq":[{"q":"美国南北战争爆发与结束的起止年份是","o":["1775至1783年","1848至1850年","1861至1865年","1898至1901年"],"a":2,"w":"美国南北战争起于1861年4月萨姆特堡炮击，止于1865年南方投降。"}],"rel":[{"t":"美国南北战争与林肯","n":"战争核心领导人物"},{"t":"共和党","n":"林肯所属反奴隶制政党"},{"t":"美国独立战争","n":"美国另一次资产阶级革命"}],"exam":[]},{"id":"a13-185","t":"门户开放政策","cid":"13j","p":3,"kind":"制度","alias":["门户开放"],"one":"1899年美国国务卿海约翰提出，要求列强在华势力范围内利益均沾。","ans":"门户开放政策是**1899年**美国国务卿**海约翰**向列强照会提出的**近代对华政策**。当时列强瓜分中国，美国因美西战争错过划分势力范围，遂主张在华**“机会均等、利益均沾”**。美国借此未动武便共享在华特权，形成列强共同支配中国的局面。","pts":["1899年美国国务卿海约翰照会列强提出","要求在华势力范围机会均等、利益均沾","标志美国对华独立外交与列强共同支配"],"mem":"场景记：1899年列强抢完中国地盘，迟到的美国国务卿海约翰喊出“门户别关，大家都进场做生意”，借机分一杯羹。","mix":"“门户开放”属于帝国主义列强在华协调侵华利益的外交政策，与现代中国主动对外开放本质迥异，次年即爆发八国联军侵华。","mcq":[{"q":"1899年提出“门户开放”政策、要求列强在华势力范围内机会均等的美国国务卿是","o":["门罗","海约翰","马歇尔","杜勒斯"],"a":1,"w":"美国国务卿海约翰于1899年9月向英、俄、德、日、意、法发出“门户开放”照会。"}],"rel":[{"t":"门罗主义","n":"19世纪美国另一次标志外交政策"},{"t":"义和团运动与《辛丑条约》","n":"次年列强共同侵华历史脉络"},{"t":"甲午中日战争","n":"引发列强瓜分狂潮的直接前因"}],"exam":[]},{"id":"a13-186","t":"中美三个联合公报","cid":"13j","p":1,"kind":"合称","alias":["中美三个联合公报","三个联合公报","八一七公报","中美建交公报"],"one":"《上海公报》《建交公报》《八一七公报》，中美关系政治基础。","ans":"中美三个联合公报是**中美关系的政治基础**，包括**1972年2月《上海公报》、1978年12月发表的《中美建交公报》、1982年8月17日《八一七公报》**。《上海公报》在尼克松访华期间发表，美方认识到台湾海峡两边的所有中国人都认为只有一个中国，台湾是中国的一部分；《建交公报》宣布两国自**1979年1月1日**起建立外交关系，**美国承认中华人民共和国政府是中国的唯一合法政府**；《八一七公报》中美方声明逐步减少对台军售。三个公报确认了**一个中国原则**，是处理台湾问题的基础。","pts":["1972上海公报，1978建交公报，1982八一七公报","1979年1月1日建交","一个中国原则；美国逐步减少对台军售"],"members":[["《上海公报》","1972年2月，尼克松访华时发表"],["《中美建交公报》","1978年12月发表，1979年1月1日建交"],["《八一七公报》","1982年8月17日，美方承诺逐步减少对台军售"]],"mem":"年份“七二、七八、八二”：七二上海，七八建交，八二八一七。顺序“上、建、八”。1979年1月1日正式建交，比公报发表晚两周多。","mix":"1979年美国国会通过的《与台湾关系法》是美国国内法，不属于三个公报，中方反对；1978年12月16日发表建交公报，1979年1月1日生效。","mcq":[{"q":"《上海公报》发表于哪一年，当时的事件是","o":["1972年，尼克松访华","1979年，邓小平访美","1982年，里根访华","1978年，中美建交"],"a":0,"w":"《上海公报》1972年2月在尼克松访华时发表。"},{"q":"下列不属于中美三个联合公报的是","o":["《上海公报》","《建交公报》","《八一七公报》","《与台湾关系法》"],"a":3,"w":"《与台湾关系法》是美国国内立法，不是联合公报。"}],"rel":[{"t":"《上海公报》","n":"第一个公报"},{"t":"尼克松访华","n":"公报背景"},{"t":"基辛格","n":"秘密访华铺路"},{"t":"联合国第2758号决议","n":"同期中国外交成果"}],"more":"1971年基辛格秘密访华；1972年2月尼克松访华；1979年1月1日中美建交，邓小平1月底访美。","exam":[]},{"id":"a13-187","t":"常春藤联盟","cid":"13j","p":2,"kind":"合称","alias":["常春藤盟校","Ivy League"],"one":"美国东北部哈佛、耶鲁、普林斯顿等八所顶尖私立研究型大学组成的联盟。","ans":"常春藤联盟（Ivy League）是**1954年**成立的**美国东北部八所私立研究型大学**体育联盟，因老校园攀满常春藤得名，现泛指美国顶尖高校。八校为**哈佛、耶鲁、普林斯顿、哥伦比亚、宾夕法尼亚、布朗、达特茅斯与康奈尔**。除康奈尔建于1865年外，其余七校皆建于殖民地时期，以雄厚科研与**通识教育**传统闻名世界。","pts":["1954年成立的美国东北部八所私立大学联盟","哈耶普哥宾布达康八所名校","七校建于殖民地时期，仅康奈尔建于1865年"],"members":[["哈佛大学","1636年建校，美国历史最悠久高校，马萨诸塞州"],["耶鲁大学","1701年建校，以人文社科与法学闻名，康涅狄格州"],["宾夕法尼亚大学","1740年建校，富兰克林倡建，拥有沃顿商学院"],["普林斯顿大学","1746年建校，以本科通识教育和基础科学著称"],["哥伦比亚大学","1754年建校，位于纽约曼哈顿，设普利策奖"],["布朗大学","1764年建校，以开放式课程体系闻名，罗德岛州"],["达特茅斯学院","1769年建校，八校中规模最小，重视本科教学"],["康奈尔大学","1865年建校，唯一建于美国独立后的常春藤成员"]],"mem":"口诀记八校：“哈耶普哥，宾布达康”。拆成两组：前四名气最大（哈佛、耶鲁、普林斯顿、哥伦比亚），后四紧随（宾大、布朗、达特茅斯、康奈尔）。再记三大“冒牌常春藤”：MIT、斯坦福、芝加哥都不在内。","mix":"高频选择题陷阱：麻省理工学院（MIT）、斯坦福大学、芝加哥大学、加州理工学院虽然学术顶尖，但均不属于常春藤联盟；常春藤全部位于美国东北部且皆为私立大学。","mcq":[{"q":"下列美国知名高校中，不属于“常春藤联盟”（Ivy League）成员的是","o":["达特茅斯学院","康奈尔大学","斯坦福大学","布朗大学"],"a":2,"w":"斯坦福大学位于美国西岸加利福尼亚州，不属于东北部八校组成的常春藤联盟；MIT、芝加哥大学同样不在其列。"}],"rel":[{"t":"哈佛大学","n":"常春藤最古老成员"},{"t":"常春藤盟校","n":"教育板块对应词条"},{"t":"罗素大学集团","n":"英国顶尖大学联盟对照"},{"t":"通识教育","n":"常春藤本科教育代表传统"}],"exam":[]},{"id":"a13-188","t":"硅谷与华尔街","cid":"13j","p":3,"kind":"地理","alias":["硅谷","华尔街"],"one":"分别指加州旧金山湾区高科技中心与纽约曼哈顿美国金融中心。","ans":"硅谷与华尔街分别是美国**科技创新与金融资本**的两大象征。**硅谷**位于**加州旧金山湾区南部**，依托高校与风投聚集半导体与互联网巨头。**华尔街**位于**纽约曼哈顿下城**，是**纽约证券交易所**所在地和美金融业代称，两者共同驱动美国现代经济。","pts":["硅谷位于加州旧金山湾区，属高科技产业中心","华尔街位于纽约曼哈顿，系美国金融中心代称","分别代表美国科技与资本两大引擎"],"mem":"东西海岸双核对照：西岸加州硅谷（以芯片材料“硅”得名，产科技），东岸纽约华尔街（纽交所驻地，控资本）。","mix":"科技股云集的纳斯达克交易所同样总部在纽约（时报广场附近），并非设在加州硅谷。","mcq":[{"q":"关于“硅谷”与“华尔街”的地理位置及定位，表述正确的是","o":["硅谷位于美国东海岸波士顿","华尔街位于纽约曼哈顿，为纽约证券交易所所在地","硅谷因盛产硅矿而得名","华尔街位于美国首都华盛顿"],"a":1,"w":"硅谷在西海岸加州旧金山湾区南部，因半导体芯片产业得名；华尔街在纽约曼哈顿。"}],"rel":[{"t":"加利福尼亚","n":"硅谷所在美国第一大州"},{"t":"纽约证券交易所","n":"坐落于华尔街的核心证交所"},{"t":"纳斯达克","n":"硅谷科技企业主要上市板块"},{"t":"2008年国际金融危机","n":"源于华尔街次贷风波"}],"exam":[]},{"id":"d13-001","t":"红船精神","cid":"13a","p":2,"kind":"概念","alias":["红船精神"],"one":"习近平2005年首次概括的中国革命精神之源，含首创、奋斗、奉献三层内涵。","ans":"**红船精神**依托1921年**中共一大嘉兴南湖红船**闭幕建党史实凝练而成，是中国共产党人精神谱系之源。**2005年6月21日**，习近平在《光明日报》发文首次系统概括其内涵：**开天辟地、敢为人先的首创精神**，**坚定理想、百折不挠的奋斗精神**，**立党为公、忠诚为民的奉献精神**。它承载党的初心使命，激励全党走在时代前列。","pts":["源于1921年中共一大嘉兴南湖红船闭幕史实","2005年6月21日习近平在《光明日报》首次提出","核心内涵：首创精神、奋斗精神、奉献精神"],"mem":"三句内涵浓缩成三词口诀：**“首创、奋斗、奉献”**（开天辟地→首创；坚定理想→奋斗；立党为公→奉献）；日期记**2005年6月21日《光明日报》**。","mix":"注意区分“红船精神”（2005年提出，三句话：首创、奋斗、奉献）与“伟大建党精神”（2021年建党百年大会提出，32字：坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民）。","mcq":[{"q":"2005年6月21日习近平在《光明日报》发表署名文章，将“红船精神”概括为首创精神、奋斗精神和","o":["奉献精神","抗战精神","创业精神","爱国精神"],"a":0,"w":"红船精神的内涵为开天辟地、敢为人先的首创精神，坚定理想、百折不挠的奋斗精神，立党为公、忠诚为民的奉献精神。"}],"rel":[{"t":"中国共产党第一次全国代表大会","n":"嘉兴南湖红船闭幕"},{"t":"伟大建党精神","n":"同源的中国共产党精神"},{"t":"中国共产党人精神谱系","n":"精神谱系源头之一"}],"more":"出处：2005年6月21日《光明日报》《弘扬“红船精神” 走在时代前列》。\n三层定位：首创精神是灵魂，奋斗精神是支柱，奉献精神是本质。","exam":[]},{"id":"d13-002","t":"新三样","cid":"13c","p":2,"kind":"概念","alias":["外贸新三样"],"one":"电动载人汽车、锂离子蓄电池、太阳能电池，中国绿色高技术外贸出口新增长极。","ans":"**“新三样”**指**电动载人汽车、锂离子蓄电池、太阳能电池**，是新时代中国外贸出口绿色化、高端化转型的标志产品，对应传统服装、家具、家电**“老三样”**。据海关总署统计，**2023年**中国“新三样”合计出口**1.06万亿元**、增长29.9%，**首次突破万亿元大关**，展现了中国产业链升级与**新质生产力**的国际竞争力。","pts":["电动载人汽车、锂离子蓄电池、太阳能电池","取代服装、家具、家电“老三样”成外贸新引擎","2023年合计出口1.06万亿元，首次突破万亿大关"],"mem":"一句话串记：“**新能源车装上锂电池，晒着太阳能板**”＝电动载人汽车+锂离子蓄电池+太阳能电池；对比“老三样”记**“衣家家”**（服装、家具、家电）。","mix":"选择题常把高铁、芯片、智能手机或无人机塞进选项冒充外贸“新三样”；准确口径特指电动载人汽车、锂离子蓄电池、太阳能电池三类绿色低碳产品。","mcq":[{"q":"2023年合计出口首次突破万亿元的中国外贸“新三样”是指","o":["服装、家具、家电","电动载人汽车、锂离子蓄电池、太阳能电池","芯片、新能源汽车、工业机器人","光伏组件、风电机组、特高压设备"],"a":1,"w":"海关总署口径的外贸“新三样”为电动载人汽车、锂离子蓄电池、太阳能电池，2023年合计出口1.06万亿元。"}],"rel":[{"t":"新质生产力","n":"绿色高端产业体现"},{"t":"碳达峰碳中和","n":"绿色低碳转型背景"},{"t":"高质量发展","n":"外贸结构升级方向"}],"more":"关键数据：2023年海关总署统计，“新三样”合计出口1.06万亿元人民币，增长29.9%，首次突破万亿元大关。","exam":[]},{"id":"d13-003","t":"滞胀","cid":"13d","p":2,"kind":"概念","alias":["停滞性通货膨胀","Stagflation"],"one":"经济停滞、高失业与高通胀并存的宏观困境，典型见于1970年代石油危机。","ans":"**滞胀**（Stagflation）是宏观经济学概念，指**经济停滞、高失业与高通货膨胀并存**的困境。**20世纪70年代**两次**石油危机**（1973、1979年）引发剧烈供给冲击，油价飙升推高成本同时抑制产出，令欧美深陷滞胀。这一现象打破了传统**菲利普斯曲线**的替代规律，令**凯恩斯主义**调控陷入两难，推动货币主义与供给学派兴起。","pts":["经济停滞、高失业与高通货膨胀同时并存","典型案例为1970年代石油危机引发的欧美供给冲击","打破传统菲利普斯曲线，推动货币主义与供给学派兴起"],"mem":"拆字记词源：英语**Stagnation（停滞）+ Inflation（通胀）= Stagflation（滞胀）**；逻辑线：油价暴涨→企业成本飙升（物价涨）同时减产裁员（经济停），两头夹击让刺激政策左右为难。","mix":"滞胀不同于单纯“通胀”（常伴随经济过热）和“通缩”（经济低迷伴随物价下跌），它最棘手之处在于“经济冷、物价热”同时出现。","mcq":[{"q":"20世纪70年代西方国家受石油危机冲击普遍陷入“滞胀”，其核心经济特征是","o":["经济增长停滞与物价持续下跌并存","经济高速增长与高失业率并存","经济增长停滞、高失业与高通货膨胀并存","物价稳定与财政赤字大幅缩减并存"],"a":2,"w":"滞胀即停滞性通货膨胀，表现为经济停滞、高失业与高通胀同时发生。"}],"rel":[{"t":"通货膨胀与通货紧缩","n":"宏观物价现象对照"},{"t":"凯恩斯主义","n":"滞胀冲击传统凯恩斯理论"},{"t":"石油输出国组织","n":"1970年代石油危机导火索"}],"more":"历史节点：1973年第一次石油危机、1979年第二次石油危机；美联储主席保罗·沃尔克1979年后大幅加息遏制恶性通胀。","exam":[]},{"id":"d13-004","t":"全球发展倡议与全球安全倡议","cid":"13h","p":2,"kind":"时事","alias":["全球发展倡议","全球安全倡议","GDI与GSI"],"one":"习近平于2021、2022年提出的两大倡议，与文明、治理倡议合称四大全球倡议。","ans":"**全球发展倡议**与**全球安全倡议**是习近平围绕构建**人类命运共同体**提出的重要倡议。**2021年9月**在第76届联大提出全球发展倡议，助力落实联合国2030议程；**2022年4月**在博鳌亚洲论坛提出全球安全倡议，倡导共同、综合、合作、可持续安全观。二者与2023年全球文明倡议、**2025年上合天津峰会**提出的**全球治理倡议**构成**四大全球倡议**。","pts":["发展倡议：2021年9月第76届联大提出，促发展","安全倡议：2022年4月博鳌提出，倡共同综合安全观","与全球文明、全球治理倡议共同构成四大全球倡议"],"mem":"时间阶梯“21-22-23-25”记四大全球倡议：**21联大谈发展**、**22博鳌谈安全**、**23北京谈文明**、**25天津（上合+）谈治理**，按“物质根基→和平环境→价值共识→制度保障”四步递进。","mix":"选择题常混淆各倡议的提出年份与场合：发展在2021年联大，安全在2022年博鳌亚洲论坛，文明在2023年高层对话会，治理在2025年9月上合天津峰会。","mcq":[{"q":"2022年4月21日，习近平主席在博鳌亚洲论坛年会开幕式上首次提出的重要国际倡议是","o":["全球发展倡议","全球文明倡议","全球治理倡议","全球安全倡议"],"a":3,"w":"全球安全倡议于2022年4月21日在博鳌亚洲论坛提出；发展倡议为2021年联大，文明为2023年，治理为2025年天津峰会。"}],"rel":[{"t":"全球四大倡议","n":"所属完整外交倡议体系"},{"t":"人类命运共同体","n":"统领性中国外交理念"},{"t":"2025年上海合作组织天津峰会","n":"提出全球治理倡议补齐四大倡议"},{"t":"联合国2030年可持续发展议程","n":"全球发展倡议对接目标"}],"more":"四大全球倡议时间表：\n2021年9月21日：全球发展倡议（第76届联大）\n2022年4月21日：全球安全倡议（博鳌亚洲论坛）\n2023年3月15日：全球文明倡议（中国共产党与世界政党高层对话会）\n2025年9月1日：全球治理倡议（“上海合作组织+”天津会议）","exam":[]},{"id":"d13-005","t":"《联合国海平面上升宣言》","cid":"13c","p":3,"kind":"时事","alias":["海平面上升宣言","A/RES/81/3"],"one":"2026年10月12日联合国大会通过，海平面上升是人类共同关切。","ans":"《联合国海平面上升宣言》作为联大决议**A/RES/81/3**的附件，于**2026年10月12日由联合国大会第八十一届会议通过**。宣言称海平面上升是**全球性问题和人类共同关切**，对**小岛屿发展中国家和最不发达国家**威胁尤大；主张依照包括《联合国海洋法公约》在内的国际法处理，**海岸线变化后依法确立的海洋区域可以维持**，国土丧失后国家地位推定延续。","pts":["2026年10月12日联大通过，决议A/RES/81/3附件","海平面上升是人类共同关切，小岛屿国家受威胁最大","海洋区域维持、国家地位延续"],"mem":"“**水涨，界不动，国还在**”：海平面上升了，海洋区域照旧、国家地位照旧。","mix":"9月24日是联大高级别会议，10月12日才是宣言正式通过的日期。","rel":[{"t":"联合国海洋法公约的海域划分","n":"海洋区域依据"},{"t":"《巴黎协定》","n":"气候治理框架"},{"t":"三大里约公约","n":"全球环境治理"}],"more":"2026年9月24日：联大海平面上升高级别会议\n2026年10月12日：联大正式通过（A/RES/81/3）","exam":[]},{"id":"d13-006","t":"三大里约公约","cid":"13c","p":2,"kind":"合称","alias":["里约三公约","里约公约"],"one":"气候变化、生物多样性、防治荒漠化三公约，都与1992年里约地球峰会相关。","ans":"三大里约公约指**《联合国气候变化框架公约》《生物多样性公约》《联合国防治荒漠化公约》**，都与**1992年在巴西里约热内卢召开的联合国环境与发展大会（地球峰会）**相关：前两项在峰会上开放签署，防治荒漠化公约由峰会成果《21世纪议程》推动谈判，**1994年通过**。三公约各自每年或每两年召开缔约方大会。2026年三场大会分别是：**防治荒漠化公约COP17（蒙古乌兰巴托，8月）**、**生物多样性公约COP17（亚美尼亚埃里温，10月31日闭幕）**、**气候变化公约COP31（土耳其安塔利亚，11月）**。","pts":["气候变化、生物多样性、防治荒漠化三公约","源于1992年里约地球峰会；荒漠化公约1994年通过","2026年：乌兰巴托、埃里温、安塔利亚三场COP"],"members":[["《联合国气候变化框架公约》","1992年开放签署；2026年COP31在安塔利亚"],["《生物多样性公约》","1992年开放签署；2026年COP17在埃里温"],["《联合国防治荒漠化公约》","1994年通过；2026年COP17在乌兰巴托"]],"mem":"“**气、生、沙**”三兄弟：气候、生物、沙漠化。2026年三场大会按时间“**蒙（8月）亚（10月）土（11月）**”。","mix":"《湿地公约》（1971年拉姆萨尔）、《蒙特利尔议定书》（臭氧层）不属于里约公约；荒漠化公约不是1992年签署的。","mcq":[{"q":"下列公约中，不属于“三大里约公约”的是","o":["《联合国气候变化框架公约》","《湿地公约》","《生物多样性公约》","《联合国防治荒漠化公约》"],"a":1,"w":"三大里约公约是气候变化、生物多样性、防治荒漠化三项；《湿地公约》1971年在拉姆萨尔签署。"}],"rel":[{"t":"联合国气候变化大会第三十一次缔约方大会（COP31）","n":"气候公约2026年大会"},{"t":"《巴黎协定》","n":"气候公约下的协定"},{"t":"臭氧层与《蒙特利尔议定书》","n":"非里约公约"}],"more":"1992年：里约联合国环境与发展大会\n1994年：《联合国防治荒漠化公约》通过\n2026年8月17日至28日：UNCCD COP17，乌兰巴托\n2026年10月31日：CBD COP17在埃里温闭幕\n2026年11月9日至22日：UNFCCC COP31，安塔利亚","exam":[]}],"tables":[{"name":"重要政治表述速查","note":"2023选择“中国新时代三大成就”指的就是二十大报告概括的“三件大事”。","rows":[["表述","提出时间与场合","内容"],["新发展理念","2015年十八届五中全会","创新、协调、绿色、开放、共享"],["“五位一体”","2012年党的十八大","经济、政治、文化、社会、生态文明建设"],["“四个全面”","2014年提出，2015年形成战略布局","最初为全面建成小康社会、全面深化改革、全面依法治国、全面从严治党；2020年十九届五中全会后第一项改为全面建设社会主义现代化国家"],["新时代三件大事","2022年党的二十大报告","迎来建党一百周年；中国特色社会主义进入新时代；完成脱贫攻坚、全面建成小康社会，实现第一个百年奋斗目标"],["中国式现代化五个特征","2022年党的二十大报告","人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路"],["“两步走”","党的十九大、二十大","2035年基本实现社会主义现代化；本世纪中叶建成社会主义现代化强国"],["全球四大倡议","2021—2025年","全球发展倡议（2021）、全球安全倡议（2022）、全球文明倡议（2023）、全球治理倡议（2025）"],["总体国家安全观","2014年中央国家安全委员会第一次会议","以人民安全为宗旨，统筹发展和安全"],["“三个代表”","2000年江泽民在广东考察时提出","始终代表中国先进生产力的发展要求、先进文化的前进方向、最广大人民的根本利益"]]},{"name":"党的三个历史决议与几次三中全会","note":"","rows":[["文件或会议","时间","要点"],["《关于若干历史问题的决议》","1945年六届七中全会","第一个历史决议，确立毛泽东思想的指导地位，为七大作准备"],["《关于建国以来党的若干历史问题的决议》","1981年十一届六中全会","第二个历史决议，否定“文化大革命”，科学评价毛泽东"],["《中共中央关于党的百年奋斗重大成就和历史经验的决议》","2021年十九届六中全会","第三个历史决议（2024选择），总结“十个坚持”历史经验"],["十一届三中全会","1978年","实行改革开放，工作重心转移到经济建设"],["十八届三中全会","2013年","《关于全面深化改革若干重大问题的决定》，提出国家治理体系和治理能力现代化"],["二十届三中全会","2024年7月","《中共中央关于进一步全面深化改革、推进中国式现代化的决定》（2025选择），提出300多项改革举措，到2029年新中国成立80周年时完成"],["二十届四中全会","2025年10月","审议通过“十五五”规划建议"],["二十届五中全会","2026年10月","审议通过《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》；决定二十一大2027年下半年在北京召开"]]}]});